def host_of(vp):
    """\u4e91\u76d8\u89c6\u89d9\u8def\u5f84 / \u5bbf\u4e3b\u673a\u8def\u5f84 \u2192 \u5bbf\u4e3b\u673a\u6302\u8f7d\u8def\u5f84\u3002

    \u63a5\u53d7\u4e09\u79cd\u5199\u6cd5\uff08\u524d\u7aef\u76ee\u5f55\u9009\u62e9\u5668 dirPick \u56de\u586b\u7684\u662f CD2 \u89c6\u89d9 /115open/\u2026\uff0c
    \u800c\u547d\u540d/\u6574\u7406\u4efb\u52a1\u4e0a\u4f20\u7684\u53ef\u80fd\u662f /\u4e3b\u53f7/\u2026 \u6216 /CloudNAS/115open/\u2026\uff09\uff1a
      /\u4e3b\u53f7/A/B      \u2192 /CloudNAS/115open/A/B
      /115open/A/B        \u2192 /CloudNAS/115open/A/B   \u2190 \u4fee\u590d\u300c\u6e90\u76ee\u5f55\u4e0d\u5b58\u5728\u300d\u7684\u6839\u56e0
      /CloudNAS/115open/A/B \u2192 \u539f\u6837
      A/B                \u2192 /CloudNAS/115open/A/B
    """
    p = (vp or '').strip()
    if not p:
        return MOUNT
    if p.startswith(CD2_ROOT):
        p = p[len(CD2_ROOT):]
    p = p.lstrip('/')
    if p == '\u4e3b\u53f7':
        p = ''
    elif p.startswith('\u4e3b\u53f7/'):
        p = p[len('\u4e3b\u53f7/'):]
    if p == '115open':
        p = ''
    elif p.startswith('115open/'):
        p = p[len('115open/'):]
    return os.path.join(MOUNT, p) if p else MOUNT


def run(cmd, t=120):
    try:
        r = subprocess.run(cmd, shell=True, capture_output=True, text=True, timeout=t)
        return (r.stdout or '').strip()
    except Exception:
        return ''


def db():
    """MediaTidy DB 连接。WAL 模式，读写都需要超时与 row 工厂。"""
    c = sqlite3.connect(DB, timeout=30)
    c.row_factory = sqlite3.Row
    return c


def db_flush():
    """切换 WAL 后强制把内容合并进主库，确保 MediaTidy 重启后一定能读到。"""
    try:
        with sqlite3.connect(DB, timeout=30) as c:
            c.execute("PRAGMA wal_checkpoint(TRUNCATE)")
            c.commit()
        return True
    except Exception:
        return False


def db_owned_by_mt():
    """MediaTidy 是否正在运行（运行中就不该直接改库）。"""
