class UHTTP(http.client.HTTPConnection):
    def __init__(self, p, t=90):
        super().__init__('localhost', timeout=t)
        self.p_ = p

    def connect(self):
        k = socket.socket(socket.AF_UNIX, socket.SOCK_STREAM)
        k.settimeout(self.timeout)
        k.connect(self.p_)
        self.sock = k


def dk(method, url, body=None, t=90):
    """Docker Engine API over unix socket."""
    try:
        c = UHTTP(DOCKER_SOCK, t)
        c.request(method, url, body=json.dumps(body) if body is not None else None,
                  headers={'Content-Type': 'application/json'})
        r = c.getresponse()
        return r.status, r.read().decode('utf-8', 'ignore')
    except Exception as e:
        return -1, str(e)


def http_health_ok(st):
    """★ 2026-10-24 P1：健康探活的唯一判定口径。
    只有 2xx/3xx 算「在线」；4xx/5xx/连接失败(-1)/超时 一律判「异常」。
    此前用 `st > 0`（404>0 也为 True）会把「端点不存在」误报成在线。"""
    try:
        return 200 <= int(st) <= 399
    except Exception:
        return False


def hreq(host, port, method, path, body=None, hdr=None, t=8):
    try:
        c = http.client.HTTPConnection(str(host), int(port), timeout=t)
        c.request(method, path, body=body, headers=hdr or {})
        r = c.getresponse()
        return r.status, r.read().decode('utf-8', 'ignore')
    except Exception as e:
        return -1, str(e)


def hget(host, port, path, hdr=None, t=8):
    s, b = hreq(host, port, 'GET', path, None, hdr, t)
    try:
        return s, json.loads(b)
    except Exception:
        return s, b


def probe(host, port, path='/', t=4):
    """轻量探测，永不抛异常，永不阻塞超过 t 秒。"""
    s, _ = hreq(host, port, 'GET', path, None, None, t)
    return s if s > 0 else 0


def tcp_alive(host, port, t=3):
    """只测 TCP 是否连得上。用于 gRPC 这类非 HTTP 端口（HTTP 探测会误判）。"""
    try:
        s = socket.create_connection((str(host), int(port)), timeout=t)
        s.close()
        return True
    except Exception:
        return False


