def license_status():
    """当前生效授权状态（本机生效授权 or 30 天试用）。"""
    now = int(time.time())
    with _sec_lock:
        c = sec_db()
        r = c.execute("SELECT * FROM licenses WHERE status='active' AND expire_at>?"
                      " ORDER BY expire_at DESC LIMIT 1", (now,)).fetchone()
        c.close()
    if r:
        return {'ok': True, 'mode': 'licensed', 'code': r['code'],
                'licensee': r['licensee'], 'plan': r['plan'],
                'features': json.loads(r['features'] or '[]'),
                'expire_at': r['expire_at'],
                'days_left': max(0, (r['expire_at'] - now) // 86400),
                'max_nodes': r['max_nodes'] or 1}
    first = sec_first_run()
    trial_end = first + SEC_PLANS['trial']['days'] * 86400
    left = (trial_end - now) // 86400
    return {'ok': left > 0, 'mode': 'trial', 'code': '',
            'features': list(SEC_PLANS['trial']['features']),
            'expire_at': trial_end, 'days_left': max(0, left),
            'max_nodes': 1, 'msg': '试用模式（未填授权码）'}


# ★★ v1.37 S5：写操作授权闸（商用开源：试用到期即只读，激活码才解锁）
#   缓存 30 秒，避免每次 POST 都查库。
_GATE_CACHE = {'t': 0.0, 'ok': True, 'msg': ''}
_GATE_OPEN_PREFIX = ('/api/sec/',)
_GATE_OPEN_EXACT = ('/api/config', '/api/changelog/bounce')


def sec_write_gate(path):
    """返回 '' 放行；返回非空串 = 拒绝理由。"""
    global _GATE_CACHE
    if path.startswith(_GATE_OPEN_PREFIX) or path in _GATE_OPEN_EXACT:
        return ''
    now = time.time()
    if now - _GATE_CACHE['t'] < 30:
        return '' if _GATE_CACHE['ok'] else _GATE_CACHE['msg']
    try:
        st = license_status()
        ok = bool(st.get('ok'))
        msg = '' if ok else ('授权已过期或被吊销（%s），当前为只读模式。'
                             '请在「设置 → 授权与账户」激活新的授权码。'
                             % (st.get('msg') or 'license expired'))
    except Exception as e:
        ok, msg = True, ''      # 授权模块本身出错时绝不能锁死面板
    _GATE_CACHE = {'t': now, 'ok': ok, 'msg': msg}
    return '' if ok else msg


