def oplog(actor, action, title, ok, msg, detail=None):
    _job_seq[0] += 1
    rec = {'seq': _job_seq[0], 'at': time.strftime('%F %T'), 'ts': time.time(),
           'actor': actor, 'action': action, 'title': title,
           'ok': bool(ok), 'msg': (msg or '')[:500], 'detail': detail}
    OPLOG.append(rec)
    return rec


def submit(action_id, fn, *a, **kw):
    """把动作丢到线程执行，立即返回 jobId。"""
    jid = uuid.uuid4().hex[:12]
    JOBS[jid] = {'id': jid, 'action': action_id, 'state': 'running',
                 'started': time.time(), 'result': None}
    def worker():
        t0 = time.time()
        try:
            res = fn(*a, **kw)
            if not isinstance(res, dict):
                res = {'ok': bool(res), 'msg': str(res)}
            if 'ok' not in res:
                res['ok'] = False
        except Exception as e:
            import traceback
            res = {'ok': False, 'msg': '执行异常：%s' % sanitize_err(e, 200),
                   'detail': sanitize_err(traceback.format_exc()[-800:], 800)}
        res['elapsed'] = round(time.time() - t0, 2)
        JOBS[jid].update({'state': 'done', 'result': res})
        JOBS[jid]['finished'] = time.time()
        if len(JOBS) > 200:
            for k in sorted(JOBS, key=lambda x: JOBS[x].get('started', 0))[:80]:
                if JOBS[k].get('state') == 'done':
                    JOBS.pop(k, None)
    threading.Thread(target=worker, daemon=True).start()
    return jid


