def tasks():
    out = []
    try:
        with db() as c:
            for r in c.execute("SELECT key,enabled,config FROM scheduled_jobs "
                                "WHERE type='organize'"):
                try:
                    j = json.loads(r['config'])
                except Exception:
                    continue
                j['_key'] = r['key']
                # enabled 取 config 里的值——这才是真正的开关。
                # ★ 2026-10-13 实测更正：旧代码用 enabled【列】覆盖（j['enabled']=bool(r['enabled'])），
                #   但该列是 MT 的 cron 开关（实时轮询方案恒为 0），覆盖后所有 MT 自建方案
                #   在面板上显示「停用」，coverage() 也把它们全部分到停用集合，判定全面失真。
                j['enabled'] = bool(j.get('enabled'))
                out.append(j)
    except Exception:
        return []
    out.sort(key=lambda x: x.get('id') or 0)
    return out


def _tail_bytes(path, nbytes):
    """只读文件末尾 nbytes 字节。日志可达 GB 级，整文件读会拖垮巡检。"""
    try:
        sz = os.path.getsize(path)
        with open(path, 'rb') as f:
            if sz > nbytes:
                f.seek(sz - nbytes)
                f.readline()          # 丢弃可能被截断的首行
            raw = f.read()
        return raw.decode('utf-8', 'ignore')
    except Exception:
        return ''


def tail(n):
    """取最近 n 条结构化日志（按时间倒序文件尾部增量读）。"""
    if not os.path.isdir(LOG_DIR):
        return []
    fs = sorted([f for f in os.listdir(LOG_DIR) if f.startswith('app-') and f.endswith('.log')])
    if not fs:
        return []
    per = max(400000, min(4000000, n * 900))
    o = []
    for fn in reversed(fs[-2:]):
        raw = _tail_bytes(os.path.join(LOG_DIR, fn), per)
        rows = []
        for l in raw.split('\n'):
            l = l.strip()
            if not l or not l.startswith('{'):
                continue
            try:
                rows.append(json.loads(l))
            except Exception:
                pass
        o = rows + o
        if len(o) >= n:
            break
    return o[-n:]


def log_heartbeat():
    """最后一条日志的时间，用于判断流水线是否还在跳动。"""
    lg = tail(50)
    if lg and lg[-1].get('time'):
        return lg[-1]['time'][:19].replace('T', ' ')
    return ''


