def disk_info():
    for ln in run("df -h /data 2>/dev/null").split('\n'):
        if not ln.strip() or 'Mounted on' in ln or ln.strip().startswith('/dev/'):
            continue
        t = ln.split()
        if t and t[0].startswith('/'):
            t = t[1:]
        if len(t) >= 5:
            return {'total': t[-5], 'used': t[-4], 'avail': t[-3], 'pct': t[-2]}
    return None


# ══════════════════════ 容器控制（真正的容器操作）══════════════════════
def ctr_inspect(cname):
    st, b = dk('GET', '/containers/%s/json' % cname)
    if st != 200:
        return None
    try:
        return json.loads(b)
    except Exception:
        return None


def ctr_state(cname):
    j = ctr_inspect(cname)
    if not j:
        return {'ok': False, 'state': 'missing'}
    stt = (j.get('State') or {})
    return {'ok': True, 'state': stt.get('Status'), 'running': bool(stt.get('Running')),
            'started': (stt.get('StartedAt') or '')[:19].replace('T', ' '),
            'restarts': j.get('RestartCount'), 'image': (j.get('Config') or {}).get('Image'),
            'health': ((stt.get('Health') or {}).get('Status')) if stt.get('Health') else None}


# ★ 2026-10-24：禁止 media-hub 对自身做 stop/restart（自杀），也禁止直接操作
#   宿主机根/系统关键容器。只允许对「受管业务容器」做生命周期操作。
#   （集中判定的纯函数见 ctr_self_guard，本处保留兜底，调用方先判一次即可。）


def ctr_action(cname, act, t=90):
    # ★ 自保兜底：即便调用方漏判，这里也再拦一次 media-hub 自身（会断面板）。
    _g = ctr_self_guard(cname, act)
    if _g:
        return _g
    m = {'start': ('POST', '/containers/%s/start' % cname),
         'stop': ('POST', '/containers/%s/stop?t=60' % cname),
         'restart': ('POST', '/containers/%s/restart?t=60' % cname),
         'pause': ('POST', '/containers/%s/pause' % cname),
         'unpause': ('POST', '/containers/%s/unpause' % cname)}
    if act not in m:
        return {'ok': False, 'msg': '不支持的操作 %s' % act}
    # ★ 显示名：cname 可能是 docker 容器名（如 moviepilot-v3），不再 KeyError —— 回退 cname。
    disp = (next((v['name'] for v in containers().values() if v.get('cname') == cname), None)
            or containers().get(cname, {}).get('name') or cname)
    meth, url = m[act]
    st, b = dk(meth, url, t=t)
    zh = {'start': '启动', 'stop': '停止', 'restart': '重启', 'pause': '暂停', 'unpause': '恢复'}
    if st in (204, 304):
        return {'ok': True, 'msg': '%s 已%s' % (disp, zh[act])}
    if st == 304:
        return {'ok': True, 'msg': '状态已是目标值'}
    return {'ok': False, 'msg': '%s%s失败 HTTP %s %s' % (disp, zh[act], st, (b or '')[:120])}


def ctr_logs(cname, n=200):
    st, b = dk('GET', '/containers/%s/logs?stdout=1&stderr=1&tail=%d' % (cname, n))
    if st != 200:
        return {'ok': False, 'msg': '读取日志失败 HTTP %s' % st, 'lines': []}
    lines = []
    for ln in b.split('\n'):
        if len(ln) > 8 and ln[0] in '\x01\x02':
            lines.append(ln[8:])
        elif ln.strip():
            lines.append(ln)
    return {'ok': True, 'lines': lines[-n:], 'msg': '%d 行' % len(lines[-n:])}


def ctr_stats(cname):
    st, b = dk('GET', '/containers/%s/stats?stream=false' % cname, t=15)
    if st != 200:
        return None
    try:
        j = json.loads(b)
    except Exception:
        return None
    cpu = 0.0
    try:
        cd = j['cpu_stats']['cpu_usage']['total_usage'] - j['precpu_stats']['cpu_usage']['total_usage']
        sd = j['cpu_stats']['system_cpu_usage'] - j['precpu_stats']['system_cpu_usage']
        n = j['cpu_stats'].get('online_cpus') or len(j['cpu_stats']['cpu_usage'].get('percpu_usage') or [1])
        if sd > 0:
            cpu = round(cd / sd * n * 100, 1)
    except Exception:
        pass
    mem = 0
    memlim = 0
    try:
        mem = j['memory_stats'].get('usage', 0)
        memlim = j['memory_stats'].get('limit', 0)
    except Exception:
        pass
    return {'cpu': cpu, 'mem': mem, 'mem_limit': memlim,
            'mem_pct': round(mem / memlim * 100, 1) if memlim else 0}


