# ══════════════════════ 整理任务动作 ══════════════════════
def _write_jobs(mutator, need_restart=True):
    """统一的方案写库流程：停 MT → 改 → checkpoint → 回读 → 启动 MT。

    mutator(c, json) -> (changed_bool, note_str)；由调用方决定改哪些字段。

    ★★★ enabled 列的真实语义（2026-10-13 实测更正，旧注释是错的）★★★
      旧注释说「MT 按 scheduled_jobs.enabled 列决定是否调度」——只对了一半：
      该列实际是 MT 的【定时任务(cron)开关】，不是实时轮询开关。实测：
        列=1 → MT 加载时把 job 注册为 cron 任务，并强制虚拟化
               realtimeMode=off + cronEnabled=true（config 里写 polling 也被无视！）
        列=0 → 严格按 config 生效（realtimeMode=polling 实时轮询 30s）
      MT 自己 UI/API 建的整理方案，列一律是 0——真正的开关是 config.enabled。
      所以这里按 config.cronEnabled 同步列：要定时的才写 1，实时轮询的写 0。
      （旧逻辑 col_en = 1 if enabled else 0 会把「启用」的实时任务变成每日定时。）
    返回 (changed_count, notes, verify_ok, stop_msg)
    """
    stop = db_stop_mt()
    time.sleep(1.2)
    changed = 0
    notes = []
    try:
        with db() as c:
            for k, v in c.execute("SELECT key,config FROM scheduled_jobs WHERE type='organize'").fetchall():
                try:
                    j = json.loads(v)
                except Exception:
                    continue
                ch, note = mutator(k, j)
                if not ch:
                    continue
                # config JSON 与 enabled 列必须保持一致：
                # 列 = MT 的 cron 开关（1=注册为定时任务并强制 rt=off），
                # 实时轮询方案（cronEnabled=false）必须写 0，否则 polling 被虚拟化掉。
                col_en = 1 if j.get('cronEnabled') else 0
                c.execute(
                    "UPDATE scheduled_jobs SET config=?, enabled=?, updated_at=datetime('now') WHERE key=?",
                    (json.dumps(j, ensure_ascii=False), col_en, k))
                changed += 1
                if note:
                    notes.append(note)
            c.commit()
            ic = c.execute('PRAGMA integrity_check').fetchone()[0]
    except Exception as e:
        if need_restart:
            db_start_mt()
        return changed, notes + ['写库异常：%s' % e], False, stop

    db_flush()
    # 回读校验：用全新连接，逐条核对 enabled 列与 config 是否一致
    # （列的基准是 cronEnabled：列=1 表示注册为定时任务，实时轮询方案应为 0）
    okv = True
    try:
        with db() as c:
            n = c.execute("SELECT count(*) FROM scheduled_jobs WHERE type='organize'").fetchone()[0]
            drift = []
            for r in c.execute("SELECT key,enabled,config FROM scheduled_jobs WHERE type='organize'"):
                try:
                    ce = 1 if json.loads(r['config']).get('cronEnabled') else 0
                except Exception:
                    continue
                if ce != (r['enabled'] or 0):
                    drift.append(r['key'])
            if drift:
                okv = False
                notes.append('回读警告：%d 条 enabled 列与 config 不一致：%s' % (len(drift), ', '.join(drift[:6])))
            notes.append('回读确认：organize 共 %d 条，integrity=%s' % (n, ic))
    except Exception as e:
        okv = False
        notes.append('回读失败：%s' % e)

    try:
        shutil.chown(DB, 0, 0)
        for f in (DB + '-wal', DB + '-shm'):
            if os.path.exists(f):
                shutil.chown(f, 0, 0)
    except Exception:
        pass

    if need_restart:
        r = db_start_mt()
        notes.append('MediaTidy %s' % r.get('msg'))
    return changed, notes, okv, stop


# ══════════════════════ 求片优先级抢占引擎（2026-10-14 用户拍板）══════════════════════
# 规则：115 的 待整理/PT/求片/** 里有待整理文件 → 暂停其他全部整理方案，
#       只保留「求片方案」按优先级顺序跑；连续 IDLE_ROUNDS 轮检测为空 →
#       自动恢复被抢占前启用的方案。人工可在 Web 调序（拖拽/按钮）与开关。
PRI_DEF = {
    'on': True,             # 引擎总开关
    'check_interval': 60,   # 检测间隔（秒）
    'idle_rounds': 3,       # 连续 N 轮无待整理文件 → 恢复其他方案
    'order': [],            # 手工优先级顺序（key 列表，越靠前越优先；空=按 id）
    'preempted': False,     # 运行期状态（持久化，重启可续）
    'saved': [],            # 抢占时被停用的方案 key 快照（恢复依据）
    # ── 2026-11-02 方案排序（一键排序/多排序方案）──
    'ssort_schemes': {},    # {名称: {name, rules}}
    'ssort_default': 'default',  # 默认排序方案（内置 default=规则引擎 / manual / 自定义）
    'ssort_active': 'default',   # 当前生效的排序方案
    'idle_cnt': 0,
    'last_pending': 0,      # 最近一次发现待整理文件的时间戳
    'last_msg': '',
    'last_ts': 0,
}
PRI_LOCK = threading.Lock()


def pri_cfg():
    d = dict(PRI_DEF)
    c = cfg().get('priority')
    if isinstance(c, dict):
        d.update({k: v for k, v in c.items() if k in PRI_DEF})
    return d


def pri_save(patch):
    d = pri_cfg()
    for k, v in (patch or {}).items():
        if k not in PRI_DEF:
            continue
        if k in ('on', 'preempted'):
            v = bool(v)
        elif k == 'check_interval':
            v = max(20, min(600, int(v or 60)))
        elif k == 'idle_rounds':
            v = max(1, min(30, int(v or 3)))
        elif k in ('order', 'saved'):
            v = [str(x) for x in (v or [])]
        elif k in ('idle_cnt', 'last_pending', 'last_ts'):
            v = int(v or 0)
        d[k] = v
    cc = cfg()
    cc['priority'] = d
    save_cfg(cc)
    _cache_drop('priority')
    return d


WISH_SOURCE_PREFIX = '/主号/待整理/PT/求片'


def _is_wish_job(j):
    """方案的 sourceDir 是否属于「求片」（/主号/待整理/PT/求片 或其子目录）"""
    sd = (j.get('sourceDir') or '').rstrip('/')
    return sd == WISH_SOURCE_PREFIX.rstrip('/') or sd.startswith(WISH_SOURCE_PREFIX)


def _job_sort_key(t):
    """按手工 order 排（order 里没出现的按 id 垫底）"""
    order = pri_cfg().get('order') or []
    k = t.get('_key')
    try:
        return (order.index(k), 0)
    except ValueError:
        return (len(order), int(t.get('id') or 0))


def wish_pending_count():
    """115 待整理/PT/求片 下还有多少待整理视频（分两层：站点/分类目录扫到底）。

    CD2 目录缓存可能滞后 → 检测前先对根目录做一次轻量刷新（cd2_refresh）。
    只统计数量不做深递归遍历文件；.strm/.tmp 等忽略。"""
    try:
        root = host_of(WISH_SOURCE_PREFIX)
        if not os.path.isdir(root):
            return 0
        n = 0
        for sub, _dirs, files in os.walk(root):
            for f in files:
                if f.lower().endswith(('.mkv', '.mp4', '.ts', '.iso', '.m2ts')):
                    n += 1
        return n
    except Exception:
        return 0


# ── 2026-11-02 方案排序：规则引擎 + 多排序方案（默认内置，可存可设默认）──
SSORT_BUILTIN = {'default': '🏠 内置默认',
                 'manual':  '✋ 手动顺序'}
SSORT_RULES_TXT = """
# 格式：组:类别|move = 基数   （类别按方案名关键字包含匹配；skip 自动 = move + 0.5）
# 效果：同一目录「移动在上、对应跳过紧随其下」；类别顺序 = 基数顺序
# 组顺序固定：PT → 未识别 → MT → RT → 115大包 → 专属 → 其他
# 组内类别默认：PT 求片→订阅 ｜ MT/RT 离线→转存→缺集→追新（缺集在追新前）
PT:求片|move=1  PT:订阅|move=3
MT:离线|move=1  MT:转存|move=3  MT:缺集|move=5  MT:追新|move=7
RT:离线|move=1  RT:转存|move=3  RT:缺集|move=5  RT:追新|move=7  RT:测试|move=9
未识别:离线|move=1  未识别:转存|move=3  未识别:缺集|move=5  未识别:追新|move=7  未识别:求片|move=9  未识别:订阅|move=11
115大包:普通|move=1
专属:普通|move=1
其他:普通|move=1
"""

def _ssort_group(name):
    n = name or ''
    if '未识别' in n: return '未识别'
    if n.startswith('PT') or '/PT/' in n or 'PT-' in n: return 'PT'
    if 'MT' in n: return 'MT'
    if 'RT' in n: return 'RT'
    if '115大包' in n: return '115大包'
    if ('ISO' in n) or ('预处理' in n) or ('自动重命名' in n): return '专属'
    return '其他'

def _ssort_cat(name):
    n = name or ''
    if '订阅' in n: return '订阅'
    if '求片' in n: return '求片'
    if '离线' in n: return '离线'
    if '转存' in n: return '转存'
    if '缺集' in n: return '缺集'
    if ('追新' in n) or ('追新' in n): return '追新'
    if '测试' in n: return '测试'
    return '普通'

def _ssort_parse(rules_txt):
    """解析规则表文本 → {(组,类别,类型): 序}。行格式：组:类别|类型=序（空格分隔多条）"""
    out = {}
    for ln in (rules_txt or '').strip().splitlines():
        ln = ln.strip()
        if not ln or ln.startswith('#'):
            continue
        for part in ln.replace('，', ',').split():
            try:
                lhs, num = part.split('=')
                grp, rest = lhs.split(':', 1)
                cat, tt = rest.split('|', 1)
                out[(grp.strip(), cat.strip(), tt.strip())] = int(num)
            except Exception:
                continue
    return out

def _ssort_rules():
    return _ssort_parse(SSORT_RULES_TXT)

def _ssort_key(t, rules):
    name = t.get('name') or ''
    grp = _ssort_group(name)
    order = {'PT': 0, '未识别': 1, 'MT': 2, 'RT': 3, '115大包': 4, '专属': 5, '其他': 6}
    base = order.get(grp, 9) * 10000
    cat = _ssort_cat(name)
    tt = 'skip' if (t.get('transferType') or '').startswith('skip') else 'move'
    r = rules.get((grp, cat, 'move'), rules.get((grp, cat, tt), 900))
    r = r + (0.5 if tt == 'skip' else 0)
    return (base + r, int(t.get('id') or 0))


def _ssort_current_jobs():
    """全部整理方案 + 真实运行态（config.enabled 才是开关真值）"""
    jobs = tasks()
    try:
        with db() as c:
            raw = {r['key']: json.loads(r['config']) for r in
                   c.execute("SELECT key,config FROM scheduled_jobs WHERE type='organize'")}
    except Exception:
        raw = {}
    for t in jobs:
        rj = raw.get(t.get('_key')) or {}
        t['transferType'] = rj.get('transferType') or t.get('transferType') or ''
        try:
            t['_running'] = rj.get('realtimeMode') == 'polling' and bool(rj.get('enabled'))
        except Exception:
            t['_running'] = False
    return jobs

def ssort_list():
    """排序方案列表 + 默认规则 + 各方案当前状态"""
    d = pri_cfg()
    schemes = d.get('ssort_schemes') or {}
    builtin = {k: {'name': v, 'builtin': True} for k, v in SSORT_BUILTIN.items()}
    merged = dict(builtin)
    for k, v in schemes.items():
        if k not in merged and isinstance(v, dict):
            merged[k] = {'name': v.get('name') or k, 'builtin': False}
    jobs = _ssort_current_jobs()
    rules = _ssort_rules()
    order_map = {t.get('_key'): _ssort_key(t, rules)[0] for t in jobs}
    manual_keys = d.get('order') or []
    return {'ok': True,
            'schemes': merged,
            'default_scheme': d.get('ssort_default') or 'default',
            'active_scheme': d.get('ssort_active') or d.get('ssort_default') or 'default',
            'default_rules': SSORT_RULES_TXT.strip(),
            'jobs': [{'key': t.get('_key'), 'id': t.get('id'), 'name': t.get('name'),
                      'tt': t.get('transferType'), 'grp': _ssort_group(t.get('name')),
                      'cat': _ssort_cat(t.get('name')),
                      'running': bool(t.get('_running')),
                      'def_pos': order_map.get(t.get('_key')),
                      'man_pos': (manual_keys.index(t.get('_key')) + 1
                                  if t.get('_key') in manual_keys else 9999)}
                     for t in jobs]}

def ssort_apply(sname):
    """把某排序方案写进 MT 的 sortOrder（停→改→checkpoint→回读→启）"""
    d = pri_cfg()
    schemes = d.get('ssort_schemes') or {}
    rules = SSORT_RULES_TXT.strip()
    if sname in schemes and isinstance(schemes[sname], dict):
        rules = schemes[sname].get('rules') or rules
    jobs = _ssort_current_jobs()

    def keyf(t):
        if sname == 'manual':
            order = d.get('order') or []
            k = t.get('_key')
            return (order.index(k) if k in order else 9999, int(t.get('id') or 0))
        if sname == 'default' or (sname in schemes and rules == SSORT_RULES_TXT.strip()):
            return _ssort_key(t, _ssort_rules())
        try:
            rr = {}
            for ln in rules.splitlines():
                ln = ln.strip()
                if not ln or ln.startswith('#'):
                    continue
                for part in ln.split():
                    lhs, num = part.split('=')
                    g, ct, tt = lhs.split(':')
                    rr[(g, ct, tt)] = int(num)
            return _ssort_key(t, rr)
        except Exception:
            return _ssort_key(t, _ssort_rules())

    ordered = sorted(jobs, key=keyf)
    pos = {t.get('_key'): i + 1 for i, t in enumerate(ordered)}
    if sname == 'default':
        pri_save({'ssort_active': sname})

    def mut(k, j):
        np = pos.get(k)
        if np is None:
            return False, None
        cur = j.get('sortOrder')
        if cur == np:
            return False, None
        j['sortOrder'] = np
        return True, 'sortOrder=%s→%s' % (cur, np)

    n, notes, ok, st = _write_jobs(mut)
    if sname != 'default' and ok:
        pri_save({'ssort_active': sname})
    _cache_drop('priority'); _cache_drop('mt')
    return {'ok': bool(ok), 'msg': ('已按「%s」排序 %d 项' % (sname, n)) if ok else st,
            'changed': notes[:30]}

def ssort_save(name, rules, as_default=False):
    """保存/更新自定义排序方案；rules 为空=克隆默认规则模板"""
    if not name or name in SSORT_BUILTIN:
        return {'ok': False, 'msg': '方案名不能为空且不能与内置重名'}
    d = pri_cfg()
    schemes = d.get('ssort_schemes') or {}
    schemes[name] = {'name': name, 'rules': rules or SSORT_RULES_TXT.strip()}
    patch = {'ssort_schemes': schemes}
    if as_default:
        patch['ssort_default'] = name
    pri_save(patch)
    return {'ok': True, 'msg': ('方案「%s」已保存%s' % (name, '（并设为默认）' if as_default else ''))}

def ssort_delete(name):
    if name in SSORT_BUILTIN:
        return {'ok': False, 'msg': '内置方案不可删除'}
    d = pri_cfg()
    schemes = d.get('ssort_schemes') or {}
    if name not in schemes:
        return {'ok': False, 'msg': '方案不存在'}
    schemes.pop(name, None)
    patch = {'ssort_schemes': schemes}
    if d.get('ssort_default') == name:
        patch['ssort_default'] = 'default'
    if d.get('ssort_active') == name:
        patch['ssort_active'] = 'default'
    pri_save(patch)
    return {'ok': True, 'msg': '方案「%s」已删除' % name}

def ssort_set_default(name):
    d = pri_cfg()
    if name not in SSORT_BUILTIN and name not in (d.get('ssort_schemes') or {}):
        return {'ok': False, 'msg': '方案不存在'}
    pri_save({'ssort_default': name})
    return {'ok': True, 'msg': '默认排序方案已设为「%s」' % name}


def pri_status():
    """Web 面板数据：全部方案（带优先级序号/角色）+ 引擎状态。"""
    d = pri_cfg()
    jobs = tasks()
    jobs.sort(key=_job_sort_key)
    items = []
    for i, t in enumerate(jobs):
        items.append({
            'key': t.get('_key'), 'id': t.get('id'), 'name': t.get('name'),
            'sourceDir': t.get('sourceDir'),
            'enabled': bool(t.get('enabled')),
            'transferType': t.get('transferType') or '',
            'realtimeMode': t.get('realtimeMode') or '',
            'wish': _is_wish_job(t),
            'prio': i + 1,
        })
    return {'ok': True, 'cfg': {k: d.get(k) for k in
                                ('on', 'check_interval', 'idle_rounds',
                                 'preempted', 'idle_cnt', 'last_pending',
                                 'last_msg', 'last_ts')},
            'saved_n': len(d.get('saved') or []),
            'wish_jobs': [x['name'] for x in items if x['wish']],
            'items': items}


def _pri_apply_preempt():
    """执行抢占：停掉全部「非求片」启用方案，确保求片方案全部启用。
    一次 _write_jobs 批量完成（停 MT→改→校验→启动）。"""
    jobs = tasks()
    wish_keys = [t['_key'] for t in jobs if _is_wish_job(t)]
    if not wish_keys:
        return {'ok': False, 'msg': '没有求片整理方案（PT/求片 未建方案），不抢占'}
    to_off = [t['_key'] for t in jobs
              if _is_wish_job(t) is False and t.get('enabled')]
    to_on = [t['_key'] for t in jobs if _is_wish_job(t) and not t.get('enabled')]

    def mut(k, j):
        if k in to_off:
            j['enabled'] = False
            return True, '暂停 ' + str(j.get('name') or k)[:18]
        if k in to_on:
            j['enabled'] = True
            return True, '启用求片方案 ' + str(j.get('name') or k)[:18]
        return False, None
    n, notes, okv, _ = _write_jobs(mut)
    if not okv:
        return {'ok': False, 'msg': '抢占写库校验未过：%s' % '；'.join(notes[-2:])[:200]}
    pri_save({'preempted': True, 'saved': to_off, 'idle_cnt': 0,
              'last_msg': '抢占：%d 个方案暂停，求片方案顶到前台' % len(to_off),
              'last_ts': int(time.time())})
    return {'ok': True, 'msg': '已抢占（暂停 %d 个方案）' % len(to_off),
            'detail': notes}


def _pri_apply_release(reason='求片队列已清空'):
    """恢复：把抢占快照里的方案重新启用（走 _write_jobs 全套校验）。"""
    d = pri_cfg()
    saved = d.get('saved') or []
    if not saved:
        pri_save({'preempted': False, 'idle_cnt': 0,
                  'last_msg': '无快照，直接复位'})
        return {'ok': True, 'msg': '无需恢复（无快照）'}
    # 只恢复「现在仍是停用」的，别动用户在抢占期间手动改过的
    cur = {t['_key']: bool(t.get('enabled')) for t in tasks()}
    to_on = [k for k in saved if not cur.get(k)]

    def mut(k, j):
        if k in to_on:
            j['enabled'] = True
            return True, '恢复 ' + str(j.get('name') or k)[:18]
        return False, None
    if to_on:
        n, notes, okv, _ = _write_jobs(mut)
        if not okv:
            return {'ok': False, 'msg': '恢复写库校验未过：%s' % '；'.join(notes[-2:])[:200]}
    pri_save({'preempted': False, 'saved': [], 'idle_cnt': 0,
              'last_msg': '恢复：%s（%d 个方案）' % (reason, len(to_on)),
              'last_ts': int(time.time())})
    return {'ok': True, 'msg': '已恢复 %d 个方案（%s）' % (len(to_on), reason)}


def pri_tick():
    """引擎单轮：检测求片队列 → 抢占 / 计数 / 到期恢复。带锁防并发。"""
    if not PRI_LOCK.acquire(blocking=False):
        return
    try:
        d = pri_cfg()
        if not d.get('on'):
            if d.get('preempted'):
                _pri_apply_release('引擎被手动关闭，自动恢复')
            return
        n = wish_pending_count()
        if n > 0:
            pri_save({'idle_cnt': 0, 'last_pending': int(time.time())})
            if not d.get('preempted'):
                r = _pri_apply_preempt()
                if r.get('ok'):
                    oplog('priority', 'preempt', '求片抢占：待整理 %d 个文件' % n,
                          True, r.get('msg'))
        else:
            if d.get('preempted'):
                cnt = int(d.get('idle_cnt') or 0) + 1
                pri_save({'idle_cnt': cnt})
                if cnt >= int(d.get('idle_rounds') or 3):
                    r = _pri_apply_release()
                    if r.get('ok'):
                        oplog('priority', 'release', '求片清空自动恢复', True,
                              r.get('msg'))
    except Exception as e:
        logger.warning('priority tick 异常: %s', e)
    finally:
        PRI_LOCK.release()


def _pri_loop():
    """后台守护：按 check_interval 跑 pri_tick（空闲时零开销）。"""
    time.sleep(45)
    while True:
        try:
            pri_tick()
        except Exception as e:
            logger.warning('priority 循环异常: %s', e)
        try:
            iv = int(pri_cfg().get('check_interval') or 60)
        except Exception:
            iv = 60
        time.sleep(max(20, iv))


def task_set(key, field, val):
    def mut(k, j):
        if k != key:
            return False, None
        old = j.get(field)
        if old == val:
            return False, '%s 已是 %s，无需修改' % (field, val)
        j[field] = val
        return True, '%s：%s → %s' % (field, old, val)
    n, notes, okv, _ = _write_jobs(mut)
    return {'ok': okv, 'msg': ('；'.join(notes) if notes else '%s 无变化' % key),
            'detail': '\n'.join(notes)}


def task_bulk(field, val, only_enabled=False):
    def mut(k, j):
        if only_enabled and not j.get('enabled'):
            return False, None
        if j.get(field) == val:
            return False, None
        j[field] = val
        return True, None
    n, notes, okv, _ = _write_jobs(mut)
    return {'ok': okv, 'msg': '已修改 %d 个任务的 %s 为 %s' % (n, field, val),
            'detail': '\n'.join(notes)}


def reuse_off_all():
    def mut(k, j):
        if not any(j.get(x) is True for x in REUSE_OFF):
            return False, None
        j.update(REUSE_OFF)
        return True, None
    n, notes, okv, _ = _write_jobs(mut)
    return {'ok': okv, 'msg': '已关闭 %d 个任务的探测复用（probeCache / cacheMetadata / destProbeCache）' % n,
            'detail': '\n'.join(notes)}


def task_del(key, force=False):
    """删除一个整理方案。

    安全约束：
      - 默认拒绝删除处于启用态的方案（需先停用），force=True 可强制。
      - 只删除 scheduled_jobs 中 type='organize' 且 key 精确匹配的行。
    严格顺序：停 MediaTidy → 备份 → 删除 → checkpoint → 回读校验 → 启动 MediaTidy。
    """
    L = []
    if not key:
        return {'ok': False, 'msg': '缺少 key'}
    with LOCK:
        with db() as c:
            row = c.execute("SELECT key,name,enabled,config FROM scheduled_jobs WHERE key=? AND type='organize'",
                            (key,)).fetchone()
        if not row:
            return {'ok': False, 'msg': '方案 %s 不存在' % key}
        # 「启用态」看 config.enabled（enabled 列是 MT 的 cron 开关，实时方案恒为 0，
        # 拿它判断会把所有 MT 自建方案都当成「已停用」而放行删除——安全漏洞）。
        try:
            _en = bool(json.loads(row['config'] or '{}').get('enabled'))
        except Exception:
            _en = bool(row['enabled'])
        if _en and not force:
            return {'ok': False, 'msg': '方案 %s「%s」处于启用态，请先停用后再删除' % (key, row['name'])}

        L.append('① 停止 MediaTidy…')
        r = db_stop_mt()
        L.append('   %s' % r.get('msg'))
        time.sleep(1.2)

        L.append('② 备份数据库')
        bak = '/data/mediatidy.db.bak_del_%s' % time.strftime('%Y%m%d-%H%M%S')
        try:
            shutil.copy2(DB, bak)
            L.append('   → %s' % os.path.basename(bak))
        except Exception as e:
            L.append('   备份失败（继续）：%s' % e)

        L.append('③ 删除方案 %s' % key)
        try:
            with db() as c:
                n = c.execute("DELETE FROM scheduled_jobs WHERE key=? AND type='organize'", (key,)).rowcount
                c.commit()
                ic = c.execute('PRAGMA integrity_check').fetchone()[0]
            L.append('   影响行数 %d，integrity=%s' % (n, ic))
        except Exception as e:
            L.append('   删除失败：%s' % e)
            db_start_mt()
            return {'ok': False, 'msg': '删除失败：%s' % e, 'detail': '\n'.join(L)}

        L.append('④ WAL checkpoint 并回读校验')
        db_flush()
        try:
            with db() as c:
                still = c.execute("SELECT key FROM scheduled_jobs WHERE key=?", (key,)).fetchone()
            if still:
                L.append('   ✗ %s 仍存在！' % key)
                gone = False
            else:
                L.append('   ✓ %s 已删除' % key)
                gone = True
        except Exception as e:
            L.append('   回读异常：%s' % e)
            gone = False

        try:
            shutil.chown(DB, 0, 0)
            for f in (DB + '-wal', DB + '-shm'):
                if os.path.exists(f):
                    shutil.chown(f, 0, 0)
        except Exception:
            pass

        L.append('⑤ 启动 MediaTidy…')
        r = db_start_mt()
        L.append('   %s' % r.get('msg'))

        return {'ok': gone,
                'msg': ('已删除方案 %s「%s」' % (key, row['name'])) if gone else ('方案 %s 未被删除，请检查' % key),
                'detail': '\n'.join(L),
                'data': {'key': key, 'name': row['name']}}


def _logged_task_del(key, force=False):
    r = task_del(key, force)
    oplog(key, 'del', '任务 %s · 删除' % key, r.get('ok'), r.get('msg'), r.get('detail'))
    return r


def do_unblock():
    with LOCK:
        rows = []
        try:
            with db() as c:
                rows = [dict(r) for r in c.execute(
                    "SELECT id,profile_id FROM organize_tasks WHERE status='running' "
                    "AND IFNULL(total_files,0)=0 AND IFNULL(done_files,0)=0")]
        except Exception as e:
            return {'ok': False, 'msg': '读取任务失败：%s' % e}
        if not rows:
            return {'ok': False, 'msg': '没有零进度的 running 任务，队列无需疏通'}

        L = ['① 停止 MediaTidy…', '   %s' % db_stop_mt().get('msg')]
        time.sleep(1.2)
        try:
            shutil.copy2(DB, '/data/mediatidy.db.bak_%s' % time.strftime('%Y%m%d-%H%M%S'))
            L.append('② 已备份数据库')
        except Exception as e:
            L.append('② 备份失败（继续）：%s' % e)
        ids = [r['id'] for r in rows]
        try:
            with db() as c:
                c.execute("UPDATE organize_tasks SET status='cancelled' WHERE id IN (%s)"
                          % ','.join('?' * len(ids)), ids)
                c.commit()
                ic = c.execute('PRAGMA integrity_check').fetchone()[0]
                left = c.execute("SELECT count(*) FROM organize_tasks WHERE status='running' "
                                 "AND IFNULL(total_files,0)=0 AND IFNULL(done_files,0)=0").fetchone()[0]
                L.append('③ 已取消 %s' % ', '.join('#%d' % i for i in ids))
                L.append('   复查剩余零进度任务：%d，integrity=%s' % (left, ic))
        except Exception as e:
            db_start_mt()
            return {'ok': False, 'msg': '取消任务失败：%s' % e}
        db_flush()
        try:
            shutil.chown(DB, 0, 0)
            for f in (DB + '-wal', DB + '-shm'):
                if os.path.exists(f):
                    shutil.chown(f, 0, 0)
        except Exception:
            pass
        L.append('④ 启动 MediaTidy…')
        L.append('   %s' % db_start_mt().get('msg'))
        return {'ok': True,
                'msg': '已取消卡死任务 %s，队列已释放' % ', '.join('#%d' % i for i in ids),
                'detail': '\n'.join(L)}


# ══════════════════════ 115 目录接入 ══════════════════════
def pick_unrec(rel, used):
    """未识别目录映射：严格复刻 RT离线 任务模板（organize:356）的目录规范。

    模板实证：RT离线 sourceDir=/主号/待整理/RT/RT离线
            → unrecognizedDir=/主号/未识别/未识别-RT/未识别-RT离线
    同族任务全部符合「源路径每级加『未识别-』前缀、平移到未识别根目录」：
      RT/RT追新 → 未识别-RT/未识别-RT追新   （organize:71）
      RT/RT缺集 → 未识别-RT/未识别-RT缺集   （organize:77）
      RT/RT转存 → 未识别-RT/未识别-RT转存   （organize:353）
      chen/ISO  → 未识别-chen/未识别-ISO    （organize:279）

    旧版把二级路径整条连写（RT/RT离线 → 未识别-RT/未识别-RT-RT离线），
    与模板规范不符，导致未识别文件落错目录，已按上式修正。
    """
    parts = [x for x in (rel or '').split('/') if x]
    if not parts:
        base = UNREC_ROOT
    else:
        base = UNREC_ROOT + '/' + '/'.join('未识别-%s' % p for p in parts)
    if base not in used:
        return base
    n = 2
    while '%s-%d' % (base, n) in used:
        n += 1
    return '%s-%d' % (base, n)


def coverage():
    en, dis, un = set(), set(), set()
    for t in tasks():
        sd = (t.get('sourceDir') or '').rstrip('/')
        if sd:
            (en if t.get('enabled') else dis).add(sd)
        if t.get('unrecognizedDir'):
            un.add(t['unrecognizedDir'].rstrip('/'))
    return en, dis, un


def tree(path=''):
    """列目录（CD2 优先，失败回退 FUSE）。

    2026-11-02 提速：原实现用 FUSE os.listdir，并且对每个子目录再 listdir 数条目，
    115 网络盘上「1 次父目录 + N 次子目录」要 10s+，用户看到的就是「加载很慢 / 加载失败」。
    现在改为一次 CD2 GetSubFiles（带 90s 内存缓存）：
      · 第一次 1~3s，之后同目录 0.03s；
      · 子目录条目数不再逐个 stat，统一给 -1（前端显示「—」）——
        点进去自然能看到内容，没必要在列表页付这个代价。
    """
    p = (path or '').strip() or V_PREFIX.rstrip('/')
    en, dis, un = coverage()
    items = []
    files = None
    try:
        files = cd2_subfiles(_cd2_path(host_of(p)))
    except Exception:
        files = None
    if files is not None:
        for it in files:
            nm = str(it.get('name') or '').strip()
            if not nm or nm.startswith('.'):
                continue
            isd = bool(it.get('dir'))
            vp = (p.rstrip('/') + '/' + nm) if p != '/' else '/' + nm
            own = None
            for s in (en | dis):
                if vp == s or vp.startswith(s + '/') or s.startswith(vp + '/'):
                    own = {'key': s,
                           'mode': ('self' if vp == s else
                                    ('inside' if vp.startswith(s + '/') else 'parent')),
                           'enabled': s in en}
                    break
            items.append({'name': nm, 'path': vp, 'dir': isd, 'count': -1,
                          'covered': own,
                          'can_add': isd and vp.startswith(V_PREFIX) and not own})
        items.sort(key=lambda x: x['name'])
        return {'path': p, 'exists': True, 'items': items, 'src': 'cd2'}
    # ── CD2 不可用：回退 FUSE（慢，但功能不瘫）──
    ar = host_of(p)
    if not os.path.isdir(ar):
        return {'path': p, 'exists': False, 'items': []}
    try:
        names = sorted(os.listdir(ar))
    except Exception as e:
        return {'path': p, 'exists': True, 'error': str(e), 'items': []}
    for n in names[:500]:
        ap = os.path.join(ar, n)
        vp = (p.rstrip('/') + '/' + n) if p else '/' + n
        isd = os.path.isdir(ap)
        cnt = -1
        if isd:
            try:
                cnt = len(os.listdir(ap))
            except Exception:
                cnt = -1
        own = None
        for s in (en | dis):
            if vp == s or vp.startswith(s + '/') or s.startswith(vp + '/'):
                own = {'key': s, 'mode': ('self' if vp == s else ('inside' if vp.startswith(s + '/') else 'parent')),
                       'enabled': s in en}
                break
        items.append({'name': n, 'path': vp, 'dir': isd, 'count': cnt, 'covered': own,
                      'can_add': isd and vp.startswith(V_PREFIX) and not own})
    return {'path': p, 'exists': True, 'items': items, 'src': 'fuse'}


def inspect(path):
    ap = host_of(path)
    if not os.path.isdir(ap):
        return {'ok': False, 'reason': '目录不存在'}
    try:
        cnt = len(os.listdir(ap))
    except Exception as e:
        return {'ok': False, 'reason': '无法读取：%s' % e}
    en, dis, un = coverage()
    for s in en:
        if path == s:
            return {'ok': False, 'reason': '已被启用中的方案覆盖：%s' % s}
        if path.startswith(s + '/') or s.startswith(path + '/'):
            return {'ok': False, 'reason': '与启用中方案 %s 重叠' % s}
    if not path.startswith(V_PREFIX):
        return {'ok': False, 'reason': '只能接入 %s 下的目录' % V_PREFIX}
    rel = path[len(V_PREFIX):]
    return {'ok': True, 'count': cnt, 'rel': rel, 'unrecognized': pick_unrec(rel, un),
            'warn_disabled': [s for s in dis if s.startswith(path + '/') or path.startswith(s + '/')]}


def scan(depth=2, mi=1):
    root = os.path.join(MOUNT, VROOT)
    if not os.path.isdir(root):
        return [], [{'path': V_PREFIX.rstrip('/'), 'reason': '待整理根目录不存在'}]
    en, dis, un = coverage()
    F, S = [], []

    def hit(vp, pool):
        b = None
        for s in pool:
            if vp == s or vp.startswith(s + '/') or s.startswith(vp + '/'):
                if b is None or len(s) > len(b):
                    b = s
        return b

    def walk(ad, rel, lv):
        if lv > depth:
            return
        try:
            e = sorted(os.listdir(ad))
        except Exception as x:
            S.append({'path': rel, 'reason': str(x)})
            return
        sb = [y for y in e if os.path.isdir(os.path.join(ad, y)) and not y.startswith('.')]
        if not sb or lv == depth:
            vp = V_PREFIX + rel
            ov = hit(vp, en)
            if ov:
                S.append({'path': vp, 'reason': '已被启用中方案覆盖：%s' % ov})
                return
            if len(e) < mi:
                S.append({'path': vp, 'reason': '内容 %d 项 < 阈值 %d' % (len(e), mi)})
                return
            F.append({'path': vp, 'rel': rel, 'items': len(e), 'warn': hit(vp, dis),
                      'unrecognized': pick_unrec(rel, un)})
            return
        for s in sb:
            walk(os.path.join(ad, s), (rel + '/' + s) if rel else s, lv + 1)

    walk(root, '', 1)
    return F, S


def ensure_dir(vp):
    ap = host_of(vp)
    if os.path.isdir(ap):
        return True, '已存在'
    try:
        os.makedirs(ap, exist_ok=True)
        time.sleep(1.2)
        if os.path.isdir(ap):
            return True, '已创建'
        open(os.path.join(ap, '.keep'), 'w').close()
        time.sleep(1.2)
        ok = os.path.isdir(ap)
        try:
            os.remove(os.path.join(ap, '.keep'))
        except Exception:
            pass
        return (True, '已创建（占位落盘）') if ok else (False, '创建后未落盘')
    except Exception as e:
        return False, str(e)


def preview(paths, tpl_id=None, dest=None):
    """按「模板定义」（cfg['templates']）生成整理方案预览。模板定义可在面板编辑/新增。

    tpl_id=None/默认模板 → 单任务（默认模板 normal 半参数）
    tpl_id=任务组模板    → 普通半 + 跳过半（group 半参数 + taskGroup 关联）
    """
    # ── 解析「模板定义」：tpl_id 缺省时按 auto_cfg 的 mode 映射 ──
    if tpl_id in (None, 'normal', 'default'):
        tpl_id = 'group' if (auto_cfg().get('mode') or 'normal') == 'group' else 'default'
    defs = tpl_defs()
    td = defs.get(tpl_id) or defs.get('default')
    base_key = td.get('base') or TPL_KEY
    tpl = tpl_resolve_base(base_key)
    if tpl is None:
        # 基准模板缺失（被删/改名）：按名称找回 RT离线
        with db() as c:
            for r2 in c.execute("SELECT name,config FROM scheduled_jobs "
                                "WHERE type='organize' ORDER BY id").fetchall():
                if TPL_NAME_HINT in (r2['name'] or ''):
                    try: tpl = json.loads(r2['config'])
                    except Exception: tpl = None
                    if tpl: break
    if tpl is None:
        # 再退化为任一在跑的整理方案
        with db() as c:
            for r2 in c.execute("SELECT config FROM scheduled_jobs "
                                "WHERE type='organize' ORDER BY id").fetchall():
                try: j = json.loads(r2['config'])
                except Exception: continue
                if j.get('enabled') or (j.get('realtimeMode') or '').lower() == 'polling':
                    tpl = j; break
    if tpl is None:
        return []
    # id 必须在整个 scheduled_jobs 表内唯一，不能只按 organize 取
    with db() as c:
        mx = c.execute("SELECT max(id) FROM scheduled_jobs").fetchone()[0] or 0
        used = set()
        for r in c.execute("SELECT config FROM scheduled_jobs WHERE type='organize'"):
            try:
                j = json.loads(r[0])
                if j.get('unrecognizedDir'):
                    used.add(j['unrecognizedDir'].rstrip('/'))
            except Exception:
                pass
    out = []
    nid = mx
    for p in paths:
        # ★ v1.07 修复「建了任务但 MT 不认」：autorun 传进来的 sourceDir 是
        #   宿主机挂载路径 /CloudNAS/115open/未识别/...，而 MT 的 sourceDir 必须是
        #   云盘视角 /主号/未识别/...。老代码原样写库 → MT 里这个任务的源目录
        #   字面名叫 "CloudNAS" → 轮询永远扫不到东西 → 用户看到「任务建了但没用」。
        #   host_of 的逆操作 cloud_of 正好做这件事。
        _p_in = (p or '').strip()
        _p_cloud = cloud_of(_p_in) if _p_in.startswith(MOUNT) else _p_in
        # rel 也用云盘视角：否则 leaf 会变成
        # 「CloudNAS-115open-未识别-未识别-MT-MT转存」、unrecognizedDir 会多套三层
        # 「未识别-CloudNAS/未识别-115open/未识别-未识别」，与 RT离线 模板的规范不符。
        rel = _p_cloud[len(V_PREFIX):] if _p_cloud.startswith(V_PREFIX) else _p_cloud
        seg = [s for s in rel.split('/') if s]
        leaf = re.sub(r'[\\/:*?"<>|]+', '-', seg[-1] if seg else '').strip() or '未命名'
        # ★ 2026-10-13「分类可识别」：只用叶子命名会分不清是谁的分类
        #   （「电影-云盘影视」看不出是 PT 下载还是 RT 转存）。
        #   带上**上两级**目录名：
        #     PT/订阅/咖啡站 → 「PT-订阅-咖啡站-云盘影视」（新目录结构）
        #     PT/电影        → 「PT-电影-云盘影视」（旧结构/两层时退一级）
        #   只有一层时保持原样（RT转存 → 「RT转存-云盘影视」），不影响既有习惯。
        if len(seg) >= 3:
            pre = [re.sub(r'[\\/:*?"<>|]+', '-', s).strip() for s in seg[-3:-1]]
            pre = [s for s in pre if s]
            if pre and not leaf.startswith(pre[-1]):
                leaf = '-'.join(pre + [leaf])
        elif len(seg) == 2:
            par = re.sub(r'[\\/:*?"<>|]+', '-', seg[-2]).strip()
            if par and not leaf.startswith(par):
                leaf = '%s-%s' % (par, leaf)
        base_name = '%s-云盘影视' % leaf
        unrec = pick_unrec(rel, used)
        used.add(unrec)
        # ── 普通半（基础方案）── 每个目录一份
        nid += 1
        x = json.loads(json.dumps(tpl))
        # ★ 配置同步铁律：新建方案原样继承基准模板，仅覆盖「每个方案必然不同」的 5 字段
        #   + 模板定义里的 normal 半参数（conc/触发方式等）。其余全部来自模板，不在代码写死。
        x.update({'id': nid, 'name': base_name, 'sourceDir': _p_cloud,
                  'destDir': (dest or tpl.get('destDir') or DEST_DIR), 'unrecognizedDir': unrec})
        x.update(REUSE_OFF)
        nv = td.get('normal') or {}
        x.update({k: v for k, v in nv.items()})
        x['realtimeDelay'] = nv.get('realtimeDelay', int(tpl.get('realtimeDelay') or 60))
        x['cronEnabled'] = nv.get('cronEnabled', False)
        x['cronExpr'] = nv.get('cronExpr', '0 0 * * *')
        out.append(x)
        # ── 任务组模板：复制一份「跳过」方案，与 MT「复制方案」产物一致 ──
        #   跳过半参数 / 后缀 / taskGroup 全部取自模板定义（可在面板编辑）。
        if td.get('kind') == 'group' and td.get('skip'):
            nid += 1
            y = json.loads(json.dumps(tpl))
            y.update({'id': nid, 'name': base_name + (td.get('suffix') or ' - 跳过'),
                      'sourceDir': _p_cloud, 'destDir': (dest or tpl.get('destDir') or DEST_DIR), 'unrecognizedDir': unrec})
            y.update(REUSE_OFF)
            sv = td.get('skip') or {}
            y.update({k: v for k, v in sv.items()})
            y['realtimeDelay'] = sv.get('realtimeDelay', 60)
            y['cronEnabled'] = sv.get('cronEnabled', False)
            y['cronExpr'] = sv.get('cronExpr', '0 0 * * *')
            if td.get('taskGroup'):
                y['taskGroup'] = {'enabled': True,
                                  'name': base_name + ' - 副本',
                                  'steps': [{'profileId': nid}, {'profileId': x['id']}]}
            out.append(y)
    return out


def create(paths):
    """创建整理方案。

    严格顺序，避免与运行中的 MediaTidy 抢同一个 SQLite：
      1. 停 MediaTidy（必须在写库之前停，否则它的内存态会覆盖）
      2. 备份数据库
      3. 写库并 commit，然后 WAL checkpoint(TRUNCATE)
      4. 回读校验，确认新行真的落盘
      5. 启动 MediaTidy

    ★ v1.07 新增「按 sourceDir 查重」：autorun 每跑一轮都会调 create()，
      老实现无条件 INSERT → 同一个源目录被反复建出 organize:1102/1103/1104
      这种同名任务，MT 里堆一排重复轮询（用户看到「任务越跑越多」）。
      现在：库里已有相同 sourceDir 的 organize 方案时，**更新那一条**
      （按 RT离线 模板刷新配置）而不是新建，返回 reused=True。
    """
    L = []
    with LOCK:
        plans = preview(paths)
        if not plans:
            return {'ok': False, 'msg': '没有可创建的计划'}
        # 查重：同 sourceDir 已存在 → 只刷新配置，不新增
        _reused = []
        _fresh = []
        _verify_keys = []      # ★ v1.07：必须在外层初始化，否则查重/写库的
                               #   except 分支引用它会 UnboundLocalError
        try:
            with db() as c:
                _sd_map = {}
                for r2 in c.execute("SELECT id,key,config FROM scheduled_jobs "
                                    "WHERE type='organize'").fetchall():
                    try:
                        _j = json.loads(r2['config'])
                    except Exception:
                        continue
                    _sd = (_j.get('sourceDir') or '').rstrip('/')
                    if _sd:
                        _sd_map.setdefault(_sd, (r2['id'], r2['key']))
                for p in plans:
                    _sd = (p.get('sourceDir') or '').rstrip('/')
                    _row = _sd_map.get(_sd) if _sd else None
                    if _row:
                        _reused.append((_row[0], _row[1], p))
                    else:
                        _fresh.append(p)
        except Exception as e:
            L.append('   查重失败（按新建处理）：%s' % str(e)[:100])
            _reused, _fresh = [], plans
            _verify_keys = []
        # _verify_keys 可能已被上面的分支填充；查重失败时从这里补齐。
        if not _verify_keys:
            _verify_keys = ['organize:%d' % p['id'] for p in _fresh]
        # 兼容旧字段名（部分调用方/日志读 new_keys）
        new_keys = _verify_keys
        new_ids = [p['id'] for p in _fresh]

        L.append('① 停止 MediaTidy…')
        r = db_stop_mt()
        L.append('   %s' % r.get('msg'))
        time.sleep(1.5)

        L.append('② 备份数据库')
        bak = '/data/mediatidy.db.bak_%s' % time.strftime('%Y%m%d-%H%M%S')
        try:
            shutil.copy2(DB, bak)
            L.append('   → %s' % os.path.basename(bak))
        except Exception as e:
            L.append('   备份失败（继续）：%s' % e)

        L.append('③ 写入方案')
        # ★ v1.07：_reused 里已有同 sourceDir 的旧方案 → 走 UPDATE 刷新配置
        #   （id/key/name 不变，只按 RT离线 模板刷新其余字段），不新增行。
        #   _fresh 才走 INSERT。回读校验统一用 _verify_keys。
        try:
            with db() as c:
                nord = 0
                for row in c.execute("SELECT config FROM scheduled_jobs WHERE type='organize'"):
                    try:
                        j = json.loads(row[0])
                        if isinstance(j.get('sortOrder'), int):
                            nord = max(nord, j['sortOrder'])
                    except Exception:
                        pass
                for _rid, _rkey, _rp in _reused:
                    try:
                        c.execute(
                            "UPDATE scheduled_jobs SET name=?, config=?, "
                            "updated_at=datetime('now') WHERE id=?",
                            (_rp.get('name') or '', json.dumps(_rp, ensure_ascii=False), _rid))
                        L.append('   ↻ 已刷新已有方案 %s（%s）'
                                 % (_rkey, (_rp.get('sourceDir') or '')[:60]))
                        _verify_keys.append(_rkey)
                    except Exception as e:
                        L.append('   刷新 %s 失败：%s' % (_rkey, str(e)[:100]))
                for cf in _fresh:
                    nord += 1
                    cf['sortOrder'] = nord
                    ok, msg = ensure_dir(cf['unrecognizedDir'])
                    L.append('   未识别目录 %s：%s' % (cf['unrecognizedDir'], msg))
                    c.execute(
                        "INSERT INTO scheduled_jobs (id,key,type,name,cron_expr,enabled,config,created_at,updated_at) "
                        "VALUES (?,?,?,?,?,?,?,datetime('now'),datetime('now'))",
                        (cf['id'], 'organize:%d' % cf['id'], 'organize', cf['name'],
                         cf.get('cronExpr', '0 0 * * *'), 0,
                         json.dumps(cf, ensure_ascii=False)))
                    L.append('   ✓ 已写入 organize:%d  %s' % (cf['id'], cf['name']))
                    _verify_keys.append('organize:%d' % cf['id'])
                c.commit()
                ic = c.execute('PRAGMA integrity_check').fetchone()[0]
        except Exception as e:
            L.append('   写入失败：%s' % e)
            db_start_mt()
            return {'ok': False, 'msg': '写库失败：%s' % e, 'detail': '\n'.join(L)}

        L.append('④ WAL checkpoint 并回读校验')
        db_flush()
        got = []
        try:
            with db() as c:
                for k in _verify_keys:
                    row = c.execute("SELECT key,name,config FROM scheduled_jobs WHERE key=?", (k,)).fetchone()
                    if row:
                        j = json.loads(row['config'])
                        got.append(k)
                        L.append('   ✓ %s 存在（源 %s）' % (k, j.get('sourceDir')))
                    else:
                        L.append('   ✗ %s 未落盘！' % k)
        except Exception as e:
            L.append('   回读异常：%s' % e)

        try:
            shutil.chown(DB, 0, 0)
            for f in (DB + '-wal', DB + '-shm'):
                if os.path.exists(f):
                    shutil.chown(f, 0, 0)
        except Exception:
            pass

        L.append('⑤ 启动 MediaTidy…')
        r = db_start_mt()
        L.append('   %s' % r.get('msg'))

        okall = len(got) == len(new_keys)
        L.append('DB integrity = %s' % (ic if 'ic' in dir() else '?'))
        _reuse_n = len(_reused)
        return {'ok': okall,
                'msg': (('已创建 %d 个整理任务（其中 %d 个为刷新已有方案）：%s'
                         % (len(got), _reuse_n, ', '.join(got))) if _reuse_n
                        else ('已创建 %d 个整理任务：%s' % (len(got), ', '.join(got)))) if okall
                       else ('仅 %d/%d 个方案落盘，请检查' % (len(got), len(new_keys))),
                'detail': '\n'.join(L),
                'data': {'created': got, 'expect': new_keys,
                         'reused': _reuse_n, 'new': len(new_keys) - _reuse_n}}


# ══════════════════════ 诊断引擎 ══════════════════════
def diagnose():
    items = []

    def add(k, n, lv, d, fix=None, hint=''):
        items.append({'key': k, 'name': n, 'level': lv, 'detail': d, 'fix': fix, 'hint': hint})

    lg = tail(6000)
    try:
        with db() as c:
            rows = [dict(r) for r in c.execute(
                "SELECT id,profile_id,total_files,done_files FROM organize_tasks WHERE status='running'")]
            tstat = {r['status']: r['n'] for r in c.execute("SELECT status,count(*) n FROM organize_tasks GROUP BY status")}
    except Exception:
        rows, tstat = [], {}

    stuck = [r for r in rows if not (r['total_files'] or 0) and not (r['done_files'] or 0)]
    if stuck:
        add('stuck', '整理队列卡死', 'bad', '任务 %s running 且零进度' % ', '.join('#%d' % r['id'] for r in stuck),
            'unblock', '队头阻塞：需标记 cancelled 并重启')
    elif rows:
        add('running', '整理进行中', 'info', '任务 %s 运行中' % ', '.join(
            '#%d %s/%s' % (r['id'], r['done_files'], r['total_files']) for r in rows))
    else:
        add('running', '整理队列', 'ok', '当前无运行中任务')

    qb = sum(1 for l in lg if '任务已在队列中' in l.get('msg', ''))
    add('queue', '定时提交', 'bad' if qb else 'ok',
        '队列被占用 %d 次' % qb if qb else '无队列占用', 'unblock' if qb else None)

    d = disk_info()
    if d:
        try:
            pct = int(d['pct'].rstrip('%'))
        except Exception:
            pct = 0
        add('disk', '磁盘空间', 'bad' if pct >= 90 else ('warn' if pct >= 85 else 'ok'),
            '已用 %s，可用 %s' % (d['pct'], d['avail']), 'rotate_log' if pct >= 85 else None,
            '可强制轮转并压缩历史日志释放空间')

    lsm = run("du -sm %s|cut -f1" % LOG_DIR)
    try:
        lsm = int(lsm)
    except Exception:
        lsm = 0
    add('log', '日志占用', 'warn' if lsm > 1024 else 'ok', '%d MB' % lsm, 'rotate_log' if lsm > 1024 else None)

    lt = sum(1 for l in lg if 'license.v3_request_failed' in l.get('msg', ''))
    lr = sum(1 for l in lg if 'protected operation rejected' in l.get('msg', ''))
    if lr:
        add('license', '授权拒绝', 'bad', '受保护操作被拒 %d 次' % lr, 'check_license')
    elif lt:
        add('license', '授权校验', 'warn', '授权服务器超时 %d 次' % lt, 'check_license')
    else:
        add('license', '授权校验', 'ok', '正常')

    c2 = run("docker logs --since 15m clouddrive2 2>&1")
    n405, n403 = c2.count('405'), c2.count('403')
    add('cd2', 'CD2 限流', 'warn' if (n405 or n403) else 'ok',
        ('405=%d 403=%d' % (n405, n403)) if (n405 or n403) else '近15分钟无 405/403',
        'cd2_rate_down' if (n405 or n403) else None)

    okf = os.path.isdir(os.path.join(MOUNT, VROOT))
    add('fuse', '115 FUSE 挂载', 'ok' if okf else 'bad',
        '%s %s' % (MOUNT, '正常' if okf else '未挂载'), 'restart_cd2' if not okf else None)

    ts = tasks()
    cl = [t['_key'] for t in ts if t.get('cleanEmptyDirs')]
    ru = [t['_key'] for t in ts if any(t.get(k) is True for k in REUSE_OFF)]
    if cl:
        add('guard', '空目录清理开关', 'warn', '%d 个任务开启：%s' % (len(cl), ', '.join(cl)), 'guard_off')
    else:
        add('guard', '空目录清理开关', 'ok', '全部已关闭')
    if ru:
        add('reuse', '探测复用开关', 'warn', '%d 个任务开启：%s' % (len(ru), ', '.join(ru)), 'reuse_off')
    else:
        add('reuse', '探测复用开关', 'ok', '全部已关闭')

    zomb = tstat.get('cancelled', 0) + tstat.get('interrupted', 0)
    if zomb > 20:
        add('zombie', '僵尸任务记录', 'warn', '%d 条 cancelled/interrupted 堆积' % zomb, 'clean_zombie')
    else:
        add('zombie', '任务记录', 'ok', 'cancelled+interrupted=%d' % zomb)

    un = sum(1 for l in lg if '未识别文件（待批量转移）' in l.get('msg', ''))
    add('unrec', '未识别文件', 'warn' if un > 50 else 'info', '近段日志 %d 条' % un)

    # 容器层健康
    for key, s in containers().items():
        if key in ('emby_adult', 'flaresolverr', 'embyboss'):
            continue
        cs = ctr_state(s['cname'])
        if not cs.get('ok'):
            add('ctr_' + key, '%s 容器' % s['name'], 'bad', '容器不存在或 Docker 不可达', None)
        elif not cs.get('running'):
            add('ctr_' + key, '%s 容器' % s['name'], 'bad', '容器未运行（%s）' % cs.get('state'),
                'start_' + key, '可在容器面板一键启动')
        elif cs.get('health') == 'unhealthy':
            add('ctr_' + key, '%s 健康' % s['name'], 'warn', '健康检查未通过', 'restart_' + key)

    bad = sum(1 for i in items if i['level'] == 'bad')
    warn = sum(1 for i in items if i['level'] == 'warn')
    return {'items': items, 'task_status': tstat,
            'summary': {'bad': bad, 'warn': warn,
                        'ok': sum(1 for i in items if i['level'] == 'ok'),
                        'info': sum(1 for i in items if i['level'] == 'info')}}


def repair(a):
    _r2 = _v2_repair(a)
    if _r2 is not None:
        return _r2
    L = []
    if a == 'unblock':
        return do_unblock()
    if a in ('guard_off', 'reuse_off'):
        if a == 'guard_off':
            return task_bulk('cleanEmptyDirs', False)
        return reuse_off_all()
    if a == 'rotate_log':
        b = run("du -sm %s|cut -f1" % LOG_DIR)
        run("logrotate -f /etc/logrotate.d/mediatidy 2>/dev/null")
        return {'ok': True, 'msg': '日志 %s MB → %s MB' % (b, run("du -sm %s|cut -f1" % LOG_DIR))}
    if a == 'vacuum':
        with LOCK:
            with db() as c:
                c.execute("PRAGMA wal_checkpoint(TRUNCATE)")
                ic = c.execute('PRAGMA integrity_check').fetchone()[0]
        return {'ok': True, 'msg': 'WAL 已收缩', 'detail': 'integrity=%s' % ic}
    if a == 'clean_zombie':
        with LOCK:
            with db() as c:
                before = c.execute("SELECT count(*) FROM organize_tasks").fetchone()[0]
                c.execute("DELETE FROM organize_tasks WHERE status IN ('cancelled','interrupted') AND IFNULL(done_files,0)=0")
                c.execute("DELETE FROM strm_tasks WHERE status IN ('cancelled') AND IFNULL(done_files,0)=0")
                c.commit()
                after = c.execute("SELECT count(*) FROM organize_tasks").fetchone()[0]
                ic = c.execute('PRAGMA integrity_check').fetchone()[0]
        return {'ok': True, 'msg': '清理僵尸记录 %d → %d 条' % (before, after), 'detail': 'integrity=%s' % ic}
    if a in ('cd2_rate_down', 'cd2_rate_up'):
        v = 2.0 if a == 'cd2_rate_down' else 3.0
        cand = [CD2_CFG, '/cd2config/cloudapidata.json',
                '/vol1/1000/docker/clouddrive2/config/cloudapidata.json',
                '/dockroot/clouddrive2/config/cloudapidata.json']
        real = next((p for p in cand if os.path.exists(p)), None)
        if not real:
            return {'ok': False, 'msg': '未找到 CD2 配置文件（尝试：%s）' % ', '.join(cand[:3])}
        try:
            shutil.copy2(real, real + '.bak_%s' % time.strftime('%Y%m%d-%H%M%S'))
        except Exception:
            pass
        ctr_action('clouddrive2', 'stop')
        try:
            d = json.load(open(real, encoding='utf-8'))
        except Exception as e:
            ctr_action('clouddrive2', 'start')
            return {'ok': False, 'msg': '读取 CD2 配置失败：%s' % e}
        if isinstance(d, dict):
            d = [d]
        n = 0
        for x in d:
            if isinstance(x, dict) and isinstance(x.get('downloader_config'), dict):
                x['downloader_config']['max_queries_per_second'] = v
                n += 1
        json.dump(d, open(real, 'w', encoding='utf-8'), ensure_ascii=False, indent=2)
        r = ctr_action('clouddrive2', 'start')
        return {'ok': r['ok'], 'msg': 'CD2 max_queries_per_second → %s（%d 处），已%s，约 10 秒后生效' % (
            v, n, '重启' if r['ok'] else '启动失败'),
            'detail': 'file=%s\n%s' % (real, r.get('msg', ''))}
    if a == 'cd2_cache':
        r = ctr_action('clouddrive2', 'restart')
        return {'ok': r['ok'], 'msg': 'CloudDrive2 已重启，目录缓存已释放' if r['ok'] else r['msg']}
    if a == 'check_license':
        code = run("curl -s -m 8 -o /dev/null -w '%{http_code}' https://api.mediatidy.io 2>/dev/null").strip()
        px = run("docker exec mediatidy env 2>/dev/null | grep -i https_proxy").strip()
        npxy = run("docker exec mediatidy env 2>/dev/null | grep -i no_proxy").strip()
        ok = code.isdigit() and int(code) > 0
        return {'ok': True,
                'msg': '授权域名 api.mediatidy.io 探测结果 HTTP %s' % (code or '无响应'),
                'detail': '容器代理: %s\nNO_PROXY: %s\n若代理未覆盖授权域名，需在 NO_PROXY 中加入该域名' % (
                    px or '未设置', npxy or '未设置')}
    if a.startswith('restart_'):
        key = a[len('restart_'):]
        if key == 'mt':
            key = 'mediatidy'
        if key in containers():
            return ctr_action(key, 'restart')
    if a.startswith('start_'):
        key = a[len('start_'):]
        if key in containers():
            return ctr_action(key, 'start')
    return {'ok': False, 'msg': '未知修复动作：%s' % a}


# ══════════════════════ 服务深度动作（真正控制容器）══════════════════════
def emby_headers(key):
    return {'X-Emby-Token': key} if key else {}


def _emby_uid(addr, port, H):
    """★ v6 取第一个用户 ID。Emby 的 /Items 必须带 UserId 才返回条目与封面，
    只读 API Key 走 admin/首个用户即可。失败返回空串（调用方自行降级）。"""
    try:
        st, us = hget(addr, port, '/Users', H, 5)
        if st == 200 and isinstance(us, list) and us:
            for u in us:
                # ★ v1.15 BUG-122：Policy 偶尔被返回成 list → `.get` 抛
                #   'list' object has no attribute 'get'，整个 uid 探测
                #   被 except 吞掉 → 拿不到 UserId → 全站 Emby 图片/
                #   条目查询降级。必须 isinstance 判一下。
                _p = u.get('Policy')
                if isinstance(_p, dict) and _p.get('IsAdministrator'):
                    return str(u.get('Id') or '')
            return str((us[0] or {}).get('Id') or '')
    except Exception:
        pass
    return ''


# ── 库里已有查询（2026-10-13：把 bot「按集查库」能力同步到 5678）──
def _q_parse(nm):
    """从文件名/路径解析画质标签。

    ★ strm 库里 MediaSources 恒空 → 拿不到真实码率/体积，只能解析文件名。
    """
    s = (nm or '').upper()
    res = ''
    for r in ('2160P', '4K', '1080P', '720P', '480P'):
        if r in s:
            res = '4K/2160p' if r in ('2160P', '4K') else r.lower()
            break
    src = ''
    for k, v in (('REMUX', 'REMUX'), ('BLURAY', 'BluRay'), ('BLU-RAY', 'BluRay'),
                 ('BDRIP', 'BDRip'), ('WEB-DL', 'WEB-DL'), ('WEBDL', 'WEB-DL'),
                 ('WEBRIP', 'WEBRip'), ('HDTV', 'HDTV'), ('HDRIP', 'HDRip'),
                 ('DVD', 'DVD')):
        if k in s:
            src = v
            break
    codec = ''
    for k, v in (('X265', 'x265'), ('H265', 'x265'), ('HEVC', 'x265'),
                 ('X264', 'x264'), ('H264', 'x264'), ('AVC', 'x264'), ('AV1', 'AV1')):
        if k in s:
            codec = v
            break
    hdr = 'HDR' if ('HDR' in s or ' DV ' in s) else ''
    return {'res': res, 'src': src, 'codec': codec, 'hdr': hdr,
            'quals': ' '.join(x for x in (res, src, codec, hdr) if x) or '—'}


def _emby_eps_sample(conf, key, series_id, season=0, limit=40):
    """取某剧（或某季）下的集样本，用来解析画质（画质写在集的文件名上）"""
    if not series_id:
        return []
    parent = series_id
    if season:
        p = ('/emby/Items?ParentId=%s&IncludeItemTypes=Season&Recursive=true'
             '&Fields=IndexNumber' % series_id)
        _st, b = hget(conf['addr'], conf['port'], p, emby_headers(key), 10)
        sid = ''
        for s in (((b or {}).get('Items') or []) if isinstance(b, dict) else []):
            try:
                if int(s.get('IndexNumber') or -1) == int(season):
                    sid = str(s.get('Id') or '')
                    break
            except Exception:
                continue
        if not sid:
            return []
        parent = sid
    p = ('/emby/Items?ParentId=%s&IncludeItemTypes=Episode&Recursive=true'
         '&Limit=%d&Fields=Path,FileName,IndexNumber,ParentIndexNumber'
         % (parent, int(limit)))
    _st, b = hget(conf['addr'], conf['port'], p, emby_headers(key), 12)
    return ((b or {}).get('Items') or []) if isinstance(b, dict) else []


def libcheck(title, season=0, tmdb=''):
    """查 Emby 库里有没有这部片/剧，带画质标签。

    ★ 剧集（Series）：画质只写在**集的文件名**上，剧集文件夹名里没有，
      所以要下钻到集（可按 season 指定季）采样解析，再聚合成画质标签。
    """
    import urllib.parse as _up
    c = cfg()
    key = c.get('emby_key', '')
    if not key:
        return {'ok': False, 'msg': '未配置 Emby API Key（设置页填 emby_key）'}
    if not str(title or '').strip():
        return {'ok': False, 'msg': '请填片名'}
    conf = containers()['emby']
    # ★ v1.15 BUG-121：先按多路搜索定位唯一条目。
    #   老实现只用一次 Emby SearchTerm；本库是 strm 库，文件夹名形如
    #   '[嫁金钗].Where.the.Mask.Ends.2026.S01.Complete.2160p.WEB-DL...'，
    #   Emby 的 SearchTerm 对中文「嫁金钗」全文匹配不到（实测返回 0 条），
    #   而英文原名又能搜回一堆无关片 → 前端 smEmbyCmp 的 items 恒为空，
    #   即用户本轮反馈的「我点击对比我EMBY库的时候，发现我EMBY库里面资源都为空」。
    hit = _emby_find_item(conf, key, str(tmdb or ''), title, orig='', year='')
    if hit:
        items = [hit]
    else:
        # 兜底：保留老 SearchTerm 路径（tmdbid 未命中、库内命名又极特殊时）
        path = ('/emby/Items?SearchTerm=%s&Recursive=true&Limit=12'
                '&IncludeItemTypes=Movie,Series'
                '&Fields=ProviderIds,ProductionYear,Path,FileName,RunTimeTicks'
                % _up.quote(str(title).strip()))
        st, b = hget(conf['addr'], conf['port'], path, emby_headers(key), 15)
        if st != 200:
            return {'ok': False, 'msg': 'Emby HTTP %s（检查 emby_key）' % st}
        items = (b or {}).get('Items') or [] if isinstance(b, dict) else []
    out = []
    all_files = []          # ★ v1.15 BUG-121：前端 smEmbyCmp 读的 files 字段
    for it in items:
        if not isinstance(it, dict):
            continue
        pid = str(((it.get('ProviderIds') or {}).get('Tmdb') or ''))
        if tmdb and pid and pid != str(tmdb):
            continue
        nm = str(it.get('Path') or it.get('FileName') or '')
        # ★★ v1.25b S7：该条目的 Emby 主图（用户原话「加上它的 TMD 封面」）
        _itag = str(it.get('ImageTags', {}).get('Primary') or '')
        _iid = str(it.get('Id') or '')
        # ★★ v1.25 BUG-169：改走 /embyimg/ 代理（api_key 不外泄）
        _pv = ('/embyimg/emby/%s/Primary?w=160' % _iid) if (_iid and _itag) else ''
        _ttype = 'tv' if it.get('Type') == 'Series' else 'movie'
        q = _q_parse(nm)
        _qd = _parse_tor_dims(nm)
        # 电影也输出 files（前端 smEpKey 对 season/episode 都为 None 的归 MOVIE）
        if it.get('Type') == 'Movie':
            d2 = _parse_tor_dims(nm)
            all_files.append({
                'name': nm.replace('\\', '/').rsplit('/', 1)[-1][:120],
                'path': nm.replace('\\', '/')[:300],
                'season': None, 'episode': None,
                'quality': q.get('quals') or '',
                'pix': d2.get('pix') or '', 'src': d2.get('src') or '',
                'vcodec': d2.get('vcodec') or '', 'hdr': d2.get('hdr') or '',
                'bitrate_mbps': d2.get('bitrate_mbps'),
                'size': _est_strm_size(nm, it), 'est': True,
                'size_txt': psz2(_est_strm_size(nm, it)),
                'pv': _pv, 'tmdb': pid, 'tmdb_type': _ttype,
                'dv': _norm_dv(d2.get('hdr'), d2.get('dv_profile')),
                'audio': (d2.get('acodec') or '') + ((' ' + d2.get('achan')) if d2.get('achan') else ''),
                'fps': d2.get('fps') or '',
                'bitrate_txt': _norm_bitrate_mbps(d2.get('bitrate_mbps')),
            })
        if it.get('Type') == 'Series':
            eps = _emby_eps_sample(conf, key, str(it.get('Id') or ''),
                                   int(season or 0), 40)
            tally = {}
            for e in eps:
                qq = _q_parse(str(e.get('Path') or e.get('FileName') or ''))
                if qq['quals'] != '—':
                    tally[qq['quals']] = tally.get(qq['quals'], 0) + 1
            if tally:
                top = sorted(tally.items(), key=lambda kv: -kv[1])
                q['quals'] = ' ／ '.join(k for k, _v in top[:3])
                seg = str(top[0][0]).split()
                q['res'] = seg[0] if seg else ''
                q['src'] = seg[1] if len(seg) > 1 else ''
                q['codec'] = seg[2] if len(seg) > 2 else ''
            # ★ v1.15 BUG-121：把「集」也输出成 files，前端才能逐集左右对照
            #   （smEmbyCmp 按 SxxExx 归组，season/episode 缺一个都会掉出对照表）
            for e in eps:
                if not isinstance(e, dict):
                    continue
                enm = str(e.get('Path') or e.get('FileName') or '')
                if not enm:
                    continue
                eq = _q_parse(enm)
                d3 = _parse_tor_dims(enm)
                all_files.append({
                    'name': enm.replace('\\', '/').rsplit('/', 1)[-1][:120],
                    'path': enm.replace('\\', '/')[:300],
                    'season': e.get('ParentIndexNumber'),
                    'episode': e.get('IndexNumber'),
                    'quality': eq.get('quals') or '',
                    'pix': d3.get('pix') or '', 'src': d3.get('src') or '',
                    'vcodec': d3.get('vcodec') or '', 'hdr': d3.get('hdr') or '',
                    'bitrate_mbps': d3.get('bitrate_mbps'),
                    # strm 库 Emby 不给真实体积 → 与 discover_better 同口径估算
                    'size': _est_strm_size(enm, e), 'est': True,
                    'size_txt': psz2(_est_strm_size(enm, e)),
                    'pv': _pv, 'tmdb': pid, 'tmdb_type': _ttype,
                    'dv': _norm_dv(d3.get('hdr'), d3.get('dv_profile')),
                    'audio': (d3.get('acodec') or '') + ((' ' + d3.get('achan')) if d3.get('achan') else ''),
                    'fps': d3.get('fps') or '',
                    'bitrate_txt': _norm_bitrate_mbps(d3.get('bitrate_mbps')),
                })
        out.append({'name': it.get('Name'), 'year': it.get('ProductionYear') or '',
                    'type': it.get('Type'), 'tmdb': pid,
                    'quals': q['quals'], 'res': q['res'], 'src': q['src'],
                    'codec': q['codec'], 'hdr': q['hdr'],
                    'pv': _pv,
                    'dv': _norm_dv(_qd.get('hdr'), _qd.get('dv_profile')),
                    'audio': (_qd.get('acodec') or '') + ((' ' + _qd.get('achan')) if _qd.get('achan') else ''),
                    'file': nm.replace('\\', '/').rsplit('/', 1)[-1][:90],
                    'path': nm.replace('\\', '/')[:300]})
    # ★ v1.15 BUG-121：files 字段（前端 smEmbyCmp 读它做左右逐集对照）
    #   只增不减：items/note 原样保留，旧调用方不破。
    _tot = sum(int(f.get('size') or 0) for f in all_files)
    return {'ok': True, 'items': out, 'n': len(out),
            'files': all_files,
            'files_total': len(all_files),
            'total_size': _tot,
            'total_size_txt': psz2(_tot),
            'found': bool(all_files),
            'note': 'strm 库无体积/码率（Emby MediaSources 为空），'
                    '画质按文件名解析；体积为码率 x 时长估算（est=true）'}


def _est_strm_size(fname, item=None):
    """★ v1.15 BUG-121：strm 库估算文件体积（Emby 不给 MediaSources.Size）。

    口径与 discover_better 完全一致：文件名码率(Mbps) x RunTimeTicks。
    这样「PT 资源体积 vs 库内体积」才是同口径可比。
    """
    try:
        d = _parse_tor_dims(fname)
        br = d.get('bitrate_mbps')
        rt = 0
        if isinstance(item, dict):
            try:
                rt = int(item.get('RunTimeTicks') or 0)
            except Exception:
                rt = 0
        if not br or rt <= 0:
            return 0
        # ticks: 1s = 10^7 ticks；Mbps -> bytes/s = Mbps*1e6/8
        return int(br * 1e6 / 8.0 * (rt / 10000000.0))
    except Exception:
        return 0


