def _gap_local_eps(series_id):
    """②-b 本地取该剧每一季实际拥有的集号（纯 Emby，零 TMDB 调用）。

    返回 {season_number:set(episode_number)}；拿不到返回 {}。
    """
    if not series_id:
        return {}
    conf = containers()['emby']
    key = (cfg().get('emby_key') or EMBY_KEY_FB)
    H = emby_headers(key)
    out = {}
    try:
        st, b = hget(conf['addr'], conf['port'],
                     '/emby/Items?ParentId=%s&IncludeItemTypes=Season&Recursive=false'
                     '&Fields=IndexNumber' % series_id, H, 15)
        seasons = (((b or {}).get('Items') or []) if isinstance(b, dict) else [])
        for sn in seasons:
            if not isinstance(sn, dict):
                continue
            snum = sn.get('IndexNumber')
            if snum is None:
                continue
            s2, b2 = hget(conf['addr'], conf['port'],
                          '/emby/Items?ParentId=%s&IncludeItemTypes=Episode&Recursive=false'
                          '&Limit=400&Fields=IndexNumber,ParentIndexNumber'
                          % str(sn.get('Id') or ''), H, 15)
            eps = (((b2 or {}).get('Items') or []) if isinstance(b2, dict) else [])
            have = set()
            for e in eps:
                if not isinstance(e, dict):
                    continue
                en = e.get('IndexNumber')
                if en is None:
                    continue
                try:
                    have.add(int(en))
                except Exception:
                    pass
            if have:
                out[int(snum)] = have
    except Exception as e:
        logger.debug('_gap_local_eps err: %s' % str(e)[:120])
    return out


_TMDB_TV_CACHE = {}


def _tmdb_tv_full(tid, ttl=1800):
    """TMDB 剧集权威季/集清单（带 30 分钟缓存，全库扫时不重复打 TMDB）。"""
    k = tmdb_key()
    if not k:
        return None
    ck = str(tid)
    now = time.time()
    if ck in _TMDB_TV_CACHE and now - _TMDB_TV_CACHE[ck][0] < ttl:
        return _TMDB_TV_CACHE[ck][1]
    j = _tmdb_get('https://api.themoviedb.org/3/tv/%s?api_key=%s&language=zh-CN'
                  % (ck, k), t=18)
    if not isinstance(j, dict) or j.get('__err'):
        return None
    seasons = {}
    for s in (j.get('seasons') or []):
        if not isinstance(s, dict):
            continue
        snum = s.get('season_number')
        if snum is None:
            continue
        sj = _tmdb_get('https://api.themoviedb.org/3/tv/%s/season/%d?api_key=%s&language=zh-CN'
                       % (ck, int(snum), k), t=18)
        eps = []
        if isinstance(sj, dict) and not sj.get('__err'):
            for e in (sj.get('episodes') or []):
                if not isinstance(e, dict):
                    continue
                en = e.get('episode_number')
                if en is None:
                    continue
                eps.append({'ep': int(en), 'name': str(e.get('name') or ''),
                            'air': str(e.get('air_date') or '')[:10]})
        seasons[int(snum)] = eps
    _TMDB_TV_CACHE[ck] = (now, seasons)
    return seasons


GAP_SCAN = {'busy': False, 'cancel': False, 'total': 0, 'done': 0, 'scanned': 0,
            'miss_shows': 0, 'miss_eps': 0, 'views': [], 'started': 0,
            'took': 0, 'rows': [], 'tmdb_miss': 0, 'tmdb_miss_rows': [],
            'finished': False, 'error': '', 'phase': ''}


def _gap_scan_one(x):
    """单部剧：本地季集 vs TMDB 权威 → 缺集行。返回 (row|None, no_tmdb|None)。"""
    tid = x.get('tmdbid') or ''
    if not tid:
        return None, x
    have_all = _gap_local_eps(x['id'])
    tmdb_all = _tmdb_tv_full(tid)
    if not tmdb_all:
        return None, x
    out_seasons = []
    miss_total = 0
    for snum in sorted(tmdb_all.keys()):
        have = have_all.get(snum) or set()
        miss = [e for e in tmdb_all[snum] if e['ep'] not in have]
        if miss:
            miss_total += len(miss)
            out_seasons.append({'season': int(snum), 'have': len(have),
                                'total': len(tmdb_all[snum]), 'missing': miss})
    if miss_total <= 0:
        return None, None
    return {'name': x.get('name') or '', 'year': x.get('year') or '',
            'tmdbid': tid, 'lib_name': x.get('name') or '',
            'lib_path': x.get('path') or '', 'vote': x.get('vote'),
            'seasons': out_seasons, 'miss_n': miss_total,
            'miss_txt': '共缺 %d 集' % miss_total, 'type': 'tv'}, None


def _gap_scan_core(views, deep, max_scan, prog, cancel_fn):
    """扫描核心（同步/后台复用）。prog 为进度 dict；cancel_fn()→bool。
    全程边扫边更新 prog（done/miss/部分 rows），前端轮询即可见进度。"""
    from concurrent.futures import as_completed
    t0 = time.time()
    prog.update({'busy': True, 'error': '', 'started': int(t0), 'done': 0,
                 'miss_shows': 0, 'miss_eps': 0, 'rows': [], 'scanned': 0,
                 'tmdb_miss': 0, 'finished': False, 'views': list(views or []),
                 'phase': 'listing'})
    try:
        if not tmdb_key():
            prog.update({'error': '未取到 TMDB key（设置页填 tmdb_key_user）',
                         'busy': False, 'finished': True, 'phase': 'error'})
            return False
        series = _gap_lib_series(views)
        series = series[:int(max_scan or 500)]
        prog['total'] = len(series)
        prog['phase'] = 'scanning'
        rows, no_tmdb = [], []
        with ThreadPoolExecutor(max_workers=8) as ex:
            futs = [ex.submit(_gap_scan_one, x) for x in series]
            for fu in as_completed(futs):
                try:
                    if cancel_fn():
                        for f in futs:
                            f.cancel()
                        prog.update({'error': '已取消', 'busy': False,
                                     'finished': True, 'phase': 'cancelled'})
                        return False
                    row, nt = fu.result()
                    prog['done'] += 1
                    if row:
                        rows.append(row)
                        prog['rows'] = sorted(rows, key=lambda z: -z['miss_n'])[:600]
                        prog['miss_shows'] = len(rows)
                        prog['miss_eps'] = sum(z['miss_n'] for z in rows)
                    elif nt:
                        no_tmdb.append(nt)
                except Exception:
                    prog['done'] += 1
        rows.sort(key=lambda z: -z['miss_n'])
        miss_eps = sum(z['miss_n'] for z in rows)
        _GAPLIB_CACHE['rows'] = rows
        _GAPLIB_CACHE['ts'] = time.time()
        prog.update({'busy': False, 'finished': True, 'scanned': len(series),
                     'miss_shows': len(rows), 'miss_eps': miss_eps,
                     'tmdb_miss': len(no_tmdb),
                     'tmdb_miss_rows': [{'name': z.get('name') or '',
                                         'year': z.get('year') or '',
                                         'lib_path': z.get('path') or ''}
                                        for z in no_tmdb[:60]],
                     'rows': rows[:600], 'took': round(time.time() - t0, 1),
                     'phase': 'done'})
        return True
    except Exception as e:
        prog.update({'busy': False, 'finished': True, 'error': str(e)[:160],
                     'phase': 'error'})
        return False


def gap_scan_library(views=None, deep=True, max_scan=2000):
    """同步扫库（保留老接口，小范围/兼容用）。大库请用 gap_scan_start 后台版。"""
    prog = {}
    ok = _gap_scan_core(views, deep, max_scan, prog, lambda: False)
    return {
        'ok': ok, 'scanned': prog.get('scanned', 0),
        'miss_shows': prog.get('miss_shows', 0), 'miss_eps': prog.get('miss_eps', 0),
        'tmdb_miss': prog.get('tmdb_miss', 0),
        'tmdb_miss_rows': prog.get('tmdb_miss_rows', []),
        'rows': prog.get('rows', []), 'views': prog.get('views', []),
        'took': prog.get('took', 0), 'msg': prog.get('error', ''),
    }


def gap_scan_start(views=None, deep=True, max_scan=8000):
    """★ 一键后台扫描：立即返回，扫描在线程里跑，前端轮询 gap_scan_progress。
    views=[] → 全部剧集库；不阻塞 HTTP，不怕浏览器 fetch 超时。"""
    with _GAP_LOCK:
        if GAP_SCAN.get('busy'):
            return {'ok': False, 'busy': True,
                    'msg': '已有一轮扫描在跑，请稍候或点「取消」'}
        views = list(dict.fromkeys([str(v) for v in (views or []) if str(v)]))
        GAP_SCAN.update({'busy': True, 'cancel': False, 'finished': False,
                         'done': 0, 'total': 0, 'scanned': 0, 'miss_shows': 0,
                         'miss_eps': 0, 'rows': [], 'error': '',
                         'started': int(time.time()), 'phase': 'listing',
                         'views': views})

    def _worker():
        _gap_scan_core(views, deep, max_scan, GAP_SCAN,
                       lambda: GAP_SCAN.get('cancel'))
    threading.Thread(target=_worker, daemon=True).start()
    return {'ok': True, 'busy': True, 'msg': '后台扫描已启动',
            'views': views, 'max': int(max_scan or 8000)}


def gap_scan_progress():
    """后台扫描进度 + 部分结果（供前端轮询）。"""
    out = {k: GAP_SCAN.get(k) for k in
           ('busy', 'cancel', 'total', 'done', 'scanned', 'miss_shows',
            'miss_eps', 'tmdb_miss', 'took', 'phase', 'error', 'finished', 'views')}
    out['ok'] = True
    out['rows'] = sorted(GAP_SCAN.get('rows') or [], key=lambda z: -z['miss_n'])[:600]
    out['tmdb_miss_rows'] = (GAP_SCAN.get('tmdb_miss_rows') or [])[:60]
    total = max(1, GAP_SCAN.get('total') or 1)
    out['pct'] = round((GAP_SCAN.get('done') or 0) * 100.0 / total, 1)
    return out


def gap_scan_cancel():
    GAP_SCAN['cancel'] = True
    return {'ok': True, 'msg': '已请求取消'}




def gap_fill_rows(rows):
    """④ 批量补齐：对勾选的缺集行逐部走 missing_download（复用老链路，零重复实现）。"""
    out = []
    for r in (rows or [])[:20]:
        if not isinstance(r, dict) or not r.get('tmdbid'):
            continue
        seasons = [{'season': s.get('season'), 'missing': s.get('missing') or []}
                   for s in (r.get('seasons') or []) if (s.get('missing') or [])]
        if not seasons:
            continue
        try:
            d = missing_download(r.get('name') or '', '', r.get('year') or '', 'tv', seasons)
        except Exception as e:
            d = {'ok': False, 'msg': str(e)[:100], 'tried': 0, 'added': 0, 'rows': []}
        out.append({'name': r.get('name') or '', 'tmdbid': r.get('tmdbid'),
                    'ok': d.get('ok'), 'tried': d.get('tried') or 0,
                    'added': d.get('added') or 0,
                    'msg': d.get('msg') or '',
                    'miss_n': sum(len(s.get('missing') or []) for s in seasons)})
    return {'ok': True, 'n': len(out), 'rows': out,
            'added': sum(z['added'] for z in out),
            'msg': '已处理 %d 部，入队 %d 个资源' % (len(out), sum(z['added'] for z in out))}


def gap_status():
    """前端状态面板：配置 + 快照 + 上一轮 + 历史。"""
    g = gap_cfg()
    with _GAP_LOCK:
        st = {k: v for k, v in _GAP_ST.items() if k != 'snap_cache'}
    st = dict(st)
    st['history'] = list(st.get('history') or [])
    st['cfg'] = g
    st['snap_age'] = int(time.time() - (_GAP_ST.get('snap_ts') or 0))
    last = _GAP_ST.get('last_run') or 0
    st['run_age'] = int(time.time() - last) if last else -1
    st['next_in'] = (max(0, int(g.get('interval') or 3600) - (time.time() - last))
                     if g.get('enabled') else -1)
    st['ok'] = True
    return st


def _gap_sched_loop():
    """定时扫描后台循环。每 30 秒醒一次，按 interval 到点跑一轮。"""
    _gap_state_load()
    time.sleep(90)          # 启动后等 90 秒，别跟预热抢资源
    while True:
        try:
            g = gap_cfg()
            if g.get('enabled'):
                last = _GAP_ST.get('last_run') or 0
                iv = max(300, int(g.get('interval') or 3600))
                if not _GAP_ST.get('busy') and (time.time() - last) > iv:
                    logger.info('gap scheduler: 自动扫描（间隔 %ss）', iv)
                    gap_run()
        except Exception as e:
            logger.debug('gap sched err: %s' % str(e)[:100])
        time.sleep(30)




# ════════════════════════════════════════════════════════════════════
# ★ v1.13 榜单预搜索（用户原话：「我希望榜单里面的资源他都会提前给我搜好…每五分钟
#   自动全量的搜索一遍…下次打开就能直接看到资源了，而不是我打开的时候才实时搜索
#   加载这样很慢」）
#
# 做法：后台单线程，每 5 分钟把 9 个分区首屏的条目（去重后）批量过一遍
#   `_mp_search_title`（复用 5 分钟结果缓存 + 同关键词在途锁），把结果写进
#   `_DISC_PREWARM`。前端打开榜单/详情时先读这份缓存，0 秒出资源；
#   缓存没有的条目才退回实时搜索（体验与现在完全一致，只是更快）。
# 约束：
#   ① 只单线程串行 —— MP 不支持并发同接口，绝不并发打。
#   ② 复用 `_MP_SEARCH_TITLE_CACHE`，同一关键词 5 分钟内不重复打 MP。
#   ③ 失败静默跳过，绝不影响任何现有功能（铁律：只增不减）。
# ════════════════════════════════════════════════════════════════════
_DISC_PREWARM = {}          # title_lower -> {'ts':, 'n':, 'rows':[精简行]}
# ★ v1.13：失败冷却表（title_lower -> 上次失败时间戳）。MP 超时不写结果缓存，
#   但也不能一轮里反复重打同一个关键词，所以单独记 60 秒失败冷却。
_DISC_PREWARM_FAIL = {}
_DISC_PREWARM_LOCK = threading.Lock()
_DISC_PREWARM_ST = {'round': 0, 'last': 0, 'last_n': 0, 'busy': False, 'err': ''}
# ★ v1.13 分级策略（配合下方串行结论）：
#   tier1（热搜/正在热映/即将上映/今日播出 —— 用户最常点的 4 个区）→ 每轮必跑；
#   tier2（其余分区）→ 每 3 轮补一次；
#   每轮只搜「缓存里没有 / 已过期 / 上次失败的」，命中即跳过，所以越跑越快。
# ★ v1.15：用户原话「榜单里面的所有内容…每五分钟自动全量的搜索一遍，
#   下次打开就能直接看到资源」。原来只覆盖 4 个区 × 8 条 = 32 部，
#   实测缓存里只有 5 部（串行 + 8 分钟周期跑不完）。
#   → 全部 9 个区都纳入 tier1（每轮必跑），每区 20 条。
_DISC_PREWARM_TIER1 = ['trending', 'now_mv', 'upcoming_mv', 'air_tv', 'top_mv',
                       'top_tv', 'new_mv', 'new_tv', 'pop_mv', 'pop_tv']
_DISC_PREWARM_PER_SEC = 20     # 每区最多预搜条数（PT 直连实测单部 1~4s）
# ★ v1.13 实测三轮结论（重要，别再改）：
#   串行 4 部 = 426s（~107s/部）
#   4 路并发 = 200s，但**MP 侧 /api/v1/search/title 自己串行跨 8 站搜**，
#     并发请求在 MP 内部排队 → 大量 HTTP -1 timed out → 缓存里全是空结果。
#   2 路并发 = 10 分钟 0 命中（同样在排队）。
#   → 最终定为**完全串行 + 单部 150s 超时 + 失败 60s 冷却**。
#     慢但每部都能真拿到结果；一轮 tier1（32 部）约 50~60 分钟，
#     靠「缓存不失效 + 分级 + 只补没搜过的」保证用户 5 分钟周期内能见到增量。
# ★ v1.15：改为 8 路并发（v1.15b 再上调，见下）。
#   理由：链路已从 MP search/title 换成 **PT 直连**
#   （_disc_prewarm_one 里走 pt_direct_search，各站独立 HTTP，无 MP 内部全局锁）。
#   上面「不能并发」的实测结论是 MP 时代的，直连后已不成立。
# ★ v1.15b BUG-123 提速（用户原话「我发现你处理问题很慢，这次给我快一点」）：
#   实测单部 14.3s（不是注释里写的 1~4s，那是最快站的理想值），
#   113 部 ÷ 4 路 × 14.3s ≈ 8 分钟一轮 → 用户打开榜单仍是实时搜索。
#   → 上调到 8 路：一轮约 3.5~4 分钟，配合「只搜没搜过的」第二轮回落到 1 分钟内。
#   pt_direct_search 内部本身是瀑布式分批 + 60 条早停，8 个任务同时跑
#   也只是把「3 站一批」的队伍排长一点，不会把 7 个站同时打满。
_DISC_PREWARM_WORKERS = 8
_PTD_PREWARM_T = 10       # ★ v1.15b：预搜单部超时（用户手搜仍是 20s）
_DISC_PREWARM_MAX = 500        # 缓存部数上限


def discover_prewarm_status(title=''):
    """预搜索进度（前端显示「已预搜 N 部，最近一轮 M 秒前」）。

    ★ v1.13：新增可选参数 title —— 传了就把该片的预搜缓存行一并返回，
      前端打开详情时直接拿到 rows，不用再等 MP 的 30~60 秒实时搜索
      （用户原话：「提前给我搜好…下次打开就能直接看到资源」）。
    """
    key = (title or '').strip().lower()
    with _DISC_PREWARM_LOCK:
        now = time.time()
        out = {'ok': True, 'n': len(_DISC_PREWARM),
               'round': _DISC_PREWARM_ST.get('round', 0),
               'last': _DISC_PREWARM_ST.get('last', 0),
               'ago': (int(now - _DISC_PREWARM_ST['last'])
                       if _DISC_PREWARM_ST.get('last') else -1),
               'last_n': _DISC_PREWARM_ST.get('last_n', 0),
               'busy': bool(_DISC_PREWARM_ST.get('busy')),
               'err': _DISC_PREWARM_ST.get('err', '')}
        if key:
            hit = _DISC_PREWARM.get(key)
            if hit:
                out['title'] = hit.get('title') or title
                out['rows'] = hit.get('rows') or []
                out['age'] = int(now - hit.get('ts', now))
        return out


def _disc_prewarm_titles(tier1_only=False):
    """取榜单分区条目（去重，按标题）。tier1_only=True 只取最常用分区的前几条。
    失败返回 []。"""
    try:
        d = discover_sections(force=False)
    except Exception as e:
        logger.debug('prewarm sections err: %s' % str(e)[:120])
        return []
    out = {}
    for sec in (d.get('sections') or []):
        is_t1 = sec.get('key') in _DISC_PREWARM_TIER1
        if tier1_only and not is_t1:
            continue
        n = 0
        for x in (sec.get('items') or []):
            t = str(x.get('title') or '').strip()
            if t and t.lower() not in out:
                out[t.lower()] = {'title': t, 'type': x.get('type') or sec.get('type'),
                                  'tier': 1 if is_t1 else 2}
                n += 1
                if n >= _DISC_PREWARM_PER_SEC:
                    break
    # tier1 永远排在前面
    return sorted(out.values(), key=lambda x: x.get('tier', 9))


def _disc_prewarm_one(item):
    """给一条榜单条目跑一次 PT 搜索，结果写缓存。返回是否新写入。"""
    t = (item or {}).get('title') or ''
    if not t:
        return False
    key = t.strip().lower()
    now0 = time.time()
    with _DISC_PREWARM_LOCK:
        hit = _DISC_PREWARM.get(key)
        fail_ts = _DISC_PREWARM_FAIL.get(key)
    # 5 分钟内已预搜过 → 跳过（与 MP 侧缓存同周期，不重复打站）
    if hit and now0 - hit.get('ts', 0) < _DISC_PREWARM_TTL:
        return False
    # 60 秒内刚失败过 → 跳过，别在同一轮里反复重打
    if fail_ts and now0 - fail_ts < 60:
        return False
    # ★ v1.13e 重构：MP search/title 实测已彻底卡死（200s 超时无响应，
    #   MP 日志「总耗时 2000~2261 秒」而各站 0~17 秒 → 内部全局锁卡死）。
    #   改用 **PT 直连**（面板侧并发抓各站搜索页 + RSS 池，7 站 3.4 秒）。
    # ★ v1.15b BUG-123：预搜专用短超时 10s（前端用户手搜仍走 20s）。
    #   预搜是「广覆盖」不是「单部求全」——慢站 10s 拿不到就本轮跳过，
    #   下 5 分钟一轮补上（_DISC_PREWARM_TTL=300 保证过期后必补）。
    #   实测单部 14.3s 的样本里，慢的是 hdfans/nicept 这类 502/429 站，
    #   早失败反而让一轮从 8 分钟压到 3 分钟。
    r = pt_direct_search(t, t=_PTD_PREWARM_T)
    rows = []
    if r.get('ok'):
        rows = r.get('rows') or []
    # ★ v1.13 关键修复：失败时**绝不写缓存**。
    #   实测 4 路并发把 MP 打爆 → 全部 HTTP -1 timed out，空结果被缓存 5 分钟，
    #   用户打开榜单详情看到「0 条资源」，比不预搜更糟。
    #   现在：失败就当作没预搜过，下一轮重试；只有真拿到结果（含 0 条但成功）才缓存。
    if not r.get('ok'):
        with _DISC_PREWARM_LOCK:
            _DISC_PREWARM.pop(key, None)
            _DISC_PREWARM_FAIL[key] = time.time()
        return False
    # 只保留前端渲染用得上的字段，避免把 raw 全量种子对象堆在内存里
    slim = []
    for x in rows[:120]:
        slim.append({k: x.get(k) for k in (
            'title', 'site', 'site_name', 'site_id', 'size', 'size_txt', 'seeders',
            'leechers', 'grabs', 'year', 'season', 'episode', 'season_end', 'se_cn',
            'type', 'pix', 'pix_rank', 'team', 'audio', 'video', 'promo',
            'promo_rank', 'labels', 'hr', 'pubdate', 'url', 'torrent_id', 'dims',
            'site_logo', 'season_episode', 'src', 'poster')})
    with _DISC_PREWARM_LOCK:
        _DISC_PREWARM[key] = {'ts': time.time(), 'title': t, 'n': len(slim),
                              'rows': slim}
        _DISC_PREWARM_FAIL.pop(key, None)
        # 缓存上限 _DISC_PREWARM_MAX 部，超出淘汰最旧的
        if len(_DISC_PREWARM) > _DISC_PREWARM_MAX:
            for k in sorted(_DISC_PREWARM,
                            key=lambda x: _DISC_PREWARM[x].get('ts', 0))[:-_DISC_PREWARM_MAX]:
                _DISC_PREWARM.pop(k, None)
    return True


def discover_prewarm_once(force=False, tier1_only=False):
    """跑一轮预搜索。返回 {n, took, new, err}。

    ★ v1.13 性能重构（实测 MP 单部 36~107 秒）：
      tier1_only=True 只跑最常用分区（热搜/正在热映/即将上映/今日播出）各 8 条，
      4 路并发，约 3~5 分钟跑完 —— 这是用户 5 分钟周期内真正看得见的；
      其余分区由后台循环在 tier1 跑完后接着补，绝不让首轮卡 40 分钟。
    """
    if _DISC_PREWARM_ST.get('busy'):
        return {'n': _DISC_PREWARM_ST.get('last_n', 0) or 0, 'new': 0,
                'took': 0, 'busy': True}
    _DISC_PREWARM_ST['busy'] = True
    _DISC_PREWARM_ST['err'] = ''
    t0 = time.time()
    n_new = [0]
    try:
        items = _disc_prewarm_titles(tier1_only=tier1_only)
        # 过滤掉 5 分钟内已预搜过的，减少无谓请求
        todo = []
        now = time.time()
        for it in items:
            k = (it.get('title') or '').strip().lower()
            with _DISC_PREWARM_LOCK:
                hit = _DISC_PREWARM.get(k)
            if hit and now - hit.get('ts', 0) < _DISC_PREWARM_TTL:
                continue
            todo.append(it)
        def _work(it):
            try:
                if _disc_prewarm_one(it):
                    n_new[0] += 1
            except Exception as e:
                logger.debug('prewarm one err: %s' % str(e)[:100])
        if todo:
            with ThreadPoolExecutor(max_workers=_DISC_PREWARM_WORKERS) as ex:
                list(ex.map(_work, todo))
        _DISC_PREWARM_ST.update({'round': _DISC_PREWARM_ST.get('round', 0) + 1,
                                 'last': int(time.time()),
                                 'last_n': len(todo)})
    except Exception as e:
        _DISC_PREWARM_ST['err'] = str(e)[:160]
    finally:
        _DISC_PREWARM_ST['busy'] = False
    return {'n': _DISC_PREWARM_ST.get('last_n', 0) or 0, 'new': n_new[0],
            'took': round(time.time() - t0, 1)}


def _disc_prewarm_loop():
    """后台循环。

    ★ v1.13e 重构（PT 直连后速度提升 ~600 倍）：
       MP 时代：单部 36~107s，串行 4 部 426s → 只能分级 + 拉长周期。
       直连时代：7 站 RSS 并发 3.4s、单站搜索页 4.6s → **每 5 分钟全量**完全可行，
       正好命中用户原话「每五分钟自动全量的搜索一遍」。
       流程：延迟 45s（等服务就绪）→ 先刷一次 RSS 池（3.4s，榜单/站点浏览立刻有数据）
            → 每 5 分钟一轮全量预搜（tier1 + tier2）。
       RSS 池本身 3 分钟过期，每轮顺带刷新，保证「打开即可见」。
    """
    time.sleep(45)
    rnd = 0
    while True:
        try:
            # 每轮先刷新 RSS 池（快，3.4s），让站点浏览/榜单预搜都有新鲜数据
            _ptd_fetch_rss_all(force=(rnd % 2 == 0))
            discover_prewarm_once()              # 全量（tier1 + tier2）
        except Exception as e:
            logger.debug('prewarm loop err: %s' % str(e)[:120])
        rnd += 1
        # ★ v1.15b：周期回到 5 分钟（命中用户原话「每五分钟自动全量搜一遍」）。
        #   限流风险已由两件事压住：① 预搜改 4 路并发，单轮从 50~60 分钟降到
        #   约 1~2 分钟，占用出口带宽的时间窗大幅缩短；② pt_direct_search 是
        #   瀑布式 + 累计 60 条早停，不会把 7 个站同时打满。
        #   若仍观察到用户搜索变慢，把这里调回 480 即可（TTL 300s 保证缓存
        #   过期后下一轮必补，不会永久缺数据）。
        time.sleep(300)


