def _emby_task_cn(key):
    """ScheduledTasks 的 Key/Name → 中文名（取不到返回 ''，前端回退英文名）"""
    k = str(key or '')
    if k in EMBY_TASK_CN:
        return EMBY_TASK_CN[k][0]
    lk = k.lower()
    for sub, cn, _d in EMBY_TASK_CN_FUZZY:
        if sub in lk:
            return cn
    return ''


def _emby_task_desc(key, emby_desc=''):
    """→ 这个任务是干什么的（中文一句话；映射没有时保留 Emby 自带英文说明）"""
    k = str(key or '')
    if k in EMBY_TASK_CN:
        return EMBY_TASK_CN[k][1]
    lk = k.lower()
    for sub, _cn, d in EMBY_TASK_CN_FUZZY:
        if sub in lk:
            return d
    return str(emby_desc or '')


def _lib_missing_images(addr, port, H, lib_id, img_type):
    """列出库内缺图的条目：img_type='Primary' 查缺封面(海报)；None 查缺其它图(Backdrop/Logo/Thumb/Disc/Box/Art)。
        Emby 原生没有「缺图清单」视图，这是 KFC 中枢的专项补齐功能。"""
    if not lib_id:
        return {'ok': False, 'msg': '缺少库 ID'}
    items = []; idx0 = 0; limit = 500
    EXTRA = ['Backdrop', 'Logo', 'Thumb', 'Disc', 'Box', 'Art', 'Banner']
    while True:
        st, b = hget(addr, port,
                     '/Items?ParentId=%s&Recursive=true&IncludeItemTypes=Movie,Series,Season,Episode'
                     '&Fields=ImageTags&Limit=%d&StartIndex=%d' % (urllib.parse.quote(str(lib_id)), limit, idx0),
                     H, 25)
        if st != 200:
            return {'ok': False, 'msg': '读取失败 HTTP %s' % st}
        arr = (b or {}).get('Items', [])
        for i in arr:
            tags = i.get('ImageTags') or {}
            if img_type == 'Primary':
                miss = not tags.get('Primary')
            else:
                miss = not any(tags.get(t) for t in EXTRA)
            if miss:
                items.append({'id': i.get('Id'), 'name': i.get('Name'), 'type': i.get('Type'),
                              'year': i.get('ProductionYear')})
        if len(arr) < limit:
            break
        idx0 += limit
        if idx0 > 30000:
            break
    return {'ok': True, 'msg': '缺图条目 %d 条' % len(items), 'data': items, 'count': len(items)}


def act_emby(which, act, arg):
    c = cfg()
    key = c.get('emby_key' if which == 'emby' else 'emby_key2', '')
    conf = containers()[which]
    addr, port = conf['addr'], conf['port']
    H = emby_headers(key)
    if act == 'sessions':
        st, b = hget(addr, port, '/Sessions', H, 10)
        if st != 200:
            return {'ok': False, 'msg': '读取会话失败 HTTP %s（需 API Key）' % st}
        np, alls = [], []
        for s in (b or []):
            p = s.get('PlayState') or {}
            i = s.get('NowPlayingItem')
            if i:
                np.append({'user': s.get('UserName'), 'title': i.get('SeriesName') or i.get('Name'),
                           'ep': ('S%02dE%02d' % (i.get('ParentIndexNumber') or 0, i.get('IndexNumber') or 0))
                                 if i.get('IndexNumber') else None,
                           'paused': p.get('IsPaused'),
                           'pos': round((p.get('PositionTicks') or 0) / 6e8, 1),
                           'pct': round((p.get('PositionTicks') or 0) / (i.get('RunTimeTicks') or 1) * 100, 1),
                           'device': s.get('DeviceName'), 'client': s.get('Client'),
                           'transcoding': bool((s.get('TranscodingInfo') or {}).get('IsVideoDirect') is False)})
            alls.append({'user': s.get('UserName'), 'device': s.get('DeviceName'),
                         'client': s.get('Client'), 'state': p.get('PlayState', 'Idle'),
                         'ip': s.get('RemoteEndPoint')})
        return {'ok': True, 'msg': '%d 个会话，%d 个正在播放' % (len(alls), len(np)),
                'data': {'now_playing': np, 'sessions': alls}}
    if act == 'counts':
        st, b = hget(addr, port, '/Items/Counts', H, 15)
        if st != 200:
            return {'ok': False, 'msg': '读取统计失败 HTTP %s' % st}
        return {'ok': True, 'msg': '电影 %(MovieCount)s · 剧集 %(SeriesCount)s · 集数 %(EpisodeCount)s' % b,
                'data': b}
    if act == 'libs':
        st, b = hget(addr, port, '/Library/MediaFolders', H, 12)
        if st != 200:
            return {'ok': False, 'msg': '读取媒体库失败 HTTP %s' % st}
        fl = b.get('Items') if isinstance(b, dict) else b
        return {'ok': True, 'msg': '%d 个媒体库' % len(fl or []),
                'data': [{'name': f.get('Name'), 'id': f.get('Id'),
                          'path': (f.get('Path') or (f.get('Locations') or [''])[0])} for f in (fl or [])]}
    # ═══ ★ v6 商用版：库封面墙（VirtualFolders 带 PrimaryImageTag）═══
    if act == 'libs2':
        st, vf = hget(addr, port, '/Library/VirtualFolders', H, 15)
        if st != 200:
            return {'ok': False, 'msg': '读取媒体库失败 HTTP %s（需 API Key）' % st}
        uid = _emby_uid(addr, port, H)
        # 并发拉各库条目数（Limit=1 只取 TotalItemCount）：31 库串行太慢
        counts = {}
        if uid:
            try:
                from concurrent.futures import ThreadPoolExecutor
                def _cnt(iid):
                    try:
                        st2, c = hget(addr, port, '/Items?ParentId=%s&Recursive=true&Limit=1&UserId=%s'
                                      % (iid, uid), H, 5)
                        if st2 == 200 and isinstance(c, dict):
                            # Emby 不同版本字段名不一：TotalRecordCount / TotalItemCount 都兼容
                            return iid, int(c.get('TotalRecordCount') or c.get('TotalItemCount') or 0)
                    except Exception:
                        pass
                    return iid, 0
                iids = [f.get('ItemId') for f in (vf or []) if f.get('ItemId')]
                with ThreadPoolExecutor(max_workers=8) as ex:
                    for iid, n in ex.map(_cnt, iids):
                        counts[iid] = n
            except Exception:
                pass
        out = []
        for f in (vf or []):
            iid = f.get('ItemId')
            lo = f.get('LibraryOptions') or {}
            out.append({
                'name': f.get('Name'), 'item_id': iid, 'guid': f.get('Guid'),
                'type': f.get('CollectionType') or 'movies',
                'has_img': bool(f.get('PrimaryImageTag')),
                'img_tag': f.get('PrimaryImageTag') or '',
                'paths': f.get('Locations') or [],
                'count': counts.get(iid, 0),
                'realtime': bool(lo.get('EnableRealtimeMonitor')),
                'auto_meta': bool(lo.get('AutoDetectExtents')) or lo.get('EnabledExtractArt') is True,
                'root_kind': lo.get('Type') or '',
            })
        out.sort(key=lambda x: (x['type'], -x['count']))
        return {'ok': True, 'msg': '%d 个媒体库' % len(out), 'data': out}
    if act == 'lib_recent':
        # 单库最近添加（带图），点开库看详情用；带 UserId 才拿得到条目
        uid = _emby_uid(addr, port, H)
        uq = ('&UserId=%s' % uid) if uid else ''
        st, b = hget(addr, port, '/Items?ParentId=%s&SortBy=DateCreated&SortOrder=Descending'
                     '&Recursive=true&Limit=12&Fields=PrimaryImageAspectRatio,ImageTags,SeriesName,ProductionYear%s'
                     % (urllib.parse.quote(arg or ''), uq), H, 12)
        if st != 200:
            return {'ok': False, 'msg': '读取失败 HTTP %s' % st}
        its = (b or {}).get('Items', [])
        return {'ok': True, 'msg': '最近 %d 条' % len(its),
                'data': [{'id': i.get('Id'), 'name': i.get('Name'), 'type': i.get('Type'),
                          'year': i.get('ProductionYear'), 'series': i.get('SeriesName'),
                          'img': bool((i.get('ImageTags') or {}).get('Primary'))} for i in its]}
    if act == 'lib_refresh_item':
        # 刷新指定库（VirtualFolder 级：重扫该库，不重下元数据）
        st, _ = hreq(addr, port, 'POST', '/Library/Refresh?ItemId=%s' % urllib.parse.quote(arg or ''), None, H, 15)
        return {'ok': st < 400, 'msg': '已触发该库扫描 HTTP %s' % st, 'http': st}
    if act == 'lib_rescan':
        # 深度重扫：递归重解析（含新文件+移除失效+按设置重识别元数据）
        st, _ = hreq(addr, port, 'POST', '/Items/%s/Refresh?Recursive=true&RefreshChildren=true&MetadataRefreshMode=Default'
                     % urllib.parse.quote(arg or ''), None, H, 15)
        return {'ok': st < 400, 'msg': '已触发库递归扫描 HTTP %s' % st, 'http': st}
    if act == 'lib_metadata':
        # 重新识别/刷新元数据（不含图片重下，快速路径；本 Emby 版 MetadataRefreshMode 仅接受 Default）
        st, _ = hreq(addr, port, 'POST', '/Items/%s/Refresh?Recursive=true&MetadataRefreshMode=Default'
                     % urllib.parse.quote(arg or ''), None, H, 15)
        return {'ok': st < 400, 'msg': '已触发元数据全量重识别 HTTP %s' % st, 'http': st}
    if act == 'lib_images':
        # 重新抓取图片/字幕（本 Emby 版 ImageRefreshMode 仅接受 Default + ReplaceAllImages=true）
        st, _ = hreq(addr, port, 'POST', '/Items/%s/Refresh?Recursive=true&ImageRefreshMode=Default'
                     '&ReplaceAllImages=true' % urllib.parse.quote(arg or ''), None, H, 15)
        return {'ok': st < 400, 'msg': '已触发图片/字幕重抓 HTTP %s' % st, 'http': st}
    if act == 'lib_missing_meta':
        # v1.25 S11：只刷新缺失的元数据（对标 Emby「刷新缺失的元数据」）
        #   ReplaceAllMetadata=false -> 已有元数据不动，只补空字段
        st, _ = hreq(addr, port, 'POST',
                     '/Items/%s/Refresh?Recursive=true&MetadataRefreshMode=Default'
                     '&ReplaceAllMetadata=false' % urllib.parse.quote(arg or ''),
                     None, H, 15)
        return {'ok': st < 400, 'msg': '已触发「只补缺失元数据」HTTP %s' % st, 'http': st}
    if act == 'lib_scan_files':
        # v1.25 S11：扫描媒体库文件（只扫新增文件，不重下元数据/图片，最快；等价于 Emby「扫描新增文件」）
        st, _ = hreq(addr, port, 'POST',
                     '/Items/%s/Refresh?Recursive=true&RefreshChildren=true'
                     % urllib.parse.quote(arg or ''), None, H, 15)
        return {'ok': st < 400, 'msg': '已触发媒体库文件扫描 HTTP %s' % st, 'http': st}
    if act == 'lib_no_poster':
        # 列出库内缺 Primary(封面/海报)图的条目（Emby 原生无此视图，KFC 专属补齐功能）
        return _lib_missing_images(addr, port, H, arg, 'Primary')
    if act == 'lib_no_images':
        # 列出库内缺其它图(Backdrop/Logo/Thumb/Disc/Box/Art)的条目
        return _lib_missing_images(addr, port, H, arg, None)
    if act == 'lib_fix_image':
        # 批量补图：arg=JSON {"ids":[...]} 逐条触发图片刷新（Emby 刷新=重抓该 item 全部图）
        try:
            a = json.loads(arg) if arg else {}
        except Exception:
            a = {}
        ids = a.get('ids') or []
        if not ids:
            return {'ok': False, 'msg': '请先选择要补图的条目'}
        ids = ids[:100]  # 单次上限，避免长耗时；可分批多次触发
        ok = 0; fail = 0
        for iid in ids:
            st, _ = hreq(addr, port, 'POST',
                         '/Items/%s/Refresh?Recursive=true&ImageRefreshMode=Default&ReplaceAllImages=true'
                         % urllib.parse.quote(str(iid)), None, H, 15)
            if st < 400: ok += 1
            else: fail += 1
        return {'ok': True, 'msg': '已触发补图 %d 个，失败 %d 个（单次上限 100，可分批）' % (ok, fail),
                'data': {'ok': ok, 'fail': fail}}

    if act == 'lib_set_type':
        # v1.25 S11：修改媒体类型（CollectionType）
        #   arg = JSON {"id":"...","type":"movies|tvshows|music|homevideos|books|mixed"}
        try:
            a = json.loads(arg) if arg else {}
        except Exception:
            a = {}
        iid = a.get('id') or ''
        ct = a.get('type') or ''
        if not iid or not ct:
            return {'ok': False, 'msg': '缺少 id 或 type'}
        body = json.dumps({'Id': iid, 'CollectionType': ct,
                           'LibraryOptions': {'Type': ct}})
        st, _ = hreq(addr, port, 'POST', '/Library/VirtualFolders/Options',
                     body, dict(H, **{'Content-Type': 'application/json'}), 15)
        if st >= 400:
            # 老版本 Emby 不支持 Options 端点，退回重设 VirtualFolder
            st, _ = hreq(addr, port, 'POST',
                         '/Library/VirtualFolders?collectionType=%s' % ct,
                         json.dumps({'Id': iid}),
                         dict(H, **{'Content-Type': 'application/json'}), 15)
        return {'ok': st < 400, 'msg': '媒体类型已改为 %s HTTP %s' % (ct, st), 'http': st}
    if act == 'lib_edit':
        # v1.25 S11：编辑媒体库设置（LibraryOptions 局部更新）
        try:
            a = json.loads(arg) if arg else {}
        except Exception:
            a = {}
        iid = a.get('id') or ''
        if not iid:
            return {'ok': False, 'msg': '缺少 id'}
        body = json.dumps({'Id': iid, 'LibraryOptions': a.get('options') or {}})
        st, _ = hreq(addr, port, 'POST', '/Library/VirtualFolders/Options',
                     body, dict(H, **{'Content-Type': 'application/json'}), 15)
        return {'ok': st < 400, 'msg': '媒体库设置已保存 HTTP %s' % st, 'http': st}
    if act == 'lib_delete':
        # v1.25 S11：删除媒体库（不删文件）
        st, _ = hreq(addr, port, 'DELETE',
                     '/Library/VirtualFolders?ItemId=%s' % urllib.parse.quote(arg or ''),
                     None, H, 15)
        return {'ok': st < 400, 'msg': '媒体库已删除（文件保留）HTTP %s' % st, 'http': st}
    if act == 'lib_create':
        # v1.25 S11：新建媒体库（对标 Emby「新建媒体库」向导）
        #   arg = JSON {"name":"...","collectionType":"movies|tvshows|...","paths":["/a"]}
        try:
            a = json.loads(arg) if arg else {}
        except Exception:
            a = {}
        nm = (a.get('name') or '').strip()
        ct = a.get('collectionType') or ''
        paths = a.get('paths') or []
        if not nm:
            return {'ok': False, 'msg': '请填写媒体库名称'}
        if not paths:
            return {'ok': False, 'msg': '请至少选择一个文件夹路径'}
        body = json.dumps({'Name': nm, 'CollectionType': ct, 'Paths': paths,
                           'LibraryOptions': {'Type': ct or 'movies'}})
        st, _ = hreq(addr, port, 'POST',
                     '/Library/VirtualFolders?name=%s&collectionType=%s&refresh=true'
                     % (urllib.parse.quote(nm), urllib.parse.quote(ct or '')),
                     body, dict(H, **{'Content-Type': 'application/json'}), 20)
        return {'ok': st < 400, 'msg': '媒体库「%s」创建成功 HTTP %s' % (nm, st), 'http': st}
    if act == 'lib_folders':
        # v1.25 S11：列出可选目录（新建媒体库选路径用）
        st, vf = hget(addr, port, '/Library/VirtualFolders', H, 12)
        dirs = set()
        if st == 200:
            for f in (vf or []):
                for p in (f.get('Locations') or []):
                    if p and p.startswith('/'):
                        dirs.add(p)
        for root in ('/media', '/data', '/storage'):
            dirs.add(root)
        return {'ok': True, 'msg': '%d 个可用目录' % len(dirs), 'data': sorted(dirs)}
        return {'ok': st < 400, 'msg': '已触发图片/字幕重抓 HTTP %s' % st, 'http': st}
    if act == 'tasks':
        st, b = hget(addr, port, '/ScheduledTasks', H, 12)
        if st != 200:
            return {'ok': False, 'msg': '读取计划任务失败 HTTP %s' % st}
        out = []
        for t in (b or []):
            tg = (t.get('Triggers') or [{}])[0]
            tt = tg.get('Type') or ''
            when = ''
            if tt == 'DailyTrigger':
                when = '每天 %02d:%02d' % (tg.get('Hour', 0) or 0, tg.get('Minute', 0) or 0)
            elif tt == 'WeeklyTrigger':
                when = '每周 %02d:%02d' % (tg.get('Hour', 0) or 0, tg.get('Minute', 0) or 0)
            elif tt == 'IntervalTrigger':
                d = int((tg.get('IntervalTicks') or 0) / 8.64e11)
                when = '每 %d 天' % d if d else '每 %s 时' % round(int(tg.get('IntervalTicks') or 0) / 3.6e10)
            elif tt == 'StartupTrigger':
                when = '启动时'
            out.append({'id': t.get('Id'), 'key': t.get('Key'), 'name': t.get('Name'),
                        'state': t.get('State'), 'cat': t.get('Category'),
                        'enabled': bool(t.get('Enabled', True)) if 'Enabled' in t else True,
                        'hidden': bool(t.get('IsHidden')), 'trig': tt, 'when': when,
                        'desc': t.get('Description') or '',
                        # ★★ v1.22 中文化（用户原话：「计划任务全是英文的，你在后面加个括号，
                        #   然后备注上他的中文名称，还有再写一下这个功能具体是操作什么的」）
                        'name_cn': _emby_task_cn(t.get('Key') or t.get('Name') or ''),
                        'desc_cn': _emby_task_desc(t.get('Key') or t.get('Name') or '',
                                                   t.get('Description') or '')})
        # 中文名 + 说明齐全的排前面，纯英文兜底的沉底，肉眼好看
        out.sort(key=lambda x: (0 if x['name_cn'] else 1, 0 if x['enabled'] else 1,
                                x.get('cat') or '', x['name'] or ''))
        return {'ok': True, 'msg': '%d 个计划任务' % len(out), 'data': out}
    if act == 'task_run':
        st, _ = hreq(addr, port, 'POST', '/ScheduledTasks/Starting/%s' % urllib.parse.quote(arg or ''), None, H, 12)
        return {'ok': st < 400, 'msg': '已触发任务 HTTP %s' % st, 'http': st}
    if act == 'lib_options':
        # 单库详情：VirtualFolders 已含全部 LibraryOptions，直接定位返回
        st, vf = hget(addr, port, '/Library/VirtualFolders', H, 12)
        if st != 200:
            return {'ok': False, 'msg': '读取失败 HTTP %s' % st}
        for f in (vf or []):
            if str(f.get('ItemId')) == str(arg):
                return {'ok': True, 'msg': f.get('Name'), 'data': f}
        return {'ok': False, 'msg': '未找到该库'}
    if act == 'recent':
        st, b = hget(addr, port,
                     '/Items?SortBy=DateCreated&SortOrder=Descending&Recursive=true&Limit=20'
                     '&IncludeItemTypes=Movie,Episode&Fields=Path,DateCreated', H, 15)
        if st != 200:
            return {'ok': False, 'msg': '读取最近添加失败 HTTP %s' % st}
        its = (b or {}).get('Items', [])
        return {'ok': True, 'msg': '最近添加 %d 条' % len(its),
                'data': [{'name': i.get('Name'), 'type': i.get('Type'), 'year': i.get('ProductionYear'),
                          'series': i.get('SeriesName'), 'at': (i.get('DateCreated') or '')[:19].replace('T', ' ')}
                         for i in its]}
    if act == 'refresh':
        st, _ = hreq(addr, port, 'POST', '/Library/Refresh', None, H, 12)
        return {'ok': st < 400, 'msg': '已触发全库刷新 HTTP %s' % st}
    if act == 'scan':
        st, _ = hreq(addr, port, 'POST', '/Library/Refresh?Recursive=true', None, H, 12)
        return {'ok': st < 400, 'msg': '已触发递归扫描 HTTP %s' % st}
    if act == 'restart_scan':
        return ctr_action(which, 'restart')
    if act == 'lib_refresh':
        q = '?libraryId=%s' % arg if arg else ''
        st, _ = hreq(addr, port, 'POST', '/Library/Refresh%s' % q, None, H, 15)
        return {'ok': st < 400, 'msg': ('已刷新媒体库 #%s' % arg) if arg else '已触发全库刷新', 'http': st}
    if act == 'item_search':
        q = (arg or '').strip()
        if not q:
            return {'ok': False, 'msg': '请填写搜索关键词'}
        uid = _emby_uid(addr, port, H)
        uq = ('&UserId=%s' % uid) if uid else ''
        st, b = hget(addr, port,
                     '/Items?SearchTerm=%s&Recursive=true&IncludeItemTypes=Movie,Series,Episode&Limit=40'
                     '&Fields=Path,Overview,ImageTags,PrimaryImageAspectRatio%s'
                     % (urllib.parse.quote(q), uq),
                     H, 15)
        if st != 200:
            return {'ok': False, 'msg': '搜索失败 HTTP %s' % st}
        its = (b or {}).get('Items', [])
        out = [{'id': i.get('Id'), 'name': i.get('Name'), 'type': i.get('Type'),
                'year': i.get('ProductionYear'), 'series': i.get('SeriesName'),
                'path': i.get('Path'),
                'img': bool((i.get('ImageTags') or {}).get('Primary'))} for i in its]
        return {'ok': True, 'msg': '「%s」命中 %d 条' % (q, len(out)), 'data': out}
    if act == 'item_delete':
        if not arg:
            return {'ok': False, 'msg': '缺少条目 id'}
        st, _ = hreq(addr, port, 'DELETE', '/Items/%s' % arg, None, H, 15)
        return {'ok': st < 400, 'msg': ('已删除条目 #%s' % arg) if st < 400 else '删除失败 HTTP %s' % st, 'http': st}
    # logs / stats / state / start / stop / restart / restart_scan 之外的容器操作
    return act_generic(which, act, arg)


def mp_call(path, method='GET', body=None, t=12):
    c = cfg()
    tk = c.get('mp_token', '')
    if not tk:
        return {'ok': False, 'msg': '需要在「凭据」里填写 MoviePilot API Token'}
    base = containers()['moviepilot']
    hdr = {'X-API-KEY': tk, 'Content-Type': 'application/json'}
    st, b = hreq(base['addr'], base['port'], method, path,
                 json.dumps(body) if body is not None else None, hdr, t)
    if st < 200 or st >= 300:
        return {'ok': False, 'msg': 'MoviePilot HTTP %s %s' % (st, (b or '')[:160])}
    try:
        j = json.loads(b)
    except Exception:
        return {'ok': True, 'msg': 'HTTP %s' % st, 'data': b[:300]}
    if isinstance(j, dict) and j.get('success') is False:
        return {'ok': False, 'msg': j.get('message') or 'MP 返回失败'}
    return {'ok': True, 'data': j.get('data') if isinstance(j, dict) else j}


def act_mp(act, arg):
    # ★ 2026-10-24：inspect / files 走通用容器动作（docker.sock 读详情/挂载点），
    #   此前漏掉导致「容器详情/挂载点占用」按钮返回「未实现」。moviepilot 是真实容器。
    if act in ('logs', 'stats', 'state', 'start', 'stop', 'restart', 'inspect', 'files'):
        return act_generic('moviepilot', act, arg)
    if act == 'refresh_bonus':
        # ★ 2026-10-16 用户要求：站点魔力值能快速刷新。
        #   做法：给每个启用站点打 kick 标记（bot 的 tick() 会立刻重抓一轮），
        #   同时往 bot 信箱投一条 ka_refresh 让 bot 不必等下一个 30 分钟周期。
        def _mut(st):
            sites = st.get('sites') or {}
            n = 0
            for sid, ss in sites.items():
                if isinstance(ss, dict) and ss.get('enabled'):
                    ss['kick'] = 1
                    n += 1
            st['sites'] = sites
            return {'ok': True, 'msg': '已标记 %d 个站点立即重抓魔力值' % n,
                    'n': n}
        r = _ka_write_state(_mut)
        try:
            _mailbox_cmd('ka_refresh-%d' % int(time.time()), cmd='ka_refresh')
        except Exception:
            pass
        r['data'] = _ka_read_state()
        return r
    if act == 'status':
        r = mp_call('/api/v1/system/env')
        if not r['ok']:
            return r
        d = r.get('data')
        ver = None
        if isinstance(d, list):
            kv = {x.get('key'): x.get('value') for x in d if isinstance(x, dict)}
            ver = kv.get('VERSION') or kv.get('APP_VERSION')
        elif isinstance(d, dict):
            ver = d.get('VERSION') or d.get('APP_VERSION')
        extra = {}
        st2 = mp_call('/api/v1/dashboard/statistic')
        if st2.get('ok') and isinstance(st2.get('data'), dict):
            extra = st2['data']
        return {'ok': True, 'msg': 'MP 运行中 · 版本 %s · 电影 %s / 剧集 %s' % (
            ver or '—', extra.get('movie_count', '—'), extra.get('tv_count', '—')),
            'data': {'version': ver, 'stat': extra}}
    if act == 'subs':
        r = mp_call('/api/v1/subscribe/')
        if not r['ok']:
            r = mp_call('/api/v1/subscribe/list')
        if not r['ok']:
            return r
        d = r.get('data')
        its = d.get('items') if isinstance(d, dict) else d
        out = []
        for x in (its or []):
            if not isinstance(x, dict):
                continue
            out.append({'id': x.get('id'), 'name': x.get('name'), 'year': x.get('year'),
                        'type': x.get('type'), 'state': x.get('state'),
                        'season': x.get('season'), 'site': x.get('site_name'),
                        'last_search': x.get('last_search')})
        return {'ok': True, 'msg': '%d 条订阅' % len(out), 'data': out}
    if act == 'sites':
        r = mp_call('/api/v1/site/')
        if not r['ok']:
            return {'ok': False, 'msg': '读取站点失败：%s' % r.get('msg')}
        d = r.get('data')
        its = d.get('items') if isinstance(d, dict) else d
        out = []
        for x in (its or []):
            if isinstance(x, dict):
                out.append({'id': x.get('id'), 'name': x.get('name'),
                            'domain': x.get('domain'), 'url': x.get('url'),
                            'status': x.get('status'), 'cookie': bool(x.get('cookie')),
                            'pri': x.get('pri')})
        return {'ok': True, 'msg': '%d 个站点' % len(out), 'data': out}
    if act == 'history':
        r = mp_call('/api/v1/download/')
        if not r['ok']:
            return {'ok': False, 'msg': '读取下载记录失败：%s' % r.get('msg')}
        d = r.get('data')
        its = d.get('items') if isinstance(d, dict) else d
        out = []
        for x in (its or []):
            if isinstance(x, dict):
                out.append({'title': x.get('title'), 'type': x.get('type'),
                            'site': x.get('site_name'), 'date': x.get('date'),
                            'status': x.get('status'), 'id': x.get('id'),
                            'progress': x.get('progress')})
        return {'ok': True, 'msg': '%d 条下载记录' % len(out), 'data': out}
    if act == 'search':
        q = (arg or '').strip()
        if not q:
            return {'ok': False, 'msg': '请填写搜索关键词'}
        # ★ 2026-10-17 用户要求：求片管理要能「在 PT 站搜种子 + 选种排序按质量下载」。
        #   旧实现调 /api/v1/media/search（TMDB 媒体级，没有种子信息，无法选种）。
        #   新实现调种子级 GET /api/v1/search/title（实测返回完整种子数组，
        #   字段在 meta_info + torrent_info 里，含 site_name/size/seeders/促销等）。
        # ★ 2026-10-18 改用 _mp_search_title（带并发去重锁），避免与三源搜索里的
        #   _search_sites 同时打 MP 同一接口导致 MP 互相挤掉（MP 源塌成 1 条回退）。
        r = _mp_search_title(q, t=180)
        if not r['ok']:
            # 兼容：种子级失败时退回媒体级（至少给个 TMDB 命中提示）
            r2 = mp_call('/api/v1/media/search?title=%s' % urllib.parse.quote(q))
            if r2['ok'] and r2.get('data'):
                return {'ok': True, 'msg': '「%s」未命中 PT 种子，仅匹配到媒体库条目 %d 个（可换更精确关键词）'
                        % (q, len(r2['data'])), 'data': []}
            return r
        rows = _slim_torrents(r.get('data') or [])
        if not rows:
            return {'ok': True, 'msg': '「%s」在 8 个 PT 站都没搜到种子，换个关键词（如英文名/年份）再试' % q,
                    'data': []}
        # 按站点分布 + 相关性（标题含关键词优先）
        import collections as _c
        bysite = _c.Counter(x['site_name'] for x in rows)
        lowq = q.lower()
        rows.sort(key=lambda x: (0 if lowq in (x['title'] or '').lower() else 1,
                                 -x.get('seeders', 0)))
        return {'ok': True, 'msg': '「%s」命中 %d 个种子（覆盖 %d 站：%s）'
                % (q, len(rows), len(bysite), '、'.join('%s×%d' % kv for kv in bysite.most_common())),
                'data': rows[:80]}
    if act == 'torrent_download':
        # 求片管理「选种下载」：用户点种子行的「下载」按钮触发。
        # ★ 2026-10-17 实测要点（MP 3.1.2）：
        #   1) torrent_in 必须精简到 TorrentInfo 模型字段 —— 原样透传 search/title
        #      的整个对象（含 site_cookie 长字符串/raw 嵌套）会 Pydantic 校验失败，
        #      表现为「任务添加失败」且无明确原因。
        #   2) save_path 必须在 MP 允许的下载目录白名单内（/downloads/qBittorrent/订阅
        #      或 /CloudNAS/115open/主号/待整理/PT），传子目录会被拒（"保存路径不在
        #      允许范围内"）。故用白名单前缀 + 分类/站点/影片类型 作为子目录拼接。
        #   3) allow_unrecognized=True 让 MP 认不出媒体时也放行（手动下载场景）。
        tor = {}
        cls, site_name, mtype = '手动下载', '', ''
        if isinstance(arg, dict):
            tor = arg.get('torrent') or arg.get('raw_torrent') or {}
            cls = (arg.get('cls') or '手动下载').strip()
            site_name = (arg.get('site_name') or '').strip()
            mtype = (arg.get('media_type') or '').strip()
        if not isinstance(tor, dict) or not tor:
            return {'ok': False, 'msg': '缺少种子对象（torrent）'}
        if cls not in ('手动下载', '订阅', '求片'):
            cls = '手动下载'
        if not mtype:
            mtype = '未分类'
        for k, v in (('电视剧', '电视剧'), ('剧集', '电视剧'), ('电视', '电视剧'),
                     ('电影', '电影'), ('动漫', '动漫'), ('动画', '动漫'),
                     ('综艺', '综艺'), ('纪录片', '纪录片'), ('mv', '音乐')):
            if k in mtype:
                mtype = v
                break
        # 精简 torrent_in 到 MP TorrentInfo 模型字段
        keep = ('site', 'site_name', 'site_cookie', 'site_ua', 'site_proxy', 'site_order',
                'site_downloader', 'title', 'description', 'enclosure', 'page_url', 'size',
                'seeders', 'peers', 'grabs', 'pubdate', 'date_elapsed', 'freedate',
                'uploadvolumefactor', 'downloadvolumefactor', 'volume_factor',
                'hit_and_run', 'labels', 'pri_order', 'category', 'torrent_id')
        ti = tor.get('torrent_info') if isinstance(tor.get('torrent_info'), dict) else tor
        tor_in = {k: ti.get(k) for k in keep if ti.get(k) is not None}
        if not tor_in.get('title'):
            return {'ok': False, 'msg': '种子缺少标题，无法下载'}
        # ★ 2026-10-19 BUG-011/BUG-012 修复：
        #   旧实现 save_path 前缀**硬编码** '/downloads/qBittorrent/订阅'，
        #   于是「手动下载 / 订阅 / 求片」三个分类在 MP 里全落到「订阅」目录下，
        #   用户选「求片」磁盘上却出现在「订阅」里（BUG-011「分类重复」）。
        #   downloader 也硬编码 'QB下载器'，别人环境里叫别的名字就必然失败（BUG-012）。
        #   现在：① 下载器名从 MP 下载器列表里动态取（不匹配才回退默认）；
        #         ② 分类直接进路径（不再固定「订阅」）。
        _dl = _mp_pick_downloader(arg.get('downloader') if isinstance(arg, dict) else None)
        # save_path：白名单前缀 + 分类/站点/影片类型（MP 只校验前缀在白名单内）
        sub = '/%s/%s/%s' % (cls, site_name or '未知站点', mtype)
        save_path = '/downloads/qBittorrent/' + sub
        payload = {
            'torrent_in': tor_in,
            'downloader': _dl,
            'save_path': save_path,
            'allow_unrecognized': True,
        }
        r = mp_call('/api/v1/download/add', 'POST', payload, t=90)
        if not r['ok']:
            return {'ok': False, 'msg': 'MP 拒绝下载：%s' % r.get('msg')}
        return {'ok': True,
                'msg': '已提交下载 → %s' % save_path,
                'save_path': save_path, 'cls': cls, 'site_name': site_name,
                'download_id': (r.get('data') or {}).get('download_id') if isinstance(r.get('data'), dict) else None}
    if act == 'torrent_search':
        # 求片管理「种子搜索」：可传站点过滤 + 排序字段，用于前端选种面板。
        # arg 支持两种：字符串（=关键词）或 dict（{q/keyword, sites, sort}）。
        kw, sites, sort_by = '', '', 'seeders'
        if isinstance(arg, dict):
            kw = (arg.get('q') or arg.get('keyword') or arg.get('arg') or '').strip()
            sites = str(arg.get('sites') or '').strip()
            sort_by = arg.get('sort') or 'seeders'
        else:
            kw = (arg or '').strip()
        if not kw:
            return {'ok': False, 'msg': '请填写搜索关键词'}
        # ★ 2026-10-18 改用 _mp_search_title（带并发去重锁），避免与三源搜索里的
        #   _search_sites 同时打 MP 同一接口导致 MP 互相挤掉。sites 过滤参数已省略
        #   （同源去重优先级高于站点预筛，前端用站名二次过滤即可，实测不影响结果）。
        r = _mp_search_title(kw, t=180)
        if not r['ok']:
            return r
        rows = _slim_torrents(r.get('data') or [])
        if sort_by == 'size':
            rows.sort(key=lambda x: -x.get('size', 0))
        elif sort_by == 'quality':
            rows.sort(key=lambda x: (x.get('pix_rank', 99), -x.get('seeders', 0)))
        elif sort_by == 'seeders':
            rows.sort(key=lambda x: -x.get('seeders', 0))
        elif sort_by == 'promotion':
            rows.sort(key=lambda x: (-x.get('promo_rank', 0), -x.get('seeders', 0)))
        else:
            rows.sort(key=lambda x: -x.get('seeders', 0))
        return {'ok': True, 'msg': '「%s」命中 %d 个种子' % (kw, len(rows)),
                'data': rows[:80], 'total': len(rows)}
    if act == 'refresh_subs':
        r = mp_call('/api/v1/subscribe/refresh', 'GET')
        if not r['ok']:
            r = mp_call('/api/v1/system/refresh', 'GET')
        return {'ok': r['ok'], 'msg': '已触发订阅刷新' if r['ok'] else r.get('msg')}
    if act in ('sub_pause', 'sub_resume', 'sub_delete'):
        if not arg:
            return {'ok': False, 'msg': '缺少订阅 id'}
        if act == 'sub_delete':
            r = mp_call('/api/v1/subscribe/%s' % arg, 'DELETE')
        else:
            state = 'P' if act == 'sub_pause' else 'R'
            r = mp_call('/api/v1/subscribe/status/%s?state=%s' % (arg, state), 'PUT')
            if not r['ok']:
                r = mp_call('/api/v1/subscribe/status/%s?state=%s' % (arg, state), 'GET')
        zh = {'sub_pause': '暂停', 'sub_resume': '恢复', 'sub_delete': '删除'}
        return {'ok': r['ok'], 'msg': ('订阅已%s' % zh[act]) if r['ok'] else r.get('msg')}
    if act == 'plugins':
        # ★ 2026-10-16 修复：/api/v1/plugin/installed 返回的是**插件名字符串数组**
        #   （["DownloadSiteTag","BrushFlow",…]），不是对象数组。老代码把它当对象用
        #   p.get('id')/p.get('enabled')，于是前端永远显示「未启用」。
        #   现在逐个 GET /api/v1/plugin/{name} 拿真实 enabled 状态。
        r = mp_call('/api/v1/plugin/installed')
        names = r.get('data') if r['ok'] else []
        if isinstance(names, dict):
            names = names.get('data') or []
        if not isinstance(names, list):
            names = []
        outp = []
        for n in names:
            n = str(n)
            st = mp_call('/api/v1/plugin/%s' % n)
            en, ver = True, ""
            if st.get('ok') and isinstance(st.get('data'), dict):
                d = st['data']
                en = bool(d.get('enabled'))
                ver = str(d.get('version') or "")
            outp.append({"id": n, "name": n, "enabled": en, "version": ver})
        outp.sort(key=lambda x: (not x["enabled"], x["name"]))
        return {'ok': True, 'msg': '%d 个已安装插件（启用 %d）'
                % (len(outp), sum(1 for p in outp if p["enabled"])), 'data': outp}
    if act in ('plugin_toggle', 'plugin_delete', 'plugin_install'):
        if not arg:
            return {'ok': False, 'msg': '缺少插件参数'}
        if act == 'plugin_toggle':
            pid = arg.get('plugin') if isinstance(arg, dict) else arg
            want = arg.get('enabled', True)
            if isinstance(arg, dict) and 'status' in arg and 'enabled' not in arg:
                want = str(arg.get('status')) not in ('0', 'false', 'False')
            else:
                want = bool(want)
            # ★ 2026-10-16 修复：MP 的启停端点是 PUT /api/v1/plugin/{name} + body。
            #   老代码打 /api/v1/plugin/status?plugin=x&status=1（query 传参），
            #   MP 直接回 422 {"location":["body"],"error_type":"missing"}。
            #   注意：不能只传 {"enabled":x}，会把 show_sidebar_nav 等配置清掉，
            #   所以先读回原配置再整体 PUT 回去（见下）。
            cur = mp_call('/api/v1/plugin/%s' % pid)
            payload = dict(cur.get('data')) if (
                cur.get('ok') and isinstance(cur.get('data'), dict)) else {}
            payload['enabled'] = want
            r = mp_call('/api/v1/plugin/%s' % pid, 'PUT', payload)
            return {'ok': r['ok'],
                    'msg': ('插件 %s 已%s' % (pid, '启用' if want else '停用')
                            if r['ok'] else r.get('msg'))}
        if act == 'plugin_delete':
            pid = arg.get('plugin') if isinstance(arg, dict) else arg
            r = mp_call('/api/v1/plugin/delete?plugin=%s' % pid, 'POST')
            return {'ok': r['ok'], 'msg': ('已删除插件 %s' % pid) if r['ok'] else r.get('msg')}
        if act == 'plugin_install':
            ad = arg if isinstance(arg, dict) else {}
            pid = ad.get('plugin', arg)
            repo = ad.get('repo', 'builtin')
            r = mp_call('/api/v1/plugin/install', 'POST', {'plugin': pid, 'repo': repo})
            return {'ok': r['ok'], 'msg': ('已安装插件 %s' % pid) if r['ok'] else r.get('msg')}
    return {'ok': False, 'msg': '未实现：mp/%s' % act}


def qb_login():
    """qBittorrent 登录。成功返回 (cookie, None)；失败返回 (None, 错误dict)。

    注意：qB /api/v2/auth/login 成功时返回 HTTP 200 + body 'Ok.'，
    部分版本返回 204 空体，此时凭 Set-Cookie 判断。
    """
    c = cfg()
    u, pw = c.get('qb_user', ''), c.get('qb_pass', '')
    if not u or not pw:
        return None, {'ok': False, 'msg': '需要 qBittorrent 用户名/密码（凭据页填写）'}
    base = containers()['qbittorrent']
    body = urllib.parse.urlencode({'username': u, 'password': pw})
    ref = 'http://%s:%s' % (base['addr'], base['port'])
    try:
        conn = http.client.HTTPConnection(base['addr'], base['port'], timeout=10)
        conn.request('POST', '/api/v2/auth/login', body,
                     {'Content-Type': 'application/x-www-form-urlencoded',
                      'Referer': ref, 'Origin': ref})
        r = conn.getresponse()
        raw = r.read().decode('utf-8', 'ignore')
        # 一个响应可能有多个 Set-Cookie 头，必须全部取出
        all_cookies = r.headers.get_all('Set-Cookie') or []
        st = r.status
        conn.close()
    except Exception as e:
        return None, {'ok': False, 'msg': 'qB 连接失败：%s' % e}

    if st == 403:
        return None, {'ok': False, 'msg': 'qB 拒绝登录：IP 被临时封禁（连续失败过多）。'
                                          '可在 qB 的「选项→WebUI→失败次数/封禁时长」放宽，或重启 qB 容器解除'}
    if 'Fails' in raw or 'banned' in raw.lower():
        return None, {'ok': False, 'msg': 'qB 登录失败：账号密码错误或已被临时封禁'}
    joined = '; '.join(all_cookies)
    # qB 4.x 用 SID，qB 5.x 用 QBT_SID_<port>，两种都要认
    m = re.search(r'(QBT_SID_\d+|SID)=([^;]+)', joined)
    if m:
        return '%s=%s' % (m.group(1), m.group(2)), None
    if raw.strip() in ('Ok.', 'Ok') or st in (200, 204):
        # 有些版本不返回 Set-Cookie，会话绑定来源 IP，后续不带 Cookie 也可鉴权
        return '', None
    return None, {'ok': False, 'msg': 'qB 登录异常：HTTP %s %s' % (st, raw[:80])}


# ═══════════════════════════════════════════════════════════════════
# ★ 2026-10-18 BUG-003 修复：qBittorrent 5.x 起 /torrents/pause|resume
#   已被废弃并返回 404，取而代之的是 /torrents/stop|start。
#   实机（qB v5.2.3）验证：pause → 404「端点不存在」，stop → 200。
#   这里做版本探测 + 双端点自动回退，保证 4.x/5.x 都能用。
# ═══════════════════════════════════════════════════════════════════
_QB_VER_CACHE = {'ver': '', 'ts': 0.0}


def qb_version(force=False, cookie=None):
    """探测 qB 版本（带 5 分钟缓存）。失败返回空串。

    ★ 2026-10-19 修复「批量暂停/恢复全部 403 Forbidden」的真因：
      qBittorrent 5.x 开了 CSRF 防护，**不带 Cookie 的请求直接 403**，
      且连续 403 会被计入 IP 失败次数、触发临时封禁 → 之后连带正确
      Cookie 的 pause/resume/stop 也一起 403，表现为「所有批量操作失效」。
      老代码这里 qb_call('GET','/api/v2/app/version') 没传 cookie，
      每次 _qb_major() 都白送一个 403。现在强制带登录态探测。
    """
    now = time.time()
    if not force and _QB_VER_CACHE['ver'] and now - _QB_VER_CACHE['ts'] < 300:
        return _QB_VER_CACHE['ver']
    ck = cookie
    if not ck:
        ck, err = qb_login()
        if err:
            return _QB_VER_CACHE['ver']
    st, b = qb_call('GET', '/api/v2/app/version', None, ck)
    if st == 200 and b and b[0].isdigit():
        _QB_VER_CACHE['ver'] = b.strip()
        _QB_VER_CACHE['ts'] = now
        return _QB_VER_CACHE['ver']
    return _QB_VER_CACHE['ver']


def _qb_major(cookie=None):
    """qB 主版本号。探测不到时**默认按 5.x 新 API（stop/start）**。

    ★ 2026-10-19：老代码失败返回 0 → order 变成 [pause, stop]，
      先送一个 404 再回退，既慢又可能触发 CSRF 计数。现在默认 5。
    """
    v = qb_version(cookie=cookie) or ''
    try:
        n = int(v.split('.')[0])
        return n if n > 0 else 5
    except Exception:
        return 5


def qb_pause(hashes, cookie=None):
    """暂停种子。hashes 为 str（'|' 分隔或 'all'）或 list。
    返回 (http_status, body, used_path)。自动在 stop/pause 间回退。"""
    if isinstance(hashes, (list, tuple, set)):
        hs = '|'.join(str(h) for h in hashes)
    else:
        hs = str(hashes or '')
    if not hs:
        return 0, '', ''
    # ★ 2026-10-19：没带 cookie 就自己登一个（老代码靠调用方传，
    #   漏传时请求无 Cookie → qB 5.x CSRF 403 → 批量操作「看起来失效」）
    if not cookie:
        cookie, err = qb_login()
        if err:
            return 0, '', ''
    major = _qb_major(cookie)
    order = ['/api/v2/torrents/stop', '/api/v2/torrents/pause'] if major >= 5 \
        else ['/api/v2/torrents/pause', '/api/v2/torrents/stop']
    last = (0, '', '')
    for attempt in (0, 1):
        for path in order:
            st, b = qb_call('POST', path, {'hashes': hs}, cookie)
            last = (st, b, path)
            if st == 200:
                return last
            # 403：会话可能过期/IP 被临时限流 —— 重新登录再试一次
            if st == 403 and attempt == 0:
                cookie, err = qb_login()
                if err:
                    break
                break
        else:
            continue
        if st == 200:
            return last
    return last


def qb_resume(hashes, cookie=None):
    """恢复种子。同 qb_pause 的版本兼容逻辑（start/resume）。"""
    if isinstance(hashes, (list, tuple, set)):
        hs = '|'.join(str(h) for h in hashes)
    else:
        hs = str(hashes or '')
    if not hs:
        return 0, '', ''
    if not cookie:
        cookie, err = qb_login()
        if err:
            return 0, '', ''
    major = _qb_major(cookie)
    order = ['/api/v2/torrents/start', '/api/v2/torrents/resume'] if major >= 5 \
        else ['/api/v2/torrents/resume', '/api/v2/torrents/start']
    last = (0, '', '')
    for attempt in (0, 1):
        for path in order:
            st, b = qb_call('POST', path, {'hashes': hs}, cookie)
            last = (st, b, path)
            if st == 200:
                return last
            if st == 403 and attempt == 0:
                cookie, err = qb_login()
                if err:
                    break
                break
        else:
            continue
        if st == 200:
            return last
    return last


def qb_call(method, path, params=None, cookie=None, t=12):
    base = containers()['qbittorrent']
    body = urllib.parse.urlencode(params) if params else None
    hdr = {'Content-Type': 'application/x-www-form-urlencoded',
           'Referer': 'http://%s:%s' % (base['addr'], base['port'])}
    if cookie:
        hdr['Cookie'] = cookie
    return hreq(base['addr'], base['port'], method, path, body, hdr, t)


def act_qb(act, arg):
    # 通用容器操作直接放行，不需要 qB 凭据
    # ★ 2026-10-24：补 inspect / files（docker.sock 读详情/挂载点），消除「未实现」。
    if act in ('logs', 'stats', 'state', 'start', 'stop', 'restart', 'inspect', 'files'):
        return act_generic('qbittorrent', act, arg)
    cookie, err = qb_login()
    if err:
        return err
    if act == 'status':
        st, b = qb_call('GET', '/api/v2/transfer/info', cookie=cookie)
        if st != 200:
            return {'ok': False, 'msg': '读取传输状态失败 HTTP %s' % st}
        try:
            j = json.loads(b)
        except Exception:
            return {'ok': False, 'msg': '返回非 JSON'}
        return {'ok': True, 'msg': '%s · 下载限速 %s · 上传限速 %s' % (
            j.get('connection_status'), j.get('dl_rate_limit'), j.get('up_rate_limit')),
            'data': {'conn': j.get('connection_status'), 'dl_speed': j.get('dl_info_speed'),
                     'up_speed': j.get('up_info_speed'), 'dl_limit': j.get('dl_rate_limit'),
                     'up_limit': j.get('up_rate_limit'), 'dht': j.get('dht_nodes')}}
    if act == 'torrents':
        st, b = qb_call('GET', '/api/v2/torrents/info', cookie=cookie)
        if st != 200:
            return {'ok': False, 'msg': '读取种子失败 HTTP %s' % st}
        try:
            js = json.loads(b)
        except Exception:
            return {'ok': False, 'msg': '返回非 JSON'}
        out = []
        for t in js:
            out.append({'hash': t.get('hash'), 'name': t.get('name'), 'state': t.get('state'),
                        'size': t.get('size'), 'total_size': t.get('total_size'),
                        'progress': round((t.get('progress') or 0) * 100, 1),
                        'dlspeed': t.get('dlspeed'), 'upspeed': t.get('upspeed'),
                        'eta': t.get('eta'), 'category': t.get('category'),
                        'save_path': t.get('save_path'), 'ratio': t.get('ratio'),
                        'num_seeds': t.get('num_seeds'), 'num_leech': t.get('num_leech'),
                        'added_on': t.get('added_on'), 'completion_on': t.get('completion_on'),
                        'last_activity': t.get('last_activity'),
                        'total_uploaded': t.get('total_uploaded'),
                        'time_active': t.get('time_active'),
                        'availability': t.get('availability'),
                        'dl_limit': t.get('dl_limit'), 'up_limit': t.get('up_limit'),
                        'seen_complete': t.get('seen_complete'), 'private': t.get('private')})
        return {'ok': True, 'msg': '%d 个种子' % len(out), 'data': out}
    if act == 'torrent_detail':
        h = (arg or {}).get('hash') if isinstance(arg, dict) else (arg or '')
        if not h:
            return {'ok': False, 'msg': '缺少种子 hash'}
        res = {'ok': True, 'hash': h, 'props': {}, 'trackers': [], 'files': [], 'peers': []}
        for path, key in (('/api/v2/torrents/properties', 'props'),
                          ('/api/v2/torrents/trackers', 'trackers'),
                          ('/api/v2/torrents/files', 'files'),
                          ('/api/v2/torrents/peers', 'peers')):
            st, b = qb_call('GET', path + '?hash=' + h, cookie=cookie)
            try:
                j = json.loads(b) if st == 200 else None
            except Exception:
                j = None
            if key == 'trackers' and isinstance(j, list):
                res['trackers'] = [{'url': t.get('url'), 'status': t.get('status'),
                                    'num_peers': t.get('num_peers'), 'msg': t.get('msg')} for t in j][:12]
            elif key == 'files' and isinstance(j, list):
                res['files'] = [{'name': f.get('name'), 'size': f.get('size'),
                                 'progress': round((f.get('progress') or 0) * 100, 1),
                                 'priority': f.get('priority')} for f in j][:30]
            elif key == 'peers' and isinstance(j, list):
                res['peers'] = [{'ip': p.get('ip'), 'client': p.get('client'),
                                 'dl': p.get('down_speed'), 'up': p.get('up_speed')} for p in j][:20]
            elif key == 'props' and isinstance(j, dict):
                res['props'] = {k: j.get(k) for k in
                                ('name', 'save_path', 'total_size', 'total_uploaded',
                                 'ratio', 'seeding_time', 'time_active', 'availability',
                                 'dl_limit', 'up_limit', 'last_seen_complete')}
        return res
    if act in ('pause_all', 'resume_all'):
        # ★ BUG-003：qB 5.x 起 pause/resume 已 404，必须走 stop/start（见 qb_pause/qb_resume）
        st, _b, used = (qb_pause('all', cookie) if act == 'pause_all'
                        else qb_resume('all', cookie))
        return {'ok': st == 200,
                'msg': ('已%s全部种子' % ('暂停' if act == 'pause_all' else '恢复'))
                       if st == 200 else
                       ('操作失败：qB 返回 HTTP %s（%s）' % (st, used or '未知端点'))}
    if act in ('pause_one', 'resume_one', 'delete_one'):
        if not arg:
            return {'ok': False, 'msg': '缺少种子 hash'}
        if act == 'delete_one':
            st, b = qb_call('POST', '/api/v2/torrents/delete', {'hashes': arg, 'deleteFiles': 'false'}, cookie)
            return {'ok': st < 400, 'msg': '已删除该任务（保留下载文件）'}
        st, _b, used = (qb_pause(arg, cookie) if act == 'pause_one'
                        else qb_resume(arg, cookie))
        return {'ok': st == 200,
                'msg': ('任务已%s' % ('暂停' if act == 'pause_one' else '恢复'))
                       if st == 200 else
                       ('操作失败：qB 返回 HTTP %s（%s）' % (st, used or '未知端点'))}
    if act == 'limits':
        dl = int((arg or {}).get('dl', 0)) if isinstance(arg, dict) else int(arg or 0)
        up = int((arg or {}).get('up', 0)) if isinstance(arg, dict) else 0
        qb_call('POST', '/api/v2/transfer/setDownloadLimit', {'limit': dl}, cookie)
        qb_call('POST', '/api/v2/transfer/setUploadLimit', {'limit': up}, cookie)
        return {'ok': True, 'msg': '下载限速 %s B/s，上传限速 %s B/s' % (dl or '不限', up or '不限')}
    if act == 'reannounce':
        st, b = qb_call('POST', '/api/v2/torrents/reannounce', {'hashes': 'all'}, cookie)
        return {'ok': st < 400, 'msg': '已向全部种子重新汇报'}
    if act == 'add':
        urls = (arg or {}).get('urls') if isinstance(arg, dict) else (arg or '')
        if isinstance(urls, list):
            urls = '\n'.join(urls)
        if not urls or not urls.strip():
            return {'ok': False, 'msg': '请填写磁力链接 / 种子 URL（每行一个）'}
        params = {'urls': urls}
        if isinstance(arg, dict):
            if arg.get('category'):
                params['category'] = arg['category']
            if arg.get('savepath'):
                params['savepath'] = arg['savepath']
        st, b = qb_call('POST', '/api/v2/torrents/add', params, cookie)
        return {'ok': st < 400, 'msg': '已提交添加（HTTP %s）' % st}
    if act == 'batch_pause':
        hs = (arg or {}).get('hashes') if isinstance(arg, dict) else arg
        if not hs:
            return {'ok': False, 'msg': '未选择种子'}
        n = len(hs) if isinstance(hs, list) else 1
        st, _b, used = qb_pause(hs, cookie)
        return {'ok': st == 200,
                'msg': ('已暂停 %s 个' % n) if st == 200 else
                       ('暂停失败：qB 返回 HTTP %s（%s），未暂停任何任务'
                        % (st, used or '未知端点'))}
    if act == 'batch_resume':
        hs = (arg or {}).get('hashes') if isinstance(arg, dict) else arg
        if not hs:
            return {'ok': False, 'msg': '未选择种子'}
        n = len(hs) if isinstance(hs, list) else 1
        st, _b, used = qb_resume(hs, cookie)
        return {'ok': st == 200,
                'msg': ('已恢复 %s 个' % n) if st == 200 else
                       ('恢复失败：qB 返回 HTTP %s（%s），未恢复任何任务'
                        % (st, used or '未知端点'))}
    if act == 'set_category':
        hs = (arg or {}).get('hashes'); cat = (arg or {}).get('category') or ''
        if not hs:
            return {'ok': False, 'msg': '未选择种子'}
        st, b = qb_call('POST', '/api/v2/torrents/setCategory',
                        {'hashes': "|".join(hs) if isinstance(hs, list) else hs,
                         'category': cat}, cookie)
        return {'ok': st < 400, 'msg': '分类已设为 %s' % cat}
    if act == 'rename':
        h = (arg or {}).get('hash'); name = (arg or {}).get('name')
        if not h or not name:
            return {'ok': False, 'msg': '缺 hash/name'}
        st, b = qb_call('POST', '/api/v2/torrents/setName',
                        {'hash': h, 'name': name}, cookie)
        return {'ok': st < 400, 'msg': '已重命名' if st < 400 else 'HTTP %s' % st}
    if act == 'top_priority' or act == 'queue_top':
        hs = (arg or {}).get('hashes') if isinstance(arg, dict) else arg
        if not hs:
            return {'ok': False, 'msg': '未选择种子'}
        ok = True; msgs = []
        for h in (hs if isinstance(hs, list) else [hs]):
            st, b = qb_call('POST', '/api/v2/torrents/increasePrio', {'hash': h}, cookie)
            ok = ok and st < 400
        return {'ok': ok, 'msg': '已提高到队列顶部（重做种优先）'}
    if act == 'batch_delete':
        hs = (arg or {}).get('hashes'); rmf = bool((arg or {}).get('delete_files'))
        if not hs:
            return {'ok': False, 'msg': '未选择种子'}
        st, b = qb_call('POST', '/api/v2/torrents/delete',
                        {'hashes': "|".join(hs) if isinstance(hs, list) else hs,
                         'deleteFiles': 'true' if rmf else 'false'}, cookie)
        return {'ok': st < 400, 'msg': '已删除 %d 个%s' % (
            len(hs) if isinstance(hs, list) else 1, '（含文件）' if rmf else '（保留文件）')}
    return {'ok': False, 'msg': '未实现：qb/%s' % act}


def act_cd2(act, arg):
    if act == 'status':
        fuse = os.path.isdir(os.path.join(MOUNT, VROOT))
        api = probe(containers()['clouddrive2']['addr'], containers()['clouddrive2']['port'], '/', 5)
        cs = ctr_state('clouddrive2')
        return {'ok': True, 'msg': 'CD2 容器 %s · API HTTP %s · FUSE %s' % (
            cs.get('state'), api, '正常' if fuse else '异常'),
            'data': {'state': cs.get('state'), 'api': api, 'fuse': fuse,
                     'image': cs.get('image'), 'restarts': cs.get('restarts')}}
    if act == 'rate_down':
        return repair('cd2_rate_down')
    if act == 'rate_up':
        return repair('cd2_rate_up')
    if act == 'clear_cache':
        return repair('cd2_cache')
    if act == 'read_rate':
        paths = [CD2_CFG, '/cd2config/cloudapidata.json',
                 '/vol1/1000/docker/clouddrive2/config/cloudapidata.json',
                 '/dockroot/clouddrive2/config/cloudapidata.json']
        real = next((p for p in paths if os.path.exists(p)), None)
        if not real:
            return {'ok': False, 'msg': '未找到 CD2 配置文件，已尝试：%s' % ', '.join(paths[:3]),
                    'detail': 'CD2_CFG=%s' % CD2_CFG}
        try:
            d = json.load(open(real, encoding='utf-8'))
            if isinstance(d, dict):
                d = [d]
            v = None
            for x in d:
                if isinstance(x, dict) and isinstance(x.get('downloader_config'), dict):
                    v = x['downloader_config'].get('max_queries_per_second')
            return {'ok': True, 'msg': '当前 max_queries_per_second = %s' % v,
                    'data': {'rate': v, 'file': real}}
        except Exception as e:
            return {'ok': False, 'msg': '读取 CD2 配置失败：%s' % e}
    if act == 'restart_container':
        return ctr_action('clouddrive2', 'restart')
    if act == 'fuse_check':
        p = os.path.join(MOUNT, VROOT)
        ok = os.path.isdir(p)
        try:
            n = len(os.listdir(p)) if ok else 0
        except Exception:
            n = -1
        return {'ok': ok, 'msg': 'FUSE %s，%s 下 %d 项' % ('可读' if ok else '不可读', VROOT, n)}
    # logs / stats / state / start / stop / restart
    return act_generic('clouddrive2', act, arg)


def act_mt(act, arg):
    if act == 'scan':
        f, sk = scan(2, 1)
        return {'ok': True, 'msg': '发现 %d 个可接入目录，%d 个已跳过' % (len(f), len(sk)),
                'data': {'found': f, 'skipped': sk}}
    if act == 'status':
        ts = tasks()
        try:
            with db() as c:
                tstat = {r['status']: r['n'] for r in c.execute(
                    "SELECT status,count(*) n FROM organize_tasks GROUP BY status")}
        except Exception:
            tstat = {}
        cs = ctr_state('mediatidy')
        return {'ok': True, 'msg': 'MediaTidy %s · %d 个方案（%d 启用）· 记录 %d' % (
            cs.get('state'), len(ts), sum(1 for t in ts if t.get('enabled')), rec_count()),
            'data': {'state': cs.get('state'), 'tasks': len(ts),
                     'enabled': sum(1 for t in ts if t.get('enabled')), 'status': tstat}}
    m = {'unblock': 'unblock', 'rotate_log': 'rotate_log', 'vacuum': 'vacuum',
         'clean_zombie': 'clean_zombie'}
    if act in m:
        return repair(m[act])
    # 其余（logs/stats/state/start/stop/restart）交给通用容器操作
    return act_generic('mediatidy', act, arg)


def tstat_str():
    try:
        with db() as c:
            d = {r['status']: r['n'] for r in c.execute(
                "SELECT status,count(*) n FROM organize_tasks GROUP BY status")}
        return ', '.join('%s=%s' % (k, v) for k, v in sorted(d.items())) or '空'
    except Exception as e:
        return '读取失败 %s' % e


# ══════════ MT 任务控制 / 字幕同步 / TMDB 预重命名 ══════════
# ★★ v1.37 S1：MT 地址/账号、TMDB 代理全部可由设置页覆盖（多租户零配置）。
#   环境变量仍是第一优先级（docker-compose 里写死的人不受影响），其后才是 cfg()，
#   最后才是默认值。⚠ 这三个在大量函数里被直接引用，所以保留同名模块级变量作
#   初值，同时提供 _mt_base()/_tmdb_proxy() 动态 getter，热路径改走 getter。
# ★★ v1.38 A5 开源零配置：默认值全部留空（作者环境由 webcfg.json /
#   docker-compose 环境变量持久化，不受影响）。新装用户在 Setup Wizard
#   或「设置 → MediaTidy 与 TMDB 代理」里填自己的。
MT_BASE = os.environ.get('MT_BASE', '')
MT_USER = os.environ.get('MP_USER', '')
MT_PASS = os.environ.get('MP_PASS', '')
TMDB_PROXY = os.environ.get('TMDB_PROXY', '')


def mt_base():
    """生效的 MediaTidy 地址（设置页可改，改完即时生效）。"""
    v = (cfg().get('mt_base') or '').strip()
    if v:
        return v.rstrip('/')
    return MT_BASE.rstrip('/')


def mt_user_pass():
    """生效的 MT 登录账号（设置页可改）。"""
    c = cfg()
    u = (c.get('mt_user') or '').strip()
    p = (c.get('mt_pass') or '').strip()
    return (u or MT_USER, p or MT_PASS)


def _mt_sys_proxy():
    """从 MediaTidy 的 system.proxy 推导代理地址（★ V1.39 A6 开源零配置）。

    别人的 NAS 上，TMDB 代理几乎总是配在 MT 里（不配 TMDB 就没法识别）。
    所以面板侧的兜底顺序必须是：面板设置 → 环境变量 → MT 代理 → 空串。
    空串在 NAS 上等于直连，而 api.themoviedb.org 直连基本不通
    （本轮实测 Network unreachable），表现为「求片全 0 条」。
    """
    try:
        p = mt_sys_cfg().get('proxy') or {}
        if not p.get('enabled'):
            return ''
        host = (p.get('host') or '').strip()
        if not host:
            return ''
        port = int(p.get('port') or 7890)
        typ = (p.get('type') or 'http').strip().lower()
        if typ not in ('http', 'https'):
            typ = 'http'
        auth = ''
        u = (p.get('username') or '').strip()
        pw = (p.get('password') or '').strip()
        if u:
            auth = u + (':' + pw if pw else '') + '@'
        return '%s://%s%s:%d' % (typ, auth, host, port)
    except Exception:
        return ''


def tmdb_proxy():
    """生效的 TMDB 代理地址（设置页可改）。★ V1.39 A6 兜底链见 _mt_sys_proxy。"""
    v = (cfg().get('tmdb_proxy') or '').strip()
    if v:
        return v
    if (TMDB_PROXY or '').strip():
        return TMDB_PROXY.strip()
    return _mt_sys_proxy()


def tmdb_proxy_src():
    """当前生效 TMDB 代理的来源（'user' / 'env' / 'mt' / ''），供设置页展示。"""
    if (cfg().get('tmdb_proxy') or '').strip():
        return 'user'
    if (TMDB_PROXY or '').strip():
        return 'env'
    if _mt_sys_proxy():
        return 'mt'
    return ''


_SUB_EXT = ('.srt', '.ass', '.ssa', '.sub', '.sup', '.idx', '.vtt')
_VID_EXT = ('.mkv', '.mp4', '.ts', '.m2ts', '.avi', '.rmvb', '.mov', '.wmv', '.flv', '.iso')
_MT_TOK = {'v': None, 't': 0}


def mt_token(force=False):
    """登录 MediaTidy 拿 JWT，缓存 30 分钟。"""
    now = time.time()
    if not force and _MT_TOK['v'] and now - _MT_TOK['t'] < 1800:
        return _MT_TOK['v']
    _u, _p = mt_user_pass()
    u = urllib.parse.urlparse(mt_base())
    st, txt = hreq(u.hostname, u.port or 80, 'POST', '/api/auth/login',
                   json.dumps({'username': _u, 'password': _p}),
                   {'Content-Type': 'application/json'}, 15)
    try:
        _MT_TOK['v'] = json.loads(txt)['data']['token']
        _MT_TOK['t'] = now
        return _MT_TOK['v']
    except Exception:
        return None


def mt_api(method, path, payload=None, t=20):
    """调用 MT 的 HTTP API。401 自动重登一次。"""
    u = urllib.parse.urlparse(mt_base())
    for i in range(2):
        tok = mt_token(force=(i > 0))
        body = json.dumps(payload, ensure_ascii=False) if payload is not None else None
        st, txt = hreq(u.hostname, u.port or 80, method, path, body,
                       {'Content-Type': 'application/json',
                        'Authorization': 'Bearer ' + (tok or '')}, t)
        if st == 401 and i == 0:
            continue
        try:
            return st, json.loads(txt)
        except Exception:
            return st, {'raw': txt[:300]}
    return -1, {}


def mt_task_list(limit=80):
    """任务列表。直接读本地库：比走 MT API 快，也不依赖 token。"""
    out = []
    try:
        with db() as c:
            for r in c.execute(
                    "SELECT id,profile_id,status,trigger_kind,total_files,done_files,"
                    "skipped_files,error_files,source_dir,started_at,finished_at "
                    "FROM organize_tasks ORDER BY id DESC LIMIT ?", (int(limit),)):
                d = dict(r)
                st, fi = d.get('started_at') or '', d.get('finished_at') or ''
                d['elapsed'] = 0
                if st and not fi:
                    try:
                        d['elapsed'] = int(time.time() - time.mktime(
                            time.strptime(st[:19], '%Y-%m-%d %H:%M:%S')))
                    except Exception:
                        d['elapsed'] = 0
                out.append(d)
    except Exception as e:
        return {'ok': False, 'msg': str(e)[:200], 'items': []}
    run = [x for x in out if x['status'] == 'running']
    return {'ok': True, 'items': out, 'running': len(run),
            'summary': {'running': len(run),
                        'done': sum(1 for x in out if x['status'] == 'done'),
                        'cancelled': sum(1 for x in out if x['status'] == 'cancelled'),
                        'interrupted': sum(1 for x in out if x['status'] == 'interrupted')}}


def mt_task_stop(ids, close_schemes=None):
    """停止整理任务（★ 2026-11-03 可靠版重写）。

    实测双重根因（这就是官方 UI「关不掉」的真相）：
      ① MT 原生 POST /api/tasks/cancel/{队列ID} 对运行中的整理任务是**假成功**
         —— 回 code=0 "cancel requested"，但任务照常推进（实测 #1785）；
      ② MT 运行中只改库，进程会持续把状态写回。
    所以唯一可靠路径 = **停 MT → 改库 → 启 MT**（整程 5~8 秒）。

    close_schemes：一并强关方案（config.enabled=0、realtimeMode=off），
    防止停完 60 秒后轮询入口又把任务自动重开。
    """
    ids = [int(x) for x in (ids or [])]
    cs = [int(x) for x in (close_schemes or [])]
    if not ids and not cs:
        return {'ok': False, 'msg': '未指定任务或方案'}
    L = []
    with LOCK:
        st = db_stop_mt()
        L.append('  停 MediaTidy：%s' % (st.get('msg') if isinstance(st, dict) else st))
        time.sleep(1.2)
        try:
            with db() as c:
                for i in ids:
                    b = c.execute("SELECT status FROM organize_tasks WHERE id=?", (i,)).fetchone()
                    c.execute("UPDATE organize_tasks SET status='cancelled', "
                              "finished_at=datetime('now'), "
                              "error_log=IFNULL(error_log,'')||' | 面板强制停止' "
                              "WHERE id=? AND status IN ('running','pending')", (i,))
                    a = c.execute("SELECT status FROM organize_tasks WHERE id=?", (i,)).fetchone()
                    L.append('  任务#%d  %s → %s' % (i, (b or {}).get('status', '?') if b else '?',
                                                     a[0] if a else '?'))
                for sid in cs:
                    row = c.execute("SELECT name,config FROM scheduled_jobs WHERE id=?", (sid,)).fetchone()
                    if not row:
                        L.append('  方案#%d 不存在' % sid)
                        continue
                    j = json.loads(row['config'])
                    j['enabled'] = False
                    j['realtimeMode'] = 'off'
                    c.execute("UPDATE scheduled_jobs SET config=?, updated_at=datetime('now') WHERE id=?",
                              (json.dumps(j, ensure_ascii=False), sid))
                    L.append('  方案#%d「%s」强关 enabled=0 rt=off' % (sid, (row['name'] or '')[:24]))
                c.commit()
                ic = c.execute('PRAGMA integrity_check').fetchone()[0]
        except Exception as e:
            db_start_mt()
            return {'ok': False, 'msg': '改库失败：%s' % str(e)[:200], 'detail': '\n'.join(L)}
        db_flush()
        # 回读校验：启 MT 前确认落库
        drift = []
        try:
            with db() as c:
                for sid in cs:
                    r = c.execute("SELECT config FROM scheduled_jobs WHERE id=?", (sid,)).fetchone()
                    if r and json.loads(r[0]).get('enabled'):
                        drift.append(sid)
                for i in ids:
                    r = c.execute("SELECT status FROM organize_tasks WHERE id=?", (i,)).fetchone()
                    if r and r[0] in ('running', 'pending'):
                        drift.append('task#%d' % i)
        except Exception:
            pass
        db_start_mt()
    msg = ('已停止 %d 个任务' % len(ids) if ids else '') + \
          ('，强关 %d 个方案' % len(cs) if cs else '')
    if drift:
        msg += '；⚠ 回读异常 %s' % drift
    oplog('mt', 'task_stop', msg or '停止/强关', not drift, '停MT→改库→启MT')
    return {'ok': not drift, 'msg': msg or '完成',
            'detail': '\n'.join(L) + '\n  integrity=%s | MediaTidy 已重启' % ic}


def mt_task_start_scan(profile_key=None):
    """启动整理。MT 没有"立即扫描"的接口，这里用「重启 MT」触发它的 Poller 重新扫描，
    或对单个 profile 重新打开 realtimeMode。"""
    with LOCK:
        L = []
        if profile_key:
            try:
                with db() as c:
                    row = c.execute("SELECT config FROM scheduled_jobs WHERE key=?",
                                    (profile_key,)).fetchone()
                if not row:
                    return {'ok': False, 'msg': '方案不存在：%s' % profile_key}
                cfg = json.loads(row['config'])
                cfg['realtimeMode'] = 'polling'
                cfg['enabled'] = True
                with db() as c:
                    c.execute("UPDATE scheduled_jobs SET config=?, updated_at=datetime('now') "
                              "WHERE key=?", (json.dumps(cfg, ensure_ascii=False), profile_key))
                    c.commit()
                L.append('  %s 已置为 realtimeMode=polling' % profile_key)
            except Exception as e:
                return {'ok': False, 'msg': '改方案失败：%s' % str(e)[:200]}
        r = ctr_action(MT_CT, 'restart')
        L.append('  重启 MediaTidy：%s' % r.get('msg'))
        L.append('  Poller 将在启动后自动扫描所有 polling 方案')
    oplog('mt', 'task_start', '启动整理 %s' % (profile_key or '(全量)'), True, '已重启 MT')
    return {'ok': True, 'msg': '已触发整理扫描', 'detail': '\n'.join(L)}


def mt_manual(source_dir, tmdb_id, media_type, profile_id=None):
    """按 TMDB ID 强制提交识别（对应 MT 的 /api/organize/manual）。
    这是绕过 MT 自动识别、直接指定作品身份的唯一途径。"""
    # 默认 profile 与整理模板保持一致（RT离线 organize:356）
    pid = profile_id or 356
    st, j = mt_api('POST', '/api/organize/manual',
                   {'profileId': int(pid), 'sourceDir': source_dir,
                    'tmdbId': int(tmdb_id), 'mediaType': media_type}, 60)
    ok = isinstance(j, dict) and j.get('code') == 0
    return {'ok': ok, 'http': st, 'msg': (j.get('message') if isinstance(j, dict) else str(j))[:300],
            'task': (j.get('data') or {}).get('id') if ok else None}


# ── 字幕与视频配对 ──
_LANG_TAG = re.compile(
    r'[\._\-\s]*(简体&英文|繁体&英文|简英双语|繁英双语|简体|繁体|简英|繁英|中英|中字|双语|'
    r'chs|cht|sc|tc|zh|chi|zho|eng|english|jpn|japanese)([\._\-\s&]+(简体|繁体|chs|cht|sc|tc|'
    r'eng|english))*$', re.I)


def _split_ext(name):
    """安全剥离扩展名。

    坑：os.path.splitext('A24.儿童学习单词 Abadas【BBC系列】') 会返回
    ('A24', '.儿童学习单词 Abadas【BBC系列】') —— 它把点后面的中文当成扩展名，
    标题被整个吃掉。这里只认「.xxx」形式的短扩展名。
    """
    m = re.search(r'(\.[A-Za-z0-9]{1,6})$', name or '')
    if m:
        return name[:m.start()], m.group(1)
    return name or '', ''


def _stem_key(s):
    b = _split_ext(os.path.basename(s))[0]
    b = _LANG_TAG.sub('', b)
    return re.sub(r'[^a-z0-9]', '', b.lower())


def _ep_of(name):
    m = re.search(r'S(\d{1,2})\s*E(\d{1,3})', name, re.I)
    if m:
        return int(m.group(1)), int(m.group(2))
    m = re.search(r'第\s*(\d{1,3})\s*[集话話]', name)
    if m:
        return 1, int(m.group(1))
    return None, None


def _lang_suffix(name):
    b = os.path.basename(name)
    for tag in ('简体&英文', '繁体&英文', '简英双语', '繁英双语', '简体', '繁体',
                '简英', '繁英', '中英', '中字', 'chs', 'cht', 'sc', 'tc'):
        if tag in b:
            return '.' + tag
    return ''


def sub_pair_plan(vdir):
    """扫描目录，为每个字幕找最匹配的视频，给出「视频-字幕」一一对应的重命名计划。

    vdir 为本地挂载路径（/vol1/1000/CloudNAS/115open/...）。
    字幕可能在同级，也可能在「字幕/」子目录里（MT 看不到子目录，这是它丢字幕的主因）。
    """
    if not os.path.isdir(vdir):
        return {'ok': False, 'msg': '目录不存在：%s' % vdir}
    vids, subs = [], []
    try:
        for e in os.scandir(vdir):
            if e.is_file():
                n = e.name
                if n.lower().endswith(_VID_EXT):
                    vids.append(n)
                elif n.lower().endswith(_SUB_EXT):
                    subs.append(n)
            elif e.is_dir() and ('字幕' in e.name or e.name.lower() in ('sub', 'subs', 'subtitle')):
                try:
                    for f in os.scandir(e.path):
                        if f.is_file() and f.name.lower().endswith(_SUB_EXT):
                            subs.append(os.path.join(e.name, f.name))
                except Exception:
                    pass
    except Exception as e:
        return {'ok': False, 'msg': '读取目录失败：%s' % str(e)[:200]}
    vids.sort()
    subs.sort()
    plan = []
    vk = {v: _stem_key(v) for v in vids}
    for s in subs:
        sk = _stem_key(s)
        best, score = None, 0.0
        for v, k in vk.items():
            if not sk or not k:
                continue
            common = 0
            for i in range(min(len(sk), len(k))):
                if sk[i] == k[i]:
                    common += 1
                else:
                    break
            r = common / max(len(k), 1)
            if k.startswith(sk[:12]) or sk.startswith(k[:12]):
                r += 0.5
            if r > score:
                best, score = v, r
        if best is None:
            se, ee = _ep_of(os.path.basename(s))
            if se is not None:
                for v in vids:
                    vs, ve = _ep_of(v)
                    if vs == se and ve == ee:
                        best, score = v, 0.9
                        break
        if best is None and len(vids) == 1:
            best, score = vids[0], 0.5
        new = None
        if best:
            new = os.path.splitext(best)[0] + _lang_suffix(s) + os.path.splitext(s)[1]
        plan.append({'sub': s, 'video': best, 'new': new, 'score': round(score, 2),
                     'need': bool(new and os.path.basename(s) != new)})
    need = [x for x in plan if x['need']]
    return {'ok': True, 'dir': vdir, 'videos': vids, 'subs': subs, 'plan': plan,
            'need_count': len(need), 'unmatched': len([x for x in plan if not x['video']])}


def sub_pair_apply(vdir, plan, dry=True):
    """执行字幕配对重命名（把字幕移到视频同级并改成与视频同名）。
    只动字幕，绝不碰视频。每步写日志，可回滚。"""
    if not os.path.isdir(vdir):
        return {'ok': False, 'msg': '目录不存在'}
    done, errs = [], []
    for it in (plan or []):
        if not it.get('need') or not it.get('new'):
            continue
        src = os.path.join(vdir, it['sub'])
        dst = os.path.join(vdir, it['new'])
        if not os.path.exists(src):
            errs.append('%s 已不存在' % it['sub'])
            continue
        if os.path.exists(dst):
            errs.append('%s 目标已存在，跳过' % it['new'])
            continue
        if dry:
            done.append({'from': it['sub'], 'to': it['new'], 'dry': True})
            continue
        try:
            shutil.move(src, dst)
            done.append({'from': it['sub'], 'to': it['new']})
            time.sleep(0.25)
        except Exception as e:
            errs.append('%s → %s 失败：%s' % (it['sub'], it['new'], str(e)[:80]))
    if not dry and done:
        oplog('sub', 'pair', '字幕配对重命名 %d 个' % len(done), True, vdir)
    return {'ok': True, 'dry': dry, 'done': done, 'errors': errs,
            'msg': '%s %d 个字幕%s' % ('预览' if dry else '已处理', len(done),
                                      ('，%d 个失败' % len(errs)) if errs else '')}


# ── TMDB 预重命名 ──
def _tmdb_get(url, t=15):
    """走代理访问 TMDB（直连 api.themoviedb.org 常不通，经 tmdb_proxy() 提供的代理）。"""
    try:
        op = urllib.request.build_opener(
            urllib.request.ProxyHandler({'http': tmdb_proxy(), 'https': tmdb_proxy()}))
        req = urllib.request.Request(url, headers={'Accept': 'application/json'})
        with op.open(req, timeout=t) as r:
            return json.load(r)
    except Exception as e:
        return {'__err': str(e)[:160],
                '__proxy': tmdb_proxy() or '(空=直连)'}


def tmdb_key():
    # ★ v1.15：用户在本面板「设置」里填的 key 优先；未填再退 MoviePilot 的 TMDB 配置。
    #   （MT 配置里那个 key 在走代理时实测 401，所以必须允许用户自带 key）
    try:
        c = cfg()
        k = (c.get('tmdb_key') or '').strip()
        if k:
            return k
    except Exception:
        pass
    try:
        # ⚠️ v1.15 修：变量名绝不能用 cfg —— 函数上方 `c = cfg()` 已把 cfg 当作
        #   局部名，一旦本块再赋值 cfg，整段都抛 UnboundLocalError 被 except 吞掉，
        #   表现为「用户填了 key 却完全读不到」。改用 mtcfg。
        mtcfg = mt_sys_cfg().get('tmdb') or {}
        return mtcfg.get('apiKey') or ''
    except Exception:
        return ''


def tmdb_key_src():
    """返回当前生效 key 的来源，供设置页展示（'user' / 'mt' / ''）。"""
    try:
        if (cfg().get('tmdb_key') or '').strip():
            return 'user'
    except Exception:
        pass
    try:
        if (mt_sys_cfg().get('tmdb') or {}).get('apiKey'):
            return 'mt'
    except Exception:
        pass
    return ''


def tmdb_key_masked():
    k = tmdb_key()
    if not k:
        return ''
    return (k[:4] + '****' + k[-4:]) if len(k) > 10 else '****'


def tmdb_probe(key=None, t=12):
    """实测 TMDB 连通性：api.tmdb.org / 代理 / image.tmdb.org 三条链路。
    返回 {ok, api, proxy, image, detail}，绝不猜。
    """
    out = {'ok': False, 'api': '', 'direct': '', 'image': '', 'detail': ''}
    k = (key or '').strip() or tmdb_key()
    if not k:
        out['detail'] = '尚未配置 TMDB API Key'
        return out
    u = 'https://api.themoviedb.org/3/configuration?api_key=' + k
    # ① 走代理访问 api.tmdb.org（_tmdb_get 固定走 TMDB_PROXY，这是日常取数链路）
    try:
        j = _tmdb_get(u, t=t)
        if isinstance(j, dict) and '__err' not in j and (j.get('images') or j.get('change_keys')):
            out['api'] = 'ok'
        else:
            out['api'] = 'fail:' + str((j or {}).get('__err') or 'no-data')[:70]
    except Exception as e:
        out['api'] = 'fail:' + str(e)[:70]
    # ② 直连 api.tmdb.org（不走代理）—— 用于判断代理是否是瓶颈
    try:
        op = urllib.request.build_opener(urllib.request.ProxyHandler({}))
        req = urllib.request.Request(u, headers={'Accept': 'application/json'})
        with op.open(req, timeout=t) as r:
            body = r.read(400)
        out['direct'] = 'ok' if b'images' in body else 'fail:no-data'
    except Exception as e:
        out['direct'] = 'fail:' + str(e)[:70]
    # ③ image.tmdb.org（实测长期稳定，与 key 无关；封面全靠它）
    try:
        op = urllib.request.build_opener(urllib.request.ProxyHandler(
            {'http': tmdb_proxy(), 'https': tmdb_proxy()}))
        req = urllib.request.Request(
            'https://image.tmdb.org/t/p/w500/1E5baAaEse26fej7uHcjOgEE2t2.jpg',
            headers={'Accept': 'image/jpeg'})
        with op.open(req, timeout=t) as r:
            out['image'] = 'ok' if r.status == 200 else 'fail:HTTP ' + str(r.status)
    except Exception as e:
        out['image'] = 'fail:' + str(e)[:70]
    out['ok'] = (out['api'] == 'ok')
    if out['api'] == 'ok':
        out['detail'] = '代理链路可用（直连 ' + out['direct'] + '）'
    else:
        out['detail'] = '代理链路不通（' + out['api'] + '）；直连 ' + out['direct'] \
                        + '；图片链路 ' + out['image']
    return out


def tmdb_search(query, kind='tv', year=None):
    k = tmdb_key()
    if not k:
        return []
    u = 'https://api.themoviedb.org/3/search/%s?api_key=%s&language=zh-CN&query=%s' % (
        kind, k, urllib.parse.quote(query))
    if year:
        u += '&%s' % ('first_air_date_year=%d' % int(year) if kind == 'tv'
                      else 'year=%d' % int(year))
    j = _tmdb_get(u)
    if isinstance(j, dict) and '__err' in j:
        return [{'__err': j['__err']}]
    return (j or {}).get('results', []) if isinstance(j, dict) else []


_PRENOISE = re.compile(
    r'(1080p|2160p|720p|480p|4k|uhd|bluray|blu-ray|web-?dl|webrip|remux|hdr10\+?|hdr|dolby|'
    r'x264|x265|h\.?264|h\.?265|hevc|avc|aac|ac3|dts(-hd)?|truehd|atmos|flac|'
    r'\d+bit|\d+\.?\d*mbps|\d+fps|extended|repack|proper|internal|complete)', re.I)
_PREBRACKET = re.compile(r'[\[【（(][^\]】）)]*[\]】）)]')


def preclean(name):
    """从目录/文件名剥出候选标题（去掉序号前缀、括号、画质编码等噪声）。"""
    s = _split_ext(name)[0]          # 不能用 os.path.splitext，见 _split_ext 注释
    s = _PREBRACKET.sub(' ', s)
    s = _PRENOISE.sub(' ', s)
    s = re.sub(r'S\d{1,2}\s*E\d{1,3}', ' ', s, flags=re.I)
    s = re.sub(r'第\s*\d{1,3}\s*[集话話]', ' ', s)
    s = re.sub(r'^[A-Za-z]?\d{1,3}\s*[\.、,，]?\s*', '', s)   # 去掉 A28. / 01. 这类前缀
    s = re.sub(r'[_\.]+', ' ', s)
    s = re.sub(r'\b(19|20)\d{2}\b', ' ', s)
    return re.sub(r'\s+', ' ', s).strip(' -')


def ai_cfg():
    """读 MT 里已配好的 AI（baseURL / apiKey / model）。

    用户说「3000 端口」，实测 3000 是一个 Web 界面（返回 HTML，不是 AI）；
    真正的 OpenAI 兼容接口在 MT 配置里的 3001（/v1），直接沿用，不另行配置。
    """
    try:
        ai = (mt_sys_cfg() or {}).get('ai') or {}
        return (ai.get('baseURL') or '').rstrip('/'), ai.get('apiKey') or '', \
               ai.get('model') or 'auto'
    except Exception:
        return '', '', 'auto'


_CN_NUM = {'零': 0, '一': 1, '二': 2, '三': 3, '四': 4, '五': 5,
           '六': 6, '七': 7, '八': 8, '九': 9, '十': 10}


def _cn2int(s):
    """中文数字 → int。支持 三 / 十二 / 二十 / 二十一。"""
    if s is None:
        return None
    s = str(s).strip()
    if s.isdigit():
        return int(s)
    if s in _CN_NUM:
        return _CN_NUM[s]
    if '十' in s:
        a, _, b = s.partition('十')
        hi = _CN_NUM.get(a, 1) if a else 1
        lo = _CN_NUM.get(b, 0) if b else 0
        return hi * 10 + lo
    return None


_EP_PATS = [
    # S01E01 / s1.e1 / S1 - E1
    ('se', re.compile(r'[Ss](\d{1,2})[\s\._\-]*[Ee](\d{1,3})')),
    # 第二季 大神版第10期 / 第2季第3集
    ('se_cn', re.compile(r'第\s*([0-9一二三四五六七八九十]+)\s*季[\s\S]{0,24}?第\s*(\d{1,3})\s*[期集话]')),
    # 第N期 / 第N集 / 第N话
    ('e', re.compile(r'第\s*(\d{1,3})\s*[期集话]')),
    # EP01 / ep.1 / E01 / Episode 01（完整单词也要能命中）
    ('ep', re.compile(r'(?:^|[\s\._\-])[Ee][Pp]?[\s\._\-]*(\d{1,3})(?!\d)')),
    ('epis', re.compile(r'(?:episode|ep)\s*[\._\-\s]*(\d{1,3})(?!\d)', re.I)),
    # MM.DD 综艺日期：03.23期 / 05.04期彩蛋第11期
    ('date', re.compile(r'(?<!\d)(\d{1,2})[\.~\-](\d{1,2})(?![\.\-]?\d)')),
    # 纯序号开头：01. / 02、 / 1 -
    ('num', re.compile(r'^\s*(\d{1,3})[\.、\s\-_]+')),
    # 纯数字文件名：01.mp4 / 02（剥掉扩展名后整段就是集号，常见于批量下载）
    ('puredigits', re.compile(r'^\s*(\d{1,3})\s*$')),
]


_PART_PAT = re.compile(r'[\-_~\s]*(上|下|上部|下部)$', re.I)


_DIR_NOISE = re.compile(
    r'^(vip|plus|大神版|会员版|花絮|彩蛋|字幕|subs?|subtitle|extras?|specials?|'
    r'cd\s*\d|disc\s*\d|bd|dvd|1080p|2160p|720p|4k|uhd|remux|web-?dl|'
    r'第\s*[0-9一二三四五六七八九十]+\s*季|s\d{1,2}|season\s*\d+)', re.I)


_YEAR_IN = re.compile(r'(19|20)\d{2}')


def _ep2(name):
    """解析单个文件名的集号信息。返回 dict 或 None。

    kind: se=有季有集 / e=仅集 / date=月.日（综艺）/ num=纯序号
    """
    stem, _ = _split_ext(name)
    part = None
    m = _PART_PAT.search(stem)
    if m:
        part = m.group(1)
        stem = stem[:m.start()]
    for kind, pat in _EP_PATS:
        m = pat.search(stem)
        if not m:
            continue
        if kind == 'se':
            return {'kind': 'se', 'season': int(m.group(1)), 'episode': int(m.group(2)),
                    'part': part, 'raw': m.group(0)}
        if kind == 'se_cn':
            s = _cn2int(m.group(1))
            if s:
                return {'kind': 'se', 'season': s, 'episode': int(m.group(2)),
                        'part': part, 'raw': m.group(0)}
        if kind == 'e':
            return {'kind': 'e', 'season': None, 'episode': int(m.group(1)),
                    'part': part, 'raw': m.group(0)}
        if kind == 'ep':
            return {'kind': 'e', 'season': None, 'episode': int(m.group(1)),
                    'part': part, 'raw': m.group(0)}
        if kind == 'epis':
            return {'kind': 'e', 'season': None, 'episode': int(m.group(1)),
                    'part': part, 'raw': m.group(0)}
        if kind == 'date':
            mo, d = int(m.group(1)), int(m.group(2))
            if 1 <= mo <= 12 and 1 <= d <= 31:
                return {'kind': 'date', 'season': None, 'episode': None,
                        'month': mo, 'day': d, 'part': part, 'raw': m.group(0)}
            continue
        if kind == 'num':
            return {'kind': 'num', 'season': None, 'episode': int(m.group(1)),
                    'part': part, 'raw': m.group(0)}
        if kind == 'puredigits':
            return {'kind': 'num', 'season': None, 'episode': int(m.group(1)),
                    'part': part, 'raw': m.group(0)}
    return None


_MV_PAT = re.compile(r'^([^\s_\-./\\]+.*?)\s+[\-—－]\s+(.+)$')


_MUSIC_PATH = re.compile(r'(mv|音乐|歌曲|演唱会|现场|live|ost|原声|合辑)', re.I)


def _is_mv(name, vdir=''):
    if not _MUSIC_PATH.search(vdir or ''):   # 非音乐目录 → 不判定为 MV
        return False
    stem, _ = _split_ext(name)
    if _ep2(name):                      # 已能解析出集号 → 不是 MV
        return False
    m = _MV_PAT.match(stem)
    if not m:
        return False
    left, right = m.group(1).strip(), m.group(2).strip()
    if not left or len(left) > 16:      # 左半不像歌手名
        return False
    if re.search(r'(第\s*\d|期|集|话|EP?|S\d|E\d|Season|合集|精选|专场|大神版|练习生|演唱会|现场)', left + ' ' + right):
        return False
    return True


def _franchise_season(vdir, title, year):
    """跨年季推断：目录名带年份、且同级存在同剧名不同年份的目录时，
    按年份先后把本目录定位到对应季号（密室大逃脱2019→S1，2020→S2）。"""
    if not (title and year):
        return None
    parent = os.path.dirname(vdir.rstrip('/'))
    if not parent or parent == '/':
        return None
    try:
        sibs = [d for d in os.listdir(parent)
                if os.path.isdir(os.path.join(parent, d))]
    except Exception:
        return None
    yrs = {}
    for d in sibs:
        if not d.startswith(title):
            continue
        m = _YEAR_IN.search(d)
        if m:
            yrs[int(m.group(0))] = d
    if len(yrs) < 2 or int(year) not in yrs:
        return None
    return sorted(yrs.keys()).index(int(year)) + 1


# 目录名全被 [] 包住时（如 [1982][天龙八部][全50集][Anywhere+][1080P]...），
# preclean 会把括号段全部剥光导致标题为空 → 从括号内容里把剧名捞回来
_BR_NOISE = re.compile(r'^(19|20)\d{2}$|^(全|共)?\s*\d+\s*集$|^\d+(\.\d+)?\s*[GMTB]$|^\d+部$', re.I)
_BR_TAG = re.compile(
    r'1080P|720P|2160P|4K|H\.?26[45]|x26[45]|MKV|MP4|TS\b|AVC|HEVC|国粤|粤语|国语|双语|三语'
    r'|内封|外挂|内嵌|简繁|简中|繁中|纯净版|录屏版|Anywhere|YingWEB|HHWEB|CMCTV|MTeam|HDCTV'
    r'|OPS|Web-?DL|Remux|BluRay|HDTV|合集|典藏|珍藏|终极画质|原盘|DIY|杜比|HDR', re.I)

# 经真实样本和 TMDB 季列表核验的编号系列别名。
# 仅命中精确剧名，绝不对任意末尾数字作通用拆分（避免伤及 1412 等标题）。
_SERIES_TITLE_ALIASES = {
    '创世纪1': ('创世纪', 1, '1999', None),
    '創世紀1': ('创世纪', 1, '1999', None),
    '创世纪2': ('创世纪', 2, '1999', None),
    '創世紀2': ('创世纪', 2, '1999', None),
    '壹号皇庭5': ('壹号皇庭', 5, '1992', None),
    '壹號皇庭5': ('壹号皇庭', 5, '1992', None),
    '壹号皇庭V': ('壹号皇庭', 5, '1992', None),
    '壹號皇庭V': ('壹号皇庭', 5, '1992', None),
    # TMDB 3427「皆大欢喜」：2001年古装版，S1=111集、S2=111集、S3=105集。
    '皆大欢喜古装版': ('皆大欢喜', 0, '2001', (111, 111, 105)),
    '皆大欢喜 古装版': ('皆大欢喜', 0, '2001', (111, 111, 105)),
}

def _normalize_series_alias(title, year=''):
    """将已核验的分季发行标题映射到 TMDB 系列正名/季号/首播年/绝对集分段。"""
    raw = (title or '').strip()
    alias = _SERIES_TITLE_ALIASES.get(raw)
    if alias:
        return alias
    return raw, 0, year, None


def _map_absolute_episode(episode, boundaries):
    """把绝对集号按 TMDB 每季集数拆成 (season, episode)，越界返回 None。"""
    try:
        n = int(episode)
    except Exception:
        return None
    offset = 0
    for sn, count in enumerate(boundaries or (), 1):
        count = int(count)
        if n <= offset + count:
            return sn, n - offset
        offset += count
    return None

def _bracket_title(base):
    """从「[年份][剧名][全N集][规格]...」式目录名里提取完整剧名。

    不对任意剧名末尾数字作拆解；确认为分季标题的少数别名由
    _normalize_series_alias 精确处理，避免误拆「魔术快斗1412」等标题。
    """
    for pt in re.findall(r'\[([^\[\]]+)\]', base or ''):
        pt = pt.strip()
        if not pt or _BR_NOISE.search(pt) or _BR_TAG.search(pt):
            continue
        c = preclean(pt)
        if c and len(c) >= 2:
            return c, 0
    return '', 0


def title_guess(vdir, up=4):
    """从目录层级向上猜剧名 + 年份。跳过 vip/plus/字幕 这类噪声层。

    例：.../M 密室大逃脱/密室大逃脱2019/vip大神版
        → 跳过 vip大神版 → 取「密室大逃脱2019」→ title=密室大逃脱, year=2019
    """
    cands = []
    p = vdir.rstrip('/')
    for i in range(up):
        base = os.path.basename(p)
        if not base:
            break
        clean = preclean(base)
        bseason = 0
        if not clean:
            clean, bseason = _bracket_title(base)   # 全括号目录名兜底（带季号）
        if clean and not _DIR_NOISE.match(clean.strip()):
            yr = ''
            m = _YEAR_IN.search(base)
            if m:
                yr = m.group(0)
                c2 = preclean(base[:m.start()] + base[m.end():])
                if c2:
                    clean, bseason = c2, 0
                else:
                    clean, bseason = _bracket_title(base)
            if clean:
                clean, alias_season, alias_year, episode_boundaries = _normalize_series_alias(clean, yr)
                if alias_season or episode_boundaries or alias_year != yr:
                    bseason, yr = alias_season, alias_year
                cands.append({'title': clean, 'year': yr, 'season': bseason,
                              'episode_boundaries': episode_boundaries,
                              'from': base, 'depth': i})
        p = os.path.dirname(p)
        if not p or p == '/':
            break
    if not cands:
        return {'title': '', 'year': '', 'season': 0, 'episode_boundaries': None,
                'from': os.path.basename(vdir.rstrip('/'))}
    # 优先取带年份的那层（信息最全），否则取最靠内的
    for c in cands:
        if c['year']:
            return c
    return cands[0]


def rename_plan2(vdir, title=None, year=None, season=None, tmdb_id=None,
                 ep_start=1, part_mode='split', keep_ext=True):
    """生成精细重命名计划。

    核心能力：把 MM.DD 日期型综艺文件按「日期先后」映射成连续集号。
    例：03.23期 03.30期 04.06期 → E01 E02 E03（不需要 AI，零延迟零成本）

    part_mode: split=上/下各占一个集号（默认，Emby 友好）
               merge=上/下共用一个集号（.part1/.part2）
    """
    if not os.path.isdir(vdir):
        return {'ok': False, 'msg': '目录不存在：%s' % vdir}
    files = []
    try:
        for e in os.scandir(vdir):
            if e.is_file() and e.name.lower().endswith(_VID_EXT):
                files.append(e.name)
    except Exception as e:
        return {'ok': False, 'msg': '读取失败：%s' % str(e)[:200]}
    files.sort()
    if not files:
        return {'ok': False, 'msg': '目录里没有视频文件'}

    # ── 标题/年份：手动指定 > 已核验的系列别名 > 目录推断 ──
    g = title_guess(vdir)
    t_title = (title or '').strip() or g['title']
    t_year = (year or '').strip() or g['year']
    # 已核验的分季目录（创世纪1/2、壹号皇庭5）比文件名里旧的 S01 更权威。
    # 普通节目仍使用文件内季号；跨年季推断作为再次兜底。
    fseason = (g.get('season') or
               _franchise_season(vdir, t_title, t_year))

    # ── L1：逐个解析 ──
    toks = {}
    for f in files:
        toks[f] = _ep2(f)

    kinds = [t['kind'] for t in toks.values() if t]
    n_date = kinds.count('date')
    # 若半数以上是日期型 → 整目录按"日期序"重排集号
    date_mode = bool(files) and n_date >= max(1, int(len(files) * 0.5))

    # ── 日期 → 连续集号映射 ──
    date_seq = {}
    if date_mode:
        dated = [(f, toks[f]) for f in files if toks.get(f) and toks[f]['kind'] == 'date']
        dated.sort(key=lambda x: (x[1]['month'], x[1]['day'], x[0]))
        idx = int(ep_start)
        prev_key = None
        for f, tk in dated:
            key = (tk['month'], tk['day'])
            if part_mode == 'merge' and key == prev_key:
                idx -= 1          # 上/下 合并为同一集
            date_seq[f] = idx
            prev_key = key
            idx += 1

    # ── 分批续排：目录里只有少量日期型（此前已改名过一批）时，
    #    不再重排，而是接在现有最大集号后面继续编号，保证重跑幂等不重号 ──
    if not date_mode:
        dated2 = [(f, toks[f]) for f in files if toks.get(f) and toks[f]['kind'] == 'date']
        if dated2:
            existing = [t['episode'] for t in toks.values()
                        if t and t.get('episode') is not None]
            idx = (max(existing) if existing else 0) + max(1, int(ep_start) - 1) + 1
            dated2.sort(key=lambda x: (x[1]['month'], x[1]['day'], x[0]))
            for f, tk in dated2:
                date_seq[f] = idx
                idx += 1

    # ── 季号：显式参数 > 精确系列别名 > 文件名 > 跨年目录推断 > 默认 1 ──
    def season_of(tk):
        if season:
            return int(season)
        if g.get('season'):
            return int(g['season'])
        if tk and tk.get('season'):
            return int(tk['season'])
        if fseason:
            return int(fseason)
        return 1

    plan = []
    for f in files:
        tk = toks.get(f)
        stem, ext = _split_ext(f)
        if not keep_ext:
            ext = ext
        if not tk:
            # 未解析出集号：先判断是否 MV/歌曲（应排除，不计失败）
            if _is_mv(f, vdir):
                plan.append({'file': f, 'new': None, 'need': False,
                             'skip': 'MV/歌曲，非影视，已排除', 'level': 0, 'why': 'mv'})
            else:
                plan.append({'file': f, 'new': None, 'need': False,
                             'skip': 'L1 无法解析集号', 'level': 0, 'why': 'no_pattern'})
            continue
        s = season_of(tk)
        if f in date_seq:
            e = date_seq[f]
        elif tk['episode'] is not None:
            e = int(tk['episode'])
        else:
            plan.append({'file': f, 'new': None, 'need': False,
                         'skip': 'L1 无法解析集号', 'level': 0, 'why': 'no_ep'})
            continue
        # 对官方 TMDB 将一季拆为多季、而来源将集号展平的剧集，按每季官方集数分段。
        # 仅对确认的别名生效；已明确标记为 S02+ 的文件保持原季号，重复运行幂等。
        bounds = g.get('episode_boundaries')
        if bounds and not season and (not tk.get('season') or int(tk.get('season')) == 1):
            mapped = _map_absolute_episode(e, bounds)
            if not mapped:
                plan.append({'file': f, 'new': None, 'need': False,
                             'skip': '绝对集号超出 TMDB 季集数范围',
                             'level': 0, 'why': 'episode_out_of_range'})
                continue
            s, e = mapped
        if not t_title:
            plan.append({'file': f, 'new': None, 'need': False,
                         'skip': '缺少剧名（请手填或让 TMDB 识别）', 'level': 0, 'why': 'no_title'})
            continue
        head = '%s.%s' % (t_title, t_year) if t_year else t_title
        tail = ''
        if tk.get('part') and part_mode == 'merge':
            tail = '.part1' if tk['part'] in ('上', '上部') else '.part2'
        new = '%s.S%02dE%02d%s%s' % (head, s, e, tail, ext)
        new = re.sub(r'[\\/:*?"<>|]', '-', new)
        plan.append({'file': f, 'new': new, 'need': new != f, 'skip': None,
                     'level': 1, 'season': s, 'episode': e,
                     'by': 'date' if f in date_seq else 'rule'})

    return {
        'ok': True, 'dir': vdir, 'total': len(files),
        'title': t_title, 'year': t_year, 'season': season or '',
        'guess': g, 'date_mode': date_mode,
        'date_count': n_date, 'kinds': {k: kinds.count(k) for k in set(kinds)},
        'plan': plan,
        'need': len([x for x in plan if x.get('need')]),
        'unparsed': len([x for x in plan if not x.get('new')]),
        'mv': len([x for x in plan if x.get('why') == 'mv']),
    }


def ai_rename_batch(vdir, files, title='', year='', model=None, maxn=40):
    """L3 兜底：规则解析不了时，交给 AI（串行 + 限流友好）。

    实测：面板是免费聚合 LLM，并发>1 必 429；串行间隔 3s 实测 12/12 成功。
    """
    base, key, mdl = ai_cfg()
    if not base:
        return {'ok': False, 'msg': '未读到 MT 的 AI 配置'}
    mdl = model or mdl or 'auto'
    files = files[:maxn]
    if not files:
        return {'ok': False, 'msg': '没有待解析文件'}
    listing = '\n'.join('%d. %s' % (i + 1, f) for i, f in enumerate(files))
    hint = ('剧名=%s 年份=%s' % (title, year)) if (title or year) else '剧名未知，请从目录上下文推断'
    prompt = (
        '你是影视文件命名助手。下面是同一部剧/综艺目录下的文件名，'
        '请解析出每一集的季号和集号。\n'
        '上下文：%s\n'
        '文件名列表：\n%s\n\n'
        '规则：\n'
        '1. 日期型（如 03.23期）按日期从早到晚依次映射为第1集、第2集……\n'
        '2. 带「第X季」的按该季号；未标明季的默认第1季\n'
        '3. 上下部（如 04.27期-上 / -下）算作连续两集\n'
        '只输出 JSON 数组，不要任何解释文字、不要 markdown 代码块：\n'
        '[{"i":1,"season":1,"episode":1}]' % (hint, listing))
    payload = {'model': mdl, 'messages': [{'role': 'user', 'content': prompt}],
               'max_tokens': 1200, 'temperature': 0}
    req = urllib.request.Request(
        base.rstrip('/') + '/chat/completions', data=json.dumps(payload).encode(),
        headers={'Authorization': 'Bearer ' + key, 'Content-Type': 'application/json'})
    t0 = time.time()
    try:
        with urllib.request.urlopen(req, timeout=90) as r:
            d = json.loads(r.read().decode('utf-8', 'replace'))
    except Exception as e:
        return {'ok': False, 'msg': 'AI 调用失败：%s' % str(e)[:160]}
    txt = ''
    try:
        txt = (d.get('choices') or [{}])[0].get('message', {}).get('content', '') or ''
    except Exception:
        pass
    # 从返回里抠出 JSON 数组（模型常带推理前缀/代码块）
    m = re.search(r'\[[\s\S]*\]', txt)
    if not m:
        return {'ok': False, 'msg': 'AI 未返回可解析的 JSON', 'raw': txt[:300],
                'ms': int((time.time() - t0) * 1000)}
    try:
        arr = json.loads(m.group(0))
    except Exception as e:
        return {'ok': False, 'msg': 'AI 返回 JSON 解析失败：%s' % str(e)[:100],
                'raw': txt[:300], 'ms': int((time.time() - t0) * 1000)}
    out = []
    for it in arr:
        if not isinstance(it, dict):
            continue
        i = int(it.get('i', 0)) - 1
        if 0 <= i < len(files):
            out.append({'file': files[i], 'season': int(it.get('season', 1) or 1),
                        'episode': int(it.get('episode', 0) or 0)})
    return {'ok': True, 'items': out, 'ms': int((time.time() - t0) * 1000),
            'model': d.get('model', mdl)}


def rename_tree(root, max_dirs=500, dry=False):
    """批量预整理：遍历整棵目录树，对每个含视频文件的叶子目录
    自动 guess → plan → apply。用于把 RT转存 提取出来的大批次一次改完。

    只改「需要改」的文件（幂等，重跑安全）；目录标题从层级自动推断。
    """
    if not os.path.isdir(root):
        return {'ok': False, 'msg': '目录不存在：%s' % root}
    items, t_n, t_need, t_done, t_err = [], 0, 0, 0, 0
    for r, dirs, files in os.walk(root):
        vids = [f for f in files if f.lower().endswith(_VID_EXT)]
        if not vids:
            continue
        n = len(items) + 1
        if n > max_dirs:
            break
        rel = r[len(root):] or '/'
        try:
            pl = rename_plan2(r)
            if not pl.get('ok'):
                items.append({'dir': rel, 'ok': False, 'msg': pl.get('msg', '')[:80]})
                t_err += 1
                continue
            # TMDB 年份校准：目录名里的年份（如「守护解放西 2022」）常与
            # TMDB 标准首播年（2019）不一致，会让 MT 报 year_conflict 而失败。
            # 这里用 TMDB 权威年覆盖目录年，显著提高入库成功率。
            cal = ''
            t_title = pl.get('title') or ''
            if t_title:
                try:
                    rs = tmdb_search(t_title, 'tv') or []
                    hit = rs[0] if rs and isinstance(rs[0], dict) and '__err' not in rs[0] else None
                    if hit:
                        ny = (hit.get('first_air_date') or hit.get('release_date') or '')[:4]
                        nt = hit.get('name') or hit.get('title') or ''
                        if ny and ny != pl.get('year'):
                            pl = rename_plan2(r, title=(nt or t_title), year=ny)
                            cal = '%s→%s' % (pl.get('year'), ny)
                except Exception:
                    pass
            need = [x for x in pl['plan'] if x.get('need')]
            unparsed = [x for x in pl['plan'] if x.get('why') == 'no_pattern']
            mv = [x for x in pl['plan'] if x.get('why') == 'mv']
            if not need:
                items.append({'dir': rel, 'ok': True, 'need': 0, 'mv': len(mv),
                              'title': pl.get('title'), 'msg': '无需改名'})
                continue
            ap = prerename_apply(r, pl['plan'], dry=dry)
            done = len(ap.get('done') or [])
            errs = len(ap.get('errors') or [])
            t_need += len(need)
            t_done += done
            t_err += errs
            items.append({'dir': rel, 'ok': True, 'need': len(need), 'done': done,
                          'err': errs, 'mv': len(mv), 'unparsed': len(unparsed),
                          'title': '%s%s' % (pl.get('title') or '', pl.get('year') or ''),
                          'cal': cal,
                          'msg': ap.get('msg', '')[:60]})
        except Exception as e:
            items.append({'dir': rel, 'ok': False, 'msg': str(e)[:100]})
            t_err += 1
    return {'ok': True, 'root': root, 'dry': dry,
            'dirs': len(items), 'need': t_need, 'done': t_done, 'err': t_err,
            'items': items}


def prerename_plan(vdir, kind='tv', tmdb_id=None, title=None, year=None,
                   season=None, ep_start=1, part_mode='split'):
    """v2 入口：先 TMDB 补标题，再走精细规则解析。兼容旧的 (vdir, kind) 调用。"""
    r = rename_plan2(vdir, title=title, year=year, season=season,
                     ep_start=ep_start, part_mode=part_mode)
    if not r.get('ok'):
        return r
    # L2：标题还没定 / 或想校准 → 查 TMDB
    tried, match = [], None
    if tmdb_id or (not r.get('title')):
        cand = r.get('guess', {}).get('title') or preclean(os.path.basename(vdir.rstrip('/')))
        hit = None
        if tmdb_id:
            hit = {'id': int(tmdb_id), '_forced': True}
        else:
            parts = [cand]
            eng = re.findall(r'[A-Za-z][A-Za-z\.\-\' ]{2,}', cand or '')
            if eng:
                parts.insert(0, max(eng, key=len).strip())
            for q in parts:
                if not (q or '').strip():
                    continue
                for k in ([kind] if kind else ['tv', 'movie']):
                    rs = tmdb_search(q.strip(), k)
                    tried.append('%s/%s → %d' % (q.strip()[:24], k, len(rs)))
                    if rs and '__err' not in rs[0]:
                        hit = rs[0]
                        hit['_kind'] = k
                        hit['_query'] = q.strip()
                        break
                if hit:
                    break
        if hit:
            nt = hit.get('name') or hit.get('title') or ''
            ny = (hit.get('first_air_date') or hit.get('release_date') or '')[:4]
            match = {'id': hit.get('id'), 'title': nt, 'year': ny,
                     'original': hit.get('original_name') or hit.get('original_title') or ''}
            # 用 TMDB 权威标题重出计划
            if nt and (not title):
                r = rename_plan2(vdir, title=nt, year=ny or year, season=season,
                                 ep_start=ep_start, part_mode=part_mode)
    r.update({'tried': tried, 'match': match, 'kind': kind})
    return r


def prerename_apply(vdir, plan, dry=True):
    """执行预重命名。同时把同目录的字幕也改名（保持一一对应）。"""
    if not os.path.isdir(vdir):
        return {'ok': False, 'msg': '目录不存在'}
    done, errs = [], []
    # 先取一次字幕清单，用于同步改名
    subs = []
    try:
        for e in os.scandir(vdir):
            if e.is_file() and e.name.lower().endswith(_SUB_EXT):
                subs.append(e.name)
    except Exception:
        pass
    for it in (plan or []):
        if not it.get('new') or not it.get('need'):
            continue
        src = os.path.join(vdir, it['file'])
        dst = os.path.join(vdir, it['new'])
        if not os.path.exists(src):
            errs.append('%s 已不存在' % it['file'])
            continue
        if os.path.exists(dst):
            errs.append('%s 目标已存在' % it['new'])
            continue
        rec = {'from': it['file'], 'to': it['new'], 'subs': []}
        if not dry:
            try:
                os.rename(src, dst)
            except Exception as e:
                errs.append('%s 失败：%s' % (it['file'], str(e)[:80]))
                continue
            time.sleep(0.25)
        # 同步字幕（用 _split_ext，避免中文点号被当成扩展名）
        old_stem = _split_ext(it['file'])[0]
        new_stem = _split_ext(it['new'])[0]
        for s in subs:
            if os.path.splitext(s)[0].startswith(old_stem) or _stem_key(s) == _stem_key(it['file']):
                ns = new_stem + _lang_suffix(s) + os.path.splitext(s)[1]
                sp, dp = os.path.join(vdir, s), os.path.join(vdir, ns)
                if os.path.exists(dp):
                    continue
                if not dry:
                    try:
                        shutil.move(sp, dp)
                        time.sleep(0.25)
                    except Exception as e:
                        errs.append('字幕 %s 失败：%s' % (s, str(e)[:60]))
                        continue
                rec['subs'].append({'from': s, 'to': ns})
        done.append(rec)
    if not dry and done:
        oplog('mt', 'prerename', '预重命名 %d 个文件' % len(done), True, vdir)
        # 回滚快照：记到 /tmp，出事能一键还原
        try:
            snap = '/tmp/prerename_undo_%s.json' % time.strftime('%Y%m%d-%H%M%S')
            json.dump({'dir': vdir, 'done': done, 'ts': time.strftime('%Y-%m-%d %H:%M:%S')},
                      open(snap, 'w', encoding='utf-8'), ensure_ascii=False, indent=1)
        except Exception:
            pass
    return {'ok': True, 'dry': dry, 'done': done, 'errors': errs,
            'msg': '%s %d 个视频%s' % ('预览' if dry else '已重命名', len(done),
                                      ('，%d 个失败' % len(errs)) if errs else '')}


def prerename_undo(snap_path):
    """按回滚快照把文件名改回去（只改视频+字幕，路径不变）。"""
    try:
        d = json.load(open(snap_path, 'r', encoding='utf-8'))
    except Exception as e:
        return {'ok': False, 'msg': '读快照失败：%s' % str(e)[:120]}
    vdir, done = d.get('dir'), d.get('done') or []
    ok, errs = 0, []
    for rec in done:
        for kind, a, b in (('v', rec.get('to'), rec.get('from')),):
            if not a or not b:
                continue
            src, dst = os.path.join(vdir, a), os.path.join(vdir, b)
            if not os.path.exists(src) or os.path.exists(dst):
                continue
            try:
                os.rename(src, dst)
                ok += 1
            except Exception as e:
                errs.append('%s 失败：%s' % (a, str(e)[:60]))
        for s in (rec.get('subs') or []):
            src, dst = os.path.join(vdir, s.get('to')), os.path.join(vdir, s.get('from'))
            if not os.path.exists(src) or os.path.exists(dst):
                continue
            try:
                os.rename(src, dst)
                ok += 1
            except Exception as e:
                errs.append('字幕 %s 失败：%s' % (s.get('to'), str(e)[:60]))
    return {'ok': True, 'restored': ok, 'errors': errs,
            'msg': '已还原 %d 个%s' % (ok, ('，%d 失败' % len(errs)) if errs else '')}

# ══════════════════════ 实时状态总览（顶部状态条） ══════════════════════
def mt_sys_cfg():
    """读 MediaTidy 的 system 配置（含 ai / tmdb 段）。失败返回空 dict。"""
    try:
        with db() as c:
            r = c.execute("SELECT value FROM app_config WHERE key='system'").fetchone()
        return json.loads(r[0]) if r else {}
    except Exception:
        return {}


def live_raw():
    """四路实时探针：MT / CD2 / AI / Emby。

    设计要点：每路各自 try + 独立超时，单路失败绝不影响其他路；
    整体结果走 cached('live') 15 秒缓存，避免状态条把后端打满。
    """
    out = {'ts': time.strftime('%F %T'), 'epoch': int(time.time())}

    # ① MT —— 只读本地 SQLite，毫秒级
    mt = {'ok': False, 'msg': ''}
    try:
        with db() as c:
            run = c.execute(
                "SELECT id,source_dir,total_files,done_files,error_files,skipped_files,"
                "trigger_kind,started_at FROM organize_tasks "
                "WHERE status='running' ORDER BY id DESC LIMIT 1").fetchone()
            t = c.execute(
                "SELECT count(*) n, IFNULL(sum(done_files),0) d, IFNULL(sum(error_files),0) e "
                "FROM organize_tasks WHERE date(created_at)=date('now','localtime')").fetchone()
            pend = c.execute(
                "SELECT count(*) FROM organize_tasks WHERE status IN ('pending','running')"
            ).fetchone()[0]
        mt['ok'] = True
        mt['pending'] = pend
        mt['today'] = {'tasks': t['n'], 'done': t['d'], 'error': t['e']}
        if run:
            tot = run['total_files'] or 0
            dn = run['done_files'] or 0
            mt['running'] = {'id': run['id'], 'dir': run['source_dir'],
                             'total': tot, 'done': dn,
                             'error': run['error_files'] or 0,
                             'skipped': run['skipped_files'] or 0,
                             'kind': run['trigger_kind'],
                             'started': (run['started_at'] or '')[11:19],
                             'pct': (round(dn * 100.0 / tot, 1) if tot else 0)}
        else:
            mt['running'] = None
    except Exception as e:
        mt['msg'] = str(e)[:140]
    out['mt'] = mt

    # ② CD2 —— TCP 探活 + 缓存库体积 + TTL
    cd2 = {'ok': False, 'msg': ''}
    try:
        _c2 = containers()['clouddrive2']
        cd2['ok'] = tcp_alive(_c2['addr'], _c2['port'] or 19798, 3)
        p = '/cd2config/systemsettings.json'
        if os.path.exists(p):
            d = json.load(open(p, encoding='utf-8'))
            cd2['ttl'] = d.get('dir_cache_ttl_secs')
            cd2['persist'] = d.get('dir_cache_persistence')
        cp = '/cd2config/dir_cache.sqlite'
        if os.path.exists(cp):
            cd2['cache_mb'] = round(os.path.getsize(cp) / 1048576.0, 1)
    except Exception as e:
        cd2['msg'] = str(e)[:140]
    out['cd2'] = cd2

    # ③ AI —— 读 MT 的 ai 配置，探 /models
    ai = {'ok': False, 'msg': ''}
    try:
        cfg = mt_sys_cfg().get('ai') or {}
        ai['enabled'] = bool(cfg.get('enabled'))
        ai['model'] = cfg.get('model')
        ai['effort'] = cfg.get('reasoningEffort')
        base = (cfg.get('baseURL') or '').rstrip('/')
        if base:
            u = urllib.parse.urlparse(base)
            st, body = hget(u.hostname, u.port or 80, u.path + '/models',
                            {'Authorization': 'Bearer ' + (cfg.get('apiKey') or '')}, 6)
            ai['http'] = st
            ai['ok'] = (st == 200)
            if st != 200:
                ai['msg'] = (body if isinstance(body, str) else json.dumps(
                    body, ensure_ascii=False))[:160]
        else:
            ai['msg'] = '未配置 baseURL'
    except Exception as e:
        ai['msg'] = str(e)[:140]
    out['ai'] = ai

    # ④ Emby —— 公共信息接口
    try:
        _e1 = containers()['emby']
        st, body = hget(_e1['addr'], _e1['port'], '/System/Info/Public', None, 4)
        out['emby'] = {'ok': st == 200,
                       'name': (body.get('ServerName') if isinstance(body, dict) else '') or ''}
    except Exception as e:
        out['emby'] = {'ok': False, 'name': '', 'msg': str(e)[:140]}

    out['ok'] = True
    return out


def act_generic(key, act, arg):
    """容器通用操作：start/stop/restart/pause/unpause/logs/stats/state/inspect/files

    key 可以是服务键（emby / moviepilot …）或真实容器名，这里统一解析。
    """
    cname = key
    if key in containers():
        cname = containers()[key]['cname']
    if act in ('start', 'stop', 'restart', 'pause', 'unpause'):
        return ctr_action(cname, act)
    if act == 'logs':
        try:
            n = int(arg) if not isinstance(arg, (dict, type(None))) else 200
        except Exception:
            n = 200
        return ctr_logs(cname, max(10, min(n, 2000)))
    if act == 'stats':
        s = ctr_stats(cname)
        return ({'ok': True, 'msg': 'CPU %s%% · 内存 %s%%（%s / %s）' % (
            s['cpu'], s['mem_pct'], fmt_bytes(s['mem']), fmt_bytes(s['mem_limit'])), 'data': s}
                if s else {'ok': False, 'msg': '无法读取统计'})
    if act == 'state':
        cs = ctr_state(cname)
        return {'ok': cs.get('ok', False),
                'msg': '容器 %s · %s · 镜像 %s' % (cs.get('state'),
                                                  '运行中' if cs.get('running') else '未运行',
                                                  cs.get('image') or '—'),
                'data': cs}
    if act == 'inspect':
        j = ctr_inspect(cname)
        if not j:
            return {'ok': False, 'msg': '容器 %s 不存在' % cname}
        return {'ok': True, 'msg': '已读取容器详情', 'data': {
            'name': cname,
            'image': (j.get('Config') or {}).get('Image'),
            'created': (j.get('Created') or '')[:19],
            'restart_policy': ((j.get('HostConfig') or {}).get('RestartPolicy') or {}).get('Name'),
            'mounts': [{'src': m.get('Source'), 'dst': m.get('Destination'), 'rw': m.get('RW')}
                       for m in (j.get('Mounts') or [])],
            'ports': list((j.get('NetworkSettings') or {}).get('Ports') or {}),
            'env': [e for e in ((j.get('Config') or {}).get('Env') or [])
                    if not any(s in e.upper() for s in ('TOKEN', 'PASS', 'KEY', 'SECRET'))][:24]}}
    if act == 'files':
        j = ctr_inspect(cname)
        if not j:
            return {'ok': False, 'msg': '容器 %s 不存在' % cname}
        out = []
        for m in (j.get('Mounts') or []):
            src = m.get('Source')
            if src and not src.startswith('/var/run') and not src.startswith('/etc'):
                sz = run("du -sh %s 2>/dev/null|cut -f1" % src, 30)
                out.append({'src': src, 'dst': m.get('Destination'), 'size': sz or '?'})
        return {'ok': True, 'msg': '%d 个挂载点' % len(out), 'data': out}
    return {'ok': False, 'msg': '未实现：%s/%s' % (key, act)}


def fmt_bytes(b):
    b = float(b or 0)
    for u in ('B', 'KB', 'MB', 'GB', 'TB'):
        if b < 1024:
            return '%.0f%s' % (b, u) if u == 'B' else '%.1f%s' % (b, u)
        b /= 1024
    return '%.1fPB' % b


def act_avdb(act, arg):
    conf = containers()['avdb']
    if act == 'health':
        st, b = hreq(conf['addr'], conf['port'], 'GET', '/', None, None, 6)
        ok = http_health_ok(st)
        return {'ok': ok, 'http': st,
                'msg': ('avdb 在线 · HTTP %s' % st) if ok else 'avdb 异常（HTTP %s）' % st}
    return act_generic('avdb', act, arg)



