# ★★ V1.46 9kg 域：MDC-NG / AVDB 深度集成 + Emby 缺图体检补齐
#   用户原话（2026-11-04）：「Web 5678 左边菜单栏加 9kg，下拉显示 MDC-NG 和
#   AVDB，把分批整理同步上来；emby 库里 strm 入库的没有图片，加检索缺少
#   封面/背景/剧照并自动补齐」。
#   · MDC API 转发必须走宿主机 LAN（实测容器内 127.0.0.1 不通，mdc-ng 是
#     host 网络但 media-hub 是 bridge → 用 mdc_addr:9207）。
#   · mdc_ng.db 只读走 /dockroot 挂载（media-hub 已挂 /vol1/1000/docker）。
#   · 分批驱动 = NAS root cron + flock 常驻；面板开关 = batch_paused 旗标文件
#     （驱动每个 tick 检查，幂等，不需要动 crontab）。
# ══════════════════════════════════════════════════════════════════════════

MDC_DB = '/dockroot/9kg/mdc/config/data/mdc_ng.db'
MDC_DRV_LOG = '/dockroot/9kg/mdc/batch_driver.log'
MDC_DRV_STATE = '/dockroot/9kg/mdc/batch_state.json'
MDC_DRV_SCRIPT = '/dockroot/9kg/mdc/_tools/mdc_batch_driver.py'
MDC_PAUSE_FLAG = '/dockroot/9kg/mdc/batch_paused'
MDC_SRC_ROOT = '/CloudNAS/115open/Adult-待整理/日韩'
MDC_TARGET_ROOT = '/CloudNAS/115open/KFC2/Adult/已刮削/日本'
MDC_TASK_CN = {-1: '失败', 0: '等待中', 1: '处理中', 2: '成功'}
MDC_STAGE_CN = {0: '初始化', 100: '解析', 200: '元数据', 300: '图片',
                400: '整理', 500: '移动', 1000: '完成'}


def _mdc_http(path, method='GET', body=None, t=10):
    conf = containers().get('mdc') or {}
    addr = conf.get('addr') or cfg().get('emby_addr') or '127.0.0.1'
    port = conf.get('port') or 9207
    data = json.dumps(body).encode() if body is not None else None
    hdr = {'Content-Type': 'application/json'} if data else None
    st, b = hreq(addr, port, method, path, data, hdr, t)
    if isinstance(b, str):
        try:
            b = json.loads(b)
        except Exception:
            pass
    return st, b


def _mdc_db(sql, timeout=6):
    """mdc_ng.db 只读查询；失败返回 None，绝不带崩接口。"""
    try:
        if not os.path.exists(MDC_DB):
            return None
        con = sqlite3.connect('file:%s?mode=ro&busy_timeout=2000' % MDC_DB,
                              uri=True, timeout=timeout)
        con.row_factory = sqlite3.Row
        rows = [dict(r) for r in con.execute(sql)]
        con.close()
        return rows
    except Exception:
        return None


def kg_mdc_overview():
    out = {'ok': True, 'api': False}
    st, b = _mdc_http('/api/manual-jobs?page=1&page_size=8', t=8)
    if st == 200 and isinstance(b, dict):
        out['api'] = True
        out['jobs'] = b.get('data') or []
        out['jobs_total'] = b.get('total_count') or 0
    else:
        out['jobs'] = []
        out['jobs_err'] = 'MDC API 不可达（HTTP %s）→ 设置页核对 mdc_addr/mdc_port' % st
    rows = _mdc_db("select status, count(*) n from task group by status") or []
    out['task_agg'] = [{'k': MDC_TASK_CN.get(int(r['status']), str(r['status'])),
                        'n': r['n'], 'raw': r['status']} for r in rows]
    out['fail_reasons'] = _mdc_db(
        "select substr(coalesce(error_message,'(无)'),1,60) e, count(*) n "
        "from task where status=-1 "
        "and created_at>=datetime('now','localtime','-24 hours') "
        "group by e order by n desc limit 8") or []
    out['throughput'] = _mdc_db(
        "select substr(end_at,12,5) m, count(*) n, sum(status=2) ok "
        "from task where end_at>=datetime('now','localtime','-30 minutes') "
        "group by m order by m desc limit 30") or []
    drv = {'installed': os.path.exists(MDC_DRV_SCRIPT),
           'paused': os.path.exists(MDC_PAUSE_FLAG)}
    if os.path.exists(MDC_DRV_STATE):
        try:
            with open(MDC_DRV_STATE, encoding='utf-8') as f:
                s = json.load(f)
            drv['done'] = len(s.get('done') or [])
            drv['tried'] = len(s.get('attempts') or {})
        except Exception:
            pass
    if os.path.exists(MDC_DRV_LOG):
        try:
            sz = os.path.getsize(MDC_DRV_LOG)
            with open(MDC_DRV_LOG, 'rb') as f:
                f.seek(max(0, sz - 8192))
                drv['log_tail'] = f.read().decode('utf-8', 'replace').strip().split('\n')[-10:]
            drv['log_mtime'] = time.strftime('%m-%d %H:%M',
                                              time.localtime(os.path.getmtime(MDC_DRV_LOG)))
        except Exception:
            pass
    out['driver'] = drv
    try:
        if os.path.isdir(MDC_SRC_ROOT):
            out['src_left'] = len([x for x in os.listdir(MDC_SRC_ROOT)
                                   if os.path.isdir(os.path.join(MDC_SRC_ROOT, x))])
    except Exception:
        pass
    return out


def kg_mdc_jobs(page=1, size=12):
    st, b = _mdc_http('/api/manual-jobs?page=%d&page_size=%d' % (page, size), t=10)
    if st != 200 or not isinstance(b, dict):
        return {'ok': False, 'msg': 'MDC API 不可达（HTTP %s）' % st}
    for j in (b.get('data') or []):
        j['status_cn'] = {1: '运行中', 2: '已完成', 0: '等待', -1: '异常/中断'}.get(
            j.get('status'), str(j.get('status')))
    return {'ok': True, 'data': b.get('data') or [],
            'num_pages': b.get('num_pages') or 0, 'total_count': b.get('total_count') or 0}


def kg_mdc_tasks(job_id='', status='', page=1, size=40, q=''):
    conds = []
    if str(job_id).isdigit():
        conds.append("manual_job_id=%d" % int(job_id))
    if str(status) in ('-1', '0', '1', '2'):
        conds.append("status=%s" % status)
    if q:
        safe = q.replace("'", "''")[:60]
        conds.append("(number like '%%%s%%' or source_path like '%%%s%%')" % (safe, safe))
    w = (' where ' + ' and '.join(conds)) if conds else ''
    try:
        off = max(0, (int(page) - 1) * int(size))
    except Exception:
        off, size = 0, 40
    rows = _mdc_db("select id,manual_job_id mid,status,stage,number,source_path,"
                   "coalesce(error_message,'') err, created_at, end_at,"
                   "case when end_at is not null and started_at is not null then "
                   "round((julianday(end_at)-julianday(started_at))*86400,1) end dur"
                   " from task%s order by id desc limit %d offset %d" % (w, int(size), off))
    if rows is None:
        return {'ok': False, 'msg': 'mdc_ng.db 不可读（检查 /dockroot 挂载）'}
    for r in rows:
        r['status_cn'] = MDC_TASK_CN.get(r.get('status'), str(r.get('status')))
        r['stage_cn'] = MDC_STAGE_CN.get(r.get('stage'), str(r.get('stage')))
        sp = str(r.get('source_path') or '')
        r['file'] = sp.rsplit('/', 1)[-1]
    cnt = _mdc_db("select count(*) n from task%s" % w) or [{'n': 0}]
    return {'ok': True, 'rows': rows, 'total': cnt[0]['n'],
            'page': int(page), 'size': int(size)}


def kg_mdc_task_log(task_id):
    if not str(task_id).isdigit():
        return {'ok': False, 'msg': 'bad id'}
    rows = _mdc_db("select stage, level, message from log where task_id=%d "
                   "order by id limit 240" % int(task_id)) or []
    return {'ok': True, 'rows': rows}


def kg_mdc_task_retry(task_id):
    """把失败/等待任务复位为「等待中」。mdc-ng 重启时接管 pending 记录
    （与分批驱动同款机制）；复位后提示用户点「重启 MDC」。"""
    if not str(task_id).isdigit():
        return {'ok': False, 'msg': 'bad id'}
    try:
        con = sqlite3.connect(MDC_DB, timeout=8)
        cur = con.execute("update task set status=0, error_message=null "
                          "where id=? and status in (-1,0)", (int(task_id),))
        con.commit()
        n = cur.rowcount
        con.execute("PRAGMA wal_checkpoint(TRUNCATE)")
        con.close()
        if n:
            return {'ok': True, 'msg': '已复位为等待中；点「重启 MDC」即可被接管重跑'}
        return {'ok': False, 'msg': '任务不存在或当前状态不可重试'}
    except Exception as e:
        return {'ok': False, 'msg': sanitize_err(e, 140)}


def kg_mdc_provider_health():
    rows = _mdc_db(
        "select substr(message, instr(message,'<')+1, "
        " instr(substr(message, instr(message,'<')),'>')-1) site,"
        " sum(message like '成功抓取%') ok, sum(level='Warn') bad, count(*) n"
        " from log where message like '%抓取到数据%' "
        " and id > (select coalesce(max(id),0)-40000 from log)"
        " group by site order by n desc limit 20") or []
    return {'ok': True, 'rows': rows}


def kg_driver_toggle(enable):
    try:
        if enable:
            if os.path.exists(MDC_PAUSE_FLAG):
                os.remove(MDC_PAUSE_FLAG)
            return {'ok': True, 'msg': '已恢复：驱动下一 tick（≤5 分钟）继续分批'}
        with open(MDC_PAUSE_FLAG, 'w', encoding='utf-8') as f:
            f.write('paused by media-hub at %s' % time.strftime('%F %T'))
        return {'ok': True, 'msg': '已暂停：当前批次跑完后不再开新批'}
    except Exception as e:
        return {'ok': False, 'msg': sanitize_err(e, 150)}


def kg_driver_state():
    out = {'paused': os.path.exists(MDC_PAUSE_FLAG),
           'script': os.path.exists(MDC_DRV_SCRIPT)}
    if out['paused']:
        try:
            with open(MDC_PAUSE_FLAG, encoding='utf-8') as f:
                out['paused_at'] = f.read()[:70]
        except Exception:
            pass
    if os.path.exists(MDC_DRV_LOG):
        try:
            sz = os.path.getsize(MDC_DRV_LOG)
            with open(MDC_DRV_LOG, 'rb') as f:
                f.seek(max(0, sz - 20000))
                out['lines'] = f.read().decode('utf-8', 'replace').strip().split('\n')[-60:]
            out['mtime'] = time.strftime('%F %T', time.localtime(os.path.getmtime(MDC_DRV_LOG)))
        except Exception:
            out['lines'] = []
    return out


# ──────────── Emby 缺图体检 / 补齐 ────────────

def _emby_local(path):
    """Emby 容器视角 Path → media-hub 可见本地路径。两种库前缀：
      /strm-mdc-ng/...  → /dockroot/mdc-ng/strm-mdc-ng/...   （KFC2 成人库）
      /strm/...         → /dockroot/mediatidy/strm/...        （KFC 主库 MT strm）
      /CloudNAS/...     → 原样（面板同挂）；/vol1/... → 剥 /vol1/1000。
    返回 None 表示面板看不到该路径。"""
    p = str(path or '')
    if p.startswith('/strm-mdc-ng/'):
        return '/dockroot/mdc-ng/strm-mdc-ng/' + p[len('/strm-mdc-ng/'):]
    if p.startswith('/strm/'):
        return '/dockroot/mediatidy/strm/' + p[len('/strm/'):]
    if p.startswith('/CloudNAS/'):
        return p
    if p.startswith('/vol1/1000/CloudNAS/'):
        return '/CloudNAS/' + p[len('/vol1/1000/CloudNAS/'):]
    return None


def _img_present(vdir, lack_types):
    """按缺项类型核本地文件：任一缺失类型在目录里有对应图 → 可重读。"""
    if not vdir or not os.path.isdir(vdir):
        return False, []
    try:
        fl = os.listdir(vdir)
    except Exception:
        return False, []
    low = [f.lower() for f in fl]
    fixable = []
    for t in lack_types:
        if t == 'primary':
            if any(f.endswith(('.jpg', '.png', '.webp')) and
                   ('poster' in f or 'strm' not in f) for f in low):
                fixable.append(t)
        elif t == 'backdrop':
            if any(f.endswith(('.jpg', '.png', '.webp')) and 'fanart' in f for f in low) \
               or 'extrafanart' in fl:
                fixable.append(t)
        elif t == 'logo':
            if any(f.endswith(('.png', '.jpg')) and 'logo' in f for f in low):
                fixable.append(t)
        elif t == 'thumb':
            if any(f.endswith(('.jpg', '.png')) and 'thumb' in f for f in low):
                fixable.append(t)
        else:
            if any(f.endswith(('.jpg', '.png', '.webp')) for f in low):
                fixable.append(t)
    return bool(fixable), fixable


_EMBY_IMG_KEYS = {'primary': 'Primary', 'backdrop': 'Backdrop',
                  'banner': 'Banner', 'logo': 'Logo', 'thumb': 'Thumb',
                  'disc': 'Disc'}


def _emby_inst(which):
    c = cfg()
    conf = containers().get(which) or containers()['emby']
    key = c.get('emby_key' if which == 'emby' else 'emby_key2', '')
    return conf['addr'], conf['port'], (key or '')


KG_GUI_PORTS = {'9208': ('mdc', 9208), '8000': ('avdb', 8000)}


def kg_gui_proxy(handler, seg_path, method, body):
    """透明反向代理：/kgui/<port>/<原路径> -> http://<addr>:<port>/<原路径>。
    HTML/JS/CSS 里的根绝对路径重写为带前缀 + 注入 fetch/XHR 拦截，保证子资源也走代理。
    二进制安全（非文本不重写）。"""
    import http.client as _hc
    segs = [s for s in str(seg_path).split('/') if s]   # ['kgui','9208','a','b']
    port_key = segs[1] if len(segs) > 1 else ''
    conf = KG_GUI_PORTS.get(port_key)
    if not conf:
        return handler._s(404, b'unknown kgui target', 'text/plain')
    key, port = conf
    c0 = containers().get(key) or {}
    addr = c0.get('addr') or cfg().get('emby_addr') or '127.0.0.1'
    rest = ('/' + '/'.join(segs[2:])) if len(segs) > 2 else '/'
    qs = urllib.parse.urlparse(handler.path).query
    tgt = rest + ('?' + qs if qs else '')
    hdrs = {'Host': '%s:%s' % (addr, port)}
    for hk in ('Content-Type', 'User-Agent', 'Rsc', 'Next-Router-State-Tree',
               'Next-Router-Prefetch', 'Next-Router-Segment-Prefetch',
               'X-Matched-Path', 'Accept-Language'):
        v = handler.headers.get(hk)
        if v:
            hdrs[hk] = v
    try:
        conn = _hc.HTTPConnection(str(addr), int(port), timeout=30)
        conn.request(method, tgt, body=body if body else None, headers=hdrs)
        r = conn.getresponse()
        data = r.read()
        conn.close()
        ctype = (r.getheader('Content-Type', '') or '').lower()
        if 'html' in ctype or 'javascript' in ctype or 'css' in ctype:
            try:
                txt = data.decode('utf-8')
                base = '/kgui/%s' % port_key
                txt = txt.replace('href="/', 'href="%s/' % base)
                txt = txt.replace('src="/', 'src="%s/' % base)
                if 'html' in ctype:
                    inject = ('<script>(function(){var B="%s";'
                              'function rw(u){try{if(typeof u==="string"&&u.charAt(0)==="/"'
                              '&&u.indexOf(B)!==0)return B+u;}catch(e){}return u;}'
                              'var f=window.fetch;window.fetch=function(u,o){'
                              'u=(typeof u==="string")?rw(u):u;return f.call(this,u,o)};'
                              'var X=XMLHttpRequest.prototype.open;'
                              'XMLHttpRequest.prototype.open=function(m,u){'
                              'return X.apply(this,[m,rw(u)].concat([].slice.call(arguments,2)))};'
                              'var H=history.pushState,p=history.replaceState;'
                              'history.pushState=function(a,b,c){try{c=rw(c)}catch(e){}'
                              'return H.call(this,a,b,c)};'
                              'history.replaceState=function(a,b,c){try{c=rw(c)}catch(e){}'
                              'return p.call(this,a,b,c)};'
                              'var ce=document.createElement.bind(document);'
                              'document.createElement=function(t,o){var e=ce(t,o);var tl=String(t||"").toLowerCase();'
                              'try{if((tl==="script"||tl==="img"||tl==="iframe")&&e){'
                              'Object.defineProperty(e,"src",{configurable:true,'
                              'get:function(){return this.getAttribute("src")||"";},'
                              'set:function(v){this.setAttribute("src",rw(v));}});}}catch(x){}'
                              'try{if(tl==="link"&&e){Object.defineProperty(e,"href",{configurable:true,'
                              'get:function(){return this.getAttribute("href")||"";},'
                              'set:function(v){this.setAttribute("href",rw(v));}});}}catch(x){}'
                              'return e;};'
                              '})();</script>' % base)
                    i0 = txt.find('<head>')
                    txt = (txt[:i0 + 6] + inject + txt[i0 + 6:]) if i0 >= 0 else (inject + txt)
                data = txt.encode('utf-8')
            except Exception:
                pass
        handler.send_response(r.status)
        for hk, hv in r.getheaders():
            if hk.lower() in ('transfer-encoding', 'content-length', 'connection',
                              'content-encoding'):
                continue
            try:
                handler.send_header(hk, hv)
            except Exception:
                pass
        handler.send_header('Content-Length', str(len(data)))
        handler.end_headers()
        handler.wfile.write(data)
    except Exception as e:
        try:
            handler._s(502, ('kgui proxy error: %s' % str(e)[:160]).encode(), 'text/plain')
        except Exception:
            pass


def kg_mdc_tree(path=''):
    """MDC file_tree 单层列目录（建任务目录选择器）。"""
    p = (path or '/CloudNAS/115open').strip()
    if len(p) > 200:
        return {'ok': False, 'msg': 'path too long', 'items': []}
    st, b = _mdc_http('/api/file_tree?root=' + urllib.parse.quote(p), t=25)
    if st != 200 or isinstance(b, str):
        return {'ok': False, 'msg': 'file_tree HTTP %s' % st, 'items': []}
    items = [{'name': x.get('name'), 'path': x.get('path'),
              'dir': bool(x.get('is_dir')), 'size': x.get('size') or 0}
             for x in (b or [])[:800]]
    items.sort(key=lambda x: (not x['dir'], str(x['name'])))
    parent = p.rsplit('/', 1)[0] or '/'
    return {'ok': True, 'path': p, 'parent': parent, 'items': items}


def _kg_launch_pending():
    """若无 running job，重启 mdc-ng 让其在启动时接管 pending 批次。
    复用 app.py 已有 act_generic -> ctr_action（docker.sock 重启）。"""
    try:
        st, lst = _mdc_http('/api/manual-jobs?page=1&page_size=100', t=15)
        data = (lst or {}).get('data') if isinstance(lst, dict) else []
        run = [j for j in (data or []) if j.get('status') == 1]
        pend = [j for j in (data or []) if j.get('status') == 0]
        if run or not pend:
            return {'ok': False, 'msg': '有运行中批次或无待启动批次' if run else '无 pending'}
        jid = sorted(pend, key=lambda x: x['id'])[-1]['id']
        r = act_generic('mdc', 'restart', None)
        oplog('web', 'kg_launch', 'MDC 手动批次 #%s 启动' % jid, bool(r.get('ok')),
              str(r.get('msg', ''))[:120])
        return {'ok': True, 'job': jid, 'msg': '已重启接管 #%s' % jid}
    except Exception as e:
        return {'ok': False, 'msg': str(e)[:150]}


def kg_mdc_job_create(b):
    """建批任务（字段搬运自原生 UI）。pathes<=60，可选 config_override。"""
    pathes = b.get('pathes') or []
    target = (b.get('target_folder') or '').strip()
    if not pathes or not isinstance(pathes, list) or len(pathes) > 60:
        return {'ok': False, 'msg': '源目录需为列表（1-60 个）'}
    if not target:
        return {'ok': False, 'msg': '缺少目标目录'}
    try:
        link_mode = int(b.get('link_mode', 2))
    except Exception:
        link_mode = 2
    payload = {'pathes': pathes, 'target_folder': target, 'link_mode': link_mode,
               'delete_empty_parent_after_move': bool(b.get('delete_empty_parent_after_move', True))}
    common = {}
    for k in ('delete_by_ext', 'delete_by_name', 'delete_by_size',
              'delete_metadata_folder_when_failed'):
        if k in b:
            common[k] = bool(b[k])
    if b.get('file_name_blacklist'):
        common['file_name_blacklist'] = [str(x)[:120] for x in b['file_name_blacklist'][:60]]
    if b.get('file_ext_filter'):
        common['file_ext_filter'] = [str(x)[:20] for x in b['file_ext_filter'][:40]]
    if common:
        payload['config_override'] = {'common': common}
    st, resp = _mdc_http('/api/manual-jobs', 'POST', payload, t=25)
    if st not in (200, 201):
        return {'ok': False, 'msg': 'MDC 拒绝创建 HTTP %s %s' % (st, str(resp)[:150])}
    out = {'ok': True, 'msg': '批次已创建', 'resp': resp}
    if bool(b.get('auto_start', True)):
        # 后台线程尝试启动（无 running 才重启接管），避免 docker restart 阻塞本响应
        threading.Thread(target=_kg_launch_pending, daemon=True).start()
        out['msg'] += '，正在后台启动（空闲即接管）'
    return out


def emby_imgscan(which='emby_adult', types='primary,backdrop,logo', limit=1600):
    """扫描缺图条目：Emby ImageTags 判定 + 面板侧本地图片文件复核（/CloudNAS 同挂）。
    which=all 两台都扫。"""
    want_all = [t for t in (types or 'primary').split(',') if t in _EMBY_IMG_KEYS] or ['primary']
    # logo/banner 对 AV 库无意义（网站根本不产出），只展示不驱动补齐判定
    want = [t for t in want_all if t not in ('logo', 'banner')] or ['primary']
    opt = [t for t in want_all if t in ('logo', 'banner')]
    servers = (['emby', 'emby_adult'] if which == 'all'
               else ['emby_adult'] if which in ('emby_adult', 'adult', 'kfc2')
               else ['emby'])
    out = {'ok': True, 'servers': [], 'scanned': 0}
    for sv in servers:
        addr, port, key = _emby_inst(sv)
        if not addr or not key:
            out['servers'].append({'server': sv, 'err': '未配置 addr/key（设置页补）'})
            continue
        items, start, total = [], 0, 0
        err = ''
        while True:
            p = ('/Items?Recursive=true&IncludeItemTypes=Movie,Series'
                 '&Fields=ImageTags,Path,ProviderIds,ProductionYear'
                 '&StartIndex=%d&Limit=800&api_key=%s' % (start, key))
            st, b = hget(addr, port, p, None, 25)
            if st != 200 or not isinstance(b, dict):
                err = 'Emby HTTP %s' % st
                break
            batch = b.get('Items') or []
            items.extend(batch)
            total = b.get('TotalRecordCount') or 0
            start += len(batch)
            if not batch or start >= total or len(items) >= int(limit):
                break
        miss = []
        for it in items:
            tags = it.get('ImageTags') or {}
            lack = [t for t in want if not tags.get(_EMBY_IMG_KEYS[t])]
            if not lack:
                continue
            lack_disp = lack + [t for t in opt if not tags.get(_EMBY_IMG_KEYS[t])]
            path = str(it.get('Path') or '')
            lp = _emby_local(path)
            vdir = os.path.dirname(lp) if lp else ''
            fixable_ok, fixable = _img_present(vdir, lack)
            miss.append({'id': it.get('Id'), 'name': it.get('Name'),
                         'type': it.get('Type'), 'lack': lack_disp,
                         'year': it.get('ProductionYear'),
                         'tmdb': (it.get('ProviderIds') or {}).get('Tmdb') or '',
                         'strm': path.lower().endswith('.strm'),
                         'local': 1 if fixable_ok else 0,
                         'fixable': fixable,
                         'vdir': vdir,
                         'path': path[-64:]})
        out['servers'].append({'server': sv, 'total': total,
                               'scanned': len(items), 'missing': len(miss),
                               'local_ready': sum(1 for m in miss if m['local']),
                               'need_scrape': sum(1 for m in miss if not m['local']),
                               'err': err, 'items': miss[:500]})
        out['scanned'] += len(items)
    return out


def emby_imgfix(items, which='emby_adult', dry=False):
    """①有本地图 → Refresh+RemoveOldImages；②无本地图 → 记入补刮单
    /dockroot/media-hub/emby_rescrape.json（MDC 页「补刮单」入口消费）。"""
    addr, port, key = _emby_inst(which)
    if not addr or not key:
        return {'ok': False, 'msg': '未配置 Emby addr/key'}
    ids = [str(x.get('id')) for x in (items or [])
           if str(x.get('id', '')).isdigit()][:200]
    if not ids:
        return {'ok': False, 'msg': '没有有效条目'}
    idmap = {str(x.get('id')): x for x in items}
    refreshed, failed, nolocal = [], [], []
    # 批量取 Path（单条详情端点在本 Emby 版本 404，必须走 /emby/Items?Ids=）
    pathmap = {}
    for k in range(0, len(ids), 50):
        chunk = ids[k:k + 50]
        st, b = hget(addr, port,
                     '/emby/Items?Ids=%s&Fields=Path&api_key=%s'
                     % (','.join(chunk), key), None, 20)
        if st == 200 and isinstance(b, dict):
            for it in (b.get('Items') or []):
                pathmap[str(it.get('Id'))] = str(it.get('Path') or '')
    for iid in ids:
        path = pathmap.get(iid, '')
        lp = _emby_local(path)
        vdir = os.path.dirname(lp) if lp else ''
        has_local = bool(vdir) and any(_img_present(vdir, ['primary', 'backdrop', 'logo', 'thumb'])[1])
        if has_local:
            if dry:
                refreshed.append(iid)
                continue
            p = '/Items/%s/Refresh?api_key=%s&Recursive=false&RemoveOldImages=true' % (iid, key)
            st2, _ = hreq(addr, port, 'POST', p, b'',
                          {'Content-Type': 'application/json'}, 12)
            (refreshed if st2 in (200, 204) else failed).append(iid)
        else:
            it = idmap[iid]
            nolocal.append({'id': iid, 'name': it.get('name') or it.get('Name'),
                            'tmdb': it.get('tmdb', ''), 'path': path[-64:]})
        time.sleep(0.15)
    try:
        os.makedirs('/dockroot/media-hub', exist_ok=True)
        with open('/dockroot/media-hub/emby_rescrape.json', 'w', encoding='utf-8') as f:
            json.dump({'ts': time.strftime('%F %T'), 'which': which,
                       'items': nolocal}, f, ensure_ascii=False)
    except Exception:
        pass
    return {'ok': True, 'dry': bool(dry),
            'refreshed': len(refreshed), 'failed': failed,
            'need_rescrape': nolocal,
            'msg': '本地图重读 %d 个；%d 个无本地图已写入补刮单；失败 %d%s' % (
                len(refreshed), len(nolocal), len(failed),
                '（试运行，未提交）' if dry else '')}


def emby_imgbackfill_check():
    """KFC2 strm 入库目录图片覆盖（本地 dockroot 视角，秒级）。
    含 strm 的目录里 jpg=0 → MDC 图片阶段失败；jpg>0 但 Emby 缺 → 没重读。"""
    root = '/dockroot/mdc-ng/strm-mdc-ng/已刮削'
    out = {'root': '/strm-mdc-ng/已刮削', 'exists': os.path.isdir(root)}
    if out['exists']:
        dirs = imgs = vids = no_img = 0
        try:
            depth = 0
            for dp, dn, fn in os.walk(root):
                depth += 1
                if depth > 12000:
                    out['capped'] = True
                    break
                n_img = sum(1 for x in fn if x.lower().endswith(('.jpg', '.png', '.webp')))
                n_vid = sum(1 for x in fn if x.lower().endswith('.strm'))
                if n_vid:
                    dirs += 1
                    imgs += n_img
                    vids += n_vid
                    if n_img == 0:
                        no_img += 1
        except Exception as e:
            out['err'] = str(e)[:80]
        out.update({'strm_dirs': dirs, 'images': imgs, 'strms': vids,
                    'dirs_without_img': no_img})
    return out


def act_mdc(act, arg):
    conf = containers()['mdc']
    if act == 'health':
        st, b = _mdc_http('/api/manual-jobs?page=1&page_size=1', t=8)
        ok = st == 200
        return {'ok': ok, 'http': st,
                'msg': ('MDC-NG 在线 · API 正常') if ok
                       else 'MDC-NG 异常（HTTP %s，设置页核对 mdc_addr/mdc_port）' % st}
    return act_generic('mdc', act, arg)


def act_flare(act, arg):
    conf = containers()['flaresolverr']
    if act in ('logs', 'stats', 'state', 'start', 'stop', 'restart'):
        return act_generic('flaresolverr', act, arg)
    if act == 'test':
        body = json.dumps({'cmd': 'request.get', 'url': 'https://www.baidu.com', 'maxTimeout': 60000})
        st, b = hreq(conf['addr'], conf['port'], 'POST', '/v1', body,
                     {'Content-Type': 'application/json'}, 70)
        if st != 200:
            return {'ok': False, 'msg': 'FlareSolverr 自检失败 HTTP %s' % st}
        try:
            j = json.loads(b)
            return {'ok': True, 'msg': 'FlareSolverr 正常，解出 cookie %d 个' % len(j.get('cookies', []))}
        except Exception:
            return {'ok': http_health_ok(st), 'msg': 'HTTP %s' % st}
    return act_generic('flaresolverr', act, arg)


def act_embyboss(act, arg):
    # ★ 2026-10-24：补 health（此前「EmbyBoss 卡密」卡的「健康检查」按钮返回「未实现」）。
    #   embyboss 是带 HTTP 服务的容器，探活即可；同时回显版本/连通性。
    if act == 'health':
        conf = containers()['embyboss']
        st, b = hreq(conf['addr'], conf['port'], 'GET', '/', None, None, 6)
        ok = http_health_ok(st)
        return {'ok': ok, 'http': st,
                'msg': ('EmbyBoss 在线 · HTTP %s' % st) if ok
                else 'EmbyBoss 异常（HTTP %s）' % st, 'data': {'http': st}}
    return act_generic('embyboss', act, arg)


