# ══════════════════ PT 全链路（v7：合并原 kfcdash 9292 面板）══════════════════
# 数据源：qBittorrent API / MoviePilot API(JWT) / MySQL(pt2cloud+kfcgame) / Emby
# ★★ v1.38 C2b 开源脱敏：MySQL 连接全部走环境变量 / 设置页，默认全空。
#   新装用户在「设置 → 数据库」填自己的（库 pt2cloud / kfcgame / embyboss
#   通常同库同账号）；老用户 webcfg.json 已持久化，升级不受影响。
def _pt_db():
    c = cfg()
    g = lambda k, env, d: (c.get(k) or os.environ.get(env) or d)
    try:
        port = int(float(str(g('ptdb_port', 'PTDB_PORT', '3306')).strip() or 3306))
    except Exception:
        port = 3306
    return {
        'host': g('ptdb_host', 'PTDB_HOST', ''),
        'port': port,
        'user': g('ptdb_user', 'PTDB_USER', ''),
        'password': g('ptdb_pass', 'PTDB_PASS', ''),
        'db': g('ptdb_name', 'PTDB_NAME', 'pt2cloud'),
    }

def _pt_db_env():
    """后台线程（无 cfg 上下文）兜底：直接读环境变量。"""
    try:
        port = int(os.environ.get('PTDB_PORT', '3306'))
    except Exception:
        port = 3306
    return {
        'host': os.environ.get('PTDB_HOST', ''),
        'port': port,
        'user': os.environ.get('PTDB_USER', ''),
        'password': os.environ.get('PTDB_PASS', ''),
        'db': os.environ.get('PTDB_NAME', 'pt2cloud'),
    }
# ★★ v1.38 C2b 开源脱敏：MP 登录账号/密码默认全空，由设置页 / 环境变量提供
#   （MP_USER / MP_PASS，或 webcfg.json 的 mp_user / mp_pass）。
#   老用户本地已持久化，升级不受影响；新装用户在设置页填自己的 MP 账号。
def _mp_cred():
    c = cfg()
    return ((c.get('mp_user') or os.environ.get('MP_USER') or '').strip(),
            (c.get('mp_pass') or os.environ.get('MP_PASS') or '').strip())
MP_USER = os.environ.get('MP_USER', '')
MP_PASS = os.environ.get('MP_PASS', '')
MP_JWT = {'v': None, 'ts': 0.0}
# ★★ v1.37 S2 开源脱敏：不再内置任何作者本人的 Emby API Key。
#   老用户本地 webcfg.json 里已有 emby_key，行为不变；全新部署由引导向导/设置页填写。
EMBY_KEY_FB = os.environ.get('EMBY_KEY_FB', '')


def my_query(sql, args=None, db=None):
    """MySQL 查询（pymysql 纯 Python，容器镜像内置）。失败抛异常由调用方兜住。"""
    import pymysql
    _pd = _pt_db()
    conn = pymysql.connect(
        host=_pd['host'], port=_pd['port'], user=_pd['user'],
        password=_pd['password'], database=db or _pd['db'],
        charset='utf8mb4', connect_timeout=8,
        cursorclass=pymysql.cursors.DictCursor)
    try:
        with conn.cursor() as cur:
            cur.execute(sql, args or ())
            return cur.fetchall()
    finally:
        try:
            conn.close()
        except Exception:
            pass


def rows_ok(rows):
    """datetime -> str，保证能 json 序列化"""
    return [{k: (v.isoformat(sep=' ') if hasattr(v, 'isoformat') else v)
             for k, v in r.items()} for r in rows]


def mp_jwt():
    """MP 账号密码换 JWT（比 X-API-KEY 稳，token 过期自动重登）"""
    if MP_JWT['v'] and time.time() - MP_JWT['ts'] < 3000:
        return MP_JWT['v']
    b = containers()['moviepilot']
    st, r = hreq(b['addr'], b['port'], 'POST', '/api/v1/login/access-token',
                 urllib.parse.urlencode({'username': (cfg().get('mp_user') or MP_USER).strip(),
                                          'password': (cfg().get('mp_pass') or MP_PASS).strip()}),
                 {'Content-Type': 'application/x-www-form-urlencoded'}, 10)
    try:
        tok = (json.loads(r) or {}).get('access_token')
    except Exception:
        tok = None
    if tok:
        MP_JWT.update(v=tok, ts=time.time())
    return tok


def mp_api(path, method='GET', body=None, t=15):
    b = containers()['moviepilot']
    tk = mp_jwt()
    if not tk:
        return {'ok': False, 'msg': 'MoviePilot 登录失败（账号密码）'}
    hdr = {'Authorization': 'Bearer %s' % tk, 'Content-Type': 'application/json'}
    st, r = hreq(b['addr'], b['port'], method, path,
                 json.dumps(body) if body is not None else None, hdr, t)
    if st == 401:
        MP_JWT.update(v=None, ts=0)
        tk = mp_jwt()
        if not tk:
            return {'ok': False, 'msg': 'MoviePilot 登录失败（token 刷新失败）'}
        st, r = hreq(b['addr'], b['port'], method, path,
                     json.dumps(body) if body is not None else None,
                     {'Authorization': 'Bearer %s' % tk, 'Content-Type': 'application/json'}, t)
    if st < 200 or st >= 300:
        return {'ok': False, 'msg': 'MoviePilot HTTP %s %s' % (st, (r or '')[:120])}
    try:
        j = json.loads(r)
    except Exception:
        return {'ok': True, 'data': (r or '')[:300]}
    if isinstance(j, dict) and j.get('success') is False:
        return {'ok': False, 'msg': j.get('message') or 'MP 返回失败'}
    return {'ok': True, 'data': j.get('data') if isinstance(j, dict) else j}


def pt_subs():
    """MP 订阅列表（精简字段 + 完结标记）"""
    r = mp_api('/api/v1/subscribe/')
    if not r.get('ok'):
        return r
    subs = r.get('data') or []
    items = []
    for s in subs:
        items.append({
            'id': s.get('id'), 'name': s.get('name') or '?', 'year': s.get('year') or '',
            'type': s.get('type') or '', 'state': s.get('state') or '',
            'poster': s.get('poster') or '', 'site': s.get('site') or '',
            # state R=完结（电影未上映也可能是 R，自动清理只处理电视剧）
            'done': (s.get('state') == 'R' and s.get('type') == '电视剧'),
        })
    return {'ok': True, 'items': items,
            'total': len(items),
            'done_n': sum(1 for x in items if x['done'])}


def pt_sub_delete(ids):
    ok, fail = [], []
    for i in ids or []:
        r = mp_api('/api/v1/subscribe/%s' % i, method='DELETE')
        (ok if r.get('ok') else fail).append(str(i))
    return {'ok': not fail, 'msg': '已取消 %s 个订阅%s' % (
        len(ok), ('，失败: ' + ','.join(fail)) if fail else ''), 'ok_ids': ok, 'fail': fail}


def _sub_tor_hashes(sub_ids):
    """勾选的订阅 → qB 里对应种子 hash 列表。

    匹配策略（从松到紧，取并集）：
      ① qB 种子 name 包含订阅名（去掉年份后缀）
      ② qB 种子 save_path 含订阅名
    只认 下载中/做种 分类，避免误伤保号辅种。
    """
    try:
        r = mp_call("/api/v1/subscribe/?page=1&count=200")
        subs = []
        dd = r.get("data")
        for x in (dd if isinstance(dd, list) else ((dd or {}).get("items") or [])):
            try:
                if int(x.get("id") or 0) in set(int(i) for i in sub_ids):
                    subs.append(str(x.get("name") or x.get("title") or "").strip())
            except Exception:
                pass
        if not subs:
            return [], []
        tors, err = _qb_all()
        if err:
            return [], subs
        def _norm(t):
            import re as _re
            t = _re.sub(r"\s*\(\d{4}\)\s*$", "", str(t or ""))
            return _re.sub(r"[\s_.\-]+", "", t).lower()
        keys = [_norm(x) for x in subs if _norm(x)]
        hits, names = [], []
        for t in tors:
            nm = str(t.get("name") or "")
            nnm = _norm(nm)
            if not nnm:
                continue
            if any(k and (k in nnm or nnm in k) for k in keys):
                hits.append(str(t.get("hash") or ""))
                names.append(nm)
        return hits, names
    except Exception as e:
        logger.debug("订阅→种子匹配失败: %s", e)
        return [], []


def pt_subs_priority(sub_ids):
    """勾选订阅 → 对应 qB 种子置顶下载（qB increasePrio）。"""
    hs, names = _sub_tor_hashes(sub_ids)
    if not hs:
        return {"ok": False, "msg": "这些订阅在 qB 里没有对应下载任务（可能还没开始下载）"}
    ok = True
    for h in hs:
        cookie, err = qb_login()
        if err:
            return {"ok": False, "msg": err.get("msg") or "qB 未登录"}
        st, _b = qb_call("POST", "/api/v2/torrents/increasePrio", {"hash": h}, cookie)
        ok = ok and st < 400
    return {"ok": ok, "msg": "已把 %d 个订阅的 %d 个种子置顶优先下载" % (
        len(set(sub_ids)), len(hs)), "torrents": names[:10]}


def pt_subs_startdl(sub_ids):
    """勾选订阅 → 对应 qB 种子开始下载（batch_resume，暂停中的会被拉起来）。"""
    hs, names = _sub_tor_hashes(sub_ids)
    if not hs:
        return {"ok": False, "msg": "这些订阅在 qB 里没有对应下载任务"}
    cookie, err = qb_login()
    if err:
        return {"ok": False, "msg": err.get("msg") or "qB 未登录"}
    st, _b, used = qb_resume(hs, cookie)
    return {"ok": st == 200,
            "msg": ("已开始下载 %d 个种子（勾选的 %d 个订阅）" % (
                len(hs), len(set(sub_ids)))) if st == 200 else
                   ("开始下载失败：qB 返回 HTTP %s（%s）" % (st, used or '未知端点')),
            "torrents": names[:10]}


def pt_sub_search(ids):
    ok, fail = [], []
    for i in ids or []:
        r = mp_api('/api/v1/subscribe/search/%s' % i, method='POST', body={})
        (ok if r.get('ok') else fail).append(str(i))
    return {'ok': not fail, 'msg': '已触发 %s 个订阅的立即搜索%s' % (
        len(ok), ('，失败: ' + ','.join(fail)) if fail else ''), 'ok_ids': ok, 'fail': fail}


def pt_autoclean(dry=False):
    """清理完结订阅：只删 state=R 且 type=电视剧 的（电影未上映也是 R，不能误删）"""
    r = pt_subs()
    if not r.get('ok'):
        return {'ok': False, 'msg': r.get('msg') or '获取订阅失败'}
    victims = [x for x in r['items'] if x['done']]
    if dry:
        return {'ok': True, 'dry': True, 'candidates': [x['name'] for x in victims],
                'msg': '可清理 %d 部完结剧' % len(victims)}
    if not victims:
        return {'ok': True, 'deleted': [], 'msg': '没有完结的电视剧订阅'}
    res = pt_sub_delete([x['id'] for x in victims])
    return res


def _pt_autoclean_loop():
    """每小时自动清理完结订阅（合并自 kfcdash，进程内守护线程）"""
    time.sleep(150)
    while True:
        try:
            r = pt_autoclean()
            if r.get('ok') and r.get('msg') != '没有完结的电视剧订阅':
                oplog('pt', 'autoclean', '自动清理完结订阅', True, r.get('msg'))
        except Exception as e:
            try:
                oplog('pt', 'autoclean', '自动清理完结订阅', False, str(e))
            except Exception:
                pass
        time.sleep(3600)


# ══════════════════════ 数据缓存（页面提速）══════════════════════
# 每个数据源都带 TTL，命中缓存直接返回；后台线程每 20s 预热一次，
# 保证用户点开页面时数据已经是热的（首屏几乎无等待）。
_CACHE = {}
# TTL 必须明显大于预热周期（sleep 15s + 一轮刷新耗时），否则用户点开正好撞上
# 过期窗口，会同步重算（svc_overview 要跑 docker inspect，实测 5~6s）→ 卡。
_CACHE_TTL = {'overview': 120, 'diagnose': 180, 'pt': 30, 'media': 180,
              'mt': 30, 'notify': 30, 'wish': 60, 'services': 120,
               'deep': 60, 'live': 15}
_CLOCK = threading.Lock()


def cached(key, fn, ttl=None, force=False, **kw):
    """带 TTL 的缓存。kw 会透传给 fn，并参与缓存 key（如 page/size）。"""
    if kw:
        key = '%s:%s' % (key, '&'.join('%s=%s' % (k, kw[k]) for k in sorted(kw)))
    now = time.time()
    if not force:
        with _CLOCK:
            e = _CACHE.get(key)
        if e and now - e[0] < (ttl or _CACHE_TTL.get(key, 30)):
            v = e[1]
            # 返回值可能是 dict，也可能是 list（list 没有 _cached/_age 这层壳）
            if isinstance(v, dict):
                v = dict(v, _cached=True, _age=round(now - e[0]))
            return v
    v = fn(**kw) if kw else fn()
    with _CLOCK:
        _CACHE[key] = (time.time(), v)
    if isinstance(v, dict):
        v = dict(v, _cached=False, _age=0)
    return v


