def pt_overview():
    """聚合 PT 全链路数据：qB / MP 订阅 / pt2cloud / wishlist / 播报 / Emby / 磁盘

    ★ 数据源之间互不依赖，全部并发拉取（原来是串行，首屏要等好几秒）。
    """
    out = {'ok': True, 'ts': time.strftime('%F %T')}

    def _disk():
        return disk_info()

    def _qb():
        cookie, err = qb_login()
        if err:
            return {'ok': False, 'msg': err.get('msg')}
        st, b = qb_call('GET', '/api/v2/transfer/info', None, cookie)
        tr = json.loads(b) if st == 200 else {}
        st2, b2 = qb_call('GET', '/api/v2/torrents/info', None, cookie)
        ts = json.loads(b2) if st2 == 200 else []
        seeding = [t for t in ts if float(t.get('progress') or 0) >= 1]
        ratios = [float(t.get('ratio') or 0) for t in seeding]

        def _added(t):
            v = t.get('added_on')
            try:
                return time.strftime('%F', time.localtime(int(v)))
            except Exception:
                return ''
        return {'ok': True,
                'dl': int(tr.get('dl_info_speed') or 0),
                'ul': int(tr.get('up_info_speed') or 0),
                'total': len(ts),
                'downloading': sum(1 for t in ts if float(t.get('progress') or 0) < 1),
                'seeding': len(seeding),
                'ratio_avg': (sum(ratios) / len(ratios)) if ratios else 0,
                'total_uploaded': sum(int(t.get('uploaded') or 0) for t in ts),
                # 做种/保种记录：全部种子按累计上传量倒序
                'seeders': [{'name': (t.get('name') or '')[:80],
                             'size': int(t.get('size') or 0),
                             'uploaded': int(t.get('uploaded') or 0),
                             'ratio': round(float(t.get('ratio') or 0), 2),
                             'days': round(int(t.get('seeding_time') or 0) / 86400, 1),
                             'state': t.get('state') or '',
                             'added': _added(t),
                             'category': t.get('category') or ''}
                            for t in sorted(ts, key=lambda x: -int(x.get('uploaded') or 0))],
                'top': [{'name': (t.get('name') or '')[:60],
                         'size': int(t.get('size') or 0),
                         'ratio': round(float(t.get('ratio') or 0), 2),
                         'state': t.get('state') or '',
                         'progress': round(float(t.get('progress') or 0) * 100, 1),
                         'category': t.get('category') or ''}
                        for t in sorted(ts, key=lambda x: -float(x.get('ratio') or 0))[:8]]}

    def _subs():
        r = pt_subs()
        return ({'ok': True, 'items': r['items'][:60], 'total': r['total'],
                 'done_n': r['done_n']} if r.get('ok') else r)

    def _pt2():
        cnt = my_query("SELECT status, COUNT(*) c FROM pt_uploads GROUP BY status")
        rec = my_query("SELECT id, media_title, torrent_name, year, media_type, quality, "
                       "status, stage, total_size, progress, updated_at "
                       "FROM pt_uploads ORDER BY id DESC LIMIT 50")
        return {'ok': True, 'counts': {x['status']: x['c'] for x in cnt},
                'recent': rows_ok(rec)}

    def _wish():
        w = my_query("SELECT * FROM kfc_wishlist ORDER BY id DESC LIMIT 10", db='kfcgame')
        return {'ok': True, 'recent': rows_ok(w)}

    def _notify():
        n = my_query("SELECT id, kind, media_title, bitrate, status, created_at "
                     "FROM kfc_pt_notify ORDER BY id DESC LIMIT 10", db='kfcgame')
        return {'ok': True, 'recent': rows_ok(n)}

    def _emby():
        ek = cfg().get('emby_key') or EMBY_KEY_FB
        st, b = hreq(containers()['emby']['addr'], containers()['emby']['port'],
                     'GET', '/emby/Items/Counts?api_key=' + ek, None, None, 6)
        j = json.loads(b) if st == 200 else {}
        return {'ok': st == 200, 'movie': j.get('MovieCount', 0),
                'series': j.get('SeriesCount', 0), 'episode': j.get('EpisodeCount', 0)}

    jobs = {'disk': _disk, 'qb': _qb, 'subs': _subs, 'pt2cloud': _pt2,
            'wish': _wish, 'notify': _notify, 'emby': _emby}
    with ThreadPoolExecutor(max_workers=7) as ex:
        futs = {k: ex.submit(v) for k, v in jobs.items()}
        for k, f in futs.items():
            try:
                out[k] = f.result()
            except Exception as e:
                out[k] = {'ok': False, 'msg': str(e)}
    return out


# ═══════════════════════════════════════════════════════════════════
#  链路健康总览（Chain Health）· /api/chain/health
# ───────────────────────────────────────────────────────────────────
#  用户需求（2026-10-24）：
#    「我刚重建了 kfcgame / 治理了 MT / CD2，要在面板上做一个跨容器健康总览，
#      打开就看清整条流水线的真实状态。」
#
#  设计（三条铁律）：
#    ① 数据源之间**互不依赖**，全部线程池并发，单源超时 ≤8s；
#       单源失败/超时**绝不阻塞整页** —— 该源降级为 {"ok":false,"err":...}，
#       前端显示「不可达」而不是空白。
#    ② 不引入任何新依赖（只用标准库 + 已有 helper）。
#    ③ 返回统一 JSON：{ok, ts, level, links:{...}}，每个 link 自带
#        {ok, level, title, metrics:[...], top:[...], jump}，前端直接渲染。
#
#  链路定义（按 PT→整理→入库→上云→落库 的真实流水线顺序）：
#     docker  容器总览（docker.sock，含 media-hub 自身只读状态）
#     qb      下载队列（qB API）
#     mp      订阅/下载历史/站点（MoviePilot API）
#     mt      整理任务/失败积压/趋势（MediaTidy 本地库）
#     cd2     挂载健康 + dir_cache 体积（CloudDrive2）
#     emby    媒体库计数（Emby API）
#     kfcgame bot 自检端点（另一任务正在修接线，失败降级为「不可用」）
# ═══════════════════════════════════════════════════════════════════
CHAIN_LINKS = ['docker', 'qb', 'mp', 'mt', 'cd2', 'emby', 'kfcgame']
CHAIN_SRC_TIMEOUT = 8


def _chain_level(ok, warn=0, bad=0):
    """链路级别：ok / warn / bad。"""
    if not ok or bad:
        return 'bad'
    if warn:
        return 'warn'
    return 'ok'


def _link_docker():
    """docker.sock：容器清单 + running/exited。media-hub 自身只读，不做任何动作。"""
    try:
        allc = ctr_list()
    except Exception as e:
        return {'ok': False, 'level': 'bad', 'title': 'Docker',
                'err': 'docker.sock 读取失败：%s' % str(e)[:100]}
    if not allc:
        return {'ok': False, 'level': 'bad', 'title': 'Docker',
                'err': 'docker.sock 未返回容器（sock 未挂载或无权限）'}
    by = {c['name']: c for c in allc}
    watch = ['kfcgame', 'moviepilot-v3', 'qbittorrent', 'mediatidy',
             'clouddrive2', 'emby-main', 'pt2cloud', 'agent2api', 'media-hub']
    rows, down = [], []
    for n in watch:
        c = by.get(n)
        if not c:
            rows.append({'name': n, 'state': 'missing', 'status': '容器不存在'})
            down.append(n)
            continue
        rows.append({'name': n, 'state': c.get('state') or '',
                     'status': (c.get('status') or '')[:40]})
        if c.get('state') != 'running':
            down.append(n)
    nrun = sum(1 for c in allc if c.get('state') == 'running')
    lvl = _chain_level(True, warn=0, bad=(1 if down else 0))
    # media-hub 自身是运行本服务的容器，不应判链路异常
    if down == ['media-hub']:
        lvl = 'warn'
    return {'ok': True, 'level': lvl, 'title': 'Docker 容器',
            'metrics': [{'k': '容器总数', 'v': len(allc)},
                        {'k': '运行中', 'v': nrun},
                        {'k': '关注容器', 'v': '%d/%d' % (len(watch) - len(down), len(watch))}],
            'rows': rows, 'down': down,
            'msg': ('全部关注容器运行中' if not down else '未运行：%s' % '、'.join(down))}


def _link_qb():
    """qB：队列统计。error 种子应随 heal 轮下降。"""
    try:
        r = qb_realtime()
    except Exception as e:
        return {'ok': False, 'level': 'bad', 'title': 'qBittorrent',
                'err': '读取失败：%s' % str(e)[:100]}
    if not r.get('ok'):
        return {'ok': False, 'level': 'bad', 'title': 'qBittorrent',
                'err': r.get('err') or 'qB 未登录/不可达'}
    tors = r.get('tors') or []
    stalled = sum(1 for t in tors if str(t.get('state') or '') in ('stalledDL', 'metaDL'))
    errs = [t for t in tors if str(t.get('state') or '') in ('error', 'missingFiles')]
    top = [{'name': t['name'], 'val': t.get('state_cn') or t.get('state')}
           for t in errs[:5]]
    lvl = _chain_level(True, warn=(1 if (stalled > 20 or errs) else 0), bad=0)
    return {'ok': True, 'level': lvl, 'title': 'qBittorrent 队列',
            'metrics': [{'k': '总种子', 'v': r.get('total', 0)},
                        {'k': '下载中', 'v': r.get('downloading', 0)},
                        {'k': '做种', 'v': r.get('seeding', 0)},
                        {'k': 'stalled', 'v': stalled},
                        {'k': 'error', 'v': len(errs)}],
            'top': top,
            'msg': '下载 %s · 上传 %s' % (r.get('global', {}).get('dl_speed_txt', '—'),
                                          r.get('global', {}).get('up_speed_txt', '—'))}


def _link_mp():
    """MP：订阅数 / 下载历史近 24h / 站点状态。"""
    try:
        subs = pt_subs()
    except Exception as e:
        subs = {'ok': False, 'msg': str(e)[:100]}
    sites = []
    try:
        s = mp_api('/api/v1/site')
        sites = s if isinstance(s, list) else (s.get('list') or [])
    except Exception:
        sites = []
    h24 = 0
    try:
        h = mp_api('/api/v1/download/history')
        items = h if isinstance(h, list) else (h.get('list') or [])
        cut = time.time() - 86400
        for it in items:
            d = it.get('date') or it.get('downloaded_at') or ''
            if d and d[:4].isdigit():
                try:
                    if time.mktime(time.strptime(d[:19].replace('T', ' '),
                                                 '%Y-%m-%d %H:%M:%S')) >= cut:
                        h24 += 1
                except Exception:
                    pass
    except Exception:
        pass
    nsub = subs.get('total', 0) if subs.get('ok') else 0
    lvl = _chain_level(bool(subs.get('ok')), warn=0, bad=(0 if subs.get('ok') else 1))
    return {'ok': bool(subs.get('ok')), 'level': lvl, 'title': 'MoviePilot',
            'metrics': [{'k': '在途订阅', 'v': nsub},
                        {'k': '下载历史(24h)', 'v': h24},
                        {'k': '启用站点', 'v': sum(1 for s in sites if s.get('active'))}],
            'msg': (subs.get('msg') or '') if not subs.get('ok') else 'API 正常'}


def _link_mt():
    """MT：进行中任务 / 失败积压 / 近 7 天失败趋势。"""
    try:
        with db() as c:
            stat = {r['status']: r['n'] for r in
                    c.execute("SELECT status,count(*) n FROM organize_tasks GROUP BY status")}
            fail = c.execute("SELECT IFNULL(SUM(error_files),0) s FROM organize_tasks").fetchone()['s']
            trend = []
            for i in range(6, -1, -1):
                day = time.strftime('%Y-%m-%d', time.localtime(time.time() - i * 86400))
                n = c.execute(
                    "SELECT IFNULL(SUM(error_files),0) s FROM organize_tasks "
                    "WHERE substr(IFNULL(finished_at,started_at),1,10)=?", (day,)).fetchone()['s']
                trend.append({'day': day[5:], 'v': int(n or 0)})
    except Exception as e:
        return {'ok': False, 'level': 'bad', 'title': 'MediaTidy',
                'err': '本地库读取失败：%s' % str(e)[:100]}
    running = stat.get('running', 0)
    zomb = stat.get('cancelled', 0) + stat.get('interrupted', 0)
    lvl = _chain_level(True, warn=(1 if (int(fail or 0) > 100000 or zomb > 50) else 0), bad=0)
    return {'ok': True, 'level': lvl, 'title': 'MediaTidy 整理',
            'metrics': [{'k': '进行中', 'v': running},
                        {'k': '失败文件', 'v': int(fail or 0)},
                        {'k': '僵尸记录', 'v': zomb},
                        {'k': '任务总数', 'v': sum(stat.values())}],
            'trend': trend,
            'msg': '失败积压 %s 个文件' % ('{:,}'.format(int(fail or 0)))}


def _link_cd2():
    """CD2：挂载健康 + dir_cache 体积。"""
    try:
        st = cd2_state()
        mnts = cd2_mounts()
        cache_mb = 0.0
        cp = '/cd2config/dir_cache.sqlite'
        if os.path.exists(cp):
            cache_mb = round(os.path.getsize(cp) / 1048576.0, 1)
    except Exception as e:
        return {'ok': False, 'level': 'bad', 'title': 'CloudDrive2',
                'err': '读取失败：%s' % str(e)[:100]}
    run = bool((st.get('ctr') or {}).get('running'))
    api = st.get('api')
    lvl = _chain_level(run and http_health_ok(api), warn=0, bad=(0 if run else 1))
    return {'ok': run, 'level': lvl, 'title': 'CloudDrive2',
            'metrics': [{'k': '容器', 'v': '运行中' if run else '已停止'},
                        {'k': 'API', 'v': ('HTTP %s' % api) if api else '不可达'},
                        {'k': '挂载根', 'v': len([m for m in mnts if not m.get('err')])},
                        {'k': 'dir_cache', 'v': '%.1f MB' % cache_mb}],
            'msg': ('挂载点 %s' % st.get('mount')) if run
            else 'CloudDrive2 容器未运行（115 网盘不可用，整理/上云会失败）'}


def _link_emby():
    """Emby：媒体库计数。"""
    try:
        ek = cfg().get('emby_key') or EMBY_KEY_FB
        stc, b = hreq(containers()['emby']['addr'], containers()['emby']['port'],
                      'GET', '/emby/Items/Counts?api_key=' + ek, None, None, 8)
        j = json.loads(b) if stc == 200 else {}
    except Exception as e:
        return {'ok': False, 'level': 'bad', 'title': 'Emby',
                'err': '读取失败：%s' % str(e)[:100]}
    ok = http_health_ok(stc)
    return {'ok': ok, 'level': _chain_level(ok, 0, 0 if ok else 1),
            'title': 'Emby 媒体库',
            'metrics': [{'k': '电影', 'v': j.get('MovieCount', 0)},
                        {'k': '剧集', 'v': j.get('SeriesCount', 0)},
                        {'k': '单集', 'v': j.get('EpisodeCount', 0)}],
            'msg': 'HTTP %s' % stc}


def _link_kfcgame():
    """kfcgame bot 自检端点。另一任务正在修接线 → 失败降级「不可用」，不阻塞整页。

    ★ 2026-10-24 实测返回结构（该端点已由 bot 侧上线，无需等接线）：
      {"overall":"bad","rings":[{"key","status","title","detail"}, ...],
       "qb_anomaly":{"total","error","stalledDL","missingFiles",...}}
      status ∈ ok / warn / bad。detail 是人话，直接透出。
    """
    try:
        _kg = containers()['kfcgame']
        stc, b = hreq(_kg['addr'], _kg['port'] or 18081, 'GET', '/api/health/chain', None, None, 8)
    except Exception as e:
        return {'ok': False, 'level': 'warn', 'title': 'KFC Bot 自检',
                'err': '不可用：%s' % str(e)[:80]}
    if not http_health_ok(stc):
        return {'ok': False, 'level': 'warn', 'title': 'KFC Bot 自检',
                'err': '端点不可用（HTTP %s，bot 侧正在修接线）' % stc}
    try:
        j = json.loads(b)
    except Exception:
        j = {}
    rings = j.get('rings') or []
    lv = {'ok': 'ok', 'warn': 'warn', 'bad': 'bad'}.get(str(j.get('overall') or ''), 'warn')
    bad = [r for r in rings if str(r.get('status')) == 'bad']
    warn = [r for r in rings if str(r.get('status')) == 'warn']
    if lv == 'ok' and bad:
        lv = 'bad'
    elif lv == 'ok' and warn:
        lv = 'warn'
    top = [{'name': r.get('title') or r.get('key'),
            'val': '%s：%s' % ('异常' if r.get('status') == 'bad' else '告警',
                               (r.get('detail') or '')[:60])}
           for r in (bad + warn)[:6]]
    return {'ok': lv == 'ok', 'level': lv, 'title': 'KFC Bot 自检',
            'metrics': [{'k': '自检环', 'v': len(rings)},
                        {'k': '异常', 'v': len(bad)},
                        {'k': '告警', 'v': len(warn)}],
            'top': top, 'rings': rings,
            'msg': '、'.join([(r.get('title') or r.get('key')) for r in (bad + warn)]) or '自检全部通过'}


def chain_health(force=False):
    """聚合探活：线程池并发，单源 ≤8s，返回统一 JSON。"""
    out = {'ok': True, 'ts': time.strftime('%F %T'), 'links': {}}
    jobs = {'docker': _link_docker, 'qb': _link_qb, 'mp': _link_mp,
            'mt': _link_mt, 'cd2': _link_cd2, 'emby': _link_emby,
            'kfcgame': _link_kfcgame}
    with ThreadPoolExecutor(max_workers=len(jobs)) as ex:
        futs = {k: ex.submit(v) for k, v in jobs.items()}
        for k, f in futs.items():
            try:
                out['links'][k] = f.result()
            except Exception as e:
                out['links'][k] = {'ok': False, 'level': 'bad',
                                   'title': k, 'err': str(e)[:120]}
    lv = [out['links'][k].get('level') for k in jobs]
    out['level'] = 'bad' if 'bad' in lv else ('warn' if 'warn' in lv else 'ok')
    out['summary'] = {'ok': lv.count('ok'), 'warn': lv.count('warn'), 'bad': lv.count('bad')}
    # ★ 2026-10-24 第七轮：HTML 部署守护状态作为 **info 级事实**挂上链路页
    #   （不参与 ok/warn/bad 汇总，避免"页面被改"把链路总状态染成异常；
    #     但用户能在链路页一眼看到"面板文件被外部改过"）。
    try:
        g = html_guard_check()
        out['links']['htmlguard'] = {
            'ok': not g.get('changed'), 'level': 'info',
            'title': '面板 HTML 部署守护',
            'msg': ('index.html 被外部修改于 %s（守护已快照，未回滚）' % g.get('changed_at'))
                   if g.get('changed') else 'index.html 与启动基线一致',
            'metrics': [{'k': '体积', 'v': '%d B' % (g.get('size') or 0)},
                        {'k': '基线', 'v': (g.get('baseline') or 'N/A')[:8]}],
            'err': ('[HTML-GUARD] 被外部覆盖，详见 /data/html_guard/' if g.get('changed') else ''),
        }
    except Exception as _e:
        out['links']['htmlguard'] = {'ok': True, 'level': 'info',
                                     'title': '面板 HTML 部署守护',
                                     'msg': '守护状态不可用：%s' % str(_e)[:80]}
    return out


# ═══ SUBMGMT-CENTER ═══
# ═══════════════════════════════════════════════════════════════════
# 订阅与求片管理中心（Web 端口 5678 · /api/submgmt/*）
# ───────────────────────────────────────────────────────────────────
# 用户需求（2026-10-12）：
#   ① 专门的「订阅与求片管理」通道，能看订阅列表（在途 / 已完成归档 / 待审核求片）
#   ② 列表项支持 勾选 / 全选 / 全选本页
#   ③ 批量操作：全部下载 · 全部暂停 · 优先下载
#   ④ 每次操作后立即反馈：自动搜索 → 未找到 / 已找到资源并开始下载 + 进度条 + 完整状态
#
# 数据源说明（关键，别搞错）：
#   · MoviePilot **现存订阅** = 在途订阅     → GET /api/v1/subscribe/     (state R=在更 P=暂停 S=已停止)
#   · MoviePilot **订阅历史** = 已完成归档   → GET /api/v1/subscribe/history/{mtype}
#       ⚠️ MP 在订阅完成时会**直接删掉 subscribe 行**（complete.py → stage_delete_sync），
#          只留 subscribehistory ⇒ 绝不能把 subscribe 当唯一数据源。
#   · bot 的求片申请 = kfcgame.kfc_req_audit（MySQL，库 kfcgame）
#   · qBittorrent   = 真实下载进度来源（MP 只负责下种子）
# ═══════════════════════════════════════════════════════════════════
KFC_DB = os.environ.get('KFC_DB', 'kfcgame')

# 订阅状态字典
# 来源：MoviePilot /app/app/schemas/subscribe.py:213 「状态：N-新建， R-订阅中」
#       + /app/app/db/models/subscribe.py:78  state 默认值 'N'
#       + /app/app/api/endpoints/subscribe.py:392  valid_states = ["R","P","S"]
SUB_STATE_ZH = {'N': '新建', 'R': '订阅中', 'P': '已暂停', 'S': '已停止',
                'ARCHIVED': '已完成归档', '': '—'}


def _qq(sql, args=None, db=None):
    """kfcgame 库查询快捷方式（复用 my_query，默认库换成 kfcgame）"""
    return my_query(sql, args, db or KFC_DB)


_QB_ALL_CACHE = {'ts': 0.0, 'data': None}   # qB 种子表短缓存（多页面轮询共享）


def _qb_all(limit=400):
    """一次拉全 qBittorrent 种子表，返回 (列表, 错误)。批量操作要反复比对，只拉一次。

    ★ 2026-10-19 v1.07 修复「订阅与求片页一直报 qB 连接失败」：
      根因：qB 的 WebUI 是单线程的，而面板上 overview / dash / qb/realtime /
      submgmt/torrents / mt 等多个页面同时 8 秒一轮回打 /api/v2/torrents/info，
      并发一高 qB 来不及响应 → qb_call(t=12) 超时 → 整块 ok:false，
      前端把错误当成「qB 连接失败」怼在用户脸上（用户原话："好多功能都没用"）。
      修复：4 秒短缓存（多页面共享，只打 qB 一次）+ 失败回退上一次成功快照
      （stale-while-error），瞬时抖动不再变成用户可见报错；并真正用上 limit。
    """
    now = time.time()
    if _QB_ALL_CACHE['data'] is not None and now - _QB_ALL_CACHE['ts'] < 4:
        return list(_QB_ALL_CACHE['data']), ''
    cookie, err = qb_login()
    if err:
        if _QB_ALL_CACHE['data'] is not None:
            return list(_QB_ALL_CACHE['data']), ''
        return [], (err.get('msg') or 'qBittorrent 未登录')
    st, b = qb_call('GET', '/api/v2/torrents/info', None, cookie)
    if st != 200:
        if _QB_ALL_CACHE['data'] is not None:
            return list(_QB_ALL_CACHE['data']), ''
        return [], 'qBittorrent HTTP %s' % st
    try:
        data = json.loads(b) or []
    except Exception as e:
        if _QB_ALL_CACHE['data'] is not None:
            return list(_QB_ALL_CACHE['data']), ''
        return [], str(e)[:80]
    if limit and len(data) > limit:
        data = data[:limit]
    _QB_ALL_CACHE['ts'] = now
    _QB_ALL_CACHE['data'] = data
    return list(data), ''


def _tor_key(s):
    """种子/片名的归一化 key：去掉季集标记、画质、扩展名后比对。

    为什么要这么干：MP 订阅名「财神窦占龙」和 qB 种子名
    「财神窦占龙.S01E11.2026.2160p.WEB-DL.x265」不是字符串相等，
    只有把噪音剥掉才能把「订阅 ↔ 种子」配起来，从而拿到真实进度。
    """
    s = str(s or '').lower()
    s = re.sub(r'\.(mkv|mp4|ts|avi|iso|torrent)$', '', s)
    s = re.sub(r'\b(s\d{1,2})?(e\d{1,3})\b', ' ', s)
    s = re.sub(r'\bs\d{1,2}\b', ' ', s)
    s = re.sub(r'\b(19|20)\d{2}\b', ' ', s)
    s = re.sub(r'\b(2160|1080|720|480|360)p?\b', ' ', s)
    s = re.sub(r'\b(web[- ]?dl|bluray|blu-ray|hdrip|hdtv|remux|x26[45]|hevc|avc|aac|'
               r'ddp?\d?(\.\d)?|ddp?a|flac|hdr|dv|sdr|10bit|8bit|complete|repack|'
               r'proper|internal|multi|chs|cht|gb|big5)\b', ' ', s)
    s = re.sub(r'[\[\]\(\)\{\}\.\-_·]+', ' ', s)
    s = re.sub(r'\s+', '', s)
    return s


def _match_tors(name, tors):
    """按归一化 key 前缀互含匹配种子（片名短、种子名长，用互含最稳）"""
    k = _tor_key(name)
    if not k or len(k) < 2:
        return []
    out = []
    for t in tors:
        tk = _tor_key(t.get('name'))
        if not tk:
            continue
        if k in tk or tk in k:
            out.append(t)
    return out


def _tor_prog(tors):
    """把一组种子汇总成进度：总大小 / 已下载 / 百分比 / 速度 / 状态。"""
    if not tors:
        return {'size': 0, 'done': 0, 'pct': 0.0, 'dl': 0, 'up': 0,
                'state': '', 'n': 0, 'eta': 0, 'seeds': 0}
    size = sum(int(t.get('size') or 0) for t in tors)
    done = sum(int(t.get('completed') or 0) for t in tors)
    dl = sum(int(t.get('dlspeed') or 0) for t in tors)
    up = sum(int(t.get('upspeed') or 0) for t in tors)
    seeds = sum(int(t.get('num_seeds') or 0) for t in tors)
    pct = (done / size * 100.0) if size else (100.0 if all(
        float(t.get('progress') or 0) >= 1 for t in tors) else 0.0)
    # 单一种子状态优先，多种子时按语义合并
    sts = [str(t.get('state') or '') for t in tors]
    if all(s in ('pausedDL', 'pausedUP', 'stoppedDL', 'stoppedUP') for s in sts):
        state = 'paused'
    elif any('error' in s or 'missing' in s for s in sts):
        state = 'error'
    elif all(float(t.get('progress') or 0) >= 1 for t in tors):
        state = 'done'
    else:
        state = 'downloading'
    # ETA：只对仍在下载的种子算（剩余字节 / 速度）
    eta = 0
    rem = sum(max(0, int(t.get('size') or 0) - int(t.get('completed') or 0))
              for t in tors if float(t.get('progress') or 0) < 1)
    if rem and dl:
        eta = int(rem / dl)
    return {'size': size, 'done': done, 'pct': round(pct, 1), 'dl': dl, 'up': up,
            'state': state, 'n': len(tors), 'eta': eta, 'seeds': seeds}


def _fmt_eta(sec):
    if not sec or sec <= 0:
        return ''
    if sec < 60:
        return '%d 秒' % sec
    if sec < 3600:
        return '%d 分' % (sec // 60)
    if sec < 86400:
        h = sec // 3600
        return '%d 小时%d 分' % (h, (sec % 3600) // 60)
    return '%d 天' % (sec // 86400)


def psz2(n):
    """人类可读体积"""
    try:
        n = float(n)
    except Exception:
        return '—'
    for u in ('B', 'KB', 'MB', 'GB', 'TB'):
        if n < 1024:
            return ('%.0f %s' % (n, u)) if u in ('B', 'KB') else ('%.2f %s' % (n, u))
        n /= 1024.0
    return '%.2f PB' % n


def spd2(n):
    return psz2(n) + '/s'


def psz(n):
    """psz2 的别名（仪表盘代码统一用短名）。"""
    return psz2(n)


def submgmt_list(force=False):
    """订阅与求片管理总表。

    统一返回三类条目：
      kind='sub'   → MP 现存订阅（在途，可暂停/恢复/搜索）
      kind='arc'   → MP 订阅历史（已完成归档，可重新下载）
      kind='req'   → bot 求片申请（kfc_req_audit，auditing/done/rejected）
    每条都带上 qBittorrent 的真实进度。
    """
    out = {'ok': True, 'ts': time.strftime('%F %T'), 'items': [],
           'counts': {}, 'qb_ok': False, 'qb_msg': ''}

    tors, qerr = _qb_all()
    out['qb_ok'] = not bool(qerr)
    out['qb_msg'] = qerr or ''

    # ── ① MP 现存订阅 ──
    subs, serr = [], ''
    r = mp_api('/api/v1/subscribe/?page=1&count=200')
    if r.get('ok'):
        d = r.get('data')
        subs = d if isinstance(d, list) else ((d or {}).get('items') or [])
        subs = [x for x in subs if isinstance(x, dict)]
    else:
        serr = r.get('msg') or '读取订阅失败'

    # ── ② MP 订阅历史（已完成归档）──
    hist = []
    for mt in ('电视剧', '电影'):
        hr = mp_api('/api/v1/subscribe/history/%s?page=1&count=200'
                    % urllib.parse.quote(mt))
        if hr.get('ok'):
            dd = hr.get('data')
            hl = dd if isinstance(dd, list) else ((dd or {}).get('items') or [])
            for x in hl:
                if isinstance(x, dict):
                    x = dict(x, _mtype=mt)
                    hist.append(x)

    # ── ③ bot 求片申请 ──
    audits = []
    aerr = ''
    try:
        audits = rows_ok(_qq(
            "SELECT id, tg, tg_name, title, year, mtype, season, start_ep, "
            "total_ep, ep_list, status, sub_id, note, created_at, decided_at "
            "FROM kfc_req_audit ORDER BY id DESC LIMIT 200"))
    except Exception as e:
        aerr = str(e)[:120]

    # MP 现存订阅 id 集合，用于给求片标注「是否已归档」
    live_ids = set()
    for s in subs:
        try:
            live_ids.add(int(s.get('id') or 0))
        except Exception:
            pass

    def _mk(kind, name, year, mtype, state, sub_id, extra):
        name = str(name or '')
        mt = _match_tors(name, tors)
        pr = _tor_prog(mt)
        it = {'kind': kind, 'name': name, 'year': str(year or ''),
              'mtype': mtype or '', 'state': state, 'sub_id': int(sub_id or 0),
              'prog': pr,
              'prog_txt': ('%s %s / %s' % (_pct_bar(pr['pct']), psz2(pr['done']),
                                           psz2(pr['size'])) if pr['n']
                           else '无下载任务')}
        it.update(extra or {})
        return it

    for s in subs:
        st = str(s.get('state') or '')
        sid = int(s.get('id') or 0)
        out['items'].append(_mk(
            'sub', s.get('name'), s.get('year'), s.get('type') or s.get('mtype'),
            st, sid,
            {'poster': s.get('poster') or '', 'season': s.get('season'),
             'site': s.get('site_name') or s.get('site') or '',
             'total_ep': s.get('total_episode'), 'start_ep': s.get('start_episode'),
             'last_search': s.get('last_search') or '',
             'state_zh': SUB_STATE_ZH.get(st, st),
             'done': False, 'tors': [t.get('hash') for t in _match_tors(s.get('name'), tors)]}))

    seen = set()
    # 归档条目若在 kfc_req_audit 里有对应申请（sub_id 相同），把 aid 带上 ——
    # 这样 Web 端就能复用审核下发通道做「重新下载」，不必让用户回群里点。
    aid_by_sub = {}
    for a in audits:
        try:
            si = int(a.get('sub_id') or 0)
        except Exception:
            si = 0
        if si:
            aid_by_sub.setdefault(si, int(a.get('id') or 0))
    for h in hist:
        sid = int(h.get('id') or 0)
        if sid in live_ids or sid in seen:
            continue
        seen.add(sid)
        out['items'].append(_mk(
            'arc', h.get('name'), h.get('year'), h.get('type') or h.get('_mtype'),
            'ARCHIVED', sid,
            {'poster': h.get('poster') or '', 'season': h.get('season'),
             'site': h.get('site_name') or '',
             'archived_at': str(h.get('date') or h.get('last_search') or '')[:19],
             'state_zh': '已完成归档', 'done': True,
             'aid': aid_by_sub.get(sid, 0), 'mtype_full': h.get('_mtype'),
             'tors': [t.get('hash') for t in _match_tors(h.get('name'), tors)]}))

    for a in audits:
        st = str(a.get('status') or '')
        sid = int(a.get('sub_id') or 0)
        # 该求片对应的 MP 订阅还在吗？不在 ⇒ 已完成归档
        archived = bool(sid) and sid not in live_ids and st == 'done'
        if st == 'auditing':
            stz = '待审核'
        elif st == 'rejected':
            stz = '已拒绝'
        elif archived:
            stz = '已完成归档'
        else:
            stz = '已下载中'
        ep = a.get('ep_list') or ''
        scope = ('S%s' % a.get('season') if a.get('season') else '')
        if a.get('start_ep'):
            scope += ('E%s' % a.get('start_ep'))
            if a.get('total_ep') and a.get('total_ep') != a.get('start_ep'):
                scope += ('-E%s' % a.get('total_ep'))
        out['items'].append(_mk(
            'req', a.get('title'), a.get('year'), a.get('mtype'),
            st, sid,
            # ★ id 与 aid 同值：前端 smKey/smReqState 两套字段都读，缺一个就兜底失败
            {'aid': a.get('id'), 'id': a.get('id'),
             'tg': a.get('tg'), 'tg_name': a.get('tg_name') or '',
             'season': a.get('season'), 'start_ep': a.get('start_ep'),
             'total_ep': a.get('total_ep'), 'ep_list': ep, 'scope_txt': scope,
             'created_at': str(a.get('created_at') or '')[:19],
             'note': a.get('note') or '', 'state_zh': stz,
             'done': archived or st == 'done',
             'archived': archived, 'poster': a.get('poster') or '',
             'tors': [t.get('hash') for t in _match_tors(a.get('title'), tors)]}))

    n_sub = sum(1 for x in out['items'] if x['kind'] == 'sub')
    out['counts'] = {
        'sub': n_sub,
        'arc': sum(1 for x in out['items'] if x['kind'] == 'arc'),
        'req': len(audits),
        'auditing': sum(1 for x in out['items']
                        if x['kind'] == 'req' and x['state'] == 'auditing'),
        'total': len(out['items']),
        'downloading': sum(1 for x in out['items'] if x['prog']['state'] == 'downloading'),
        'paused': sum(1 for x in out['items']
                      if x['kind'] == 'sub' and x['state'] == 'P'),
        'seeding': sum(1 for x in out['items'] if x['prog']['state'] == 'done'),
    }
    # ★ BUG-006 修复：读失败不能再被静默降级成「订阅 0」。
    #   errs 提升为顶层字段，前端据此渲染红条 + 重试按钮。
    out['errs'] = {'subs': serr, 'audit': aerr}
    out['err_msg'] = '；'.join(
        [x for x in (('MP 订阅读取失败：' + serr) if serr else '',
                     ('求片库读取失败：' + aerr) if aerr else '') if x])
    out['partial'] = bool(serr or aerr)
    out['total'] = len(out['items'])
    return out


def _pct_bar(pct, width=12):
    """纯文本进度条（Web 端也用它，避免前端重复实现）"""
    try:
        pct = float(pct)
    except Exception:
        pct = 0.0
    pct = max(0.0, min(100.0, pct))
    fill = int(round(pct / 100.0 * width))
    return '█' * fill + '░' * (width - fill)


def submgmt_act(act, ids, only_req=None):
    """批量操作。

    act:
      'search'   → 立即搜索（全部下载：让 MP 马上找资源）
      'pause'    → 全部暂停（MP 订阅置 P + qB 种子暂停）
      'resume'   → 全部恢复
      'priority' → 优先下载（只跑选中的：勾中的 resume，其余全部 pause）
      'kick'     → 对单条订阅触发立即搜索（内部用）
    返回带 per-item 回执的明细，前端可逐条渲染「未找到 / 已找到开始下载」。
    """
    ids = [int(x) for x in (ids or []) if str(x).strip().lstrip('-').isdigit()]
    detail = []
    tors, qerr = _qb_all()

    def _find_sub(sid):
        r = mp_api('/api/v1/subscribe/%s' % sid)
        if r.get('ok') and isinstance(r.get('data'), dict):
            return r['data']
        return None

    if act in ('search', 'kick'):
        for sid in ids:
            s = _find_sub(sid)
            if not s:
                # 订阅不在 → 可能已完成归档
                detail.append({'id': sid, 'ok': False, 'found': False,
                               'msg': '订阅不存在（可能已完成归档）'})
                continue
            name = s.get('name') or ''
            before = _match_tors(name, tors)
            r = mp_api('/api/v1/subscribe/search/%s' % sid, method='POST', body={})
            if not r.get('ok'):
                detail.append({'id': sid, 'ok': False, 'found': False,
                               'name': name, 'msg': '搜索请求失败：%s'
                               % (r.get('msg') or '')[:60]})
                continue
            time.sleep(0.4)
            # 重新拉种子，看看有没有新下的
            time.sleep(1.2)
            t2, _ = _qb_all()
            after = _match_tors(name, t2)
            pr = _tor_prog(after)
            new = len(after) - len(before)
            if after:
                detail.append({
                    'id': sid, 'ok': True, 'found': True, 'name': name,
                    'msg': ('已找到资源并开始下载' if new > 0
                            else '已在下载中（未发现新资源）'),
                    'new': new, 'prog': pr, 'prog_txt':
                        '%s %s / %s' % (_pct_bar(pr['pct']), psz2(pr['done']),
                                        psz2(pr['size'])),
                    'torrents': [{'name': t.get('name'), 'hash': t.get('hash'),
                                  'state': t.get('state'),
                                  'progress': round(float(t.get('progress') or 0) * 100, 1),
                                  'dlspeed': int(t.get('dlspeed') or 0),
                                  'size': int(t.get('size') or 0)}
                                 for t in after]})
            else:
                detail.append({'id': sid, 'ok': True, 'found': False, 'name': name,
                               'msg': '未找到资源（站点尚未收录，稍后会自动重试）'})
        ok_n = sum(1 for x in detail if x.get('ok'))
        found_n = sum(1 for x in detail if x.get('found'))
        miss_n = sum(1 for x in detail if x.get('ok') and not x.get('found'))
        fail_n = len(detail) - ok_n
        parts = []
        if found_n:
            parts.append('%d 条已找到资源并开始下载' % found_n)
        if miss_n:
            parts.append('%d 条未找到' % miss_n)
        if fail_n:
            parts.append('%d 条失败' % fail_n)
        return {'ok': fail_n == 0, 'detail': detail,
                'msg': '已触发搜索 %d 条：%s' % (len(detail), '，'.join(parts) or '无变化')}

    if act in ('pause', 'resume'):
        state = 'P' if act == 'pause' else 'R'
        for sid in ids:
            s = _find_sub(sid)
            if not s:
                detail.append({'id': sid, 'ok': False,
                               'msg': '订阅不存在（可能已完成归档）'})
                continue
            r = mp_api('/api/v1/subscribe/status/%s?state=%s' % (sid, state),
                       method='PUT')
            if not r.get('ok'):
                r = mp_api('/api/v1/subscribe/status/%s?state=%s' % (sid, state),
                           method='GET')
            name = s.get('name') or ''
            hs = [t.get('hash') for t in _match_tors(name, tors) if t.get('hash')]
            n_qb = 0
            if hs:
                cookie, err = qb_login()
                if not err:
                    st2, _b, _u = (qb_pause(hs, cookie) if act == 'pause'
                                   else qb_resume(hs, cookie))
                    n_qb = len(hs) if st2 == 200 else 0
            detail.append({'id': sid, 'ok': bool(r.get('ok')), 'name': name,
                           'msg': ('已暂停' if act == 'pause' else '已恢复')
                                  + ('（含 %d 个下载任务）' % n_qb if n_qb else ''),
                           'qb': n_qb,
                           'mp_msg': (r.get('msg') or '') if not r.get('ok') else ''})
        ok_n = sum(1 for x in detail if x.get('ok'))
        miss_n = sum(1 for x in detail if not x.get('ok'))
        msg = '已%s %d 条订阅' % ('暂停' if act == 'pause' else '恢复', ok_n)
        if miss_n:
            msg += '，%d 条不存在（可能已完成归档）' % miss_n
        return {'ok': ok_n == len(detail), 'detail': detail, 'msg': msg}

    if act == 'priority':
        # ── 优先下载 ──────────────────────────────────────────────────
        # 语义：把「勾中的订阅/求片」提到最优先，**并且只暂停它们所属的其它任务**。
        # ⚠️ 绝对不能无差别暂停 qB 里所有种子！（老实现 paused_all=14 把无关的
        #    真实下载任务也全停了，属于严重缺陷，2026-10-12 已修正）
        # 正确做法：
        #   ① 勾中的 MP 订阅 → 置 R + 立即搜索；勾中求片 → 走审核下发通道
        #   ② 只暂停「未被勾中、但属于其它 MP 订阅」的 qB 种子
        #   ③ 完全不碰没有归属（category 为空 / 不属于任何订阅）的种子
        cookie, err = qb_login()
        sel_h = set()
        sel_names = []
        for sid in ids:
            s = _find_sub(sid)
            if not s:
                continue
            name = s.get('name') or ''
            sel_names.append(name)
            mp_api('/api/v1/subscribe/status/%s?state=R' % sid, method='PUT')
            mp_api('/api/v1/subscribe/search/%s' % sid, method='POST', body={})
            for t in _match_tors(name, tors):
                if t.get('hash'):
                    sel_h.add(t.get('hash'))

        # 收集「其它订阅」覆盖的种子 —— 只有这些才允许被暂停
        other_h = set()
        try:
            rr = mp_api('/api/v1/subscribe/?page=1&count=200')
            if rr.get('ok'):
                dd = rr.get('data')
                live = dd if isinstance(dd, list) else ((dd or {}).get('items') or [])
                keep = set(ids)
                for s in live:
                    try:
                        osid = int(s.get('id') or 0)
                    except Exception:
                        continue
                    if not osid or osid in keep:
                        continue
                    # 未勾中的订阅 → 置暂停 + 收集其种子
                    mp_api('/api/v1/subscribe/status/%s?state=P' % osid,
                           method='PUT')
                    for t in _match_tors(s.get('name'), tors):
                        h = t.get('hash')
                        # 已归属勾中订阅的种子不重复暂停
                        if h and h not in sel_h:
                            other_h.add(h)
        except Exception:
            pass

        paused_n = 0
        if not err and other_h:
            st2, _b, _u = qb_pause(sorted(other_h), cookie)
            paused_n = len(other_h) if st2 == 200 else 0
        elif err:
            paused_n = 0
        # 勾中的种子：确保在跑（之前若被暂停过要恢复）
        if not err and sel_h:
            qb_resume(sorted(sel_h), cookie)

        if err:
            return {'ok': False, 'prio': 0, 'paused_other': 0,
                    'msg': 'qBittorrent 未响应：%s' % err}
        return {'ok': True, 'prio': len(sel_h), 'paused_other': paused_n,
                'sel_names': sel_names[:20],
                'msg': ('已优先 %d 个下载任务' % len(sel_h)
                        + ('，暂停其它订阅的 %d 个任务' % paused_n if paused_n
                           else '，其它订阅无需调整'))}

    return {'ok': False, 'msg': '未知操作：%s' % act}


def submgmt_kick_one(sid):
    """单条「立即下载」：等同 search，但强制恢复订阅状态为 R"""
    mp_api('/api/v1/subscribe/status/%s?state=R' % int(sid), method='PUT')
    return submgmt_act('search', [int(sid)])


def submgmt_redl_arc(sub_id, aid=0):
    """归档条目重新下载。

    归档 = MP 已完成订阅并删掉了 subscribe 行，所以在 MP 里查不到。
    重新下载必须**拿到原始申请上下文**（title/year/type/tmdb_id/季集）才能重建订阅：
      · 有 aid（该归档来自 bot 求片）→ 用 kfc_req_audit 里的完整信息重建，最准
      · 没 aid（别的来源）          → 只能按片名 + 季号尝试建订阅（尽力而为）
    """
    sub_id = int(sub_id or 0)
    aid = int(aid or 0)
    if aid:
        r = submgmt_audit(aid, 'approve')
        if r.get('ok'):
            return {'ok': True, 'msg': '已按原始申请重新下发：%s' % r.get('msg'),
                    'sub_id': r.get('sub_id'), 'kicked': r.get('kicked')}
        return r
    # 没有申请上下文：从归档条目本身推（至少要有片名）
    item = None
    for x in (submgmt_list().get('items') or []):
        if x['kind'] == 'arc' and x['sub_id'] == sub_id:
            item = x
            break
    if not item:
        return {'ok': False, 'msg': '找不到归档条目（可能已过期，请刷新）'}
    payload = {'name': item.get('name'), 'year': item.get('year') or '',
               'type': item.get('mtype') or '电视剧'}
    if item.get('season'):
        payload['season'] = int(item['season'])
    r = mp_api('/api/v1/subscribe/', method='POST', body=payload)
    if not r.get('ok'):
        return {'ok': False,
                'msg': '重建订阅失败（缺 TMDB 身份，建议在机器人群里点「重新下载」）：%s'
                       % (r.get('msg') or '')}
    sid = 0
    d = r.get('data')
    if isinstance(d, dict):
        try:
            sid = int(d.get('id') or 0)
        except Exception:
            sid = 0
    if sid:
        mp_api('/api/v1/subscribe/search/%s' % sid, method='POST', body={})
    return {'ok': True, 'msg': '已重建订阅并触发搜索', 'sub_id': sid}


# ═══════════════════════════════════════════════════════════════════
# 求片审核（Web 端直接通过 / 拒绝 / 优先下载）
# ═══════════════════════════════════════════════════════════════════
def submgmt_audit(aid, action, note=''):
    """Web 端点对求片申请执行 通过 / 拒绝。

    通过 = 走与 bot 完全相同的下发通道（MP 订阅 + 立即搜索），
    状态写回 kfc_req_audit，保证两端数据一致。

    实现方式：直接在 media-hub 里复刻 push_audit_to_mp 的核心步骤
    （读申请 → 建订阅 → kick 搜索 → 写状态）。
    """
    aid = int(aid)
    rows = _qq("SELECT * FROM kfc_req_audit WHERE id=%s", (aid,))
    if not rows:
        return {'ok': False, 'msg': '找不到申请 #%s' % aid}
    a = dict(rows[0])
    title = a.get('title') or ''
    mtype = a.get('mtype') or '电视剧'
    season = int(a.get('season') or 0)
    start_ep = int(a.get('start_ep') or 0)
    total_ep = int(a.get('total_ep') or 0)

    if action == 'reject':
        _qw("UPDATE kfc_req_audit SET status='rejected', admin=0, note=%s, "
            "decided_at=NOW() WHERE id=%s", ((note or 'Web 端拒绝')[:200], aid))
        return {'ok': True, 'msg': '已拒绝 #%s %s' % (aid, title)}

    if action != 'approve':
        return {'ok': False, 'msg': '未知操作 %s' % action}

    payload = {'name': title, 'year': a.get('year') or '',
               'type': mtype,
               'media_source': a.get('media_source') or 'themoviedb',
               'media_id': a.get('tmdb_id') or ''}
    if season:
        payload['season'] = season
    if start_ep:
        payload['start_episode'] = start_ep
        payload['total_episode'] = total_ep or start_ep

    r = mp_api('/api/v1/subscribe/', method='POST', body=payload)
    if not r.get('ok'):
        return {'ok': False, 'msg': '下发 MoviePilot 失败：%s' % (r.get('msg') or '')}
    sid = 0
    d = r.get('data')
    if isinstance(d, dict):
        try:
            sid = int(d.get('id') or 0)
        except Exception:
            sid = 0
    elif isinstance(d, int):
        sid = d
    # 立即触发搜索
    kicked = False
    if sid:
        kr = mp_api('/api/v1/subscribe/search/%s' % sid, method='POST', body={})
        kicked = bool(kr.get('ok'))
    _qw("UPDATE kfc_req_audit SET status='done', admin=0, sub_id=%s, "
        "note=%s, decided_at=NOW() WHERE id=%s",
        (sid, ('Web 端通过' + ('，已触发立即搜索' if kicked else ''))[:200], aid))
    return {'ok': True, 'msg': '已通过 #%s %s%s' % (
        aid, title, '（订阅 #%d，已触发搜索）' % sid if sid else ''),
        'sub_id': sid, 'kicked': kicked}


def _qw(sql, args=None, db=None):
    """kfcgame 库写操作（复用 PT_DB 账号，但指向 kfcgame 库）"""
    import pymysql

    _pd = _pt_db()

    conn = pymysql.connect(
        host=_pd['host'], port=_pd['port'], user=_pd['user'],
        password=_pd['password'], database=db or KFC_DB,
        charset='utf8mb4', connect_timeout=8)
    try:
        with conn.cursor() as cur:
            cur.execute(sql, args or ())
            n = cur.rowcount
        conn.commit()
        return n
    finally:
        try:
            conn.close()
        except Exception:
            pass


_TG_NAME_CACHE = {}      # tg id -> 显示名（求片面板回填，避免每条都查库）


def submgmt_reqstat(force=False):
    """求片清单（申请 → 下载 → 入库）三段状态总览。"""
    out = {'ok': True, 'ts': time.strftime('%F %T'), 'items': [],
           'counts': {}, 'err': ''}
    try:
        rows = rows_ok(_qq(
            "SELECT id, tg, tg_name, title, year, mtype, season, start_ep, "
            "total_ep, ep_list, status, sub_id, note, created_at, decided_at "
            "FROM kfc_req_audit ORDER BY id DESC LIMIT 100"))
    except Exception as e:
        out.update(ok=False, err=str(e)[:150])
        return out
    # 拉一次 MP 现存订阅 + qB 种子，用同一份数据给所有条目算进度
    live = set()
    r = mp_api('/api/v1/subscribe/?page=1&count=200')
    if r.get('ok'):
        dd = r.get('data')
        for s in (dd if isinstance(dd, list) else ((dd or {}).get('items') or [])):
            try:
                live.add(int(s.get('id') or 0))
            except Exception:
                pass
    tors, _ = _qb_all()
    for a in rows:
        sid = int(a.get('sub_id') or 0)
        st = str(a.get('status') or '')
        pr = _tor_prog(_match_tors(a.get('title'), tors))
        if st == 'auditing':
            stage, sn = '待审核', 0
        elif st == 'rejected':
            stage, sn = '已拒绝', 0
        elif st == 'done' and sid and sid in live:
            stage, sn = '下载中', 2
        elif st == 'done' and sid and sid not in live:
            stage, sn = '已完成归档', 4
        elif st == 'done':
            stage, sn = '已下载中', 2
        else:
            stage, sn = st or '—', 0
        # 三段播报：下载中 → 下载完成等待入库 → 入库完成
        if sn == 2 and pr['n'] and pr['pct'] >= 100:
            stage, sn = '下载完成，等待入库', 3
        # ★ BUG-002 修复：前端 smKey/smStateTag/smAuditable 读 x.aid / x.state，
        #   而后端只返回 id/status → 所有求片共用 key 'req:undefined'。
        #   现在契约统一：同时提供 id/aid 与 status/state/state_zh。
        a['aid'] = a.get('id')
        a['state'] = st
        a['state_zh'] = {'auditing': '待审核', 'done': '已完成', 'rejected': '已拒绝'}.get(
            st, st or '—')
        # ★ v1.07：kfc_req_audit.tg_name 早期写入时可能为空（只存了数字 tg id），
        #   求片进度面板「申请人」一列就整列空白，用户以为数据坏了。
        #   现在用 kfcgame.kfc_members 回填显示名（只读，不改原值，带缓存）。
        if not (a.get('tg_name') or '').strip():
            _tgk = str(a.get('tg') or '')
            _nm = _TG_NAME_CACHE.get(_tgk)
            if _nm is None:
                _nm = ''
                try:
                    for _r in rows_ok(my_query(
                            "SELECT tg_name, tg_username FROM kfcgame.kfc_members "
                            "WHERE tg=%s LIMIT 1", (a.get('tg'),), db=None)):
                        _nm = (_r.get('tg_name') or _r.get('tg_username') or '').strip()
                        break
                except Exception:
                    pass
                _TG_NAME_CACHE[_tgk] = _nm
            if _nm:
                a['tg_name'] = _nm
        a['stage'] = stage
        a['stage_n'] = sn
        a['prog'] = pr
        a['prog_txt'] = ('%s %s / %s' % (_pct_bar(pr['pct']), psz2(pr['done']),
                                         psz2(pr['size'])) if pr['n'] else '')
        a['spd_txt'] = spd2(pr['dl']) if pr['dl'] else ''
        a['eta_txt'] = _fmt_eta(pr['eta'])
        out['items'].append(a)
    out['counts'] = {
        'auditing': sum(1 for x in out['items'] if x['status'] == 'auditing'),
        'downloading': sum(1 for x in out['items'] if x['stage_n'] == 2),
        'waiting_in': sum(1 for x in out['items'] if x['stage_n'] == 3),
        'archived': sum(1 for x in out['items'] if x['stage_n'] == 4),
        'rejected': sum(1 for x in out['items'] if x['status'] == 'rejected'),
    }
    out['total'] = len(out['items'])
    return out


def _cnt(seq):
    """计数器：iterable → {值: 次数}（phase 分布统计）"""
    d = {}
    for x in seq:
        d[x] = d.get(x, 0) + 1
    return d


def _qb_phase(pct, state):
    """qB 状态 → 统一 phase。pct 为 0~100（也兼容 0~1 小数，自动识别）。

    ★ 2026-10-19 修复用户点名 bug：「明明有些种子是做种完成的，但状态还是做种中」。
      根因：qb_realtime() 传的是 qB 原始 progress（0~1 小数，如 1.0），
      而这里判的是 `if pct < 100` → 1.0 永远小于 100 → 全部掉进
      `return "downloading"`，做种完成的种子全被标成「下载中」。
      现在函数内部做量纲归一：<=1.0 的小数按 0~1 解释并 ×100。
    ★ 2026-10-18 修复「排队做种被当成做种中」：queuedUP → queue_seeding。"""
    try:
        v = float(pct or 0)
    except Exception:
        v = 0.0
    # 量纲归一：progress 原值 0~1（含 1.0）→ 百分数
    if 0 < v <= 1.0000001:
        v = v * 100.0
    pct = v
    stt = str(state or "")
    if stt == "error":
        return "error"
    if stt == "missingFiles":
        return "missing_files"
    if stt in ("checking", "checkingDL", "checkingUP", "checkingResumeData"):
        return "checking"
    if stt == "moving":
        return "moving"
    if stt == "allocating":
        return "allocating"
    if stt == "metaDL":
        return "meta"
    if stt in ("stoppedDL", "stoppedUP"):
        return "stopped"
    if stt in ("pausedUP", "pausedDL"):
        return "seed_paused" if pct >= 100 else "downloading_paused"
    if stt == "queuedDL":
        return "queued_dl"
    if stt == "queuedUP":
        return "queue_seeding"
    if pct < 100:
        return "downloading"
    if stt in ("uploading", "forcedUP"):
        return "seeding"
    if stt == "stalledUP":
        return "seeding_idle"
    return "seeding" if pct >= 100 else "downloading"


