def _match_any(t, table):
    """在 t 里按 table 顺序找第一个命中的值（table 元素 = (关键词, 归一值)）。"""
    for kw, val in table:
        if kw in t:
            return val
    return ''


def _parse_tor_dims(title, size_bytes=0):
    """★ v1.13：把种子标题拆成「全维度」结构化字段（用户要求可逐维筛选）。

    入参 title 如 '假金钗.2026.S01E04.2160p.WEB-DL.SDR.10-bit.12.2Mbps.25fps.H265.AAC 2.0.QHstudIo'
    返回 dict，缺的维度给 ''（前端「未识别」永远可选，绝不藏资源）。
    另返回 bitrate_mbps（码率，用户要求「按码率排序」）。
    """
    t = str(title or '').lower()
    out = {
        'pix': '', 'src': '', 'vcodec': '', 'acodec': '', 'achan': '',
        'bitdepth': '', 'hdr': '', 'dv_profile': '', 'fps': '',
        'team': '', 'bitrate_mbps': None,
    }
    if not t:
        return out
    # ── 分辨率 ──（★ v1.15 改为 _detect_pix：数字白名单 + 词边界 + 取最清晰档）
    out['pix'] = _detect_pix(t)
    # ── 压制类型 ──
    out['src'] = _match_any(t, _SRC_KIND)
    # ── 视频编码 ──
    out['vcodec'] = _match_any(t, _VCODEC)
    # ── 音频编码 ──（★ 顺序敏感：truehd/dts 要先于 aac 命中）
    out['acodec'] = _match_any(t, _ACODEC)
    # ── 声道 ──
    out['achan'] = _match_any(t, _ACHAN)
    # ── 色深 ──
    out['bitdepth'] = _match_any(t, _BITDEPTH)
    # ── 动态范围 ──（★ HDR 判定要避开 SDR：先扫 DV/HDR10 等具体标签）
    if 'sdr' in t and 'dv' not in t and 'hdr' not in t.replace('sdr', ''):
        out['hdr'] = 'SDR'
    else:
        out['hdr'] = _match_any(t, _HDR)
    # ── 杜比视界版本（P4/P5/P7/P8/P8.1/P8.4）★ 用户点名 ──
    out['dv_profile'] = _match_any(t, _DV_PROFILE)
    # ── 帧率 ──
    out['fps'] = _match_any(t, _FPS)
    # ── 码率：'12.2Mbps' / '12.2 Mbps' / '12.2Mb/s' / '12200Kbps' ──
    m = re.search(r'(\d+(?:\.\d+)?)\s*(?:mbps|mb/s|mbp/s)', t)
    if m:
        try:
            out['bitrate_mbps'] = round(float(m.group(1)), 2)
        except Exception:
            pass
    else:
        m = re.search(r'(\d+(?:\.\d+)?)\s*kbps', t)
        if m:
            try:
                out['bitrate_mbps'] = round(float(m.group(1)) / 1000.0, 2)
            except Exception:
                pass
    # ── 发布组 ──（★ v1.15 重写：先剥扩展名 → 剥已知技术词 → 取尾段）
    #   历史踩坑（全部实测复现过）：
    #   ① '-XXX$' 对 '...QHstudIo.mkv' 无效（结尾是扩展名不是发布组）
    #   ② '[-.]XXX\.(mkv|...)$' 会把 'XviD.MP3.avi' 的 'MP3'、'.part1.mkv' 的
    #      'part1' 抠出来（技术词/分卷号不是发布组）
    #   ③ '[-.]XXX\.[a-z]{1,5}$' 兜底更糟：会把 'avi'/'mkv'/'mpg' 本身抠出来
    #   现在：先无条件剥掉扩展名，再反向剥掉所有「已知技术词」尾段，
    #         最后剩下的第一个尾段才是发布组。全链路命中黑名单即放弃（宁空不误判）。
    raw = str(title or '').strip()
    m = re.search(r'-([a-z0-9]{2,20})\s*$', raw, re.I)
    if m:
        g = m.group(1).lower()
        if g not in _TEAM_BLACK and not re.match(r'^part\d+$', g):
            out['team'] = m.group(1)
    if not out['team']:
        # ① 剥扩展名（'xxx.mkv' → 'xxx'）
        stem = re.sub(r'\.(mkv|mp4|ts|avi|m2ts|iso|rmvb|flv|wmv|mpg|mpeg|3gp|mov|vob)$',
                      '', raw, flags=re.I)
        # ② 按 '.' / '-' / ' ' 切段，反向剥掉技术词 / 分卷号 / 声道段
        segs = [x for x in re.split(r'[.\-_ ]+', stem) if x]
        while segs:
            g = segs[-1].lower()
            if (g in _TEAM_BLACK or re.match(r'^part\d+$', g)
                    or re.match(r'^\d+(\.\d+)?$', g)          # 纯数字（码率/声道号）
                    or re.match(r'^\d+bit$', g)                 # 10bit
                    or re.match(r'^\d+fps$', g)                 # 25fps
                    or re.match(r'^[sp]\d+e\d+$', g)            # S01E04
                    or re.match(r'^\d{3,4}p$', g)):             # 2160p
                segs.pop()
                continue
            # ③ 剩下的第一段：要求是字母开头、长度 2~20 的字母数字串
            if re.match(r'^[a-z][a-z0-9]{1,19}$', g, re.I) and len(g) >= 2:
                out['team'] = segs[-1]
            break
    # 码率兜底：体积 / 时长未知，无法算 → 留 None（前端排序时排最后）
    return out


