def pt_site_logo(name):
    """MP 中文站点名 → {name, domain, logo, sym, br}。logo 取不到时前端退字母砖。"""
    nm = str(name or '').strip()
    key = nm.lower()
    dom = _PT_SITE_DOMAIN.get(nm) or _PT_SITE_DOMAIN.get(key) or ''
    br = _PT_SITE_BR.get(dom, ['#64748b', (nm or '?')[:2].upper()])
    return {
        'name': nm,
        'domain': dom,
        # Google favicon 服务（站点墙内可达性由前端 onerror 兜底）
        'logo': ('https://www.google.com/s2/favicons?domain=%s&sz=64' % dom) if dom else '',
        'sym': '📡',
        'br': br,
    }


def pt_site_logos():
    """全站映射表（前端一次性拿到，避免每个种子都查一次）。"""
    out = {}
    names = list(_PT_SITE_DOMAIN.keys()) + ['馒头', '咖啡', '大青虫', 'CARPT',
                                            '织梦', '老师', '高清视界', 'PTS',
                                            '红豆饭', '拾刻']
    for nm in names:
        if nm and nm not in out:
            out[nm] = pt_site_logo(nm)
    # 同时按域名给一份，直连通道直接用
    for dom in _PT_SITE_BR:
        if dom not in out:
            out[dom] = _ptd_logo_obj(dom, dom)
    return out


# -*- coding: utf-8 -*-
"""PT 直连搜索通道：绕过 MP 卡死的 search/title，直接抓各站 RSS / 搜索页。

实测依据（2026-10-21，全部有日志/响应证据）：
  - MP /api/v1/search/title 已完全不可用（curl 200s 超时无响应，3 次实测）
  - MP 日志：provider.py 站点搜索完成「总耗时 2000~2261 秒」，但同批
    indexer 各站「耗时 0~17 秒」→ MP 内部全局锁卡死，非并发导致
  - MP /api/v1/site/rss 毫秒级返回 7 站 RSS 地址（带 passkey）
  - MP /api/v1/site/{id} 毫秒级返回 9 站元数据（cookie/domain/ua）
  - MP /api/v1/site/icon/{id} 返回站点图标 base64
  - RSS 实测：7 站并发 3.4 秒，每站 50 条
  - 搜索页实测：咖啡站 torrents.php?search= 4.6 秒返回 48 条
"""
import io, os, re, json, time, html as _html
import threading
import concurrent.futures

# ── 站点清单（MP /api/v1/site/rss + /api/v1/site/{id} 实测，2026-10-21）──
# id/name/domain 与 MP 一致；rss 从 /api/v1/site/rss 动态取（带 passkey，会变）
PT_DIRECT_SITES = {
    8:  {'name': '织梦',     'domain': 'zmpt.cc',      'nx': True},
    9:  {'name': '老师',     'domain': 'nicept.net',   'nx': True},
    10: {'name': '大青虫',   'domain': 'cyanbug.net',  'nx': True},
    11: {'name': '高清视界', 'domain': 'hdarea.club',  'nx': True},
    12: {'name': 'PTS',      'domain': 'ptskit.org',  'nx': True},
    13: {'name': '馒头',     'domain': 'kp.m-team.cc', 'nx': False},  # M-Team 新版 SPA，无 RSS
    14: {'name': '咖啡',     'domain': 'ptcafe.club',  'nx': True},
    15: {'name': 'CARPT',    'domain': 'carpt.net',    'nx': False},  # 无 RSS
    16: {'name': '红豆饭',   'domain': 'hdfans.org',   'nx': True},
}

_PTD_LOCK = threading.Lock()
_PTD_RSS_CACHE = {}      # domain -> {'ts':, 'items':[精简行]}
_PTD_RSS_TTL = 60        # ★ 2026-10-24：cookie 失效后 RSS 是唯一通道，
                        #   缓存从 3 分钟压到 1 分钟，保证新种能被搜到
_PTD_SITE_CACHE = {}     # site_id -> {'ts':, 'cookie':, 'ua':, 'domain':}
_PTD_SITE_TTL = 600
_PTD_ICON_CACHE = {}     # domain -> data-uri（站点图标 base64，来自 MP）
_PTD_FAIL = {}           # domain -> 上次失败时间（60s 冷却，避免一轮内反复打）
_PTD_TRY = {'n': 0}          # ★ v1.13f：本轮真实发起过的 HTTP 尝试数。
                            #   用来识别「一条 HTTP 都没打就返回 0 条」的假空结果
                            #   （全部站点都在冷却里）→ 见 pt_direct_search 的重试。


def _ptd_log(msg):
    try:
        logger.info('[pt-direct] %s' % str(msg)[:200])
    except Exception:
        pass


def _ptd_site_meta(site_id, force=False):
    """取站点 cookie/ua/domain（MP /api/v1/site/{id}，毫秒级）。带 10 分钟缓存。

    ★ v1.14 补 id/name/domain 原样带出（调用方要拼 download.php），
      并把 www. 前缀保留成 _dom_raw（PTS 站必须用 www.ptskit.org，见 BUG-113）。
    """
    now = time.time()
    with _PTD_LOCK:
        c = _PTD_SITE_CACHE.get(site_id)
    if c and not force and now - c.get('ts', 0) < _PTD_SITE_TTL:
        return c
    r = mp_call('/api/v1/site/%s' % site_id, t=12)
    if not r.get('ok'):
        return c or {}
    d = r.get('data') or {}
    if not isinstance(d, dict):
        return c or {}
    dom = str(d.get('domain') or '').lower()
    if dom.startswith('www.'):
        dom = dom[4:]
    meta = {'ts': now, 'cookie': d.get('cookie') or '', 'ua': d.get('ua') or '',
            'domain': dom, 'name': d.get('name') or '', 'is_active': d.get('is_active'),
            # ★ v1.14：site_id + 原始域名（带 www.）—— 下载种子要用
            'id': site_id,
            'dom_raw': str(d.get('domain') or '').lower()}
    with _PTD_LOCK:
        _PTD_SITE_CACHE[site_id] = meta
    return meta


def _ptd_rss_urls(kw=''):
    """各站 RSS 地址（带 passkey）。MP /api/v1/site/rss，毫秒级。"""
    r = mp_call('/api/v1/site/rss', t=15)
    if not r.get('ok'):
        return {}
    out = {}
    for s in (r.get('data') or []):
        if not isinstance(s, dict):
            continue
        u = str(s.get('rss') or '').strip()
        # ★ 2026-10-24：站点 cookie（cf_clearance）全部过期 → 搜索页全 302，
        #   RSS（passkey 通道）成为唯一可用来源。
        #   rows=50 → 200 扩大覆盖；并追加 search=关键词（NexusPHP 的
        #   torrentrss.php 支持 search 参数，实测「嫁金钗」3 天前的种子也能命中）。
        if re.search(r'[?&]rows=\d+', u):
            u = re.sub(r'([?&]rows=)\d+', r'\g<1>200', u)
        elif '?' in u:
            u += '&rows=200'
        if kw:
            k = str(kw).strip()
            if k and not re.search(r'[?&]search=', u):
                u += ('&' if '?' in u else '?') + 'search=' + urllib.parse.quote(k)
        dom = str(s.get('domain') or '').lower().split('//')[-1].split('/')[0]
        if dom.startswith('www.'):
            dom = dom[4:]
        if u and dom:
            out[dom] = {'url': u, 'id': s.get('id'), 'name': s.get('name') or dom}
    return out


def _ptd_icon(domain):
    """站点图标（MP /api/v1/site/icon/{id} 的 base64 data-uri）。失败退 Google favicon。"""
    dom = str(domain or '').lower()
    if not dom:
        return ''
    with _PTD_LOCK:
        c = _PTD_ICON_CACHE.get(dom)
    if c is not None:
        return c
    uri = ''
    # 反查 site_id
    sid = None
    for k, v in PT_DIRECT_SITES.items():
        if v['domain'] == dom:
            sid = k
            break
    if sid:
        r = mp_call('/api/v1/site/icon/%s' % sid, t=12)
        if r.get('ok'):
            ic = (r.get('data') or {}).get('icon') if isinstance(r.get('data'), dict) else None
            if ic and str(ic).startswith('data:'):
                uri = str(ic)
    if not uri:
        uri = 'https://www.google.com/s2/favicons?domain=%s&sz=64' % dom
    with _PTD_LOCK:
        _PTD_ICON_CACHE[dom] = uri
    return uri


# ★ v1.15：直连 HTTP 连接池（keep-alive）。
#   实测：urllib 默认每次新建 TCP+TLS 握手，单站搜索页 2~3 秒里
#   握手占 ~0.6~1.2 秒（公网 + Cloudflare）。7 站 × 每轮都重新握 →
#   纯浪费 5~8 秒。改成按 host 复用连接后，第二轮起每站省 ~40%。
#   线程安全：http.client 连接非线程安全 → 每线程一个连接（threading.local）。
import http.client
import ssl as _ssl
_PTD_CONN = threading.local()
_PTD_CONN_HOST = {}      # host -> {'ts':, 'n':}（只做观测，不参与逻辑）
_PTD_CONN_LOCK = threading.Lock()
# 不校验证书：PT 站证书链经常缺中间证书，且都是自己人在内网访问
_PTD_CTX = _ssl.create_default_context()
_PTD_CTX.check_hostname = False
_PTD_CTX.verify_mode = _ssl.CERT_NONE
_PTD_KEEP_TTL = 55       # 连接空闲超过 55 秒就重连（避开 Cloudflare 60s idle 回收）


def _ptd_conn_for(host):
    """取（或新建）本线程到 host 的 HTTPS 长连接。"""
    now = time.time()
    c = getattr(_PTD_CONN, 'c', None)
    h = getattr(_PTD_CONN, 'h', None)
    ts = getattr(_PTD_CONN, 'ts', 0)
    if c is not None and h == host and now - ts < _PTD_KEEP_TTL:
        return c
    if c is not None:
        try:
            c.close()
        except Exception:
            pass
    c = http.client.HTTPSConnection(host, 443, timeout=12, context=_PTD_CTX)
    _PTD_CONN.c = c
    _PTD_CONN.h = host
    _PTD_CONN.ts = now
    return c


def _ptd_drop_conn():
    """出错后丢弃本线程连接（下次自动重连）。"""
    c = getattr(_PTD_CONN, 'c', None)
    if c is not None:
        try:
            c.close()
        except Exception:
            pass
    _PTD_CONN.c = None
    _PTD_CONN.h = None


def _ptd_http_get(url, cookie='', ua='', t=20):
    """直连抓 URL（PT 站在公网，面板容器可直接出网——RSS 实测 3.4s 通）。
    返回 (status, text)。永不抛异常。

    ★ v1.15：改用 keep-alive 连接池（见 `_ptd_conn_for`），
      同一线程连续抓同一 host 时复用 TCP/TLS 连接，省 40% 耗时。
      连接被对端关闭时自动重试一次（Cloudflare 会主动回收空闲连接）。
    """
    import urllib.parse as _up
    try:
        pr = _up.urlparse(url)
        host = pr.netloc
        path = pr.path or '/'
        if pr.query:
            path += '?' + pr.query
    except Exception as e:
        return -1, str(e)[:160]
    hdr = {'User-Agent': ua or 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) '
            'AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0 Safari/537.36',
           'Accept': 'text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8',
           'Accept-Language': 'zh-CN,zh;q=0.9,en;q=0.8',
           'Connection': 'keep-alive'}
    if cookie:
        hdr['Cookie'] = cookie
    for attempt in (0, 1):
        c = None
        try:
            c = _ptd_conn_for(host)
            c.timeout = t
            c.request('GET', path, headers=hdr)
            resp = c.getresponse()
            body = resp.read()
            # 2xx 才算成功；4xx/5xx 由调用方按状态码处理
            if resp.status >= 400:
                return resp.status, body[:400].decode('utf-8', 'ignore')
            return resp.status, body.decode('utf-8', 'ignore')
        except Exception as e:
            _ptd_drop_conn()
            if attempt == 0:
                # 连接被回收/半开 → 重连后再试一次（最常见于 keep-alive 空闲后）
                continue
            return -1, str(e)[:160]
    return -1, 'unreachable'


# ─────────── RSS 解析（NexusPHP torrentrss.php）───────────
def _ptd_parse_rss(xml, domain, site_name):
    """NexusPHP RSS XML → 精简种子行（字段与 _slim_torrents_impl 对齐）。"""
    out = []
    if not xml:
        return out
    items = re.findall(r'<item>(.*?)</item>', xml, re.S)
    for it in items:
        def _tag(name):
            m = re.search(r'<%s(?:\s[^>]*)?>(.*?)</%s>' % (name, name), it, re.S)
            if not m:
                return ''
            v = m.group(1)
            if v.startswith('<![CDATA['):
                v = v[8:-3] if v.endswith(']]>') else v[8:]
            return _html.unescape(re.sub(r'<[^>]+>', '', v)).strip()
        title = _tag('title')
        if not title:
            continue
        # ★ v1.13e：NexusPHP RSS 标题形如
        #   "[Irreplaceable 2026 S01E09 2160p ...-UBWEB[无可替代 | 第09集 | ...]]"
        #   外层是描述用的方括号包裹，且尾部带中文别名/演员信息 —— 清洗成纯发布名。
        title = title.strip()
        while title.startswith('['):
            title = title[1:]
        title = title.rstrip(']').strip()
        # 截掉尾部 "[中文名 | 第NN集 | ...]"（只截最外层那一组）
        _d = title.rfind('[')
        if _d > 8:
            title = title[:_d].strip()
        link = _tag('link')
        # enclosure 里的 length = 字节数
        msize = re.search(r'<envelope[^>]*length="(\d+)"', it)
        if not msize:
            msize = re.search(r'length="(\d+)"', it)
        size = int(msize.group(1)) if msize else 0
        # 描述里抠种子数/做种数（NexusPHP RSS 的 description 是表格）
        desc = _tag('description')
        mseed = re.search(r'(\d+)\s*(?:seeders?|做种|在做)', desc, re.I)
        seeders = int(mseed.group(1)) if mseed else 0
        mleech = re.search(r'(\d+)\s*(?:leechers?|下载)', desc, re.I)
        leechers = int(mleech.group(1)) if mleech else 0
        pub = _tag('pubDate')[:16]
        # ★ v1.14：RSS link = https://<dom>/details.php?id=NNNN → torrent_id
        #   （磁力下载必须靠它，之前一直是 None，导致前端下载按钮不亮）
        _tid = None
        _ml = re.search(r'(?:details|torrents)\.php\?[^"\s]*?id=(\d+)', link or '')
        if _ml:
            _tid = _ml.group(1)
        # ★ v1.14：RSS description 里 NexusPHP 会带 doubaninfo.com/dbposter/xxx.jpg
        # 优先级：① doubaninfo.com/dbposter/xxx.jpg（豆瓣海报，最准）
        #         ② 描述里第一张 <img src=...>（zmpt 等站用 pic.814000.xyz 图床）
        #         ③ 任意 http(s) 图片（兜底）
        _poster = ''
        for _pat in (
            r'src="(https?://[^"\s]*?doubaninfo[^"\s]*?\.(?:jpg|jpeg|png|webp))"',
            r'(https?://[^\s"\'<>]*?doubaninfo[^\s"\'<>]*?\.(?:jpg|jpeg|png|webp))',
            r'<img[^>]+src="(https?://[^"\s]+\.(?:jpg|jpeg|png|webp))"',
        ):
            _pm = re.search(_pat, desc, re.I)
            if _pm:
                _poster = _pm.group(1)
                break
        # ★ v1.13f：RSS 标题/描述里的促销标记（2X 免费 / 50% / 免费）
        _promo = ''
        _hay = (title + ' ' + desc).lower()
        if re.search(r'2x\s*free|2x\s*\u514d\u8d39', _hay):
            _promo = '免费2x'
        elif re.search(r'\bfree\b|\u514d\u8d39|50%', _hay):
            _promo = '免费'
        out.append({
            'title': title,
            'site': site_name, 'site_name': site_name, 'site_id': None,
            'size': size, 'size_txt': psz2(size),
            'seeders': seeders, 'leechers': leechers, 'grabs': 0,
            'year': None, 'season': None, 'episode': None, 'season_end': None,
            'season_episode': '', 'se_cn': '',
            'type': '', 'pix': '', 'pix_rank': 8, 'team': '', 'audio': '', 'video': '',
            'promo': _promo, 'promo_rank': {'免费2x': 3, '免费': 2}.get(_promo, 0),
            'labels': [], 'hr': None,
            'pubdate': pub, 'url': link, 'torrent_id': _tid,
            'poster': _poster,
            'dims': _parse_tor_dims(title, size),
            'site_logo': _ptd_logo_obj(domain, site_name),
            'raw': None, 'src': 'rss',
        })
    return out


# ─────────── 搜索页解析（NexusPHP torrents.php）───────────
def _ptd_parse_search(html_txt, domain, site_name):
    """NexusPHP 搜索结果页 → 精简种子行。

    ★ v1.13e 实测（咖啡站，2026-10-21）：
      <a title="Joy Of Life 2019 S01 Complete 1080p DSNP WEB-DL H264 AAC-UBWEB"
         href="details.php?id=117624&amp;hit=1"><b>同标题</b></a>
      同行后续 td：<td class="rowfollow nowrap"><span title="2026-08-05 15:21:50">2月<br />16天</span>
                  <td class="rowfollow">77.58<br />GB</td>          ← 体积
                  <td class="rowfollow" align="center"><b><a href="...#seeders">1</a></b></td>  ← 做种
      注意 href 里是 **&amp;**（HTML 实体），老正则写 & 导致一条都匹配不到。
    """
    out = []
    if not html_txt:
        return out
    # 以「种子名链接」为锚点，向后取同一 <tr> 里的体积/做种/下载/发布时间
    for m in re.finditer(
            r'<a\s+title="([^"]+)"\s+href="details\.php\?id=(\d+)(?:&amp;[^"]*)?"',
            html_txt):
        title = _html.unescape(m.group(1)).strip()
        tid = m.group(2)
        if not title or len(title) < 3 or title.isdigit():
            continue
        # 向后窗口取体积/做种/日期。★ v1.13e 实测：窗口大小按站点差异很大 ——
        #   咖啡站约 1500 字符；**高清视界(hdarea) 在种子名后插了一大段
        #   豆瓣/IMDb 评分 HTML，体积 td 跑到 @3582** → 窗口取 6000 才不漏。
        #   上限 6000 仍远小于两个相邻种子名的间距（一条种子行约 8~10KB），
        #   不会串到下一条。
        win = html_txt[m.end():m.end() + 6000]
        # 体积：实测 HTML 是 `<td class="rowfollow">66.24<br />GB</td>`
        #   （数字与单位之间是 <br />，老正则写死空格所以一条都没匹配到）。
        #   兼容 `<br/>` / `<br>` / 空格 / 换行四种分隔。
        size = 0
        ms = re.search(
            r'<td class="rowfollow(?: nowrap)?[^>]*>\s*([\d.]+)\s*'
            r'(?:<br\s*/?>|&nbsp;|\s)+\s*(TB|GB|MB|KB)\s*<', win, re.I)
        if ms:
            unit = {'TB': 1024 ** 4, 'GB': 1024 ** 3, 'MB': 1024 ** 2,
                    'KB': 1024}.get(ms.group(2).upper(), 0)
            try:
                size = int(float(ms.group(1)) * unit)
            except Exception:
                size = 0
        seeders = 0
        mseed = re.search(r'dllist=1#seeders">(\d+)</a>', win)
        if mseed:
            seeders = int(mseed.group(1))
        leechers = 0
        ml = re.search(r'dllist=1#leechers">(\d+)</a>', win)
        if ml:
            leechers = int(ml.group(1))
        grabs = 0
        mg = re.search(r'viewsnatches\.php\?id=\d+"><b>(\d+)</b>', win)
        if mg:
            grabs = int(mg.group(1))
        # 发布时间：取 rowfollow nowrap 里第一个 span title（发布列在最前）
        pub = ''
        mp = re.search(r'<td class="rowfollow nowrap"><span title="(\d{4}-\d{2}-\d{2}[^"]*)"', win)
        if mp:
            pub = mp.group(1)[:10]
        # ★ v1.14 BUG-116：搜索页海报。hdarea 等站在种子名**之前**的 td 里放
        #   `<img class="torrent-poster-thumb" data-full="https://doubaninfo.com/dbposter/xxx.jpg">`
        #   取「本 anchor 之前最近的一个 data-full」即本条海报（向后取会串到别的行）。
        _poster = ''
        _pre = html_txt[max(0, m.start() - 6000):m.start()]
        _dp = re.findall(r'data-full="(https?://[^"]+?\.(?:jpg|jpeg|png|webp))"', _pre, re.I)
        if _dp:
            _poster = _dp[-1]
        else:
            _dp2 = re.findall(r'src="(https?://doubaninfo\.com/dbposter/[^"]+?\.(?:jpg|jpeg|png|webp))"',
                              _pre, re.I)
            if _dp2:
                _poster = _dp2[-1]
        out.append({
            'title': title,
            'site': site_name, 'site_name': site_name, 'site_id': None,
            'size': size, 'size_txt': psz2(size) if size else '',
            'seeders': seeders, 'leechers': leechers, 'grabs': grabs,
            'year': None, 'season': None, 'episode': None, 'season_end': None,
            'season_episode': '', 'se_cn': '',
            'type': '', 'pix': '', 'pix_rank': 8, 'team': '', 'audio': '', 'video': '',
            'promo': '', 'promo_rank': 0, 'labels': [], 'hr': None,
            'pubdate': pub, 'url': 'https://%s/details.php?id=%s' % (domain, tid),
            'torrent_id': tid,
            'poster': _poster,
            'dims': _parse_tor_dims(title, size),
            'site_logo': _ptd_logo_obj(domain, site_name),
            'raw': None, 'src': 'search',
        })
    return out


# ════════════════════════════════════════════════════════════════════
# ★ v1.14 下载链路：直连行 → 真实磁力（用户反复点名的核心缺口）
#
#   背景（2026-10-21 实测）：
#     · MP /api/v1/download/add 必须带完整 torrent_in，而真实 torrent_in
#       只能从 MP 的 search/title 拿 —— 那个接口已彻底卡死（坑 33）
#     · 但 MP /api/v1/site 给的 cookie + RSS 里的 torrent_id 足够我们
#       自己下种子：download.php?id=<tid> 直接返回 application/x-bittorrent
#     · 把 .torrent 解出 info dict → sha1(bencode(info)) = info_hash
#       → 拼 magnet:?xt=urn:btih:<ih>&dn=<name>&tr=<announce>
#       → 直接推 qB（已有 submgmt_batch_dl 通道，带 passkey 的 tracker）
#
#   实测：zmpt.cc / hdarea.club 的 download.php 均 200 + x-bittorrent；
#         cyanbug / ptcafe / hdfans / nicept 返回 HTML（需登录态/风控），
#         这些站点降级为「详情页外链」，前端照样能给用户出路子。
# ════════════════════════════════════════════════════════════════════
_PTD_POSTER_CACHE = {}     # tmdbid/title -> {'ts':, 'poster':}（TMDB 海报兜底）
_PTD_POSTER_TTL = 86400    # 海报 URL 不变，缓存 24 小时
_PTD_POSTER_LOCK = threading.Lock()


def _tor_name(title):
    """种子标题 → 干净片名（供求片 TMDB 海报兜底用）。

    例：'假金钗.2026.S01E04.2160p.WEB-DL...mkv' → '假金钗'
        'Where the Mask Ends S01E09 2026 2160p YK HQ WEB-DL' → 'Where the Mask Ends'
    保守：抠不出返回 ''（调用方跳过，绝不猜影片）。
    """
    t = str(title or '').strip()
    if not t:
        return ''
    t = re.sub(r'\.(mkv|mp4|avi|ts|iso|rmvb)$', '', t, flags=re.I)
    # 中文站：第一段（. / 空格 / - 分隔）通常就是片名
    m = re.match(r'^([\u4e00-\u9fff][\u4e00-\u9fff0-9\uff1a\u00b7\u300a\u300b]{1,30})'
                 r'[\s\.\-_]', t)
    if m:
        nm = m.group(1).strip('\u300a\u300b ._-')
        if len(nm) >= 2:
            return nm
    # 英文站：从开头吃到年份/季集/画质标记之前
    m = re.match(r'^(.*?)(?:\s(?:19|20)\d{2}\b|\s[Ss]\d{1,2}[Ee]\d{1,3}\b'
                 r'|\s[Ss]\d{1,2}\b|\s\d{3,4}[pP]\b)', t)
    if m:
        nm = m.group(1).strip(' ._-')
        nm = re.sub(r'\s+\([^)]*\)\s*$', '', nm).strip()
        if len(nm) >= 2:
            return nm
    return ''


def _emby_poster(name):
    """★ v1.14 BUG-116c：从 Emby 库里按片名找海报（本地图源，一定通）。

    TMDB 实测 401/代理 EOF 时全站榜单空白，用户点名「球片根本就求不了」。
    Emby 是本地的，且已入库的片在这里必有 Primary 海报 —— 拿它当兜底，
    至少「已入库/部分入库」的片有图。未入库的仍然靠豆瓣图/TMDB。
    返回 '' 表示没找到（调用方不得塞占位图）。
    """
    nm = str(name or '').strip()
    if len(nm) < 2:
        return ''
    try:
        conf = containers().get('emby') or {}
        ek = cfg().get('emby_key') or EMBY_KEY_FB
        if not conf.get('addr'):
            return ''
        st, b = hreq(conf['addr'], conf['port'], 'GET',
                     '/emby/Items?SearchTerm=%s&Recursive=true&Limit=6'
                     '&IncludeItemTypes=Movie,Series&Fields=ProviderIds,ProductionYear'
                     '&api_key=%s' % (urllib.parse.quote(nm), ek), None, None, 8)
        if st != 200 or not b:
            return ''
        items = (json.loads(b) or {}).get('Items') or []
    except Exception:
        return ''
    for it in items:
        if not isinstance(it, dict):
            continue
        iid = it.get('Id')
        if not iid:
            continue
        # 名字对得上才算（SearchTerm 是模糊匹配，防止串片）
        _n = str(it.get('Name') or '')
        if nm.lower() not in _n.lower() and _n.lower() not in nm.lower():
            continue
        # ★★ v1.25 BUG-169：改走 /embyimg/ 代理，绝不把 api_key 明文下发前端
        return '/embyimg/emby/%s/Primary?w=160' % iid
    return ''


def _ptd_poster_fill(rows):
    """★ v1.14 BUG-116b：给没有封面的直连行补 TMDB 海报（兜底）。

    实测：hdarea 的搜索页每行带 data-full 豆瓣海报；但织梦/大青虫/咖啡/
    红豆饭的搜索页**完全没有图**，用户看到一列纯文字资源列表，体验很差。
    这里按标题里抠出的片名去 TMDB 搜一次，拿 poster_path 拼官方 CDN。
    全部命中走缓存，同一部片只打 TMDB 一次。
    """
    todo = {}
    for r in (rows or []):
        if not isinstance(r, dict) or r.get('poster'):
            continue
        t = str(r.get('title') or '')
        if not t:
            continue
        nm = _tor_name(t)
        if not nm or len(nm) < 2:
            continue
        ck = nm.lower()
        with _PTD_POSTER_LOCK:
            c = _PTD_POSTER_CACHE.get(ck)
        if c and time.time() - c.get('ts', 0) < _PTD_POSTER_TTL:
            if c.get('poster'):
                r['poster'] = c['poster']
            continue
        todo.setdefault(ck, []).append(r)
    if not todo:
        return
    def _one(nm, lst):
        po = ''
        # ① TMDB（最快，但依赖外部 API；挂了就静默跳过）
        try:
            for kind in ('tv', 'movie'):
                rs = tmdb_search(nm, kind=kind) or []
                for x in rs:
                    if isinstance(x, dict) and x.get('poster_path') and not x.get('__err'):
                        po = '/tmdbimg/t/p/w300%s' % x['poster_path']
                        break
                if po:
                    break
        except Exception:
            pass
        # ② Emby 本地库（TMDB 挂掉时的保底，已入库的片必有图）
        if not po:
            po = _emby_poster(nm)
        for r in lst:
            if po:
                r['poster'] = po
    keys = list(todo.keys())[:24]
    with concurrent.futures.ThreadPoolExecutor(max_workers=6) as ex:
        futs = [ex.submit(_one, k, todo[k]) for k in keys]
        for f in concurrent.futures.as_completed(futs):
            try:
                f.result()
            except Exception:
                pass
    now = time.time()
    with _PTD_POSTER_LOCK:
        for k in keys:
            _PTD_POSTER_CACHE[k] = {'ts': now,
                                    'poster': todo[k][0].get('poster') or ''}


_PTD_MAG_CACHE = {}        # (domain, tid) -> {'ts':, 'magnet':, 'ok':bool}
_PTD_MAG_TTL = 3600        # info_hash 不会变，缓存 1 小时
_PTD_MAG_LOCK = threading.Lock()


def _ptd_bdecode(s):
    """极简 bdecode（只解 .torrent，够用即可）。出错抛 ValueError。"""
    def _dec(i):
        c = s[i:i + 1]
        if c == b'd':
            i += 1
            d = {}
            while s[i:i + 1] != b'e':
                k, i = _dec(i)
                v, i = _dec(i)
                d[k] = v
            return d, i + 1
        if c == b'l':
            i += 1
            l = []
            while s[i:i + 1] != b'e':
                v, i = _dec(i)
                l.append(v)
            return l, i + 1
        if c == b'i':
            j = s.index(b'e', i)
            return int(s[i + 1:j]), j + 1
        j = s.index(b':', i)
        n = int(s[i:j])
        return s[j + 1:j + 1 + n], j + 1 + n
    v, _ = _dec(0)
    return v


def _ptd_bencode(o):
    """极简 bencode（用于重算 info_hash，key 必须排序）。"""
    if isinstance(o, dict):
        r = b'd'
        for k in sorted(o.keys()):
            r += _ptd_bencode(k) + _ptd_bencode(o[k])
        return r + b'e'
    if isinstance(o, list):
        r = b'l'
        for x in o:
            r += _ptd_bencode(x)
        return r + b'e'
    if isinstance(o, bytes):
        return str(len(o)).encode() + b':' + o
    return b'i' + str(o).encode() + b'e'


def _ptd_dom_for_dl(dom):
    """下载用的域名：PTS 站裸域解析失败，必须 www.（与 BUG-113 同源）。"""
    d = str(dom or '').lower()
    if d == 'ptskit.org':
        return 'www.ptskit.org'
    return d


def _ptd_torrent_magnet(domain, tid, site_id=None):
    """下种子 → 真实磁力。失败返回 ''（调用方降级为详情页外链）。

    带 1 小时缓存（info_hash 恒定），绝不重复打站。
    """
    dom = str(domain or '').lower()
    tid = str(tid or '').strip()
    if not dom or not tid or not tid.isdigit():
        return ''
    ck = (dom, tid)
    now = time.time()
    with _PTD_MAG_LOCK:
        c = _PTD_MAG_CACHE.get(ck)
    if c and now - c.get('ts', 0) < _PTD_MAG_TTL:
        return c.get('magnet') or ''
    # 站点元数据（cookie/ua）优先按 site_id，退化按域名
    meta = {}
    if site_id:
        meta = _ptd_site_meta(site_id) or {}
    if not meta.get('cookie'):
        for sid, v in PT_DIRECT_SITES.items():
            if v.get('domain') == dom:
                meta = _ptd_site_meta(sid) or {}
                break
    d = _ptd_dom_for_dl(dom)
    url = 'https://%s/download.php?id=%s' % (d, tid)
    try:
        st, body = _ptd_http_get_raw(url, cookie=meta.get('cookie') or '',
                                     ua=meta.get('ua') or '', t=25)
    except Exception as e:
        _ptd_log('magnet http err %s/%s %s' % (dom, tid, str(e)[:100]))
        with _PTD_MAG_LOCK:
            _PTD_MAG_CACHE[ck] = {'ts': now, 'magnet': '', 'ok': False}
        return ''
    magnet = ''
    if st == 200 and body and body[:1] == b'd':
        try:
            t = _ptd_bdecode(body)
            info = t.get(b'info') or {}
            name = info.get(b'name') or b''
            try:
                name_s = name.decode('utf-8')
            except Exception:
                name_s = name.decode('utf-8', 'ignore')
            ih = hashlib.sha1(_ptd_bencode(info)).hexdigest()
            trs = []
            ann = t.get(b'announce')
            if ann:
                trs.append(ann.decode('utf-8', 'ignore'))
            for grp in (t.get(b'announce-list') or []):
                for tr in (grp or []):
                    trs.append(tr.decode('utf-8', 'ignore'))
            # 去重保序
            seen = set()
            trs = [x for x in trs if x and not (x in seen or seen.add(x))]
            magnet = 'magnet:?xt=urn:btih:%s&dn=%s' % (ih, urllib.parse.quote(name_s))
            for tr in trs[:4]:
                magnet += '&tr=' + urllib.parse.quote(tr)
        except Exception as e:
            _ptd_log('magnet parse err %s/%s %s' % (dom, tid, str(e)[:80]))
    else:
        _ptd_log('magnet dl fail %s/%s st=%s len=%s'
                 % (dom, tid, st, len(body or b'')))
    with _PTD_MAG_LOCK:
        _PTD_MAG_CACHE[ck] = {'ts': now, 'magnet': magnet, 'ok': bool(magnet)}
    return magnet


def _ptd_http_get_raw(url, cookie='', ua='', t=20):
    """同 _ptd_http_get 但返回原始 bytes（下 .torrent 必须用二进制）。"""
    import urllib.request
    import urllib.error
    hdr = {'User-Agent': ua or 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) '
            'AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0 Safari/537.36',
           'Accept': '*/*',
           'Accept-Language': 'zh-CN,zh;q=0.9,en;q=0.8'}
    if cookie:
        hdr['Cookie'] = cookie
    try:
        req = urllib.request.Request(url, headers=hdr)
        with urllib.request.urlopen(req, timeout=t) as resp:
            return resp.status, resp.read()
    except Exception as e:
        return -1, str(e)[:160].encode('utf-8', 'ignore')


def _ptd_logo_obj(domain, site_name):
    """站点 logo 对象（前端 discSiteLogo 同结构）。"""
    dom = str(domain or '').lower()
    if dom.startswith('www.'):
        dom = dom[4:]
    br = _PT_SITE_BR.get(dom, ['#64748b', (site_name or '?')[:2].upper()])
    return {'name': site_name or dom, 'domain': dom,
            'logo': _ptd_icon(dom), 'sym': '📡', 'br': br}


def _ptd_dedupe(rows):
    """按 (title, size, site) 去重，保留先到的。

    ★ v1.13f BUG-114：直连行以前 season/episode 恒为 None（MP 通道才有），
      导致前端「选集下载」在直连结果上完全失效 —— 勾了 E04 却把整季包
      甚至别的集也留下。现在去重前统一用 `_tor_se()` 兜底解析
      （与 MP 通道同一套保守策略：解析不出就 None，绝不猜）。
      同时补 se_cn / season_end，前端 S01E04 徽标才显示得出来。
    """
    seen = set()
    out = []
    for r in rows:
        k = (str(r.get('title') or '').lower(), int(r.get('size') or 0),
             str(r.get('site_name') or ''))
        if k in seen:
            continue
        seen.add(k)
        if r.get('season') is None and r.get('episode') is None:
            _sn, _ep = _tor_se(r.get('title') or '')
            r['season'] = _sn
            r['episode'] = _ep
            if _sn is not None and r.get('season_end') is None:
                _m = re.search(r'[Ss]\d{1,2}\s*[-~\u5230\u81f3]\s*[Ss]?(\d{1,2})',
                               r.get('title') or '')
                if _m and int(_m.group(1)) > _sn:
                    r['season_end'] = int(_m.group(1))
        if r.get('season') is not None or r.get('episode') is not None:
            r['se_cn'] = (('S%02d' % r['season']) if r.get('season') is not None else '') + \
                         (('E%02d' % r['episode']) if r.get('episode') is not None else '')
        # ★ v1.13f：促销字段（直连搜索页/ RSS 都能抠到 50% / 2X 免费）
        if not r.get('promo'):
            _t = str(r.get('title') or '')
            if re.search(r'2x\s*free|2X\s*\u514d\u8d39', _t, re.I):
                r['promo'] = '免费2x'
            elif re.search(r'\bfree\b|\u514d\u8d39|50%', _t, re.I):
                r['promo'] = '免费'
        out.append(r)
    return out


def _ptd_fetch_rss_all(kw='', force=False, t=20):
    """并发抓全部 7 站 RSS → {domain: [rows]}。带 3 分钟缓存。

    ★ 实测：7 站并发总耗时 3.4 秒（vs MP 单次搜索 2000+ 秒）。
    """
    now = time.time()
    # ★ 2026-10-24：缓存 key 形如 `dom`（无关键词）或 `dom|<kw>`（带关键词）。
    #   老代码把**所有** key 一起返回 → 不同关键词的缓存互相污染，
    #   _rss_match 遍历到几十个 key，sites 计数虚高到 194（实际只有 7 站）。
    _want = ('|' + str(kw)) if kw else ''
    def _key_ok(k):
        return k.endswith(_want) if _want else ('|' not in k)
    with _PTD_LOCK:
        cache = {k: v for k, v in _PTD_RSS_CACHE.items() if _key_ok(k)}
    if not force and cache:
        fresh = {k: v for k, v in cache.items()
                 if now - v.get('ts', 0) < _PTD_RSS_TTL}
        if len(fresh) == len(cache) and cache:
            return {k: v.get('items') or [] for k, v in cache.items()}
    urls = _ptd_rss_urls(kw)
    if not urls:
        # RSS 地址取不到 → 用上一次缓存（哪怕过期）
        return {k: v.get('items') or [] for k, v in cache.items()}

    def _one(dom, info):
        # ★ v1.13f BUG-112 同源修复：RSS 也改分级冷却（瞬时错 15s / 风控 60s）
        with _PTD_LOCK:
            ft = _PTD_FAIL.get(dom)
            fw = _PTD_FAIL.get('waf:' + dom)
        if fw and now - fw < 60:
            return dom, None
        if ft and now - ft < 15:
            return dom, None
        st, body = _ptd_http_get(info['url'], t=min(t, 8))
        if st != 200 or not body or '<item>' not in body:
            if st in (403, 503) or 'cloudflare' in str(body or '').lower()[:400]:
                with _PTD_LOCK:
                    _PTD_FAIL['waf:' + dom] = time.time()
            else:
                with _PTD_LOCK:
                    _PTD_FAIL[dom] = time.time()
            _ptd_log('RSS fail %s st=%s len=%s' % (dom, st, len(body or '')))
            return dom, None
        rows = _ptd_parse_rss(body, dom, info.get('name') or dom)
        with _PTD_LOCK:
            _ck = dom + ('|' + str(kw) if kw else '')
            _PTD_RSS_CACHE[_ck] = {'ts': time.time(), 'items': rows}
            _PTD_FAIL.pop(dom, None)
            _PTD_FAIL.pop('waf:' + dom, None)
        return dom, rows

    res = {}
    with concurrent.futures.ThreadPoolExecutor(max_workers=7) as ex:
        futs = [ex.submit(_one, d, i) for d, i in urls.items()]
        for f in concurrent.futures.as_completed(futs):
            try:
                dom, rows = f.result()
                if rows is not None:
                    res[dom] = rows
            except Exception as e:
                _ptd_log('RSS task err %s' % str(e)[:120])
    # 补上缓存里存在但本轮没抓到的（失败冷却中的站）—— 同样只补同 kw 的
    with _PTD_LOCK:
        for dom, v in _PTD_RSS_CACHE.items():
            if dom not in res:
                res[dom] = v.get('items') or []
    return res


def _ptd_search_site(site_id, kw, t=20):
    """单站搜索页抓取（NexusPHP torrents.php?search=）。

    ★ v1.13e BUG-106：旧实现 `if not meta.get('nx')` —— meta 是
       _ptd_site_meta() 的返回 dict（cookie/ua/domain），**根本没有 nx 键**
       （nx 在 PT_DIRECT_SITES 里）→ 条件恒真 → 每个站都直接 return []，
       表现为「搜索 5.2 秒返回 0 条」而 HTTP 一次都没打（took=0.0s）。
       现在 nx 从 PT_DIRECT_SITES 取。

    ★ v1.13f BUG-112（用户实锤「求片搜索根本没结果」的真正残留根因）：
      旧实现**任何**失败都写 60 秒冷却。而面板同时跑着
      「后台 5 分钟预搜循环 + 用户手动搜索 + RSS 池刷新」三条流，
      只要有一轮里 7 个站同时抽风（DNS 瞬挂 / Cloudflare 403 / 502），
      接下来 60 秒内**所有**搜索都直接 return []，表现为
      「took=3.9s、rows=0、sites=0，一次 HTTP 都没打」——
      用户看到的就是「搜索转两秒就返回 0 条，根本没有结果」。
      → 现在冷却**分级**：瞬时网络错（DNS/超时/5xx）只冷却 15 秒；
        风控 403/云flare 挑战才冷却 60 秒；**域名解析失败自动换 www. 前缀重试**
        （PTS 站 ptskit.org 裸域 DNS 无记录，必须 www.ptskit.org —— BUG-113）。

    ★ v1.13f BUG-113：`ptskit.org` 裸域在容器内 DNS 解析失败
      （`[Errno -5] Name has no usable address`），`www.ptskit.org` 正常。
      所以单站抓取带「裸域 → www. 前缀」自动降级。
    """
    meta = _ptd_site_meta(site_id)
    if not meta:
        return []
    if not PT_DIRECT_SITES.get(site_id, {}).get('nx'):
        return []          # 馒头/CARPT：M-Team 新版 SPA / 无 RSS，不抓搜索页
    dom = meta.get('domain') or ''
    if not dom:
        return []
    now = time.time()
    # ── 分级冷却：瞬时错 15s（ key = dom ），风控 60s（ key = 'waf:'+dom ）──
    with _PTD_LOCK:
        ft = _PTD_FAIL.get(dom)
        fw = _PTD_FAIL.get('waf:' + dom)
    if fw and now - fw < 60:
        return []
    if ft and now - ft < 15:
        return []
    # 域名候选：裸域优先，解析失败换 www. 前缀（PTS 站必须这样）
    cands = [dom]
    if not dom.startswith('www.') and '.' in dom:
        cands.append('www.' + dom)
    rows = []
    for d in cands:
        url = ('https://%s/torrents.php?notnewword=1&search=%s'
               % (d, urllib.parse.quote(kw)))
        with _PTD_LOCK:
            _PTD_TRY['n'] = _PTD_TRY.get('n', 0) + 1
        st, body = _ptd_http_get(url, cookie=meta.get('cookie') or '',
                                 ua=meta.get('ua') or '', t=t)
        if st == 200 and body and 'details.php' in body:
            with _PTD_LOCK:
                _PTD_FAIL.pop(dom, None)
                _PTD_FAIL.pop('waf:' + dom, None)
            rows = _ptd_parse_search(body, d, meta.get('name') or dom)
            # 解析成功但真的 0 条（站内没这片的种子）→ 也清冷却，别冤枉站
            if not rows:
                with _PTD_LOCK:
                    _PTD_FAIL.pop(dom, None)
                    _PTD_FAIL.pop('waf:' + dom, None)
            return rows
        # DNS 解析失败 → 换 www. 前缀再试（不写冷却，避免把好站误锁）
        if st == -1 and 'Name has no usable address' in str(body or ''):
            _ptd_log('search dns-miss %s → try www.' % d)
            continue
        # 403 / 云flare 挑战 → 风控冷却 60s
        if st in (403, 503) or 'cloudflare' in str(body or '').lower()[:400]:
            with _PTD_LOCK:
                _PTD_FAIL['waf:' + dom] = time.time()
            _ptd_log('search waf %s st=%s len=%s' % (d, st, len(body or '')))
            return []
        # 其它（超时 / 502 / 连接重置）→ 只冷却 15s
        with _PTD_LOCK:
            _PTD_FAIL[dom] = time.time()
        _ptd_log('search fail %s st=%s len=%s' % (d, st, len(body or '')))
        return []
    return rows


def _ptd_row_type(title):
    """直连行的大类粗判（电影/电视剧）。只用于前端图标，下载时按标题重判。"""
    t = str(title or '')
    if re.search(r'[Ss]\d{1,2}[Ee]\d{1,3}', t) or re.search(r'[Ss]\d{1,2}\s*(?:Complete|全集)', t, re.I):
        return 'tv'
    if re.search(r'\b(E\d{1,3})\b', t):
        return 'tv'
    return 'movie'


# ★ v1.15 性能重构（用户原话：「我求片的时候发现我搜索之后站点的响应非常慢」）
#   实测结论（2026-10-21，7 站并发跑 `嫁金钗`）：
#     7 站全并发 → 67~78 秒（Cloudflare 限流，4 站 20s 读超时）
#     4 站并发 → 45 秒；3 站并发 → 28 秒；2 站并发 → 103 秒（更糟）
#     单站串行 → 每站 2~3 秒，7 站约 15 秒且**全部 200 成功**
#   → 真正的问题不是「并发不够」，而是**同时打太多站会触发各站 CDN 限流**。
#   所以策略改为「**分批 + 短超时 + 早停**」：
#     ① 分 3 批（每批 3 站），批内并发；单站超时压到 8 秒
#        → 最坏 3×8=24s，最好 3×3=9s，比原来 67~78s 快 3~7 倍。
#     ② **早停**：任意时刻已拿到 >= _PTD_FAST_ENOUGH 条就不再打下一批
#        （用户要的是「有资源可看」，不是「把 7 站全跑完」）。
#     ③ RSS 池（3.4s，且已缓存）**先**跑，作为第一批结果的即时补充，
#        让首屏在 5 秒内必有内容。
#     ④ 仍然保留「全站 0 条 + 一次 HTTP 都没打」时的冷却清理重试（BUG-112）。
_PTD_FAST_ENOUGH = 25      # ★ 2026-10-24：60 条要跑完 3 波（~32s），用户以为「没反应」。
                        #   实测 RSS 首波就能给 50+ 条 → 降到 25，通常 1~2 波收工（~16s）。
_PTD_BATCH = 3             # 每批并发几个站（实测 3 是甜点）
_PTD_SITE_T = 8            # 单站搜索页超时（秒）—— 比原来的 20s 砍掉 60%


def _pt_push_qb(magnet, name='', category='missing'):
    """把磁力/种子 URL 推进 qB（缺集扫描一键下载用）。

    ★ v1.16 新增。复用既有 qb act='add' 的同一套 qb_call，绝不另起炉炉。
      分类默认 missing（求片缺集），与 keepalive / 订阅 分开，方便用户
      在 qB 里一眼看出哪些是缺集补全任务。
    """
    mag = str(magnet or '').strip()
    if not mag:
        return {'ok': False, 'msg': '空链接'}
    if not (mag.startswith('magnet:') or mag.startswith('http')
            or mag.endswith('.torrent')):
        return {'ok': False, 'msg': '非磁力/种子链接'}
    try:
        r = act_qb('add', {'urls': mag, 'category': category})
        if isinstance(r, dict) and r.get('ok'):
            return {'ok': True, 'msg': r.get('msg') or '已提交 qB', 'name': name}
        return {'ok': False, 'msg': (r or {}).get('msg') or 'qB 提交失败'}
    except Exception as e:
        return {'ok': False, 'msg': str(e)[:100]}


def pt_direct_search(q, t=20, use_rss=True):
    """★ v1.13e 新增：PT 直连搜索（主通道）。

    策略（★ v1.15 分批+早停重构，见上方实测注释）：
      1. RSS 池（3.4s，已缓存）先补量 —— 首屏 5 秒内必有内容
      2. 分 3 批（每批 3 站）并发抓 NexusPHP 搜索页，单站 8 秒超时
      3. 早停：累计 >= _PTD_FAST_ENOUGH 条即收工
    返回 {'ok':True,'rows':[...], 'src':'direct', 'sites':N}
    失败返回 {'ok':False,'msg':...}（调用方退回 MP）
    """
    kw = (q or '').strip()
    if not kw:
        return {'ok': False, 'msg': '空关键词'}
    kw_low = kw.lower()
    t0 = time.time()
    rows = []
    sites_ok = 0

    def _search_batch(sids):
        """跑一批站点，返回 (rows, sites_ok)。"""
        _rows = []
        _ok = 0
        if not sids:
            return _rows, _ok
        with concurrent.futures.ThreadPoolExecutor(max_workers=len(sids)) as ex:
            futs = {ex.submit(_ptd_search_site, sid, kw, _PTD_SITE_T): sid for sid in sids}
            for f in concurrent.futures.as_completed(futs):
                try:
                    r = f.result()
                    if r:
                        _rows.extend(r)
                        _ok += 1
                except Exception as e:
                    _ptd_log('search task err %s' % str(e)[:120])
        return _rows, _ok

    def _rss_match():
        """RSS 池宽匹配补量（已缓存，3.4s 一轮）。"""
        _rows = []
        _ok = 0
        try:
            # ★ 2026-10-24：传 kw 让 RSS 走服务端 search（passkey 通道，
            #   不受 cf_clearance 过期影响）；服务端不支持的站本地再过滤一遍。
            pool = _ptd_fetch_rss_all(kw=(kw or ''))
            for dom, items in (pool or {}).items():
                for it in (items or []):
                    tl = str(it.get('title') or '').lower()
                    # 中文站：关键词整体命中；英文站：按空格拆词任命中
                    if kw_low and (kw_low in tl or all(
                            w and w in tl for w in kw_low.split() if len(w) > 1)):
                        _rows.append(it)
                        _ok += 1
                        break
        except Exception as e:
            _ptd_log('rss pool err %s' % str(e)[:120])
        return _rows, _ok

    # ── 1. RSS 池先跑（缓存命中时 <0.1s，让首屏尽快有内容）──
    if use_rss:
        rr, ro = _rss_match()
        rows.extend(rr)
        sites_ok += ro
        # ★ RSS 已经够多就直接收工，别再打搜索页（cookie 失效后搜索页基本全 302）
        if len(_ptd_dedupe(rows)) >= _PTD_FAST_ENOUGH:
            rows = _ptd_dedupe(rows)
            _ptd_log('search "%s" rows=%d sites=%d took=%.1fs (RSS 足够，早停)'
                     % (kw, len(rows), sites_ok, time.time() - t0))
            return {'ok': True, 'rows': rows, 'src': 'direct',
                    'sites': sites_ok, 'took': round(time.time() - t0, 1)}
    # ── 2. 瀑布式抓搜索页（★ v1.15 核心提速，实测见下方注释）──
    #   老实现 7 站一次性全并发 → Cloudflare 限流 → 4 站 20s 读超时 → 67~78s。
    #   实测各站「单独跑」耗时（2026-10-21）：
    #     高清视界 0.7s/100 条 · PTS 0.4s/0 条 · 咖啡 2.8s/50 条
    #     织梦 3.7s/0 条 · 大青虫 3.6s/0 条 · 老师 7.3s/0 条 · 红豆饭 54s/0 条
    #   → 真正「又快又多」的只有前 3~4 站。改成**瀑布**：
    #     第 1 波只打 2 个快站（1 秒内回来，命中就 100+ 条 → 直接收工）；
    #     不够再打第 2 波（+2 站）；仍不够才打剩下的慢站。
    #   收益：常见片 1~2 秒出结果（原来 67~78 秒），**快 40 倍**。
    with _PTD_LOCK:
        _PTD_TRY['n'] = 0
    nx_ids = [sid for sid, v in PT_DIRECT_SITES.items() if v.get('nx')]
    # 按实测「快 + 高产」排序：高清视界 / PTS / 咖啡 / 织梦 / 大青虫 / 老师 / 红豆饭
    _ORDER = ['hdarea.club', 'www.ptskit.org', 'ptcafe.club', 'zmpt.cc',
              'cyanbug.net', 'nicept.net', 'hdfans.org']
    def _ord(sid):
        d = PT_DIRECT_SITES[sid].get('domain') or ''
        if d == 'ptskit.org':
            d = 'www.ptskit.org'
        return _ORDER.index(d) if d in _ORDER else 99
    nx_ids.sort(key=_ord)
    # 瀑布波次：2 + 2 + 3（前两波就能覆盖绝大多数场景）
    _WAVES = [2, 2, 3, 9]
    _wi = 0
    for wsz in _WAVES:
        if _wi >= len(nx_ids):
            break
        batch = nx_ids[_wi:_wi + wsz]
        _wi += wsz
        br, bo = _search_batch(batch)
        rows.extend(br)
        sites_ok += bo
        if len(_ptd_dedupe(rows)) >= _PTD_FAST_ENOUGH:
            break
        if time.time() - t0 > 25:          # 硬上限 25 秒，绝不让用户干等
            break
    # ★ v1.13f BUG-112 关键补丁：如果「一次 HTTP 都没打」却返回 0 条，
    #   说明全部站点都在冷却里（上一轮集体抽风留下的）。这时候用户等 3 秒
    #   拿到 0 条会以为「根本没搜」—— 直接清掉瞬时冷却重打一轮。
    if not rows and _PTD_TRY.get('n', 0) == 0:
        _ptd_log('search all-cooled "%s" → clear & retry once' % kw)
        now2 = time.time()
        with _PTD_LOCK:
            for k in list(_PTD_FAIL.keys()):
                if not str(k).startswith('waf:'):
                    if now2 - _PTD_FAIL[k] < 60:
                        _PTD_FAIL.pop(k, None)
        with _PTD_LOCK:
            _PTD_TRY['n'] = 0
        _wi = 0
        for wsz in _WAVES:
            if _wi >= len(nx_ids):
                break
            batch = nx_ids[_wi:_wi + wsz]
            _wi += wsz
            br, bo = _search_batch(batch)
            rows.extend(br)
            sites_ok += bo
            if len(_ptd_dedupe(rows)) >= _PTD_FAST_ENOUGH:
                break
    rows = _ptd_dedupe(rows)
    # ★ v1.14：TMDB 海报兜底（只对空缺封面的行，命中即缓存）
    try:
        _ptd_poster_fill(rows)
    except Exception as e:
        _ptd_log('poster fill err %s' % str(e)[:100])
    _ptd_log('search "%s" rows=%d sites=%d took=%.1fs'
             % (kw, len(rows), sites_ok, time.time() - t0))
    return {'ok': True, 'rows': rows, 'src': 'direct',
            'sites': sites_ok, 'took': round(time.time() - t0, 1)}


def pt_direct_status():
    """直连通道健康状态（前端/运维可观测）。"""
    now = time.time()
    with _PTD_LOCK:
        rss = {d: {'n': len(v.get('items') or []),
                   'age': int(now - v.get('ts', now))}
               for d, v in _PTD_RSS_CACHE.items()}
        fails = {d: int(now - ts) for d, ts in _PTD_FAIL.items() if now - ts < 300}
    urls = {}
    try:
        urls = _ptd_rss_urls()
    except Exception:
        pass
    return {'ok': True, 'rss_sites': len(rss), 'rss_total': sum(v['n'] for v in rss.values()),
            'rss': rss, 'rss_urls': len(urls), 'fails': fails,
            'sites': {str(k): v['name'] for k, v in PT_DIRECT_SITES.items()}}


def _mp_invite_bonus() -> dict:
    """各站「兑换邀请」所需魔力值（用户 2026-10-16 要求加到站点规则里）。"""
    # 与 Bot 保号侧的邀请资格阈值保持一致（keepalive.py::_invite_progress）
    return {"m-team.cc": 6000, "nicept.net": 300, "hdarea.club": 700}


def _mp_site_rules() -> dict:
    """各站保号规则明细（域名 → {text, invite_bonus}），供 Web 下拉菜单展示。"""
    ka = _ka_read_state()
    cfg = ka.get("_cfg") or []
    inv = _mp_invite_bonus()
    out = {}
    for c in cfg:
        dom = str(c.get("home") or "")
        dom = dom.lower().split("//")[-1].split("/")[0]
        if dom.startswith("www."):
            dom = dom[4:]
        if not dom:
            continue
        req = c.get("req") or {}
        sst = ((ka.get("sites") or {}).get(c.get("id")) or {}).get("stats") or {}
        lines = [
            "【%s】%s" % (c.get("name") or dom, dom),
            "",
            "· 登录保活：每 %s 天访问一次（站点红线 %s 天）" % (
                req.get("login_interval"), req.get("login_days")),
            "· 保持流量：%s 天内上传/下载必须有增量" % req.get("no_traffic_days"),
            "· 分享率：≥ %s（下载为 0 时按无限处理）" % req.get("min_ratio"),
            "· H&R：%s" % req.get("hr_desc"),
        ]
        if req.get("newbie") and c.get("id") in ("mteam", "nicept", "hdarea"):
            lines.append("· 新手考核：%s" % (c.get("newbie_desc") or "见站规"))
        ib = inv.get(dom, 0)
        if ib:
            lines += ["", "🎁 兑换邀请：需魔力值 %s（当前 %s）" % (
                ib, int(sst.get("bonus") or 0))]
        else:
            lines += ["", "🎁 兑换邀请：本规则未配置魔力值门槛"]
        out[dom] = {"text": "\n".join(lines), "invite_bonus": ib,
                    "name": c.get("name") or dom}
    return out


def mp_dashboard() -> dict:
    """★ 2026-10-16 用户要求：把 MP 的仪表盘也拉到 Web。
    MP：站点数/启用、刷流任务状态、订阅数、下载器、转移统计。
    ★ 追加：站点规则（含兑换邀请所需魔力值）+ 插件真实启用状态。"""
    out = {"ok": True, "sites": {}, "brush": {}, "subs": {},
           "downloader": {}, "rules": {}, "plugins": []}
    try:
        out["rules"] = _mp_site_rules()
    except Exception as e:
        out["rules"] = {"err": str(e)[:80]}
    try:
        rp = mp_call('/api/v1/plugin/installed')
        names = rp.get('data') if rp['ok'] else []
        if isinstance(names, dict):
            names = names.get('data') or []
        if not isinstance(names, list):
            names = []
        pl = []
        for n in names:
            n = str(n)
            st = mp_call('/api/v1/plugin/%s' % n, t=10)
            en, ver = True, ""
            if st.get('ok') and isinstance(st.get('data'), dict):
                en = bool(st['data'].get('enabled'))
                ver = str(st['data'].get('version') or "")
            pl.append({"id": n, "name": n, "enabled": en, "version": ver})
        pl.sort(key=lambda x: (not x["enabled"], x["name"]))
        out["plugins"] = pl
    except Exception as e:
        out["plugins_err"] = str(e)[:80]
    try:
        r = mp_call("/api/v1/site/")
        if not r.get("ok"):
            out["sites"] = {"total": 0, "active": 0, "with_cookie": 0,
                            "with_apikey": 0, "list": [], "ok": False,
                            "err": r.get("msg") or "读取 MP 站点失败"}
        else:
            sites = r.get("data") or []
            out["sites"] = {
                "ok": True,
                "total": len(sites),
                "active": sum(1 for s in sites if s.get("is_active")),
                "with_cookie": sum(1 for s in sites
                                   if len(str(s.get("cookie") or "")) > 3),
                "with_apikey": sum(1 for s in sites if s.get("apikey")),
                "list": _mp_sites_with_bonus(sites),
            }
    except Exception as e:
        out["sites"] = {"total": 0, "active": 0, "with_cookie": 0, "with_apikey": 0,
                        "list": [], "ok": False, "err": str(e)[:120]}
    # ★ 2026-10-18 用户点名 bug：「MP 容器里站点刷流每个站点数据都是 0」。
    #   根因：MP 500 / BrushFlow 插件未装时 mp_call 返回 ok:false、data 为空，
    #   老代码静默把空列表写成 0，前端完全看不出是「真的 0」还是「读失败」。
    #   现在：区分 ok/err，失败时给可执行原因，前端红条展示。
    # site_id → 站名映射（BrushFlow 任务只给 site_id，需要换算成中文站名展示）
    site_names = {}
    try:
        _rs = mp_call("/api/v1/site/")
        if _rs.get("ok"):
            for _s in (_rs.get("data") or []):
                if isinstance(_s, dict):
                    site_names[_s.get("id")] = str(_s.get("name") or "")
    except Exception:
        pass
    try:
        rb = mp_call("/api/v1/plugin/BrushFlow")
        if not rb.get("ok"):
            msg = rb.get("msg") or "MP 接口返回失败"
            if "404" in str(msg):
                msg = ("MoviePilot 未安装 BrushFlow 刷流插件"
                       "（/api/v1/plugin/BrushFlow → 404）。"
                       "请在 MP「插件中心」安装并启用后刷新。")
            out["brush"] = {"total": 0, "enabled": 0, "names": [],
                            "ok": False, "err": msg}
        else:
            dd = rb.get("data")
            if not isinstance(dd, dict):
                dd = {}
            tasks = dd.get("tasks") or []
            if not isinstance(tasks, list):
                tasks = []
            cfg = dd.get("config") or dd.get("setting") or {}
            out["brush"] = {
                "total": len(tasks),
                "enabled": sum(1 for t in tasks if t.get("enabled")),
                "names": [str(t.get("name"))[:20] for t in tasks],
                # ★ 2026-10-18 字段实测修正：BrushFlow task 用的是 site_id（整数）而不是
                #   sites/site 数组；也没有 state/last_run 字段。老代码读错字段名 →
                #   detail 里 sites/state/last 全空，看起来就像「每个站点数据都是 0」。
                #   现在 site_id → 站名（对照 /api/v1/site/ 的 id），并补全真实配置项。
                "detail": [{"name": str(t.get("name"))[:30],
                            "id": str(t.get("id") or "")[:32],
                            "enabled": bool(t.get("enabled")),
                            "site_id": t.get("site_id"),
                            "site": site_names.get(t.get("site_id"), ""),
                            "sites": ([site_names.get(t.get("site_id"), "")]
                                      if t.get("site_id") else []),
                            "state": "enabled" if t.get("enabled") else "disabled",
                            "downloader": str(t.get("downloader") or ""),
                            "brush_interval": t.get("brush_interval"),
                            "check_interval": t.get("check_interval"),
                            "maxdlcount": t.get("maxdlcount"),
                            "freeleech": t.get("freeleech"),
                            "hr": t.get("hr"),
                            "seeder": t.get("seeder"),
                            "pubtime": t.get("pubtime"),
                            "qb_category": str(t.get("qb_category") or ""),
                            "save_path": t.get("save_path"),
                            "notify": bool(t.get("notify")),
                            "last": ""}
                           for t in tasks][:40],
                "ok": True,
                "plugin_cfg": cfg if isinstance(cfg, dict) else {},
                "site_names": site_names,
            }
    except Exception as e:
        out["brush"] = {"total": 0, "enabled": 0, "names": [],
                        "ok": False, "err": str(e)[:120]}
    try:
        rs = mp_call("/api/v1/subscribe/?page=1&count=1")
        if not rs.get("ok"):
            out["subs"] = {"total": 0, "ok": False,
                           "err": rs.get("msg") or "读取 MP 订阅失败"}
        else:
            dd = rs.get("data")
            if isinstance(dd, dict):
                out["subs"] = {"total": dd.get("total") or len(dd.get("items") or []),
                               "ok": True}
            elif isinstance(dd, list):
                out["subs"] = {"total": len(dd), "ok": True}
            else:
                out["subs"] = {"total": 0, "ok": True}
    except Exception as e:
        out["subs"] = {"total": 0, "ok": False, "err": str(e)[:120]}
    # ★ 2026-10-18：/api/v1/downloader/ 在 MP v3 已不存在（实测 404 Not Found），
    #   下载器真实来源是 /api/v1/system/setting 的 downloader_clients / 或
    #   /api/v1/downloader/types。这里做多路径探测 + 显式失败原因。
    try:
        dls, derr = [], ""
        for pth in ("/api/v1/downloader/", "/api/v1/downloader/list",
                    "/api/v1/system/setting"):
            rd = mp_call(pth)
            if not rd.get("ok"):
                derr = rd.get("msg") or ""
                continue
            dd = rd.get("data")
            if isinstance(dd, list):
                dls = dd
                break
            if isinstance(dd, dict):
                cand = (dd.get("downloader_clients") or dd.get("downloaders")
                        or dd.get("data") or [])
                if isinstance(cand, list) and cand:
                    dls = cand
                    break
        if dls:
            out["downloader"] = {
                "total": len(dls), "ok": True,
                "names": [str(d.get("name") or d.get("type") or "")[:20] for d in dls],
                "detail": [{"name": str(d.get("name") or d.get("type") or ""),
                            "type": str(d.get("type") or ""),
                            "enabled": bool(d.get("enabled", True)),
                            "host": str(d.get("host") or d.get("addr") or "")[:40]}
                           for d in dls][:20],
            }
        else:
            out["downloader"] = {
                "total": 0, "names": [], "ok": False,
                "err": ("未取到下载器列表：%s。MP v3 已移除 /api/v1/downloader/，"
                        "请在 MP 设置里确认下载器配置。" % (derr or "接口均无数据"))}
    except Exception as e:
        out["downloader"] = {"total": 0, "names": [], "ok": False, "err": str(e)[:120]}
    return out


# ★ v1.18 BUG-134：会话首次出现时间表（session_id -> {'first','last'}）。
#   用途：给「同时两个人在看」提供**固定**的排序锚点。
#   Emby /Sessions 的顺序随心跳变化，前端整块重渲染就会换位（用户原话：
#   「我看的时候它会上下乱跳…谁先看的谁就在下面 谁后看的谁就在上面固定住了」）。
#   这里记录「第一次见到这条会话」的时刻，进程内恒定 → 排序永远稳定。
_SESS_ORDER = {}
_SESS_ORDER_LOCK = threading.Lock()


def emby_libstats():
    """Emby 媒体库统计卡（用户 2026-10-22 v1.19 参考 Docker PANE L 重做）。

    参考图的「媒体库监控」卡片语言：
      头部 = 应用图标 + 名称 + 当前状态（例：「4 位用户正在播放」）
      中部 = 4 列统计（用户 / 播放中 / 电影 / 剧集），当前列高亮
      底部 = 每行一条影片（封面 + 片名 + 用户 + 进度条 + 直连徽标）
    数据源全部是 Emby 官方只读接口，不写任何东西：
      /emby/Users        → 用户总数（有权限时才能列全部）
      /emby/Items/Counts → MovieCount / SeriesCount / EpisodeCount / UserCount
      /emby/Sessions     → 播放中数目（复用 emby_sessions 的判定）
    结果缓存 8 秒（前端 2s 轮询，不打满 Emby）。
    """
    out = {"ok": False, "user_n": 0, "playing": 0, "movie": 0, "series": 0,
           "episode": 0, "server": "", "err": ""}
    try:
        ek = cfg().get('emby_key') or EMBY_KEY_FB
        addr = containers()['emby']['addr']
        port = containers()['emby']['port']
        j = _emby_http("/emby/Items/Counts", t=8)
        if isinstance(j, dict):
            out["movie"] = int(j.get("MovieCount") or 0)
            out["series"] = int(j.get("SeriesCount") or 0)
            out["episode"] = int(j.get("EpisodeCount") or 0)
            out["user_n"] = int(j.get("UserCount") or 0)
        # 用户数：Counts 没给 UserCount 时回落 /emby/Users（取不到就给 0，不报错）
        if not out["user_n"]:
            try:
                uj = _emby_http("/emby/Users", params={"Recursive": "false"}, t=8)
                _u = uj if isinstance(uj, list) else (uj or {}).get("Items") or []
                out["user_n"] = len([x for x in _u if isinstance(x, dict)])
            except Exception:
                pass
        # 播放中：跟 emby_sessions 同一套口径（IsPaused is False 且位置>0）
        try:
            sj = _emby_http("/emby/Sessions", t=8)
            rows = sj if isinstance(sj, list) else (sj or {}).get("Items") or []
            n = 0
            for x in rows:
                if not isinstance(x, dict):
                    continue
                pi = x.get("PlayState") or {}
                if not x.get("NowPlayingItem"):
                    continue
                if pi.get("IsPaused") is False and int(pi.get("PositionTicks") or 0) > 0:
                    n += 1
            out["playing"] = n
        except Exception:
            pass
        try:
            si = _emby_http("/emby/System/Info", t=6)
            if isinstance(si, dict):
                out["server"] = str(si.get("ServerName") or "")
        except Exception:
            pass
        out["ok"] = True
    except Exception as e:
        out["err"] = str(e)[:120]
    return out


def emby_series(limit=60, sort="DateCreated", q=""):
    """★ v1.24 Emby 剧集列表（带 TMDB ID）—— 用户原话：
       「订阅与求片那边你给我把缺集扫描加上去然后要能进行全选或者是批量选择
         然后把缺的补齐」。
    缺集扫描需要「哪些剧值得扫」的候选清单，而 /api/emby/libstats 只给计数、
    submgmt 的 items 又不带 tmdbid → 这里直连 Emby /emby/Items 拉剧集清单，
    每行带 ProviderIds.Tmdb，前端拿它去 /api/missing/scan_batch 求差集。
    只读，绝不写 Emby。结果缓存 30 秒（避免反复拖慢 Emby）。
    """
    out = {"ok": False, "rows": [], "n": 0, "total": 0, "server": "", "err": ""}
    try:
        ek = cfg().get('emby_key') or EMBY_KEY_FB
        # ★ v1.24b：SortBy 必须是**单个字段名**（Emby 不接受 "DateCreated,Desc"
        #   这种逗号组合串，会让 /emby/Items 直接返回 400 → 上层拿到 None →
        #   表现成「导入媒体库剧集」一个都没有）。方向由 SortOrder 单独控制。
        #   Fields 去掉 Overview（大库上单条几百字节 × 60 条没必要，还容易超时）。
        params = {
            "IncludeItemTypes": "Series",
            "Recursive": "true",
            "Fields": "ProviderIds,ProductionYear,CommunityRating,OfficialRating",
            "SortBy": sort,
            "SortOrder": "Descending",
            "Limit": str(int(limit or 60)),
            "StartIndex": "0",
        }
        # 兜底：调用方（或老调用）传了逗号组合串时，只取第一段
        if "," in (sort or ""):
            params["SortBy"] = (sort or "").split(",")[0]
        if q:
            params["SearchTerm"] = q
        j = _emby_http("/emby/Items", params=params, t=15)
        items = (j or {}).get("Items") if isinstance(j, dict) else None
        if not isinstance(items, list):
            items = []
        out["total"] = int((j or {}).get("TotalRecordCount") or 0)
        for x in items:
            if not isinstance(x, dict):
                continue
            pid = x.get("ProviderIds") or {}
            tid = pid.get("Tmdb") or pid.get("tmdb") or pid.get("TMDB") or ""
            img = x.get("ImageTags") or {}
            pt = ""
            if isinstance(img, dict):
                pt = img.get("Primary") or img.get("Thumb") or ""
            out["rows"].append({
                "id": str(x.get("Id") or ""),
                "name": str(x.get("Name") or ""),
                "year": str(x.get("ProductionYear") or ""),
                "tmdbid": str(tid or ""),
                "vote": x.get("CommunityRating"),
                "rating": str(x.get("OfficialRating") or ""),
                "poster": ("/emby/Items/%s/Images/Primary?tag=%s&api_key=%s"
                           % (x.get("Id"), pt, ek)) if pt else "",
                "overview": str(x.get("Overview") or "")[:200],
            })
        try:
            si = _emby_http("/emby/System/Info", t=6)
            if isinstance(si, dict):
                out["server"] = str(si.get("ServerName") or "")
        except Exception:
            pass
        out["ok"] = True
        out["n"] = len(out["rows"])
    except Exception as e:
        out["err"] = str(e)[:120]
    return out


# ═══════════════════════════════════════════════════════════════════════════
# ★★ v1.25 「后台实时任务」聚合（用户原话，2026-10-22）：
#   「仪表盘这边呢，再加一个后台实时任务，然后把我在后台运行的所有任务都给加上去。
#     就比如说什么，EMBY 里面我打开了计划任务里面的某一项啊，或者是我后台订阅什么的，
#     反正总之把所有正在执行的任务都给加上去」。
# 设计：只读聚合，零写操作；每路各自 try + 独立超时；整体 8 秒缓存
#   （前端 15s 轮询，绝不打满后端）。任务分四类：
#     mt      MT 整理任务（本地 SQLite running 行）
#     emby    Emby 计划任务（State == Running 的那些）
#     sub     订阅与求片（submgmt 里扫描中的条目）
#     qb      qBittorrent 正在下载/做种的活动任务
# 每条带：来源 / 名称 / 状态 / 进度 / 已运行时长 / 详情文案。
# ═══════════════════════════════════════════════════════════════════════════
def jobs_raw():
    out = {'ok': True, 'ts': time.strftime('%F %T'), 'jobs': [],
           'counts': {'running': 0, 'queued': 0, 'total': 0}, 'err': ''}

    def add(src, name, state, detail, pct=None, elapsed='', kind='', act=''):
        out['jobs'].append({'src': src, 'name': name, 'state': state,
                            'detail': detail, 'pct': pct, 'elapsed': elapsed,
                            'kind': kind, 'act': act})

    # ① MT 整理任务（本地 SQLite，毫秒级）
    try:
        with db() as c:
            run = c.execute(
                "SELECT id,source_dir,total_files,done_files,error_files,skipped_files,"
                "trigger_kind,started_at,status FROM organize_tasks "
                "WHERE status IN ('running','pending') ORDER BY id DESC LIMIT 8").fetchall()
            pend = c.execute(
                "SELECT count(*) FROM organize_tasks WHERE status='pending'").fetchone()[0]
        for r in run:
            tot = r['total_files'] or 0
            dn = r['done_files'] or 0
            pct = round(dn * 100.0 / tot, 1) if tot else 0
            st = 'running' if r['status'] == 'running' else 'queued'
            add('mt', 'MT 整理 #%s' % r['id'], st,
                '%s · %s/%s 个 · 失败 %s · 跳过 %s' % (
                    r['trigger_kind'] or '手动', dn, tot,
                    r['error_files'] or 0, r['skipped_files'] or 0),
                pct=pct if st == 'running' else None,
                elapsed=(r['started_at'] or '')[11:19], kind=r['trigger_kind'] or '')
        out['counts']['queued'] += int(pend or 0)
    except Exception as e:
        out['err'] += 'mt:%s;' % str(e)[:80]

    # ② Emby 计划任务（State == Running / Waiting 的）
    try:
        sv = emby_servers()
        for s in (sv.get('servers') or [])[:2]:
            if not s.get('ok'):
                continue
            addr, port = s.get('host'), s.get('port')
            if not addr:
                continue
            _ek = (cfg().get('emby_key') or EMBY_KEY_FB)
            _H = emby_headers(_ek)
            st, b = hget(addr, port, '/ScheduledTasks', _H, 10)
            if st != 200 or not isinstance(b, list):
                continue
            for t in b:
                state = str(t.get('State') or '')
                if state not in ('Running', 'Waiting'):
                    continue
                nm = t.get('Name') or t.get('Key') or ''
                add('emby', _emby_task_cn(t.get('Key') or nm) or nm, 'running',
                    '%s · %s' % (s.get('name') or addr, (t.get('Description') or '')[:70]),
                    kind='计划任务', act=t.get('Key') or t.get('Id') or '')
    except Exception as e:
        out['err'] += 'emby:%s;' % str(e)[:80]

    # ③ 订阅与求片（扫描中的条目）
    try:
        sm = submgmt_list()
        for it in (sm.get('items') or []):
            stt = str(it.get('status') or '')
            if stt in ('scanning', 'searching', 'downloading', 'queued'):
                add('sub', (it.get('title') or it.get('name') or '未命名'), 'running',
                    '%s · %s' % (it.get('kind') or '', it.get('msg') or it.get('note') or ''),
                    kind=stt)
    except Exception as e:
        out['err'] += 'sub:%s;' % str(e)[:80]

    # ④ qBittorrent 活动任务（下载中 + 做种中）
    try:
        qb = qb_realtime()
        for t in ((qb.get('torrents') or []))[:8]:
            stt = str(t.get('state') or '')
            if stt in ('downloading', 'uploading', 'stalledDL', 'queuedDL', 'metaDL'):
                add('qb', (t.get('name') or '')[:60], 'running',
                    '%s · %s%%' % (stt, round(t.get('progress', 0) * 100)),
                    pct=round((t.get('progress') or 0) * 100, 1), kind=stt)
    except Exception as e:
        out['err'] += 'qb:%s;' % str(e)[:80]

    # ⑤ media-hub 自己的后台 job（ASYNC_ACTS 走 submit() 起的线程）
    #    用户原话：「我在后台运行的所有任务都给加上去」→ 除了 MT / Emby /
    #    订阅 / qB 这四路外部服务，Web UI 自己「↻ 刷新」类动作（如
    #    /api/auto/rescan、/api/create、cd2 refresh 等）也是后台任务，
    #    必须一并可见，否则用户点完按钮不知道它在不在跑。
    try:
        now = time.time()
        for jid, j in list(JOBS.items()):
            st = str(j.get('state') or '')
            act = j.get('action') or '后台动作'
            started = j.get('started') or 0
            el = int(now - started) if started else 0
            if st == 'running':
                add('hub', str(act), 'running', 'media-hub 后台线程执行中',
                    elapsed='%02d:%02d:%02d' % (el // 3600, (el % 3600) // 60, el % 60),
                    kind='hub', act=jid)
            elif st == 'done':
                r = j.get('result') or {}
                ok = bool(r.get('ok'))
                # 只回传最近 90 秒内完成的，避免刷屏
                fin = j.get('finished') or 0
                if fin and now - fin <= 90:
                    out.setdefault('recent', []).append({
                        'src': 'hub', 'name': str(act),
                        'state': 'done' if ok else 'error',
                        'detail': (r.get('msg') or '')[:120],
                        'at': time.strftime('%H:%M:%S', time.localtime(fin))})
    except Exception as e:
        out['err'] += 'hub:%s;' % str(e)[:80]

    out['counts']['running'] = sum(1 for j in out['jobs'] if j['state'] == 'running')
    out['counts']['total'] = len(out['jobs'])
    # 最近完成（前端「刚刚完成」区）
    rc = out.get('recent') or []
    out['counts']['recent'] = len(rc)
    return out


def emby_sessions():
    """Emby 当前观看会话（仪表盘用）——用户 2026-10-15 要求：
    谁在看/看什么/进度/画质/设备，全部详细展示。"""
    out = {"ok": False, "sessions": [], "err": ""}
    try:
        j = _emby_http("/emby/Sessions", t=12)
        if j is None:
            out["err"] = "Emby 不可达"
            return out
        rows = []
        for x in (j if isinstance(j, list) else []):
            if not isinstance(x, dict):
                continue
            now = x.get("NowPlayingItem") or {}
            if not now:
                continue                      # 没有播放项的会话跳过
            pi = x.get("PlayState") or {}
            item = now.get("Type") or ""
            # ★ 画质：strm 库 MediaSources 为空，必须从 **item 自己的 MediaStreams**
            #   取（顺序与 bot 播报完全一致：分辨率→压制/来源→动态范围→色深→
            #   编码→音频→码率），拿不到再用文件名兜底，最后用码率×时长估算体积。
            vstream, astream = {}, {}
            for m in (now.get("MediaStreams") or []):
                if not isinstance(m, dict):
                    continue
                if m.get("Type") == "Video" and not vstream:
                    vstream = m
                elif m.get("Type") == "Audio" and not astream:
                    astream = m
            q = []
            h = int(vstream.get("Height") or now.get("Height") or 0)
            w = int(vstream.get("Width") or now.get("Width") or 0)
            if h >= 2160 or w >= 3840:
                q.append("4K")
            elif h >= 1440:
                q.append("2K")
            elif h >= 1080:
                q.append("1080p")
            elif h >= 720:
                q.append("720p")
            elif h:
                q.append("%dp" % h)
            # ★★ v1.25b S5：动态范围统一英文规范（Dolby Vision P8 / HDR10 / HDR10+ / HLG / SDR）。
            #   用户原话：「杜比世界，你不要只写个杜比世界……P7、B5、P8 都要给我标清楚了」。
            vr = str(vstream.get("VideoRange") or vstream.get("VideoRangeType") or "")
            _rng = _norm_dv(vr, vstream.get("DvProfile"))
            if _rng and _rng != 'SDR':
                q.append(_rng)
            elif _rng == 'SDR':
                q.append("SDR")
            bd = int(vstream.get("BitDepth") or 0)
            if bd:
                q.append("%dbit" % bd)
            if vstream.get("Codec"):
                q.append(str(vstream["Codec"]).upper())
            _disp = str(astream.get("DisplayTitle") or "").upper()
            _ac = str(astream.get("Codec") or "").upper()
            _ch = astream.get("Channels") or 0
            if "ATMOS" in _disp:
                q.append("杜比全景声")
            elif "DTS" in _disp:
                q.append("DTS")
            elif _ac:
                q.append("%s %s" % (_ac, ("%.1f" % _ch) if _ch and _ch != 2 else "2.0"))
            _br = int(vstream.get("BitRate") or now.get("Bitrate") or 0)
            if _br:
                _mb = _norm_bitrate_mbps(_br)
                if _mb:
                    q.append(_mb)
            qual_str = " · ".join(q)
            # 文件名兜底（MediaStreams 也没字段时）
            if qual_str in ("", "SDR") and now.get("Path"):
                import re as _re
                pth = str(now.get("Path") or "")
                ex = []
                if _re.search(r"2160p|4K|3840", pth, _re.I):
                    ex.append("4K")
                if _re.search(r"\bREMUX\b", pth, _re.I):
                    ex.append("REMUX")
                elif _re.search(r"BluRay|Blu-Ray", pth, _re.I):
                    ex.append("BluRay")
                elif _re.search(r"WEB-DL|WEBDL", pth, _re.I):
                    ex.append("WEB-DL")
                elif _re.search(r"\bHDTV\b", pth, _re.I):
                    ex.append("HDTV")
                if _re.search(r"HDR10\+|HDR10Plus", pth, _re.I):
                    ex.append("HDR10+")
                elif _re.search(r"\bHDR10\b|\bHDR\b", pth, _re.I):
                    ex.append("HDR10")
                if _re.search(r"10[- ]?bit", pth, _re.I):
                    ex.append("10bit")
                if _re.search(r"H\.?265|HEVC|x265", pth, _re.I):
                    ex.append("H265")
                elif _re.search(r"H\.?264|x264|AVC", pth, _re.I):
                    ex.append("H264")
                _m2 = _re.search(r"(DDP[ .]?[57]\.[01]|EAC3[ .]?[57]\.[01]|TrueHD|Atmos|DTS)",
                                 pth, _re.I)
                if _m2:
                    ex.append(_m2.group(1).upper().replace(" ", ""))
                _mbr = _re.search(r"(\d+(?:\.\d+)?)\s*Mbps", pth, _re.I)
                if _mbr:
                    ex.append(_norm_bitrate_mbps(_mbr.group(1)))
                if ex:
                    qual_str = " · ".join(ex)
            if not qual_str:
                qual_str = "—"
            # 体积：SizeInMb → 码率×时长估算 → 未知
            # ★ 2026-10-16 用户要求：只给数字，不要「（按码率×时长估算）」这类括号注释
            msrc = (now.get("MediaSources") or [])
            sz_mb = int((msrc[0] or {}).get("SizeInMb") or 0) if msrc else 0
            if sz_mb:
                size_txt = (("%.1f GB" % (sz_mb / 1024)) if sz_mb >= 1024
                            else ("%d MB" % sz_mb))
            else:
                rt = float(now.get("RunTimeTicks") or 0) / 10_000_000.0
                if _br > 0 and rt > 0:
                    size_txt = "%.1f GB" % (_br / 8.0 * rt / 1024 ** 3)
                else:
                    size_txt = "未知"
            trans = bool(pi.get("PlayMethod") == "Transcode")
            # 播放进度（被上面的画质块替换时误删，补回）
            pos = float(pi.get("PositionTicks") or 0)
            dur = float(now.get("RunTimeTicks") or 0)
            pct = round(pos / dur * 100, 1) if dur > 0 else 0
            # 图片：剧照优先，退回海报
            ek = cfg().get('emby_key') or EMBY_KEY_FB
            # ★ 必须是完整 URL（浏览器直连 Emby 8096），不能给相对路径——
            #   media-hub 自己没有 /emby/ 反代，相对路径会 404。
            ebase = "http://%s:%s" % (containers()['emby']['addr'],
                                      containers()['emby']['port'])
            img = ""
            iid = str(now.get("Id") or "")
            sid = str(now.get("SeriesId") or now.get("ParentBackdropItemId") or "")
            # ★ 2026-10-16 用户要求「图片保留原始尺寸，不要裁切」：
            #   不传 maxWidth（Emby 默认返回**原图**，等比不裁）；
            #   前端只用 CSS width + height:auto 等比缩放，比例绝对忠实。
            # ★ v1.18 BUG-134「有的没有图」真因修复：
            #   老逻辑只试 Backdrop → Primary（Primary 还要求 ImageTags 存在）。
            #   **strm 库里大量条目既没有 Backdrop 也没有 Primary**，实测就是
            #   「两条会话一条有图一条没图」。现在改成逐级候选列表：
            #   剧集 Backdrop → 条目 Backdrop → 条目 Primary → 剧集 Primary
            #   → 条目 Thumb（Emby 总会生成 Thumb）→ 剧集 Primary 兜底。
            #   前端拿 img_list 依次 onerror 换下一张，全失败才显示占位。
            _bt = now.get("BackdropImageTags") or []
            _pt = (now.get("ImageTags") or {}).get("Primary")
            _tt = (now.get("ImageTags") or {}).get("Thumb")
            img_list = []
            # ★★ V1.44：一律走后端代理（不再把 api_key 明文下发，也不再让浏览器直连 8096）
            #   并把候选顺序改成「条目 Primary → 剧集 Primary → Backdrop → Thumb」：
            #   strm 库里 Backdrop 经常没有，先试 Primary 命中率最高。
            if _pt and iid:
                img_list.append("/embyimg/emby/%s/Primary?w=300" % iid)
            if sid and sid != iid:
                img_list.append("/embyimg/emby/%s/Primary?w=300" % sid)
            if _bt and iid:
                img_list.append("/embyimg/emby/%s/Backdrop?w=300" % iid)
            if _bt and sid and sid != iid:
                img_list.append("/embyimg/emby/%s/Backdrop?w=300" % sid)
            if _tt and iid:
                img_list.append("/embyimg/emby/%s/Thumb?w=300" % iid)
            _seen_i = set()
            img_list = [u for u in img_list if not (u in _seen_i or _seen_i.add(u))]
            img = img_list[0] if img_list else ""
            # ★ v1.18 BUG-134「两个人看会上下乱跳」真因修复（后端第一道保险）：
            #   Emby /Sessions 的返回顺序**不稳定**（内部按最后心跳排序，
            #   而心跳每秒都在变）→ 前端每次整块重建就换位 → 卡片上下跳。
            #   这里给每条会话打一个**会话级固定**的排序键 first_ts
            #   （首次见到该会话的时间；同 id 心跳只更新 last）。
            #   前端按它升序排：**先看的永远在下面，后看的永远在上面**，
            #   刷新一万次也不会跳位。
            _sid = str(x.get("Id") or "")
            _nowt = time.time()
            with _SESS_ORDER_LOCK:
                _rec = _SESS_ORDER.get(_sid)
                if not _rec:
                    _SESS_ORDER[_sid] = {'first': _nowt, 'last': _nowt}
                    _rec = _SESS_ORDER[_sid]
                else:
                    _rec['last'] = _nowt
                if len(_SESS_ORDER) > 400:
                    for _k in [k for k, v in _SESS_ORDER.items()
                               if _nowt - v['first'] > 21600]:
                        _SESS_ORDER.pop(_k, None)
                first_ts = _rec['first']
            _tgm = tg_name_map().get(str(x.get("UserName") or "")) or {}
            rows.append({
                # ★ v1.18：会话唯一键（前端 DOM id / 排序锚点都靠它）
                "session_id": _sid,
                "first_ts": int(first_ts),
                "user": x.get("UserName") or "未知",
                "tg": _tgm.get("tg") or 0,
                "tg_username": _tgm.get("username") or "",
                "tg_url": _tgm.get("url") or "",
                "item_name": now.get("SeriesName") or now.get("Name") or "",
                "ep": (("S%02dE%02d" % (now.get("ParentIndexNumber") or 0,
                                        now.get("IndexNumber") or 0))
                       if (now.get("ParentIndexNumber") and now.get("IndexNumber")) else ""),
                "type": {"Episode": "剧集", "Movie": "电影"}.get(item, item),
                "pct": pct,
                "pos_min": round(pos / 6e8, 1),
                "dur_min": round(dur / 6e8, 1),
                # ★ v1.16 BUG-133：秒级播放进度（精确到秒）+ 剩余秒数，
                #   供前端渲染「00:12:34 / 00:47:00 · 剩 00:34:26」。
                "pos_sec": int(round(pos / 1e7)),
                "dur_sec": int(round(dur / 1e7)),
                "left_sec": int(round(max(0.0, dur - pos) / 1e7)),
                "quality": qual_str or "—",
                "size": size_txt,
                "img": (img_list[0] if img_list else ''),
                # ★ v1.18：多级候选图（前端逐个回退，解决「有的没有图」）
                "img_list": img_list,
                # ★★ V1.44：TMDB id（前端图全裂时可以按 id 重新找图）
                "tmdb": str((now.get("ProviderIds") or {}).get("Tmdb") or ""),
                "ip": x.get("RemoteEndPoint") or "",
                "transcode": trans,
                "client": x.get("Client") or "",
                # ★ 2026-10-16 用户要求：Emby 在线播放补播放器版本号。
                #   ClientVersion=播放器自身版本（如 Infuse 8.1.4），
                #   ApplicationVersion=Emby 客户端完整版本串，两者互补取用。
                "client_ver": (x.get("ClientVersion")
                               or x.get("ApplicationVersion") or ""),
                "app_ver": x.get("ApplicationVersion") or "",
                "device": x.get("DeviceName") or "",
                "playing": bool(pi.get("IsPaused") is False and pos > 0),
                "paused": bool(pi.get("IsPaused")),
            })
        out.update(ok=True, sessions=rows, n=len(rows),
                   playing=sum(1 for r in rows if r["playing"] and not r["paused"]))
    except Exception as e:
        out["err"] = str(e)[:100]
    return out


# ══════════════════ Emby 双实例 / 播放数据 / 排名（v1.21） ══════════════════
# ★ v1.21 用户原话：「首先我的服务器名字不叫橘映。还有就是我服务器名字，你就根据我的
#   EMBY上面设置的名字来就行。比如说叫KFC还有一个KFC2也加上去，然后他们的具体数量都给我
#   精确到具体数字，比如说426454等等，反正你要精确到具体数字」
# 实测（2026-10-22 核实）：
#   KFC  = emby-main   8096  ServerName=KFC   v4.10.1.0  api_key  = cfg()['emby_key']
#   KFC2 = emby-adult  8896  ServerName=KFC2  v4.8.11.0  api_key  = cfg()['emby_key2']
# 名字一律以 Emby 自己的 /emby/System/Info 的 ServerName 为准，**不写死、不猜**；
# 拿不到 ServerName 时回落 CONTAINERS 注册表里的 name。
def emby_instances():
    """生效的双 Emby 实例清单（v1.37：端口随配置走，不再写死）。

    返回 [(key, short, port, dbname), ...]；端口为 '' 表示不读播放库。
    """
    _c = containers()
    return [('emby', 'main', str(_c['emby']['port']), 'playback_reporting.db'),
            ('emby_adult', 'adult', str(_c['emby_adult']['port']), None)]


EMBY_INSTANCES = emby_instances()
# playback_reporting.db 容器内路径（media-hub 已挂载 /vol1/1000/docker => /dockroot）
# ★★ v1.37 S1：playback_reporting.db 容器内路径也配置化（各人挂载点/容器名不同）。
#   <inst>_pr_db_path；留空则自动按 cname 猜（<dockroot>/<cname>/config/data/...）。
PR_DB_DEF = {
    'main':  '/dockroot/emby-main/config/data/playback_reporting.db',
    'adult': '/dockroot/emby-adult/config/data/playback_reporting.db',
}


def pr_db_paths():
    """生效的 playback_reporting.db 路径表。"""
    c = cfg()
    out = {}
    for k, v in PR_DB_DEF.items():
        p = (c.get(k + '_pr_db_path') or '').strip()
        out[k] = p or v
    return out
EMBY_RO_CACHE = {}


def _emby_inst_key(which):
    """按实例取 api_key：主用 emby_key，副用 emby_key2，都空则回落内置 key。"""
    c = cfg()
    if which == 'emby':
        return c.get('emby_key') or EMBY_KEY_FB
    return c.get('emby_key2') or ''


def _emby_inst_http(which, path, params=None, t=10):
    """按实例打 Emby 官方只读接口；失败返回 None（绝不让一个实例带崩整页）。"""
    conf = containers().get(which)
    if not conf:
        return None
    k = _emby_inst_key(which)
    if not k:
        return None
    q = dict(params or {})
    q['api_key'] = k
    full = path + '?' + urllib.parse.urlencode(q)
    st, b = hreq(conf['addr'], conf['port'], 'GET', full, None, None, t)
    if st != 200:
        return None
    try:
        return json.loads(b)
    except Exception:
        return None


def _emby_inst_stats(which, short):
    """单实例：ServerName + 精确库统计 + 用户数 + 播放中数。全部精确到个位。"""
    conf = containers()[which]
    o = {'key': which, 'short': short, 'name': conf['name'],
         'cname': conf['cname'], 'port': conf['port'],
         'server': '', 'version': '', 'ok': False,
         'movie': 0, 'series': 0, 'episode': 0, 'user_n': 0, 'playing': 0,
         'err': ''}
    try:
        si = _emby_inst_http(which, '/emby/System/Info', t=6)
        if isinstance(si, dict):
            # ★ 名字只认 Emby 自己设置的 ServerName（用户明确要求）
            o['server'] = str(si.get('ServerName') or '')
            o['version'] = str(si.get('Version') or '')
        if o['server']:
            o['name'] = o['server']          # UI 一律显示 Emby 真名
        cj = _emby_inst_http(which, '/emby/Items/Counts', t=8)
        if isinstance(cj, dict):
            o['movie'] = int(cj.get('MovieCount') or 0)
            o['series'] = int(cj.get('SeriesCount') or 0)
            o['episode'] = int(cj.get('EpisodeCount') or 0)
            o['user_n'] = int(cj.get('UserCount') or 0)
        if not o['user_n']:
            uj = _emby_inst_http(which, '/emby/Users', {'Recursive': 'false'}, t=8)
            _u = uj if isinstance(uj, list) else (uj or {}).get('Items') or []
            o['user_n'] = len([x for x in _u if isinstance(x, dict)])
        # 播放中：NowPlayingItem 存在且未暂停且位置>0
        sj = _emby_inst_http(which, '/emby/Sessions', t=8)
        rows = sj if isinstance(sj, list) else (sj or {}).get('Items') or []
        for x in rows:
            if not isinstance(x, dict) or not x.get('NowPlayingItem'):
                continue
            pi = x.get('PlayState') or {}
            if pi.get('IsPaused') is False and int(pi.get('PositionTicks') or 0) > 0:
                o['playing'] += 1
        o['ok'] = True
    except Exception as e:
        o['err'] = str(e)[:100]
    return o


def emby_servers(force=False):
    """★ v1.21 双 Emby 实例总览（KFC + KFC2），名字与数字全部取真实值。

    缓存 12 秒：前端 2s 轮询，两个实例 × 4 个接口不能每 tick 全打一遍。
    """
    ck = 'emby_servers'
    now = time.time()
    if (not force) and ck in EMBY_RO_CACHE and now - EMBY_RO_CACHE[ck][0] < 12:
        return EMBY_RO_CACHE[ck][1]
    from concurrent.futures import ThreadPoolExecutor
    out = {'ok': True, 'servers': [], 'total': {'movie': 0, 'series': 0,
                                                'episode': 0, 'user_n': 0, 'playing': 0},
           'err': ''}
    try:
        with ThreadPoolExecutor(max_workers=2) as ex:
            res = list(ex.map(lambda t: _emby_inst_stats(t[0], t[1]), EMBY_INSTANCES))
        out['servers'] = res
        for r in res:
            for f in ('movie', 'series', 'episode', 'user_n', 'playing'):
                out['total'][f] += int(r.get(f) or 0)
        if not any(r['ok'] for r in res):
            out['ok'] = False
            out['err'] = '两个 Emby 均不可达'
    except Exception as e:
        out['ok'] = False
        out['err'] = str(e)[:120]
    EMBY_RO_CACHE[ck] = (now, out)
    return out


def _pr_db(short):
    """playback_reporting.db 只读连接；文件不存在 / 被锁都返回 None（不崩）。"""
    path = pr_db_paths().get(short)
    if not path or not os.path.exists(path):
        return None
    try:
        return sqlite3.connect('file:%s?mode=ro' % path, uri=True, timeout=6)
    except Exception:
        return None


# ═══════════════════════════════════════════════════════════════════════════
# ★★ V1.45 A3 · Emby 官方「活动日志」播放记录兜底（activitylog.db）
#   用户原话：「我发现我KFC2进行观看的时候，它是没有播放记录的」
#   实机：emby-adult/config/data 只有 activitylog.db，**没有 playback_reporting.db**
#         （emby-main 两个都有）→ 老逻辑 `_pr_db()` 返回 None 就直接空榜。
#   方案：读 Emby 自己写的 ActivityLog（只读、绝不写），按「开始播放/停止播放」
#         事件对配对出播放时长，字段口径与 playback_reporting 对齐，
#         让 rank / plays / 日志中心在 KFC2 上一样有真实数据。
#   ⚠ 版本差异（全部实测，两套都兼容）：
#       emby-main  ：Type 列不存在，走 TypeId JOIN ActivityLogTypes
#                    （名字是 playback.start / playback.stop）
#       emby-adult ：有 Type 文本列（VideoPlayback / VideoPlaybackStopped）
#                    且 InternalItemId 为空 → 只能用「用户+片名+时间序」配对
#   ⚠ 日志文案有两套语序（实测都有）：
#       "HanYQAQ 在 Android 上开始播放 尚公主 - S1, Ep4 - xxx"
#       "iPhone 上 haoyu2006 已停止播放 琅琊榜 - S1, Ep20 - xxx"
#   铁律：只读 sqlite、带 busy timeout、任何异常都返回空结构，绝不带崩接口。
# ═══════════════════════════════════════════════════════════════════════════
ACTIVITY_DB_DEF = {
    'main':  '/dockroot/emby-main/config/data/activitylog.db',
    'adult': '/dockroot/emby-adult/config/data/activitylog.db',
}
_ACT_TTL = 25.0
_ACT_CACHE = {}


def activity_db_paths():
    """生效的 activitylog.db 路径（<inst>_activity_db_path 可覆盖，与 pr_db 同规则）。"""
    c = cfg()
    out = {}
    for k, v in ACTIVITY_DB_DEF.items():
        p = (c.get(k + '_activity_db_path') or '').strip()
        out[k] = p or v
    return out


def _act_db(short):
    """activitylog.db 只读连接；无文件 / 被锁 → None（不抛）。"""
    path = activity_db_paths().get(short)
    if not path or not os.path.exists(path):
        return None
    try:
        con = sqlite3.connect('file:%s?mode=ro' % path, uri=True, timeout=4)
        con.execute('SELECT 1 FROM ActivityLog LIMIT 1')
        return con
    except Exception:
        return None


def _act_schema(con):
    """探测该 Emby 版本的 ActivityLog 结构：有无 Type 文本列 / 有无 TypeId+字典表。"""
    try:
        cols = {str(r[1]) for r in con.execute('PRAGMA table_info(ActivityLog)')}
    except Exception:
        cols = set()
    has_type = 'Type' in cols
    has_typeid = 'TypeId' in cols
    has_types_tbl = False
    if has_typeid:
        try:
            con.execute('SELECT Name FROM ActivityLogTypes LIMIT 1')
            has_types_tbl = True
        except Exception:
            has_types_tbl = False
    return has_type, has_typeid and has_types_tbl


def _act_kind(txt):
    """事件文案 → 'start' / 'stop' / None（两套 Emby 命名都吃）。"""
    t = str(txt or '')
    low = t.lower()
    if 'stopped' in low or 'playback.stop' in low or '停止播放' in t:
        return 'stop'
    if low == 'videoplayback' or 'playback.start' in low or '开始播放' in t:
        return 'start'
    return None


# Emby 官方活动日志文案只有两种语序（本机两套版本实测各有）：
#   A 型「<用户> 在 <设备> 开始播放  <条目>」
#       例：HanYQAQ 在 Android 上开始播放 尚公主 - S1, Ep4 - 一个故事换一个吻？暮晚摇言尚亲了！
#   B 型「<设备> 上 <用户> 已停止播放  <条目>」
#       例：iPhone 上 haoyu2006 已停止播放 琅琊榜 - S1, Ep20 - 琅琊榜.2015.S01E20....fps
# ★ V1.45 A3b：改「动词锚定」解析 —— 先找动词（开始播放/已停止播放/停止播放），
#   再按动词前面的「在」还是「上」判定谁是用、谁是设备。
#   老实现是两条贪婪正则 + 一段死代码，会把设备名连同尾字「上」一起吃掉。
_ACT_VERBS = ('已停止播放', '开始播放', '停止播放')


def _act_parse(name):
    """活动日志标题 → (user, device, item)；解析不出给 ('', '', 原文)，调用侧自行回落。"""
    raw = str(name or '').strip()
    vi, vl = -1, ''
    for v in _ACT_VERBS:
        k = raw.find(v)
        if k > 0 and (vi < 0 or k < vi):
            vi, vl = k, v
    if vi < 0:
        return '', '', raw
    head = raw[:vi].strip()
    item = raw[vi + len(vl):].strip()
    if not item:
        return '', '', raw
    # A 型：用户 在 设备（动词紧跟设备，尾字是「上」要剥掉）
    if ' 在 ' in head or head.count('在') >= 1:
        m = re.split(r'\s*在\s+', head, maxsplit=1)
        if len(m) == 2 and m[0].strip() and m[1].strip():
            dev = re.sub(r'\s*上\s*$', '', m[1].strip())
            return m[0].strip(), dev, item
    # B 型：设备 上 用户
    m = re.split(r'\s*上\s+', head, maxsplit=1)
    if len(m) == 2 and m[0].strip() and m[1].strip():
        return m[1].strip(), m[0].strip(), item
    # 兜底：整段当用户，条目已拿到
    return head, '', item


def _act_users(which):
    """Emby 用户：显示名列表 + UserId→Name（带 5 分钟缓存）。"""
    ck = 'act_users_%s' % which
    hit = _ACT_CACHE.get(ck)
    if hit and time.time() - hit[0] < 300:
        return hit[1]
    names = []
    try:
        uj = _emby_inst_http(which, '/emby/Users', {'Recursive': 'false'}, t=8)
        rows = uj if isinstance(uj, list) else (uj or {}).get('Items') or []
        for x in rows:
            if isinstance(x, dict) and x.get('Name'):
                names.append(str(x['Name']))
    except Exception:
        pass
    _ACT_CACHE[ck] = (time.time(), names)
    return names


def _act_user_avatars(which):
    """★ V1.45 B8：显示名 → 头像代理地址（活动日志只有名字，没有 UserId/GUID）。

    用户原话：「播放排名那个，我希望每个人都有头像」。KFC2 走 activitylog 兜底时
    拿到的是**用户名**而不是 Emby UserId，所以这里按名字回查 /emby/Users 的
    PrimaryImageTag，再拼成和主实例同一条 /embyimg 代理路径（key 不落前端）。
    没有头像的给空串，前端回落首字母色块，绝不显示破图。
    """
    ck = 'act_avatars_%s' % which
    hit = _ACT_CACHE.get(ck)
    if hit and time.time() - hit[0] < 300:
        return hit[1]
    out = {}
    try:
        uj = _emby_inst_http(which, '/emby/Users', {'Recursive': 'false'}, t=8)
        rows = uj if isinstance(uj, list) else (uj or {}).get('Items') or []
        for x in rows:
            if not isinstance(x, dict):
                continue
            nm = str(x.get('Name') or '')
            uid = str(x.get('Id') or '')
            if not nm or not uid:
                continue
            if x.get('PrimaryImageTag'):
                out[nm.lower()] = '/embyimg/%s/users/%s/Primary?w=96' % (
                    which, urllib.parse.quote(uid))
    except Exception:
        pass
    _ACT_CACHE[ck] = (time.time(), out)
    return out


def _act_items(which):
    """条目名 → Item 元信息（用于 rank/plays 补 TMDB/海报）。缓存 30 分钟，最多 400 条。"""
    ck = 'act_items_%s' % which
    hit = _ACT_CACHE.get(ck)
    if hit and time.time() - hit[0] < 1800:
        return hit[1]
    out = {}
    try:
        jj = _emby_inst_http(which, '/emby/Items',
                             {'Recursive': 'true', 'Limit': 400,
                              'Fields': 'ProviderIds,ImageTags,Year,Container,MediaSources,Path,RunTimeTicks'},
                             t=12)
        rows = (jj or {}).get('Items') or []
        for x in rows:
            if not isinstance(x, dict):
                continue
            nm = str(x.get('Name') or '')
            if not nm:
                continue
            iid = str(x.get('Id') or '')
            out.setdefault(nm, {
                'id': iid,
                'type': str(x.get('Type') or ''),
                'year': x.get('ProductionYear') or '',
                'tmdb': str(((x.get('ProviderIds') or {}) if isinstance(x.get('ProviderIds'), dict) else {}).get('Tmdb') or ''),
                'img_tag': bool((x.get('ImageTags') or {}) if isinstance(x.get('ImageTags'), dict) else {}),
                'series': str(x.get('SeriesName') or ''),
            })
    except Exception:
        pass
    _ACT_CACHE[ck] = (time.time(), out)
    return out


def _act_events(short, since_ms=0, limit=6000):
    """读播放事件并配对成记录。

    返回 {'rows': [...], 'ok': True, 'src': 'activitylog', 'err': ''}
    row 字段与 emby_plays 对齐：ts/user/item/type/device/client/play_sec/n/method/server
    配对规则：同一 (user, item) 按时间序 start→stop 计时长；
              单次超过 12h 视为忘记上报（直接截断，不虚增榜）。
    """
    out = {'ok': False, 'rows': [], 'src': 'activitylog', 'err': ''}
    con = _act_db(short)
    if con is None:
        out['err'] = '该实例既无播放报表库，也无活动日志库'
        return out
    try:
        con.row_factory = sqlite3.Row
        has_type, has_typeid = _act_schema(con)
        if has_type:
            sel = ("SELECT Id, Name, Type AS TName, InternalItemId, InternalUserId, "
                   "DateCreatedMs, LogSeverity FROM ActivityLog ORDER BY Id DESC LIMIT ?")
        elif has_typeid:
            sel = ("SELECT a.Id, a.Name, t.Name AS TName, a.InternalItemId, a.InternalUserId, "
                   "a.DateCreatedMs, a.LogSeverity FROM ActivityLog a "
                   "LEFT JOIN ActivityLogTypes t ON t.TypeId = a.TypeId "
                   "ORDER BY a.Id DESC LIMIT ?")
        else:
            out['err'] = '活动日志表结构无法识别'
            return out
        raw = []
        for r in con.execute(sel, [int(limit)]):
            ms = int(r['DateCreatedMs'] or 0)
            if since_ms and ms < since_ms:
                continue
            kind = _act_kind(r['TName'])
            if not kind:
                continue
            raw.append((int(r['Id'] or 0), kind, str(r['Name'] or ''), ms,
                        str(r['InternalItemId'] or ''), int(r['InternalUserId'] or 0)))
        raw.sort(key=lambda x: x[0])       # 按事件顺序配对
        # 配对：open[(user,item)] = (start_ms, start_id)
        open_ev, rows = {}, []
        for eid, kind, name, ms, iid, cuid in raw:
            u, dev, item = _act_parse(name)
            u = u or ('uid:%d' % cuid if cuid else '')
            key = (u, item)
            if kind == 'start':
                open_ev[key] = (ms, eid, dev, iid)
            else:
                st = open_ev.pop(key, None)
                if st:
                    dur = (ms - st[0]) / 1000.0
                    if dur < 0:
                        dur = 0
                    if dur > 12 * 3600:          # 忘记上报 → 截断，别把榜灌水
                        dur = 12 * 3600
                    rows.append({'ts': time.strftime('%Y-%m-%d %H:%M:%S', time.localtime(ms / 1000.0)),
                                 'ts_ms': ms, 'user': u, 'item': item,
                                 'device': dev or st[2] or '', 'client': dev or st[2] or '',
                                 'play_sec': int(round(dur)), 'n': 1,
                                 'item_id': iid or st[3] or '', 'uid_int': cuid,
                                 'method': '', 'type': '', 'server': ''})
                else:
                    # 只有 stop（开始事件被 limit 截掉）→ 记一条 0 时长，仍进明细
                    rows.append({'ts': time.strftime('%Y-%m-%d %H:%M:%S', time.localtime(ms / 1000.0)),
                                 'ts_ms': ms, 'user': u, 'item': item,
                                 'device': dev or '', 'client': dev or '',
                                 'play_sec': 0, 'n': 1,
                                 'item_id': iid or '', 'uid_int': cuid,
                                 'method': '', 'type': '', 'server': ''})
        # 仍在播（只有 start 没有 stop）：补一条 0 秒的进行中记录，明细可见
        for (u, item), (ms, eid, dev, iid) in open_ev.items():
            rows.append({'ts': time.strftime('%Y-%m-%d %H:%M:%S', time.localtime(ms / 1000.0)),
                         'ts_ms': ms, 'user': u, 'item': item,
                         'device': dev or '', 'client': dev or '',
                         'play_sec': 0, 'n': 1, 'item_id': iid or '', 'uid_int': 0,
                         'method': '', 'type': '', 'server': ''})
        rows.sort(key=lambda x: -x['ts_ms'])
        out['rows'] = rows
        out['ok'] = True
    except Exception as e:
        out['err'] = str(e)[:140]
    finally:
        try:
            con.close()
        except Exception:
            pass
    return out


def _act_since(days=1):
    """CST 自然日窗口起点（毫秒），与 _day_start 同口径。"""
    try:
        base = datetime.datetime.utcnow() + datetime.timedelta(hours=8)
    except Exception:
        base = datetime.datetime.now()
    d = (base - datetime.timedelta(days=max(0, int(days or 0)))).strftime('%Y-%m-%d 00:00:00')
    try:
        dt = datetime.datetime.strptime(d, '%Y-%m-%d %H:%M:%S') - datetime.timedelta(hours=8)
        return int((dt - datetime.datetime(1970, 1, 1)).total_seconds() * 1000)
    except Exception:
        return 0


def emby_rank_activity(kind='user_today', days=1, which='emby_adult', short='adult'):
    """KFC2 榜单：活动日志聚合（与 emby_rank 同 kind 语义、同 row 字段）。"""
    out = {'ok': False, 'kind': kind, 'days': days, 'rows': [], 'err': '',
           'window': '', 'total_sec': 0, 'src': 'activitylog'}
    try:
        days = max(1, min(3650, int(days or 1)))
        need_days = kind not in ('user_today', 'item_today', 'item_plays')
        since = _act_since(days if need_days else 0)
        ev = _act_events(short, since_ms=since)
        out['err'] = ev.get('err') or ''
        if not ev.get('ok'):
            return out
        rows = ev['rows']
        agg = {}
        if kind in ('user_today', 'user_days'):
            for r in rows:
                k = r['user'] or '(未知用户)'
                a = agg.setdefault(k, {'sec': 0, 'n': 0})
                a['sec'] += r['play_sec']; a['n'] += r['n']
            ordered = sorted(agg.items(), key=lambda x: -x[1]['sec'])[:100]
            names = _act_users(which)
            low = {n.lower(): n for n in names}
            avatars = _act_user_avatars(which)
            for i, (k, v) in enumerate(ordered, 1):
                nm = low.get(k.lower(), k)
                out['rows'].append({'rank': i, 'name': nm, 'id': '',
                                    'sec': int(v['sec']), 'n': int(v['n']),
                                    'pause_sec': 0,
                                    'avatar': avatars.get(str(nm).lower(), ''),
                                    'client': ''})
        elif kind == 'device':
            for r in rows:
                k = r['device'] or r['client'] or '(未知设备)'
                a = agg.setdefault(k, {'sec': 0, 'n': 0})
                a['sec'] += r['play_sec']; a['n'] += r['n']
            ordered = sorted(agg.items(), key=lambda x: -x[1]['sec'])[:100]
            for i, (k, v) in enumerate(ordered, 1):
                out['rows'].append({'rank': i, 'name': k, 'sec': int(v['sec']),
                                    'n': int(v['n']), 'client': k})
        else:
            # item_* ：按片名聚合；kind=item_plays 按次数排
            imap = _act_items(which)
            for r in rows:
                k = r['item'] or '(未知条目)'
                a = agg.setdefault(k, {'sec': 0, 'n': 0, 'id': r.get('item_id') or '',
                                       'dev': r.get('device') or ''})
                a['sec'] += r['play_sec']; a['n'] += r['n']
            key = (lambda x: -x[1]['n']) if kind == 'item_plays' else (lambda x: -x[1]['sec'])
            ordered = sorted(agg.items(), key=key)[:100]
            for i, (k, v) in enumerate(ordered, 1):
                meta = imap.get(k) or {}
                tt = str(meta.get('type') or '')
                img = ''
                if meta.get('id'):
                    img = '/embyimg/%s/%s/Primary?w=200' % (which, meta['id'])
                out['rows'].append({'rank': i, 'name': k, 'id': meta.get('id') or v['id'],
                                    'sec': int(v['sec']), 'n': int(v['n']),
                                    'type': tt, 'client': v['dev'], 'media': '',
                                    'tmdb': meta.get('tmdb') or '',
                                    'year': meta.get('year') or '',
                                    'series': meta.get('series') or '',
                                    'img': img})
        out['rows'].sort(key=lambda x: -int(x.get('sec') or 0))
        for i, r in enumerate(out['rows'], 1):
            r['rank'] = i
        out['total_sec'] = sum(int(r.get('sec') or 0) for r in out['rows'])
        out['window'] = time.strftime('%Y-%m-%d %H:%M:%S', time.localtime(since / 1000.0)) if since else ''
        out['ok'] = True
    except Exception as e:
        out['err'] = str(e)[:140]
    return out


def emby_plays_activity(days=30, which='emby_adult', short='adult', user='', q=''):
    """KFC2 播放明细：活动日志（字段与 emby_plays 对齐，缺的画质留空但绝不破版）。"""
    out = {'ok': False, 'rows': [], 'total': 0, 'users': [], 'days': days,
           'err': '', 'src': 'activitylog'}
    try:
        days = max(1, min(3650, int(days or 30)))
        ev = _act_events(short, since_ms=_act_since(days))
        out['err'] = ev.get('err') or ''
        if not ev.get('ok'):
            return out
        rows = ev['rows']
        names = _act_users(which)
        low = {n.lower(): n for n in names}
        imap = _act_items(which)
        fin = []
        cnt = {}
        for r in rows:
            un = low.get((r['user'] or '').lower(), r['user'] or '')
            if user and un != user:
                continue
            if q and q.lower() not in (r['item'] or '').lower():
                continue
            cnt[un] = cnt.get(un, 0) + 1
            meta = imap.get(r['item']) or {}
            tt = str(meta.get('type') or ('Episode' if re.search(r'S\d{1,2}[, ]Ep|S\d{1,2}E\d', r['item'] or '') else 'Movie'))
            img = ('/embyimg/%s/%s/Primary?w=160' % (which, meta['id'])) if meta.get('id') else ''
            fin.append({'ts': r['ts'], 'user': un, 'user_id': str(r.get('uid_int') or ''),
                        'item_id': r.get('item_id') or meta.get('id') or '',
                        'item': r['item'], 'type': tt,
                        'method': '活动日志', 'client': r.get('client') or '',
                        'device': r.get('device') or '',
                        'play_sec': int(r.get('play_sec') or 0), 'pause_sec': 0,
                        'ip': '', 'transcode': '',
                        'tmdb': meta.get('tmdb') or '', 'imdb': '',
                        'year': meta.get('year') or '', 'series': meta.get('series') or '',
                        'season': None, 'episode': None, 'overview': '',
                        'quality': '', 'size': '', 'path': '', 'img': img,
                        'server': which,
                        'server_name': (containers().get(which) or {}).get('name', '')})
        out['rows'] = fin
        out['total'] = len(fin)
        out['users'] = [{'id': '', 'name': k, 'n': v} for k, v in
                        sorted(cnt.items(), key=lambda x: -x[1])]
        out['ok'] = True
    except Exception as e:
        out['err'] = str(e)[:140]
    return out


def _emby_user_map(which):
    """UserId → 显示名（优先 /emby/Users 的 Name；取不到返回空 dict）。"""
    uj = _emby_inst_http(which, '/emby/Users', {'Recursive': 'false'}, t=8)
    rows = uj if isinstance(uj, list) else (uj or {}).get('Items') or []
    return {str(x.get('Id')): str(x.get('Name') or '') for x in rows if isinstance(x, dict)}


def _emby_item_meta(which, item_id):
    """按 ItemId 补 TMDB / 年份 / 简介 / 图片 tag（Emby 官方只读接口）。"""
    if not item_id:
        return {}
    # ★ v1.21：必须用 /emby/Items?Ids=xxx。直连 /emby/Items/{id} 会 404
    #   「找不到文件」（实测 4.10.1.0 / 4.8.11.0 均如此），TMDB/图片/画质全丢。
    j = _emby_inst_http(which, '/emby/Items',
                        {'Ids': item_id,
                         'Fields': 'ProviderIds,ProductionYear,Overview,ParentId,'
                                   'SeriesName,ParentIndexNumber,IndexNumber,'
                                   'RunTimeTicks,MediaStreams,MediaSources,Path,'
                                   'Container,ImageTags,BackdropImageTags,'
                                   'SeriesPrimaryImageTag'}, t=8)
    items = (j.get('Items') if isinstance(j, dict) else None) or []
    it = items[0] if items and isinstance(items[0], dict) else None
    if not it:
        return {}
    pv = it.get('ProviderIds') or {}
    img = it.get('ImageTags') or {}
    back = it.get('BackdropImageTags') or []
    # 剧集优先用剧集封面（SeriesPrimaryImageTag），电影用 Primary
    prim = (it.get('SeriesPrimaryImageTag')
            or (img.get('Primary') if isinstance(img, dict) else '')
            or '')
    # 剧集：父条目 Id（用于取剧照）+ 季/集号
    par = str(it.get('ParentId') or '')
    if it.get('SeriesName') and par and not img.get('Primary'):
        prim = prim or ''
    return {
        'tmdb': pv.get('Tmdb') or pv.get('TmdbId') or '',
        'imdb': pv.get('Imdb') or '',
        'year': it.get('ProductionYear') or '',
        'overview': str(it.get('Overview') or '')[:300],
        'series': it.get('SeriesName') or '',
        'season': it.get('ParentIndexNumber'),
        'episode': it.get('IndexNumber'),
        'run_ticks': it.get('RunTimeTicks') or 0,
        'img_tag': prim,
        'img_id': it.get('SeriesId') or item_id,   # 剧集封面要按 SeriesId 取
        'backdrop_tag': (back[0] if back else ''),
        'path': str(it.get('Path') or ''),
        # ★★ v1.25b S5/S7：文件体积大小。
        #   真实库：MediaSources[0].SizeInMb → Path 实际大小；
        #   strm 虚拟库（实测 MediaSources 全空、Path 是容器内看不到的 /strm/...）：
        #   退到「码率 × RunTimeTicks」估算，与 libcheck / discover_better 同口径，绝不空着。
        'size_txt': _emby_size_txt(it) or _est_emby_strm_size(it),
        # ★ v1.21：MediaStreams 有值就真实画质；strm 库全 null 时用路径推断，
        #   两者**合并**（码率来自 Bitrate，分辨率/编码来自路径），不二选一。
        # ★★ v1.25 R6：两段画质串之间必须补 ' · ' 分隔。
        #   之前直接相加，Bitrate 段（'25.2 Mbps'）会和分辨率段
        #   （'4K 2160P'）粘成 '25.2 Mbps4K 2160P' —— 用户点名批评排版。
        'media': _emby_media_txt(it),
    }


def _emby_size_txt(it):
    """文件体积大小：MediaSources[0].SizeInMb → Path 实际大小 → ''（用户要求「标上去」）。"""
    try:
        ms = (it.get('MediaSources') or [])
        mb = 0
        if ms and isinstance(ms[0], dict):
            try:
                mb = int(float(ms[0].get('SizeInMb') or 0))
            except Exception:
                mb = int(float(ms[0].get('Size') or 0) / 1048576)
        if mb > 0:
            return ('%.1f GB' % (mb / 1024.0)) if mb >= 1024 else ('%d MB' % mb)
        p = str(it.get('Path') or '')
        if p and os.path.exists(p):
            b = os.path.getsize(p)
            if b > 0:
                gb = b / 1024.0 ** 3
                if gb >= 1:
                    return '%.1f GB' % gb
                return '%d MB' % (b / 1048576)
    except Exception:
        pass
    return ''


def _est_emby_strm_size(it):
    """strm 虚拟条目体积估算：码率(Mbps) x RunTimeTicks。
    与 _est_strm_size 同口径；Emby 的 Bitrate 单位实测是 bps，做三量纲兼容。"""
    try:
        br = _norm_bitrate_mbps(it.get('Bitrate'))
        if not br:
            return ''
        try:
            mbps = float(br.split()[0])
        except Exception:
            return ''
        try:
            rt = int(it.get('RunTimeTicks') or 0)
        except Exception:
            rt = 0
        if mbps <= 0 or rt <= 0:
            return ''
        b = int(mbps * 1e6 / 8.0 * (rt / 10000000.0))
        if b <= 0:
            return ''
        gb = b / 1024.0 ** 3
        if gb >= 1:
            return '%.1f GB' % gb
        return '%d MB' % (b / 1048576)
    except Exception:
        return ''


def _emby_media_txt(it):
    """合并 MediaStreams 段与路径推断段，段间补 ' · '（用户要求画质排版规范）。

    ★★ v1.25 R6 修复：旧代码 `_emby_quality(it) + _emby_quality_guess(...)`
    当 _emby_quality 以码率结尾、_emby_quality_guess 以分辨率开头时，会粘成
    '25.2 Mbps4K 2160P'。现在按段拆分后统一 join。
    """
    try:
        a = _emby_quality(it)
        b = _emby_quality_guess(str(it.get('Path') or ''),
                                str(it.get('Name') or ''))
    except Exception:
        return ''
    segs = []
    for x in (a, b):
        for seg in str(x or '').split('\u00b7'):
            seg = seg.strip()
            if seg and seg not in segs:
                segs.append(seg)
    return ' \u00b7 '.join(segs)


def _emby_quality_guess(path, name):
    """strm 虚拟条目没有 MediaStreams/MediaSources（实测全为 null），
    画质只能从**路径/片名**推断（用户要求画质详细，不能空着）。"""
    t = ('%s %s' % (path or '', name or '')).upper()
    if not t.strip():
        return ''
    parts = []
    if re.search(r'\b4K\b|2160P|UHD|BLURAY.*2160', t):
        parts.append('4K 2160P')
    elif re.search(r'1440P|\b2K\b', t):
        parts.append('1440P')
    elif re.search(r'1080P|FHD', t):
        parts.append('1080P')
    elif re.search(r'720P|\bHD\b', t):
        parts.append('720P')
    elif re.search(r'\bSD\b|480P', t):
        parts.append('480P')
    for k, lab in ((r'BLURAY|原盘|BDMV', 'BluRay'), (r'WEB-?DL|WEBDL', 'WEB-DL'),
                   (r'WEBRIP', 'WEBRip'), (r'HDRIP', 'HDRip'),
                   (r'\bDVD\b|DVDSCR', 'DVD'), (r'\bHDTV\b', 'HDTV'),
                   (r'REMUX', 'REMUX')):
        if re.search(k, t):
            parts.append(lab)
            break
    # ★★ v1.25b S5：英文规范 + profile 标清楚（用户点名 P7/P8）
    _dvp = None
    _mdv = re.search(r'\bDV\s*\.?\s*P(\d)', t, re.I)
    if _mdv:
        _dvp = _mdv.group(1)
    if re.search(r'\bDV\b|DOLBY.?VISION|DOVI', t, re.I):
        parts.append(_norm_dv('DOVI', _dvp))
    if re.search(r'HDR10\+|HDR10PLUS', t, re.I):
        parts.append('HDR10+')
    elif re.search(r'\bHDR10\b|\bHDR\b', t, re.I):
        parts.append('HDR10')
    elif re.search(r'\bHLG\b', t, re.I):
        parts.append('HLG')
    # ★★ v1.25 S18：文件名明确写了 SDR 时要标出来（用户要求「该怎么样显示就怎么样显示」）。
    #   之前只识别 HDR/DV，SDR 片源画质串里缺一档，看起来像「漏了信息」。
    elif re.search(r'\bSDR\b', t, re.I):
        parts.append('SDR')
    if re.search(r'\bHEVC\b|\bH\.?265\b|\bX265\b', t):
        parts.append('HEVC')
    elif re.search(r'\bAVC\b|\bH\.?264\b|\bX264\b', t):
        parts.append('H.264')
    if re.search(r'\bATMOS\b', t):
        parts.append('Atmos')
    elif re.search(r'TRUEHD|DTS-?HD|\bDTS\b|FLAC|\bEAC3\b|\bAAC\b', t):
        parts.append('高清音频')
    if re.search(r'60FPS|\b60P\b', t):
        parts.append('60FPS')
    # ★★ v1.25b S7：文件名里带码率的，一并按 Mbps 输出（用户原话
    #   「画质为什么是 KBPS 啊？MBPS 为什么改成 KBBs？」「该怎么样显示就怎么样显示」）
    _mb = re.search(r'(\d+(?:\.\d+)?)\s*MBPS', t)
    if _mb:
        try:
            parts.append('%.1f Mbps' % float(_mb.group(1)))
        except Exception:
            pass
    else:
        _kb = re.search(r'(\d+(?:\.\d+)?)\s*KBPS', t)
        if _kb:
            try:
                parts.append('%.1f Mbps' % (float(_kb.group(1)) / 1000.0))
            except Exception:
                pass
    return ' · '.join(parts)


def _norm_dv(vr, dvp=None):
    """动态范围字符串规范化成英文规范写法。
    用户原话（2026-10-22）：「杜比世界，你不要只写个杜比世界，我都说了是写英文的，然后
    P7、B5、P8 都要给我标清楚了，还有 HDR 也是，HDR10 和 10 加号都要有」。
    输入：Emby 的 VideoRange / VideoRangeType + DvProfile；输出规范串：
      Dolby Vision P8 / P7 / P5 / P4（带 profile 时标到个位数）
      HDR10+ / HDR10 / HLG / SDR
    """
    v = str(vr or '').upper().replace('_', '').replace('-', '').replace(' ', '')
    is_dv = ('DOVI' in v or 'DOLBYVISION' in v or 'DV' == v or v.startswith('DV'))
    is_hdr10p = ('HDR10PLUS' in v or 'HDR10+' in v)
    is_hdr10 = ('HDR10' in v or 'HDR' == v or 'SMPTEST2084' in v)
    is_hlg = ('HLG' in v or 'ARIBSTDB67' in v)
    is_sdr = (v in ('SDR', 'UNKNOWN', '') or 'SDR' in v)
    p = None
    try:
        if dvp not in (None, '', 0, '0'):
            p = int(float(dvp))
    except Exception:
        p = None
    # profile 只接受 P4~P8.4 这一档（P5/P7/P8 常见，P4 兼容）
    if p is not None and (p < 4 or p > 8):
        p = None
    if is_dv:
        return ('Dolby Vision P%d' % p) if p else 'Dolby Vision'
    if is_hdr10p:
        return 'HDR10+'
    if is_hdr10:
        return 'HDR10'
    if is_hlg:
        return 'HLG'
    if is_sdr:
        return 'SDR'
    return str(vr or '')


def _norm_bitrate_mbps(br):
    """码率 → Mbps 规范串。用户原话：「排版给我排好一点，我看你播放数据那边排的，画质为什么
    是 KBPS 啊？MBPS 为什么改成 KBBs？」—— 一律 Mbps，一位小数，单位空格分隔。"""
    try:
        b = float(br or 0)
    except Exception:
        return ''
    if b <= 0:
        return ''
    if b > 100000:            # 已经是 bps
        return '%.1f Mbps' % (b / 1e6)
    if b > 100:               # kbps
        return '%.1f Mbps' % (b * 1000 / 1e6)
    return '%.2f Mbps' % (b * 1e6 / 1e6)   # 已是 Mbps


def _emby_quality(it):
    """画质摘要：分辨率 → 压制/来源 → 动态范围 → 编码 → 音频 → 码率。
    与 ovSessions 的展示口径保持一致（用户要求「画质信息等等参数全部要详细」）。"""
    if not isinstance(it, dict):
        return ''
    vs, as_ = None, None
    for m in (it.get('MediaStreams') or []):
        if m.get('CodecType') == 'Video' and vs is None:
            vs = m
        elif m.get('CodecType') == 'Audio' and as_ is None:
            as_ = m
    parts = []
    if vs:
        w = int(vs.get('Width') or 0)
        h = int(vs.get('Height') or 0)
        if w and h:
            parts.append('%d×%d' % (w, h))
            if h >= 2160:
                parts.append('4K')
            elif h >= 1440:
                parts.append('2K')
            elif h >= 1080:
                parts.append('1080P')
            elif h >= 720:
                parts.append('720P')
        # ★★ v1.25b S5：动态范围统一英文规范（Dolby Vision P8 / HDR10 / HDR10+ / HLG / SDR）
        rng = (vs.get('VideoRangeType') or vs.get('VideoRange') or '')
        if str(rng).upper() not in ('', 'UNKNOWN', 'SDR'):
            parts.append(_norm_dv(rng, vs.get('DvProfile')))
        elif str(rng).upper() == 'SDR':
            parts.append('SDR')
        bd = vs.get('BitDepth')
        if bd:
            parts.append('%sbit' % bd)
        if vs.get('Codec'):
            parts.append(str(vs.get('Codec')).upper())
        fr = vs.get('RealFrameRate') or vs.get('AverageFrameRate')
        if fr:
            try:
                _fr = float(fr)
                if _fr > 0:
                    parts.append(('%gfps' % _fr) if _fr != int(_fr) else ('%dfps' % int(_fr)))
            except Exception:
                pass
    if as_:
        ch = as_.get('Channels')
        if as_.get('Codec'):
            parts.append(str(as_.get('Codec')).upper() + ((' %d.0' % ch) if ch else ''))
        _ad = str(as_.get('DisplayTitle') or '').upper()
        if 'ATMOS' in _ad:
            parts.append('Dolby Atmos')
    # ★★ v1.25b S5：码率一律 Mbps（原来是 %dkbps，用户点名批评）
    _m = _norm_bitrate_mbps(it.get('Bitrate'))
    if _m:
        parts.append(_m)
    return ' · '.join(parts)


def _emby_img_url(which, item_id, tag, kind='Primary', w=200):
    """Emby 图片直连（只读）：/emby/Items/{id}/Images/{kind}/{tag}?api_key=..."""
    if not item_id or not tag:
        return ''
    conf = containers().get(which) or {}
    k = _emby_inst_key(which)
    if not k:
        return ''
    return 'http://%s:%s/emby/Items/%s/Images/%s/%s?width=%d&quality=90&api_key=%s' % (
        conf.get('addr', ''), conf.get('port', ''), item_id, kind, tag, w, k)


def emby_plays(q='', user='', days=30, itype='', page=1, size=50, server=''):
    """★ v1.21 播放数据明细（用户原话：「加一个播放数据，然后我可以在播放数据里面筛选每一个
    用户的播放记录，这些都给我详细一点，像tmdb呀，图片，还有它播放的画质信息等等参数全部要
    详细，还有它播放设备」）。

    server（★★ V1.45 A3 扩展）：''/emby=KFC · emby_adult=KFC2 · all=两台合并（含分页）。
    数据源优先级：
      ① Emby 官方 playback_reporting.db（只读，绝不写）—— 字段最全（画质/码率/IP/转码原因）
      ② ★ 缺库时自动降级 Emby 官方 activitylog.db（KFC2 实测只有这一份）→
         「我KFC2进行观看的时候没有播放记录」从此不再成立；
         降级来源的行会带 method='活动日志'，前端据此显示不同标识，绝不冒充报表库数据。
    """
    sv = str(server or '')
    if sv == 'all':
        return _plays_merge(q, user, days, itype, page, size)
    short = 'adult' if sv == 'emby_adult' else 'main'
    which = 'emby_adult' if short == 'adult' else 'emby'
    con = _pr_db(short)
    if con is None:
        r = emby_plays_activity(days=days, which=which, short=short, user=user, q=q)
        r['fallback'] = 'activitylog'
        r.setdefault('server', which)
        return _plays_page(r, page, size)
    out = emby_plays_pr(con, q=q, user=user, days=days, itype=itype, page=page, size=size,
                        which=which, short=short)
    if not out.get('ok') and not out.get('rows'):
        r = emby_plays_activity(days=days, which=which, short=short, user=user, q=q)
        r['fallback'] = 'activitylog'
        out = _plays_page(r, page, size)
    out.setdefault('server', which)
    return out


def _plays_page(d, page, size):
    """给 activitylog 兜底结果补上分页（与报表库分支返回同构，前端一套代码通吃）。"""
    try:
        page = max(1, int(page or 1)); size = max(1, min(200, int(size or 50)))
    except Exception:
        page, size = 1, 50
    rows = d.get('rows') or []
    d['total'] = len(rows)
    d['rows'] = rows[(page - 1) * size: page * size]
    d['page'] = page; d['size'] = size
    return d


def _plays_merge(q, user, days, itype, page, size):
    """KFC + KFC2 播放明细合并（按时间倒序 + 分页）。"""
    a = emby_plays(q=q, user=user, days=days, itype=itype, page=1, size=200, server='')
    b = emby_plays(q=q, user=user, days=days, itype=itype, page=1, size=200, server='emby_adult')
    rows = list(a.get('rows') or []) + list(b.get('rows') or [])
    rows.sort(key=lambda r: str(r.get('ts') or ''), reverse=True)
    users = {}
    for r in rows:
        k = r.get('user') or ''
        if k:
            users[k] = users.get(k, 0) + 1
    try:
        page = max(1, int(page or 1)); size = max(1, min(200, int(size or 50)))
    except Exception:
        page, size = 1, 50
    parts = a.get('parts') if isinstance(a.get('parts'), dict) else {}
    return {'ok': bool(a.get('ok') or b.get('ok')), 'rows': rows[(page - 1) * size: page * size],
            'total': len(rows), 'page': page, 'size': size,
            'days': days, 'users': [{'id': '', 'name': k, 'n': v} for k, v in
                                    sorted(users.items(), key=lambda x: -x[1])],
            'server': 'all', 'src': 'merged',
            'parts': {'main': {'ok': bool(a.get('ok')), 'rows': a.get('total') or 0,
                               'src': a.get('src') or 'playback_reporting',
                               'err': (a.get('err') or '')[:80]},
                      'adult': {'ok': bool(b.get('ok')), 'rows': b.get('total') or 0,
                                'src': b.get('src') or 'activitylog',
                                'err': (b.get('err') or '')[:80]}},
            'err': '' if (a.get('ok') or b.get('ok')) else (a.get('err') or b.get('err') or '')}


def emby_plays_pr(con, q='', user='', days=30, itype='', page=1, size=50,
                  which='emby', short='main'):
    """playback_reporting.db 明细（原 emby_plays 主体，抽函数以便与活动日志兜底并列）。"""
    out = {'ok': False, 'rows': [], 'total': 0, 'page': page, 'size': size,
           'users': [], 'days': days, 'err': '', 'src': 'playback_reporting'}
    try:
        days = max(1, min(3650, int(days or 30)))
        page = max(1, int(page or 1))
        size = max(1, min(200, int(size or 50)))
        con.row_factory = sqlite3.Row
        try:
            umap = _emby_user_map(which)
            # ★★ v1.25 R4：窗口起点同样按 CST 自然日，和 emby_rank 保持同口径
            since = _day_start(days)
            wh, ar = ['DateCreated >= ?'], [since]
            if user:
                wh.append('UserId = ?')
                ar.append(user)
            if itype:
                wh.append('ItemType = ?')
                ar.append(itype)
            if q:
                wh.append('ItemName LIKE ?')
                ar.append('%' + q + '%')
            wsql = ' AND '.join(wh)
            try:
                out['total'] = int(con.execute(
                    'SELECT COUNT(*) c FROM PlaybackActivity WHERE ' + wsql, ar).fetchone()['c'])
            except Exception:
                out['total'] = 0
            # 用户下拉：该实例在窗口内出现过的用户
            try:
                for r in con.execute(
                        'SELECT UserId, COUNT(*) c FROM PlaybackActivity WHERE DateCreated >= ? '
                        'GROUP BY UserId ORDER BY c DESC LIMIT 200', [since]):
                    out['users'].append({'id': r['UserId'],
                                         'name': umap.get(str(r['UserId'])) or str(r['UserId']),
                                         'n': r['c']})
            except Exception:
                pass
            off = (page - 1) * size
            for r in con.execute(
                    'SELECT * FROM PlaybackActivity WHERE ' + wsql +
                    ' ORDER BY DateCreated DESC LIMIT ? OFFSET ?', ar + [size, off]):
                d = dict(r)
                iid = str(d.get('ItemId') or '')
                meta = {}
                if iid:
                    mck = 'ipm_%s_%s' % (which, iid)
                    if mck in EMBY_RO_CACHE and time.time() - EMBY_RO_CACHE[mck][0] < 1800:
                        meta = EMBY_RO_CACHE[mck][1]
                    else:
                        meta = _emby_item_meta(which, iid)
                        EMBY_RO_CACHE[mck] = (time.time(), meta)
                out['rows'].append({
                    'ts': str(d.get('DateCreated') or '')[:19],
                    'user': umap.get(str(d.get('UserId') or '')) or str(d.get('UserId') or ''),
                    'user_id': str(d.get('UserId') or ''),
                    'item_id': iid,
                    'item': str(d.get('ItemName') or ''),
                    'type': str(d.get('ItemType') or ''),
                    'method': str(d.get('PlaybackMethod') or ''),
                    'client': str(d.get('ClientName') or ''),
                    'device': str(d.get('DeviceName') or ''),
                    'play_sec': int(d.get('PlayDuration') or 0),
                    'pause_sec': int(d.get('PauseDuration') or 0),
                    'ip': str(d.get('RemoteAddress') or ''),
                    'transcode': str(d.get('TranscodeReasons') or ''),
                    'tmdb': meta.get('tmdb', ''),
                    'imdb': meta.get('imdb', ''),
                    'year': meta.get('year', ''),
                    'series': meta.get('series', ''),
                    'season': meta.get('season'),
                    'episode': meta.get('episode'),
                    'overview': meta.get('overview', ''),
                    'quality': meta.get('media', ''),
                    # ★★ v1.25b S5：用户原话「并且把那个文件体积大小也给我标上去」。
                    #   MediaSources[0].SizeInMb 优先，其次 Path 文件实际大小，都没有留空。
                    'size': meta.get('size_txt', ''),
                    'path': meta.get('path', ''),
                    # ★ v1.21：剧集要按 SeriesId 取剧照，电影按自身 Id 取海报
                    # ★★ v1.25 BUG-169：改走 /embyimg/ 代理（api_key 不外泄）
                    'img': ('/embyimg/%s/%s/Primary?w=160' % (which, meta.get('img_id') or iid))
                           if (meta.get('img_tag') or meta.get('img_id') or iid) else '',
                    'server': which,
                    'server_name': (containers().get(which) or {}).get('name', ''),
                })
            out['ok'] = True
        finally:
            con.close()
    except Exception as e:
        out['err'] = str(e)[:140]
    return out


def _day_start(offset_days=0):
    """「今日 00:00:00」按 **CST(UTC+8)** 自然日起算。

    ★★ v1.25 R4 修复（用户原话：「今日用户观看时长」榜永远是空的）：
      Emby 的 PlaybackActivity.DateCreated 写的是 **UTC 墙钟**（实测：容器
      date -u 01:12 时，最新记录停在 2026-10-22 09:12 —— 正好 UTC+8），
      而老代码用 datetime.now().strftime('%Y-%m-%d 00:00:00') 取「本地今日 0 点」。
      容器 TZ=UTC → 北京时间早上 8 点之前，「今日榜」窗口落在还没发生的时间段，
      18 个 kind/days 组合里 15 个恒为 0 行。
      现在统一切到 CST 自然日：北京时间今天 00:00 → 换算成 UTC 时间串，
      与库里同口径可比。offset_days 用于「昨天/前七天」。
    """
    try:
        now_cst = datetime.datetime.utcnow() + datetime.timedelta(hours=8)
    except Exception:
        now_cst = datetime.datetime.now()
    d = (now_cst - datetime.timedelta(days=offset_days)).strftime('%Y-%m-%d 00:00:00')
    # CST 00:00 → UTC 前一日 16:00
    try:
        dt = datetime.datetime.strptime(d, '%Y-%m-%d %H:%M:%S') - datetime.timedelta(hours=8)
        return dt.strftime('%Y-%m-%d %H:%M:%S')
    except Exception:
        return d


def _rank_one(kind, days, which, short):
    """单实例排名：优先 playback_reporting.db，缺库自动降级 Emby 官方活动日志。"""
    con = _pr_db(short)
    if con is None:
        r = emby_rank_activity(kind=kind, days=days, which=which, short=short)
        r['fallback'] = 'activitylog'
        return r
    # ★ emby_rank_pr 内部 finally 已负责 close（沿用 v1.21 原写法，避免二次关闭）
    out = emby_rank_pr(con, kind, days, which, short)
    if not out.get('ok') and not out.get('rows'):
        r = emby_rank_activity(kind=kind, days=days, which=which, short=short)
        r['fallback'] = 'activitylog'
        return r
    return out


def emby_rank(kind='user_today', days=1, server=''):
    """★ v1.21 排名（用户原话：「还有就是加一个排名进去就是机器人的那种排名，里面有好多选择，
    比如说今日每个用户观看时长从高到低排，然后影片播放时长从高到低排」）。

    kind 取值：
      user_today   今日每用户观看时长降序
      user_days    N 日每用户观看时长降序
      item_today   今日影片播放时长降序
      item_days    N 日影片播放时长降序
      item_plays   影片播放次数降序
      device       设备/客户端播放时长降序
    server 取值（★★ V1.45 A3 扩展）：
      ''/emby      只看主实例 KFC（老行为，向后完全兼容）
      emby_adult   只看 KFC2
      all          ★ KFC + KFC2 合并排名（用户原话：「我KFC2进行观看的时候，
                   它是没有播放记录的」→ 现在两台都进榜，同名用户时长相加）
    数据源：playback_reporting.db 只读聚合；缺库（KFC2 实测就没有）自动降级到
    Emby 官方 activitylog.db（见 A3 兜底层）。全程只读，绝不写。
    """
    try:
        days = max(1, min(3650, int(days or 1)))
    except Exception:
        days = 1
    sv = str(server or '')
    if sv == 'all':
        return _rank_merge(kind, days)
    if sv == 'emby_adult':
        r = _rank_one(kind, days, 'emby_adult', 'adult')
        r.setdefault('server', 'emby_adult')
        return r
    r = _rank_one(kind, days, 'emby', 'main')
    r.setdefault('server', 'emby')
    return r


def _rank_merge(kind, days):
    """KFC + KFC2 合并榜：分别聚合后按 name 合并（时长相加 / 次数相加），再重排名。"""
    a = _rank_one(kind, days, 'emby', 'main')
    b = _rank_one(kind, days, 'emby_adult', 'adult')
    out = {'ok': bool(a.get('ok') or b.get('ok')), 'kind': kind, 'days': days,
           'server': 'all', 'rows': [], 'err': '', 'window': '', 'total_sec': 0,
           'parts': {'main': {'ok': bool(a.get('ok')), 'rows': len(a.get('rows') or []),
                              'err': (a.get('err') or '')[:80],
                              'src': a.get('src') or 'playback_reporting'},
                     'adult': {'ok': bool(b.get('ok')), 'rows': len(b.get('rows') or []),
                               'err': (b.get('err') or '')[:80],
                               'src': b.get('src') or 'playback_reporting'}}}
    merged = {}
    for part, tag in ((a, 'KFC'), (b, 'KFC2')):
        for r in (part.get('rows') or []):
            nm = str(r.get('name') or '(未知)')
            cur = merged.get(nm)
            if not cur:
                cur = dict(r)
                cur['sec'] = int(r.get('sec') or 0)
                cur['n'] = int(r.get('n') or 0)
                cur['pause_sec'] = int(r.get('pause_sec') or 0)
                cur['servers'] = [tag]
                merged[nm] = cur
            else:
                cur['sec'] += int(r.get('sec') or 0)
                cur['n'] += int(r.get('n') or 0)
                cur['pause_sec'] += int(r.get('pause_sec') or 0)
                # ★ V1.45 B8：头像取「先有先得」——主实例没设头像时，
                #   用另一台实例查到的（保证排名里每个人都有头像）
                if not cur.get('avatar') and r.get('avatar'):
                    cur['avatar'] = r.get('avatar')
                if not cur.get('img') and r.get('img'):
                    cur['img'] = r.get('img')
                if tag not in cur['servers']:
                    cur['servers'].append(tag)
    rows = sorted(merged.values(), key=lambda x: (-int(x.get('sec') or 0)))
    for i, r in enumerate(rows, 1):
        r['rank'] = i
        r['server_txt'] = ' / '.join(r.pop('servers', []) or [])
    out['rows'] = rows
    out['total_sec'] = sum(int(r.get('sec') or 0) for r in rows)
    out['window'] = (a.get('window') or b.get('window') or '')
    return out


def emby_rank_pr(con, kind='user_today', days=1, which='emby', short='main'):
    """playback_reporting.db 聚合（原 emby_rank 主体，抽成函数以便与活动日志兜底并列）。"""
    out = {'ok': False, 'kind': kind, 'days': days, 'rows': [], 'err': '',
           'window': '', 'total_sec': 0, 'src': 'playback_reporting'}
    try:
        days = max(1, min(3650, int(days or 1)))
        # ★ 连接由调用方 _rank_one 传入并负责关闭（这里不再 close）
        con.row_factory = sqlite3.Row
        try:
            umap = _emby_user_map(which)
            if kind in ('user_today', 'item_today', 'item_plays'):
                # ★★ v1.25 R4：今日榜按 CST 自然日（见 _day_start 注释）
                since = _day_start(0)
            else:
                since = _day_start(days)
            out['window'] = since
            # ★★ v1.25b S4：用户头像（Emby /emby/Users/{id} 的 PrimaryImageTag）。
            #   用户原话：「播放排名的话，再加上他们的 emby 相应的头像」。
            #   拿不到头像的给空串，前端回落首字母色块（绝不显示破图）。
            def _emby_user_avatar(uid):
                try:
                    uj = _emby_inst_http(which, '/emby/Users/%s' % urllib.parse.quote(str(uid)), {}, t=6)
                    if not isinstance(uj, dict):
                        return ''
                    tg = (uj.get('PrimaryImageTag') or '')
                    if not tg:
                        return ''
                    # ★★ v1.25 BUG-169：改走**后端代理** /embyimg/<which>/users/<uid>/Primary。
                    #   原来直接把 Emby 地址 + api_key 明文拼进 JSON 下发给浏览器 →
                    #   ① 任何人 F12 就能拿走 Emby API Key（开源项目尤其致命）；
                    #   ② 内网 IP 泄露；
                    #   ③ 头像 URL 跨实例不可用。
                    #   现在前端只见 /embyimg/...，key 全程留在服务端。
                    return '/embyimg/%s/users/%s/Primary?w=96' % (which, urllib.parse.quote(str(uid)))
                except Exception:
                    return ''
            _AV_CACHE = {}
            def _av(uid):
                if uid not in _AV_CACHE:
                    _AV_CACHE[uid] = _emby_user_avatar(uid)
                return _AV_CACHE[uid]
            if kind in ('user_today', 'user_days'):
                sql = ('SELECT UserId, SUM(PlayDuration) s, COUNT(*) n, '
                       'SUM(PauseDuration) p FROM PlaybackActivity WHERE DateCreated >= ? '
                       'GROUP BY UserId ORDER BY s DESC LIMIT 100')
                for r in con.execute(sql, [since]):
                    nm = umap.get(str(r['UserId'])) or str(r['UserId'])
                    out['rows'].append({'rank': 0, 'name': nm, 'id': str(r['UserId']),
                                        'sec': int(r['s'] or 0), 'n': int(r['n'] or 0),
                                        'pause_sec': int(r['p'] or 0),
                                        'avatar': _av(str(r['UserId']))})
            def _emby_rank_item(iid):
                """影片排行补 TMDB / 封面 / 年份 / 路径（用户原话：「影片排名什么的你这个
                只有一个简单的文字排名，就只有他的名字排名。但是你要把他的 TMD 的封面啊，
                TMD 直达链接，还有等等等等都给放上去。」）。
                带 30 分钟缓存：排行榜一轮最多 100 条，且 15s 才刷一次，不能每条都回查 Emby。"""
                iid = str(iid or '')
                if not iid:
                    return {}
                ck = 'irk_%s_%s' % (which, iid)
                hit = EMBY_RO_CACHE.get(ck)
                if hit and time.time() - hit[0] < 1800:
                    return hit[1]
                m = _emby_item_meta(which, iid) or {}
                row = {
                    'tmdb': m.get('tmdb', ''),
                    'imdb': m.get('imdb', ''),
                    'year': m.get('year', ''),
                    'series': m.get('series', ''),
                    'season': m.get('season'),
                    'episode': m.get('episode'),
                    'overview': m.get('overview', ''),
                    'media': m.get('media', ''),
                    'path': m.get('path', ''),
                    # ★★ v1.25 BUG-169：海报同样改走 /embyimg/ 代理（不带 api_key）
                    'img': ('/embyimg/%s/%s/Primary?w=200' % (which, m.get('img_id') or iid))
                           if (m.get('img_tag') or m.get('img_id') or iid) else '',
                }
                EMBY_RO_CACHE[ck] = (time.time(), row)
                return row
            elif_done = {'v': False}
            if kind in ('item_today', 'item_days'):
                sql = ('SELECT ItemId, ItemName, ItemType, SUM(PlayDuration) s, COUNT(*) n '
                       'FROM PlaybackActivity WHERE DateCreated >= ? '
                       'GROUP BY ItemId ORDER BY s DESC LIMIT 100')
                for r in con.execute(sql, [since]):
                    _m = _emby_rank_item(r['ItemId'])
                    out['rows'].append({'rank': 0, 'name': str(r['ItemName'] or ''),
                                        'id': str(r['ItemId'] or ''),
                                        'type': str(r['ItemType'] or ''),
                                        'sec': int(r['s'] or 0), 'n': int(r['n'] or 0),
                                        **_m})
            elif kind == 'item_plays':
                sql = ('SELECT ItemId, ItemName, ItemType, COUNT(*) n, SUM(PlayDuration) s '
                       'FROM PlaybackActivity WHERE DateCreated >= ? '
                       'GROUP BY ItemId ORDER BY n DESC LIMIT 100')
                for r in con.execute(sql, [since]):
                    _m = _emby_rank_item(r['ItemId'])
                    out['rows'].append({'rank': 0, 'name': str(r['ItemName'] or ''),
                                        'id': str(r['ItemId'] or ''),
                                        'type': str(r['ItemType'] or ''),
                                        'sec': int(r['s'] or 0), 'n': int(r['n'] or 0),
                                        **_m})
            elif kind == 'device':
                sql = ('SELECT DeviceName, ClientName, SUM(PlayDuration) s, COUNT(*) n '
                       'FROM PlaybackActivity WHERE DateCreated >= ? '
                       'GROUP BY DeviceName, ClientName ORDER BY s DESC LIMIT 100')
                for r in con.execute(sql, [since]):
                    out['rows'].append({'rank': 0,
                                        'name': str(r['DeviceName'] or '未知设备'),
                                        'client': str(r['ClientName'] or ''),
                                        'sec': int(r['s'] or 0), 'n': int(r['n'] or 0)})
            for i, r in enumerate(out['rows']):
                r['rank'] = i + 1
            out['total_sec'] = sum(r['sec'] for r in out['rows'])
            out['ok'] = True
        finally:
            con.close()
    except Exception as e:
        out['err'] = str(e)[:140]
    return out


# ═══════════════════════════════════════════════════════════════════════════
# ★★ v1.22 飞牛 NAS 硬件仪表盘（用户原话，2026-10-22）：
#   「仪表盘的话，再加一个我飞牛NAS的仪表盘，就比如说我内存什么的，还有硬盘
#     什么的，温度啊繁忙度等等」
#
# 为什么必须走「宿主机采集 → 写文件 → 后端读文件」这条路：
#   media-hub 容器里读不到 /sys/class/hwmon 与 /proc/diskstats（只挂了 docker.sock
#   + /dockroot + /CloudNAS，没挂全 /sys），docker exec 在这台 NAS 上又不可用
#   （setns 失败）。所以温度/磁盘 io 繁忙度只能由宿主机侧脚本每 10s 采一次，
#   写进 /vol1/1000/docker/media-hub/nas_metrics.json —— 而该目录正是容器里
#   /dockroot（bind mount），后端能直接读。
#   ★ 绝不在后端 ssh/scp 到宿主机：那会把 loadavg 已经 12~21 的机器再拖死。
#
# 采集脚本：/tmp/nas_collect.sh（已由 crontab 每 10s 调度，6 个 offset 错峰）
# 缓存：后端 2s（前端 2s 轮询不会重复读盘）
# ═══════════════════════════════════════════════════════════════════════════
_NAS_METRICS_PATH = os.environ.get('NAS_METRICS_FILE',
                                   '/dockroot/media-hub/nas_metrics.json')
_NAS_CACHE = {'ts': 0.0, 'data': None}


def _temp_tone(c):
    """温度 → 健康档（CPU/SSD 用）"""
    try:
        c = float(c)
    except Exception:
        return ''
    if c >= 75:
        return 'bad'
    if c >= 62:
        return 'warn'
    return 'ok'


def nas_metrics(force: bool = False) -> dict:
    """读宿主机采集脚本产出的 nas_metrics.json，补一层前端友好的派生字段。

    返回结构（前端 ovNasCard 直接用）：
      ok / ts / age_sec / stale
      mem{total_gb,used_gb,avail_gb,pct}
      swap{total_gb,used_gb,pct}
      loadavg / nproc / load_pct
      cpu_temp{max,tone,cores}
      dimm[{c,tone}]           内存条 SPD 温度（jc42 传感器）
      nvme[{c,tone}]           NVMe 传感器温度
      other[{name,label,c,tone}]
      disks[{dev,size_gb,used_gb,avail_gb,pct_num,pct,mp,tone}]
      io_busy_pct / io_top[{dev,ms,pct}]
      raids[{md,state,level,degraded,tone}]
    """
    now = time.time()
    if not force and _NAS_CACHE['data'] is not None and now - _NAS_CACHE['ts'] < 2.0:
        return _NAS_CACHE['data']
    out = {'ok': False, 'err': '', 'path': _NAS_METRICS_PATH, 'ts': 0, 'age_sec': 0,
           'stale': True}
    try:
        if not os.path.exists(_NAS_METRICS_PATH):
            out['err'] = '宿主机采集脚本尚未产出（crontab 每 10s 写一次）'
            _NAS_CACHE.update({'ts': now, 'data': out})
            return out
        with open(_NAS_METRICS_PATH, encoding='utf-8') as f:
            raw = json.load(f)
        gb = lambda kb: round((int(kb or 0) / 1048576.0), 1)
        m = raw.get('mem') or {}
        out['mem'] = {'total_gb': gb(m.get('total_kb')), 'used_gb': gb(m.get('used_kb')),
                      'avail_gb': gb(m.get('avail_kb')),
                      'pct': (round(m.get('used_kb', 0) / m.get('total_kb', 1) * 100, 1)
                              if m.get('total_kb') else 0)}
        sw = raw.get('swap') or {}
        out['swap'] = {'total_gb': gb(sw.get('total_kb')), 'used_gb': gb(sw.get('used_kb')),
                       'pct': (round(sw.get('used_kb', 0) / sw.get('total_kb', 1) * 100, 1)
                               if sw.get('total_kb') else 0)}
        try:
            la = [float(x) for x in str(raw.get('loadavg') or '0 0 0').split()[:3]]
        except Exception:
            la = [0, 0, 0]
        npr = int(raw.get('nproc') or 1) or 1
        out['loadavg'] = raw.get('loadavg') or ''
        out['nproc'] = npr
        out['load_pct'] = round(la[0] / npr * 100, 1)
        cores = []
        for c in (raw.get('cpu_temps') or []):
            try:
                cores.append(float(c))
            except Exception:
                pass
        cmax = raw.get('cpu_temp_max')
        if cmax is None and cores:
            cmax = max(cores)
        out['cpu_temp'] = {'max': cmax, 'tone': _temp_tone(cmax), 'cores': cores,
                           'n': len(cores)}
        out['dimm'] = [{'c': x, 'tone': _temp_tone(x)} for x in (raw.get('dimm_temps') or [])]
        out['nvme'] = [{'c': x, 'tone': _temp_tone(x)} for x in (raw.get('nvme_temps') or [])]
        out['other'] = [{'name': o.get('name') or '', 'label': o.get('label') or '',
                         'c': o.get('c'), 'tone': _temp_tone(o.get('c'))}
                        for o in (raw.get('other_temps') or [])]
        disks = []
        for d in (raw.get('disks') or []):
            try:
                sz = int(d.get('size') or 0)
                us = int(d.get('used') or 0)
                av = int(d.get('avail') or 0)
            except Exception:
                continue
            pn = round(us / sz * 100, 1) if sz else 0
            disks.append({'dev': d.get('dev') or '', 'mp': d.get('mp') or '',
                          'size_gb': round(sz / 1073741824.0, 1),
                          'used_gb': round(us / 1073741824.0, 1),
                          'avail_gb': round(av / 1073741824.0, 1),
                          'pct_num': pn, 'pct': d.get('pct') or ('%d%%' % pn),
                          'tone': 'bad' if pn >= 95 else ('warn' if pn >= 85 else 'ok')})
        disks.sort(key=lambda x: -x['pct_num'])
        out['disks'] = disks
        it = raw.get('io_top') or []
        mx = max([int(x.get('ms') or 0) for x in it] or [1]) or 1
        out['io_top'] = [{'dev': x.get('dev') or '', 'ms': int(x.get('ms') or 0),
                          'pct': round(int(x.get('ms') or 0) / mx * 100, 1)}
                         for x in sorted(it, key=lambda y: -(int(y.get('ms') or 0)))[:6]]
        out['io_busy_pct'] = raw.get('io_busy_pct') or 0
        out['raids'] = [{'md': r.get('md') or '', 'state': r.get('state') or '',
                         'level': r.get('level') or '', 'degraded': int(r.get('degraded') or 0),
                         'tone': 'bad' if (int(r.get('degraded') or 0) > 0
                                           or r.get('state') not in ('active', 'clean')) else 'ok'}
                        for r in (raw.get('raids') or [])]
        out['ts'] = int(raw.get('ts') or 0)
        out['age_sec'] = max(0, int(now - out['ts'])) if out['ts'] else 0
        # 采集脚本 10s 一次；超过 45s 没更新视为失联（脚本挂了 / crontab 没了）
        out['stale'] = bool(out['age_sec'] > 45)
        out['ok'] = True
    except Exception as e:
        out['err'] = str(e)[:140]
    _NAS_CACHE.update({'ts': now, 'data': out})
    return out


KFCGAME_CFG = "/dockroot/kfcgame/config.json"


def bot_lines_health():
    """★ v1.25 S14 机器人线路健康检查（用户原话：「跟机器人那边更新一下，所有机器人
       那边都更新一下，别人获取线路的时候不要给错误的线路」「我发现你每次给的都是我
       本地的内网线路，都是我本地的IP地址加上端口号的，根本就不是域名的，赶快给我改掉」）。

    三源对比：
      · kfcgame config.json 的 emby.lines（**机器人实际下发给群友的线路**）
      · RT emby_access_lines（RT 面板的线路池）
      · emby302_configs（RT 302 服务器配置，public_url）
    判定：裸 IP / http+非标端口 / frp 命名 → 标记 bad，说明"群友拿到的是错的"。
    """
    import re as _re
    out = {"ok": True, "bot": [], "rt": [], "bad_in_bot": 0, "msg": ""}

    def _judge(name, url):
        """返回 (is_bad, reason)"""
        u = str(url or "").strip().lower()
        nm = str(name or "").strip().lower()
        if not u:
            return True, "地址为空"
        host = u.split("//", 1)[-1].split("/", 1)[0].split(":", 1)[0]
        if _re.match(r"^\d{1,3}(\.\d{1,3}){3}$", host):
            return True, "裸 IP 地址（%s）——群友拿到的是内网/无域名线路" % host
        if u.startswith("http://") and ":" in u.split("//", 1)[-1].split("/", 1)[0]:
            return True, "http + 非标端口——不是正式公网站点"
        for k in ("ipv4", "ipv6", "88frp", "frp", "frpc", "frps", "natfrp", "内网", "穿透"):
            if k in nm:
                return True, "线路名含「%s」——内网穿透通道，不应下发给群友" % k
        if not u.startswith("https://") and "://" not in u:
            return True, "不是合法 URL"
        return False, ""

    # ① 机器人实际下发的线路（kfcgame config.json）
    try:
        cg = json.load(open(KFCGAME_CFG, encoding="utf-8"))
        em = cg.get("emby") or {}
        for i, l in enumerate(em.get("lines") or []):
            nm = l.get("name") or ("线路%d" % (i + 1))
            u = l.get("url") or ""
            bad, why = _judge(nm, u)
            out["bot"].append({"name": nm, "url": u, "bad": bad, "why": why,
                               "enabled": l.get("enabled", True)})
            if bad:
                out["bad_in_bot"] += 1
        out["bot_public_url"] = em.get("public_url") or ""
        b, w = _judge("public_url", out["bot_public_url"])
        out["public_url_bad"] = b
        out["public_url_why"] = w
    except Exception as e:
        out["bot_err"] = str(e)[:100]
    # ② RT 线路池（只读）
    try:
        for r in _rtq("SELECT id,name,url,enabled FROM emby_access_lines ORDER BY id"):
            bad, why = _judge(r["name"], r["url"])
            out["rt"].append({"id": r["id"], "name": r["name"], "url": r["url"],
                              "enabled": r["enabled"], "bad": bad, "why": why})
    except Exception as e:
        out["rt_err"] = str(e)[:100]
    nb = len([x for x in out["bot"] if x["bad"]])
    if nb:
        out["msg"] = "机器人配置里有 %d 条问题线路（裸 IP / frp / http+端口），群友可能拿到错误线路" % nb
    elif not out["bot"]:
        out["msg"] = "读不到机器人线路配置（kfcgame config.json 的 emby.lines 为空？）"
    else:
        out["msg"] = "机器人下发的 %d 条线路全部是公网域名，群友拿到即正确线路 ✅" % len(out["bot"])
    return out


def db_accounts(q="", limit=300, src=""):
    """三源合并账号视图。每行：tg/实时用户名/Emby名/密码/到期/等级/V积分/
    灵石/来源(boss|game|rt)/备注。q 过滤用户名/UID/Emby名。"""
    rows = {}
    try:
        for r in _bossq(
                "SELECT tg, embyid, name, pwd, pwd2, lv, cr, ex, us, iv, ch, "
                "open_code, last_renew_code "
                "FROM embyboss.emby"):
            t = str(r["tg"])
            rows[t] = {"tg": t, "emby_id": r.get("embyid") or "",
                       "emby_name": r.get("name") or "",
                       "emby_pwd": r.get("pwd") or "", "sec": r.get("pwd2") or "",
                       "lv": r.get("lv") or "d", "created": str(r.get("cr") or "")[:19],
                       "expires": str(r.get("ex") or "")[:19],
                       "days_pool": int(r.get("us") or 0),
                       "vp": int(r.get("iv") or 0),
                       "open_code": r.get("open_code") or "",
                       "last_renew_code": r.get("last_renew_code") or "",
                       "src": "boss"}
    except Exception as e:
        logger.warning("db_accounts boss 源失败: %s", e)
    # game 档案 + 灵石
    try:
        for r in _xq(
                "SELECT m.tg, m.tg_name, m.tg_username, c.ls "
                "FROM kfcgame.kfc_members m LEFT JOIN kfcgame.kfc_cultivator c ON c.tg=m.tg "
                "LIMIT 500"):
            t = str(r["tg"])
            d = rows.setdefault(t, {"tg": t, "src": "game"})
            d["tg_name"] = r.get("tg_name") or ""
            d["tg_user"] = r.get("tg_username") or ""
            d["ls"] = int(r.get("ls") or 0)
            if d.get("src") == "boss":
                d["src"] = "boss+game"
            elif d.get("src") == "game" and d.get("emby_id"):
                d["src"] = "boss+game"
    except Exception as e:
        logger.warning("db_accounts game 源失败: %s", e)
    # RT 只读补充（tg_user_id 绑定的号）
    try:
        # 预载 115 盘位 id→name 映射，便于 db 页面直接显示可读名称
        _p115 = {}
        try:
            for _p in _rtq("SELECT id, name FROM pan115_configs ORDER BY id"):
                _p115[_p["id"]] = _p["name"]
        except Exception:
            pass
        for r in _rtq(
                "SELECT tg_user_id, username, emby_user_id, expiry_date, points, "
                "       status, remark, cookie_valid, route_mode, created_at, "
                "       user_mode, allowed_modes, max_devices, pan115_config_id "
                "FROM emby_users WHERE tg_user_id IS NOT NULL AND tg_user_id<>0"):
            t = str(r["tg_user_id"])
            d = rows.setdefault(t, {"tg": t, "src": "rt"})
            d["rt_name"] = r.get("username") or ""
            d.setdefault("emby_name", d.get("emby_name") or r.get("username") or "")
            d.setdefault("emby_id", r.get("emby_user_id") or "")
            d.setdefault("expires", str(r.get("expiry_date") or "")[:19])
            d["rt_points"] = int(r.get("points") or 0)
            d["rt_status"] = r.get("status") or ""
            d["rt_cookie_ok"] = int(r.get("cookie_valid") or 0)
            d["rt_remark"] = r.get("remark") or ""
            d["rt_route"] = r.get("route_mode") or ""
            d["rt_created"] = str(r.get("created_at") or "")[:19]
            # ★ Task4：RT 扩展字段（115 模式/允许模式/最大设备/115盘位）
            d["rt_user_mode"] = r.get("user_mode") or ""
            d["rt_allowed"] = r.get("allowed_modes") or ""
            d["rt_max_dev"] = int(r.get("max_devices") or 0)
            d["rt_pan115_id"] = int(r.get("pan115_config_id") or 0)
            d["rt_pan115_name"] = _p115.get(r.get("pan115_config_id"), "") or ""
            if d["src"] == "rt":
                d["src"] = "rt"
            elif "rt" not in d["src"]:
                d["src"] += "+rt"
    except Exception as e:
        logger.warning("db_accounts rt 源失败: %s", e)
    # 统一补 tg_name/tg_username（boss-only 或 RT-only 行可能没有 game 档案）
    try:
        for r in _xq("SELECT tg, tg_name, tg_username FROM kfcgame.kfc_members"):
            t = str(r["tg"])
            d = rows.get(t)
            if d is None:
                continue
            if not d.get("tg_name"):
                d["tg_name"] = r.get("tg_name") or ""
            if not d.get("tg_user"):
                d["tg_user"] = r.get("tg_username") or ""
    except Exception as e:
        logger.warning("db_accounts members 补登失败: %s", e)
    # ★ Emby 服务器全量账号合并（2026-10-15 用户要求）：把「没绑 TG」的 Emby
    #   账号也列出来，标注「未绑定 TG 账号」——这些号历史上多半是 RT 开的。
    try:
        ej = _emby_http("/emby/Users", params={"Recursive": "false"}, t=15)
        # ★ v1.15 BUG-122（真因，前面两处 Policy 只是症状）：
        #   `/emby/Users` 的返回值**不总是** {'Items': [...]} 对象。
        #   Emby 在某些配置/版本（或经反代）下直接返回 **JSON 数组**，
        #   此时 `(ej or {}).get('Items')` 抛
        #   'list' object has no attribute 'get'，整个 emby-server 补充源
        #   被 except 吞掉 → 账号视图少了「服务器上有、未绑定 TG 的号」，
        #   而且用户每次进账号页都刷一条 WARNING。
        #   容器内实测已复现：ej 是 list。
        if isinstance(ej, list):
            _users = ej
        elif isinstance(ej, dict):
            _users = ej.get("Items") or []
        else:
            _users = []
        for u in _users:
            if not isinstance(u, dict):
                continue
            uid = str(u.get("Id") or "")
            nm = str(u.get("Name") or "").strip()
            if not uid or not nm:
                continue
            hit_row = next((x for x in rows.values()
                            if (x.get("emby_id") or "") == uid
                            and int(x.get("tg") or 0) > 0), None)
            if hit_row:
                hit_row["emby_on_server"] = True
                # ★ v1.15 BUG-122：Policy 理论上恒为 dict，但 Emby 某些版本/
                #   代理层会把它返回成 list → `.get` 直接抛
                #   'list' object has no attribute 'get'，整个 emby-server
                #   补充源被 except 吞掉 → 账号视图少了「未绑定 TG 的号」。
                #   实测日志：db_accounts emby-server 源失败:
                #   'list' object has no attribute 'get'
                _pol = u.get("Policy")
                _pol = _pol if isinstance(_pol, dict) else {}
                hit_row.setdefault("emby_disabled", bool(_pol.get("IsDisabled")))
                continue
            # 服务器上有、本地没绑 TG 的号 → 单列一行（禁止与有 TG 的合并）
            key = "srv:" + uid
            rows[key] = {"tg": "", "src": "emby-server", "emby_id": uid,
                         "emby_name": nm, "tg_bind": "",
                         "emby_on_server": True,
                         "unbound_tg": True,
                         "expires": "", "note": "未绑定 TG 账号"}
    except Exception as e:
        logger.warning("db_accounts emby-server 源失败: %s", e)
    out = list(rows.values())
    for d in out:
        d.setdefault("lv", "d")
    if src:
        out = [x for x in out if src in (x.get("src") or "")]
    if q:
        ql = q.lower()
        out = [x for x in out if ql in str(x.get("tg", "")).lower()
               or ql in (x.get("tg_name") or "").lower()
               or ql in (x.get("emby_name") or "").lower()
               or ql in (x.get("rt_name") or "").lower()]
    def _sortkey(x):
        return str(x.get("expires") or "9999")
    out.sort(key=_sortkey)
    return {"ok": True, "total": len(out), "rows": out[:int(limit)],
            "tg_owner": cfg().get('tg_owner') or os.environ.get('TG_OWNER_UID') or 0}


def db_account_edit(body):
    """编辑账号任意字段：tg + 需要改的键（emby_name/emby_pwd/expires/vp/lv/days_pool）。
    emby_name/emby_pwd 会同步改 Emby 服务器（改名走 Policy 接口，改密走 Password 接口）。"""
    tg = str(body.get("tg") or "").strip()
    if not tg.isdigit():
        return {"ok": False, "msg": "tg 必须是数字 UID"}
    fields = []
    args = {"tg": int(tg)}
    for key, col in (("emby_name", "name"), ("emby_pwd", "pwd"),
                     ("lv", "lv"), ("days_pool", "us"), ("vp", "iv")):
        if key in (body.get("set") or {}):
            fields.append("`%s`=%%(%s)s" % (col, key))
            args[key] = body["set"][key]
    if "expires" in (body.get("set") or {}):
        v = str(body["set"]["expires"] or "").strip()
        fields.append("ex=%s" % ("NULL" if not v else "'" + v.replace("'", "") + "'"))
    if not fields:
        return {"ok": False, "msg": "没有要修改的字段"}
    try:
        # 先确保 boss 有行（game 用户可能还没进台账）
        _bossq("INSERT IGNORE INTO emby (tg, lv, us, iv) VALUES (%(tg)s,'d',0,0)",
               {"tg": int(tg)})
        sql = "UPDATE emby SET " + ", ".join(fields) + " WHERE tg=%(tg)s"
        # 上面手工拼的 ex 用字符串值——仅数字/日期格式，已去引号，可控
        import pymysql
        _bd2 = _boss_db()
        _pd = _pt_db()
        conn = pymysql.connect(host=_pd["host"], port=_pd["port"],
                               user=_bd2["user"], password=_bd2["password"],
                               database=_bd2["db"], charset="utf8mb4",
                               connect_timeout=8, autocommit=False)
        try:
            with conn.cursor() as cur:
                cur.execute(sql, args)
            conn.commit()
        finally:
            conn.close()
        # Emby 服务器侧同步改密（改了密码必须让服务器生效，否则登录不上）
        msg = "已更新 %d 个字段" % len(fields)
        new_pw = (body.get("set") or {}).get("emby_pwd")
        emby_id = None
        try:
            r = _bossq("SELECT embyid FROM emby WHERE tg=%(tg)s", {"tg": int(tg)})
            emby_id = (r[0].get("embyid") if r else None)
        except Exception:
            pass
        if new_pw and emby_id:
            try:
                _ec = containers()["emby"]
                _ek = cfg().get("emby_key") or EMBY_KEY_FB
                st, b = hreq(_ec["addr"], _ec["port"], "POST",
                            "/emby/Users/%s/Password" % emby_id,
                            json.dumps({"Id": emby_id, "NewPw": new_pw}),
                            {"X-Emby-Token": _ek,
                             "Content-Type": "application/json"}, 10)
                msg += "｜Emby 改密 %s" % ("✅" if st in (200, 204) else "❌HTTP%s" % st)
            except Exception as e:
                msg += "｜Emby 改密异常 %s" % str(e)[:40]
        oplog("web", "db_edit", "编辑账号 %s" % tg, True, msg)
        return {"ok": True, "msg": msg}
    except Exception as e:
        oplog("web", "db_edit", "编辑账号 %s" % tg, False, str(e)[:120])
        return {"ok": False, "msg": str(e)[:120]}


def rt_pull_sync():
    """RT → boss/game 单向补登：RT 有 TG 绑定但 boss 台账没行的用户，
    建台账行 + 档案（名字/到期/备注搬过去）。RT 零写入。"""
    n_new = n_upd = 0
    try:
        rtu = _rtq("SELECT tg_user_id, username, emby_user_id, expiry_date, points, "
                   "remark FROM emby_users WHERE tg_user_id IS NOT NULL AND tg_user_id<>0")
        for r in rtu:
            t = int(r["tg_user_id"])
            exist = _bossq("SELECT tg, embyid FROM emby WHERE tg=%(tg)s", {"tg": t})
            if not exist:
                _bossq("INSERT INTO emby (tg, embyid, name, lv, us, iv) "
                       "VALUES (%(tg)s, %(eid)s, %(n)s, 'b', 0, 0)",
                       {"tg": t, "eid": r.get("emby_user_id") or "",
                        "n": r.get("username") or ""})
                n_new += 1
            elif exist and not (exist[0].get("embyid") or "") and r.get("emby_user_id"):
                _bossq("UPDATE emby SET embyid=%(eid)s, name=IFNULL(NULLIF(name,''),%(n)s) "
                       "WHERE tg=%(tg)s",
                       {"eid": r["emby_user_id"], "n": r.get("username") or "", "tg": t})
                n_upd += 1
            # ★ Task3：RT→boss 续期同步。RT 侧续期后，把 expiry_date 回填到统一台账
            #   emby.ex（仅当新到期比现有更晚或原为空，避免把已续的覆盖回更早值）。
            try:
                rd = r.get("expiry_date")
                if rd:
                    ex = str(rd)[:19]
                    if ex:
                        _bossq(
                            "UPDATE emby SET ex=%(ex)s WHERE tg=%(tg)s "
                            "AND (ex IS NULL OR ex='' OR ex < %(ex)s)",
                            {"ex": ex, "tg": t})
            except Exception as _e:
                logger.warning("rt_pull_sync 续期同步跳过(tg=%s): %s", t, _e)
        # 同步建档 kfc_members（实时用户名兜底 RT.username）
        for r in rtu:
            try:
                _xq("INSERT INTO kfcgame.kfc_members (tg, tg_name, tg_username, last_seen) "
                         "VALUES (%(tg)s, %(n)s, '', NOW()) "
                         "ON DUPLICATE KEY UPDATE tg_name=IF(VALUES(tg_name)<>'',VALUES(tg_name),tg_name), "
                         "last_seen=NOW()",
                         {"tg": int(r["tg_user_id"]), "n": r.get("username") or ""})
            except Exception:
                pass
    except Exception as e:
        return {"ok": False, "msg": str(e)[:100]}
    return {"ok": True, "new": n_new, "upd": n_upd,
            "msg": "RT→台账 补登 %d、回填 %d" % (n_new, n_upd)}


def rt_push_account(tg, emby_id, username, password="", days=30):
    """★ 高级：把 boss/game 建的 Emby 账号写入 RT 的 emby_users（让 ta 出现在 RT
    面板/RT bot）。只做 INSERT（绝不 UPDATE/DELETE），字段完全仿照 RT 自建号；
    已存在（emby_user_id / username / tg 任一命中）则跳过，天然幂等。"""
    import sqlite3
    tg = int(tg)
    username = str(username or "").strip()[:64]
    if not emby_id or not username:
        return {"ok": False, "msg": "缺 emby_id 或 username"}
    try:
        conn = sqlite3.connect(RT_DB, timeout=10)
        cur = conn.cursor()
        cur.execute("SELECT id FROM emby_users WHERE emby_user_id=? OR tg_user_id=? OR username=?",
                    (str(emby_id), tg, username))
        if cur.fetchone():
            conn.close()
            return {"ok": True, "skipped": True, "msg": "RT 已有该账号（幂等跳过）"}
        now = time.strftime("%Y-%m-%d %H:%M:%S.000000+08:00")
        exp = "" if not days else time.strftime(
            "%Y-%m-%d %H:%M:%S.000000+08:00", time.localtime(time.time() + days * 86400))
        cur.execute(
            "INSERT INTO emby_users (username, password, emby_user_id, emby_password, "
            " emby302_config_id, transfer_quota_on, transfer_usage, expiry_date, user_mode, "
            " bypass302, status, tg_user_id, created_at, updated_at, pan115_config_id, "
            " max_devices, allowed_modes, is_admin, points, is_whitelist, route_mode) "
            "VALUES (?,?,?,?,?,0,0,?, 'self_pan',0,'active',?,?,?, '1',2,'self_pan',0,0,0,'')",
            (username, "", str(emby_id), password or "", 1, exp or None, tg, now, now))
        conn.commit()
        rid = cur.lastrowid
        conn.close()
        oplog("web", "rt_push", "账号 %s(%s) 写入RT#%s" % (username, tg, rid), True, "RT 面板可见")
        return {"ok": True, "rt_id": rid, "msg": "已写入 RT（id=%s），RT 面板即时可见" % rid}
    except Exception as e:
        return {"ok": False, "msg": str(e)[:120]}


def rt_push_missing():
    """批量：把 boss 台账里已有 embyid 但 RT 没有的账号补进 RT（只 INSERT）。"""
    try:
        rows = _bossq("SELECT tg, embyid, name, pwd, ex FROM emby "
                      "WHERE embyid IS NOT NULL AND embyid<>'' AND name IS NOT NULL AND name<>''")
    except Exception as e:
        return {"ok": False, "msg": "读 boss 台账失败: %s" % str(e)[:60]}
    done, skipped = [], 0
    for r in rows:
        try:
            if int(r["tg"]) <= 0:
                continue
            rr = rt_push_account(r["tg"], r["embyid"], r["name"], r.get("pwd") or "", 0)
            if rr.get("ok") and not rr.get("skipped"):
                done.append(r["name"])
            elif rr.get("skipped"):
                skipped += 1
        except Exception:
            continue
    return {"ok": True, "pushed": done, "skipped": skipped,
            "msg": "新写入 RT %d 个，已存在跳过 %d 个" % (len(done), skipped)}


def rt_snapshot():
    """RT 关键配置的只读展示：线路/pan115/302/策略模板（Web 控制中心用）。"""
    out = {"lines": [], "pan115": [], "emby302": [], "templates": [], "checkin": {},
           # ★★ v1.25 S14：RT 账号池（用户原话：「你根本就看不到别人的状态，还有绑定的
           #   115账号等，这个你全部从RT里面给我设置好，并且他们的所有信息我应该都能
           #   看到才对。他们的用户名、密码我都应该能看到。」）
           "users": [], "users_total": 0, "pan115_full": []}
    try:
        # ★★ v1.25 S14（用户原话：「RT 的服务器线路我都说了要改 IPV4和88FRRP那个
        #   给删掉，我早就不用了」）。数据库是闭源 RT 的，media-hub **只读绝不改库**，
        #   所以这里做「展示层过滤」：内网 IP + 端口 的裸线路（ipv4 / 88frp）标记
        #   is_public=0 + drop=1，前端默认不渲染它们，只留公网域名线路。
        #   用户仍可在前端勾选「显示已停用/内网线路」把它们捞回来（只增不减）。
        def _line_public(u):
            """公网域名（https://xxx.tld[:port]）→ True；裸 IP 或 http+端口 → False"""
            u = str(u or '').strip().lower()
            if not u:
                return False
            host = u.split('//', 1)[-1].split('/', 1)[0].split(':', 1)[0]
            if not host:
                return False
            # 纯 IPv4 字面量 → 内网/裸 IP 线路
            import re as _re
            if _re.match(r'^\d{1,3}(\.\d{1,3}){3}$', host):
                return False
            # 域名但走 http + 非标端口（88frp 那种）也按"非公网站点"处理
            if u.startswith('http://') and ':' in u.split('//', 1)[-1].split('/', 1)[0]:
                return False
            return True
        # 命名黑名单：用户明说「IPV4和88FRRP那个给删掉，我早就不用了」
        # （这两条虽然 URL 一个是域名一个是裸 IP，但名字就是内网穿透通道，一并收起）
        _LINE_NAME_DROP = ('ipv4', 'ipv6', '88frp', 'frp', 'frpc', 'frps',
                           'natfrp', '内网', '穿透', 'tunnel')
        for r in _rtq("SELECT * FROM emby_access_lines ORDER BY id"):
            u = r["url"] or ''
            nm = str(r["name"] or '').strip().lower()
            is_pub = _line_public(u)
            name_drop = any(k in nm for k in _LINE_NAME_DROP)
            drop = 0 if (is_pub and not name_drop) else 1
            out["lines"].append({
                "id": r["id"], "name": r["name"], "url": u,
                "enabled": r["enabled"], "whitelist_only": r.get("whitelist_only"),
                "is_public": is_pub,
                # drop=1 → 前端默认隐藏（ipv4 / 88frp 这类用户明说不要的）
                "drop": drop,
            })
        out["pan115"] = [{"id": r["id"], "name": r["name"]}
                         for r in _rtq("SELECT id, name FROM pan115_configs ORDER BY id")]
        # ★★ v1.25 S14：115 盘位全量详情（用户要看到绑定的 115 账号）。
        #   cookie 只回传「长度 + 前后各 6 位」给前端做脱敏小眼睛，绝不整串下发。
        try:
            for r in _rtq("SELECT * FROM pan115_configs ORDER BY id"):
                ck = str(r.get("cookie") or "")
                out["pan115_full"].append({
                    "id": r["id"], "name": r["name"],
                    "cookie_len": len(ck),
                    "cookie_head": ck[:6], "cookie_tail": ck[-6:] if len(ck) > 12 else "",
                    "has_cookie": bool(ck),
                    "transfer_dir_name": r.get("transfer_dir_name") or "",
                    "offline_dir_name": r.get("offline_dir_name") or "",
                })
        except Exception:
            pass
        for r in _rtq("SELECT * FROM emby302_configs"):
            out["emby302"].append({
                "id": r["id"], "name": r["name"], "url": r["url"],
                "server_mode": r.get("server_mode"),
                "checkin_min": r.get("checkin_reward_min"),
                "checkin_max": r.get("checkin_reward_max"),
                "public_url": r.get("public_url")})
            if r["id"] == 1:
                out["checkin"] = {"min": r.get("checkin_reward_min"),
                                  "max": r.get("checkin_reward_max"),
                                  "mode": r.get("server_mode")}
        # ★★ v1.25 S14：RT 账号池列表（用户原话：「你根本就看不到别人的状态，还有
        #   绑定的115账号等，这个你全部从RT里面给我设置好，并且他们的所有信息我应该
        #   都能看到才对。他们的用户名、密码我都应该能看到。」）
        #   字段全部来自 RT emby_users（只读）。密码是 bcrypt 哈希的照原样回传
        #   （前端小眼睛默认打码）；RT 自己面板能看到的也就是这个，Web 端对齐。
        try:
            _p115 = {p["id"]: p["name"] for p in out["pan115_full"]}
            for r in _rtq(
                    "SELECT id,username,password,emby_user_id,emby_password,status,"
                    "expiry_date,user_mode,max_devices,tg_user_id,pan115_config_id,"
                    "last_play_at,points,is_admin,is_whitelist,route_mode,"
                    "allowed_libs,policy_template_id,remark,created_at "
                    "FROM emby_users ORDER BY id"):
                out["users"].append({
                    "id": r["id"], "username": r["username"] or '',
                    "password": r["password"] or '',
                    "emby_user_id": r["emby_user_id"] or '',
                    "emby_password": r["emby_password"] or '',
                    "status": r["status"] or '',
                    "expiry_date": r["expiry_date"] or '',
                    "user_mode": r["user_mode"] or '',
                    "max_devices": r["max_devices"],
                    "tg_user_id": r["tg_user_id"],
                    "tg_bound": bool(r["tg_user_id"]),
                    "pan115_id": r["pan115_config_id"],
                    "pan115_name": _p115.get(r["pan115_config_id"], ''),
                    "last_play_at": r["last_play_at"] or '',
                    "points": r["points"],
                    "is_admin": bool(r["is_admin"]),
                    "is_whitelist": bool(r["is_whitelist"]),
                    "route_mode": r["route_mode"] or '',
                    "allowed_libs": r["allowed_libs"] or '',
                    "policy_template_id": r["policy_template_id"],
                    "remark": r["remark"] or '',
                    "created_at": r["created_at"] or '',
                })
            out["users_total"] = len(out["users"])
        except Exception as e:
            out["users_err"] = str(e)[:80]
        out["templates"] = [{"id": r["id"], "name": r["name"],
                             "user_mode": r.get("user_mode"),
                             "max_devices": r.get("max_devices")}
                            for r in _rtq("SELECT * FROM emby_policy_templates ORDER BY id")]
        # 负载均衡/服务器核心设置（server_mode=线路分发策略、sync、安全限流）
        try:
            cfg1 = _rtq("SELECT * FROM emby302_configs WHERE id=1")
            if cfg1:
                r0 = cfg1[0]
                out["server"] = {
                    "server_mode": r0.get("server_mode"), "share_mode": r0.get("share_mode"),
                    "sync_enabled": r0.get("sync_enabled"), "sync_cron": r0.get("sync_cron"),
                    "sync_default_days": r0.get("sync_default_days"),
                    "enable_emby_native": r0.get("enable_emby_native"),
                    "lib_control_mode": r0.get("lib_control_mode"),
                    "checkin_enabled": r0.get("checkin_enabled"),
                    "checkin_min": r0.get("checkin_reward_min"), "checkin_max": r0.get("checkin_reward_max"),
                    "public_url": r0.get("public_url"), "url": r0.get("url"),
                    "auto_renew_enabled": r0.get("auto_renew_enabled"),
                    "auto_renew_cost": r0.get("auto_renew_cost"), "auto_renew_days": r0.get("auto_renew_days"),
                }
        except Exception:
            pass
        try:
            sec = {}
            for r in _rtq("SELECT key, value FROM system_configs "
                          "WHERE key LIKE 'security%' OR key LIKE 'emby_register%' "
                          "OR key LIKE 'transfer_quota%' OR key LIKE 'emby_default%'"):
                sec[r["key"]] = r["value"]
            out["security"] = sec
        except Exception:
            pass
    except Exception as e:
        out["err"] = str(e)[:80]
    return out


# ────────────────────── 每日 0 点备份 ──────────────────────
def _tg_send_one(tok, chat_id, text):
    """单机器人单条发送（经 Clash CONNECT 隧道，纯 stdlib）。返回 True/False。"""
    import socket as _sk, ssl as _ssl
    for pm in ("HTML", None):
        payload = {"chat_id": chat_id, "text": text[:4000],
                   "disable_web_page_preview": True}
        if pm:
            payload["parse_mode"] = pm
        body = json.dumps(payload).encode()
        try:
            _px = urllib.parse.urlparse(tmdb_proxy())
            k = _sk.create_connection((_px.hostname or '127.0.0.1', _px.port or 7893), timeout=12)
            k.sendall(b"CONNECT api.telegram.org:443 HTTP/1.1\r\n"
                      b"Host: api.telegram.org:443\r\n\r\n")
            buf = b""
            while b"\r\n\r\n" not in buf and len(buf) < 1024:
                d = k.recv(128)
                if not d:
                    break
                buf += d
            if b" 200" not in buf.split(b"\r\n")[0]:
                k.close()
                continue
            w = _ssl.create_default_context().wrap_socket(k, server_hostname="api.telegram.org")
            w.sendall(("POST /bot%s/sendMessage HTTP/1.1\r\n"
                       "Host: api.telegram.org\r\n"
                       "Content-Type: application/json\r\n"
                       "Content-Length: %d\r\nConnection: close\r\n\r\n"
                       % (tok, len(body))).encode() + body)
            resp = b""
            while True:
                d = w.recv(256)
                if not d:
                    break
                resp += d
            w.close()
            js = resp.split(b"\r\n\r\n", 1)[-1]
            if js and json.loads(js.decode("utf-8", "ignore")).get("ok"):
                return True
        except Exception:
            continue
    return False


def _tg_owner(text, token=None):
    """多机器人通知：依次发往 cfg.tg_bots 里所有启用的机器人（各自 token+chat_id）。
    兼容旧配置：无 tg_bots 时回退 cfg.tg_token → kfcgame config.json，目标 cfg.tg_owner。
    返回是否至少一个成功。"""
    owner = int(cfg().get('tg_owner') or os.environ.get('TG_OWNER_UID') or 0)
    targets = []
    # 显式 token
    if token:
        targets.append((str(token), owner))
    # 多机器人列表（用户在面板自填 token/chat_id）
    for b in (cfg().get('tg_bots') or []):
        try:
            if b.get('enabled', True) and b.get('token'):
                cid = b.get('chat_id')
                try:
                    cid = int(cid) if str(cid).strip() else owner
                except Exception:
                    cid = owner
                targets.append((str(b['token']), cid))
        except Exception:
            continue
    # 旧单机器人回退
    if not targets:
        toks = []
        try:
            toks.append(str(cfg().get('tg_token') or ''))
        except Exception:
            pass
        try:
            toks.append(str(json.load(open("/dockroot/kfcgame/config.json")).get("bot_token") or ""))
        except Exception:
            pass
        for t in [x for x in toks if x][:2]:
            targets.append((t, owner))
    if not targets:
        return False
    okany = False
    seen = set()
    for tok, chat in targets:
        key = (tok, chat)
        if key in seen:
            continue
        seen.add(key)
        if _tg_send_one(tok, chat, text):
            okany = True
    return okany


def tg_test():
    """★ v5 发送一条 TG 测试通知给群主（验证 token / UID 是否配对）。"""
    from datetime import datetime as _dt
    now = _dt.now().strftime('%F %T')
    tok = str(cfg().get('tg_token') or '')
    owner = cfg().get('tg_owner') or os.environ.get('TG_OWNER_UID') or ''
    src = '自定义 Bot Token' if tok else 'kfcgame 内置机器人'
    text = ("🧪 <b>TG 通知测试</b>\n\n"
            "如果你收到了这条消息，说明通知链路已打通 ✅\n\n"
            "📅 %s\n🤖 来源：%s\n👤 目标 UID：<code>%s</code>\n\n"
            "以后 bot 求片、更新公告、备份私发都会走这个通道。"
            % (now, src, owner))
    ok = _tg_owner(text)
    return {'ok': ok,
            'msg': ('测试消息已发送（%s）' % src) if ok else
                   '发送失败：请检查 TG Bot Token / 目标 UID 是否正确（填了 Token 就必须配对同一个 Bot 创建的 UID）',
            'owner': owner, 'src': src}


def _wx_push(item_id, text):
    """双通道私发群主：① web_inbox 信箱（game bot 60s 轮询兜底）
    ② 直连 Telegram sendMessage（token 借用 game 配置）——秒到。"""
    try:
        _tg_owner(text)
    except Exception as e:
        logger.debug("直发群主失败（走信箱兜底）: %s", e)
    try:
        f = "/dockroot/kfcgame/keepalive/web_inbox.json"
        raw = {}
        if os.path.exists(f):
            try:
                raw = json.load(open(f, encoding="utf-8"))
            except Exception:
                raw = {}
        items = raw.get("items") or []
        if len(items) > 40:
            items = items[-40:]
        items.append({"id": item_id, "text": text, "ts": time.time()})
        raw["items"] = items
        tmp = f + ".tmp"
        json.dump(raw, open(tmp, "w", encoding="utf-8"), ensure_ascii=False)
        os.replace(tmp, f)
        return True
    except Exception as e:
        logger.warning("web_inbox 写入失败: %s", e)
        return False


def _mailbox_cmd(item_id, cmd, **extra):
    """往 bot 信箱投一条「动作」条目（2026-06 新增）。

    与 _wx_push 的区别：不带 text，而是带 cmd —— bot 的 mailbox 轮询到后
    直接执行对应动作（目前只有 ka_refresh = 立刻重抓保号/魔力值），
    不再往群里/私聊发文字。用于「Web 点按钮 → bot 立刻干活」这类联动。
    """
    try:
        f = "/dockroot/kfcgame/keepalive/web_inbox.json"
        raw = {}
        if os.path.exists(f):
            try:
                raw = json.load(open(f, encoding="utf-8"))
            except Exception:
                raw = {}
        items = raw.get("items") or []
        if len(items) > 40:
            items = items[-40:]
        items.append(dict({"id": item_id, "cmd": cmd, "ts": time.time()}, **extra))
        raw["items"] = items
        tmp = f + ".tmp"
        json.dump(raw, open(tmp, "w", encoding="utf-8"), ensure_ascii=False)
        os.replace(tmp, f)
        return True
    except Exception as e:
        logger.warning("web_inbox cmd 写入失败: %s", e)
        return False


def _dump_db_pymysql(dbname, outpath):
    """纯 Python mysqldump（media-hub 无 docker CLI）：结构+数据全量。
    root 账号跨库可用。返回 (ok, bytes)。"""
    import pymysql
    # ★★ 开源脱敏：不内置任何 root 密码。由环境变量 DB_ROOT_PASSWORD 或
    #   webcfg.json 的 db_root_pass 提供；全新部署在设置页/引导向导填写。
    RW = dict(host=_pt_db()['host'], port=_pt_db()['port'], user='root',
              password=(cfg().get('db_root_pass') or os.environ.get('DB_ROOT_PASSWORD', '')),
              charset='utf8mb4',
              connect_timeout=10)
    total = 0
    try:
        conn = pymysql.connect(**RW, database=dbname)
        with open(outpath, "w", encoding="utf-8") as f:
            f.write("-- KFC unified dump %s db=%s\nSET NAMES utf8mb4;\n"
                    "SET FOREIGN_KEY_CHECKS=0;\n" % (time.strftime("%F %T"), dbname))
            cur = conn.cursor()
            cur.execute("SHOW TABLES")
            tables = [r[0] for r in cur.fetchall()]
            for t in tables:
                cur.execute("SHOW CREATE TABLE `%s`" % t)
                ddl = cur.fetchone()[1]
                f.write("DROP TABLE IF EXISTS `%s`;\n%s;\n" % (t, ddl))
                cur.execute("SELECT * FROM `%s`" % t)
                cols = [d[0] for d in cur.description]
                while True:
                    rows = cur.fetchmany(500)
                    if not rows:
                        break
                    for r in rows:
                        vals = []
                        for v in r:
                            if v is None:
                                vals.append("NULL")
                            elif isinstance(v, (int, float)):
                                vals.append(str(v))
                            else:
                                sv = str(v)
                                vals.append("'" + sv.replace("\\", "\\\\")
                                            .replace("'", "\\'") + "'")
                        f.write("INSERT INTO `%s` (%s) VALUES (%s);\n"
                                % (t, ", ".join("`%s`" % c for c in cols),
                                   ", ".join(vals)))
            f.write("SET FOREIGN_KEY_CHECKS=1;\n")
        conn.close()
        total = os.path.getsize(outpath)
        return total > 100, total
    except Exception as e:
        logger.warning("pymysql dump %s 失败: %s", dbname, e)
        return False, 0


def backup_once():
    """统一每日备份：kfcgame+pt2cloud（纯Python dump）、embyboss 复用 boss 原生
    每日备份文件、RT 官方 sqlite backup、四份关键 config → tar.gz。
    返回 (tgz, size, detail, ok数)。"""
    ts = time.strftime("%Y%m%d-%H%M%S")
    os.makedirs(BK_DIR, exist_ok=True)
    ddir = os.path.join(BK_DIR, "raw_" + ts)
    os.makedirs(ddir, exist_ok=True)
    detail, ok = [], 0
    # ① kfcgame + pt2cloud：pymysql 全量
    for dbname in ("kfcgame", "pt2cloud"):
        pth = os.path.join(ddir, dbname + ".sql")
        o, sz = _dump_db_pymysql(dbname, pth)
        if o:
            ok += 1
            detail.append("%s %.0fKB" % (dbname, sz / 1024))
        else:
            detail.append("%s ❌" % dbname)
    # ② embyboss：拿 boss 自己每天 02:30 的最新备份；没有则现 dump
    try:
        bdir = "/dockroot/embyboss/db_backup"
        files = sorted([f for f in os.listdir(bdir) if f.endswith(".sql")])
        if files:
            srcf = os.path.join(bdir, files[-1])
            data = open(srcf, "rb").read()
            open(os.path.join(ddir, "embyboss.sql"), "wb").write(data)
            ok += 1
            detail.append("embyboss %.0fKB(复用%s)" % (len(data)/1024, files[-1][:23]))
        else:
            raise RuntimeError("no native")
    except Exception:
        o, sz = _dump_db_pymysql("embyboss", os.path.join(ddir, "embyboss.sql"))
        if o:
            ok += 1
            detail.append("embyboss %.0fKB(现dump)" % (sz / 1024))
        else:
            detail.append("embyboss ❌")
    # ③ RT sqlite：python3 官方在线备份（media-hub 自带 python3 + sqlite3 模块）
    rtdst = os.path.join(ddir, "resourcetool.db")
    try:
        import sqlite3
        src = sqlite3.connect("file:%s?mode=ro" % RT_DB, uri=True, timeout=10)
        dst = sqlite3.connect(rtdst)
        src.backup(dst)
        dst.close(); src.close()
        if os.path.getsize(rtdst) > 10000:
            ok += 1
            detail.append("RT %.0fMB" % (os.path.getsize(rtdst) / 1048576))
        else:
            detail.append("RT ❌")
    except Exception as e:
        detail.append("RT ❌ %s" % str(e)[:30])
    # ④ configs（含 kfcgame secrets/state → cookie 全量）
    for name, src in (("boss_config", "/dockroot/embyboss/config.json"),
                      ("game_config", "/dockroot/kfcgame/config.json"),
                      ("ka_secrets", "/dockroot/kfcgame/keepalive/secrets.json"),
                      ("ka_state", "/dockroot/kfcgame/keepalive/state.json"),
                      ("hub_config", CFG)):
        try:
            data = open(src, "rb").read()
            open(os.path.join(ddir, name + ".json"), "wb").write(data)
        except Exception:
            pass
    # ⑤ tar + 清理 + 保留 7 份
    tgz = os.path.join(BK_DIR, "kfcdb_%s.tar.gz" % ts)
    rc = run("tar czf '%s' -C '%s' . 2>/dev/null && rm -rf '%s'" % (tgz, ddir, ddir), t=300)
    size = os.path.getsize(tgz) if os.path.exists(tgz) else 0
    if size:
        ok += 1
    try:
        olds = sorted([f for f in os.listdir(BK_DIR) if f.startswith("kfcdb_")])
        for f in olds[:-7]:
            fp = os.path.join(BK_DIR, f)
            if fp != tgz:
                os.remove(fp)
        for d in sorted([x for x in os.listdir(BK_DIR) if x.startswith("raw_")]):
            dp = os.path.join(BK_DIR, d)
            if os.path.isdir(dp):
                shutil.rmtree(dp, ignore_errors=True)
    except Exception:
        pass
    return tgz, size, "、".join(detail), ok


def backup_loop():
    """每 60 秒检查一次，跨过 0 点触发当天备份（date 幂等，重启不重发）。"""
    last_day = None
    while True:
        try:
            day = time.strftime("%Y%m%d")
            h = time.localtime().tm_hour
            if day != last_day and h == 0:
                last_day = day
                logger.info("每日备份启动 %s", day)
                tgz, size, detail, ok = backup_once()
                mb = size / 1048576.0
                txt = ("🗄 <b>每日数据库备份 %s</b>\n"
                       "━━━━━━━━━━━━\n"
                       "📦 产物｜<code>%s</code>（%.1f MB）\n"
                       "🧩 内容｜%s\n"
                       "🧾 路径｜/vol1/1000/docker/kfcgame/backups/" % (day, os.path.basename(tgz) if size else "失败", mb, detail))
                _wx_push("bk-" + day, txt)
                logger.info("每日备份完成 %.1fMB ok=%s", mb, ok)
            elif last_day is None and h >= 1:
                last_day = day  # 启动时已过零点，今天不补跑（避免重启风暴）
        except Exception as e:
            logger.warning("备份循环异常: %s", e)
        time.sleep(60)



# ────────────────────── boss → RT 续期同步 + RT HTTP 操作 ──────────────────────
# RT 管理面板 HTTP API（:29999）。一律走 HTTP（绝不直写 RT sqlite）：
# login / renew / set_cookie / create，与 kfcgame 的 rtapi 同语义。
# 作用：boss（EmbyBoss）在 Web/机器人里续期后，台账 embyboss.emby.ex 变化，
# 这里定期对账把「比 RT 更晚的到期」补续到 RT，实现三端（BS/GX/RT）全同步。
# ★★ 开源脱敏：RT 连接不内置作者账号/密码/内网地址。
#   由环境变量 RT_URL / RT_USER / RT_PASS 或 webcfg.json 同名键提供；
#   全新部署在设置页填写自己的 RT，未配置则该功能不点亮（不影响其它模块）。
RT_HTTP = {"url": os.environ.get("RT_URL", ""),
           "user": os.environ.get("RT_USER", ""),
           "pass": os.environ.get("RT_PASS", "")}

_RT_TK = {"t": "", "ts": 0.0}
_RT_TK_LOCK = threading.Lock()


def _rt_token():
    """登录 RT 取 Bearer token（6h 缓存）。返回 token 或 ''。"""
    now = time.time()
    with _RT_TK_LOCK:
        if _RT_TK["t"] and now - _RT_TK["ts"] < 6 * 3600:
            return _RT_TK["t"]
    import urllib.request as _ur
    try:
        data = json.dumps({"username": RT_HTTP["user"],
                           "password": RT_HTTP["pass"]}).encode()
        req = _ur.Request(RT_HTTP["url"].rstrip("/") + "/api/auth/login",
                          data=data, headers={"Content-Type": "application/json"},
                          method="POST")
        with _ur.urlopen(req, timeout=20) as resp:
            j = json.loads(resp.read().decode() or "{}")
        tk = (j or {}).get("token") or ""
        if tk:
            with _RT_TK_LOCK:
                _RT_TK["t"] = tk
                _RT_TK["ts"] = time.time()
        return tk
    except Exception as e:
        logger.warning("RT 登录失败: %s", e)
        return ""


def _rt_http_req(method, path, body=None):
    """RT HTTP 请求（带 Bearer）。返回 (status, json)。"""
    import urllib.request as _ur, urllib.error as _ue
    tk = _rt_token()
    if not tk:
        return 0, {"message": "RT 登录失败"}
    url = RT_HTTP["url"].rstrip("/") + path
    data = json.dumps(body).encode() if body is not None else None
    hdr = {"Authorization": "Bearer " + tk, "Accept": "application/json"}
    if data is not None:
        hdr["Content-Type"] = "application/json"
    try:
        req = _ur.Request(url, data=data, headers=hdr, method=method)
        with _ur.urlopen(req, timeout=40) as r:
            return r.status, json.loads(r.read().decode() or "{}")
    except _ue.HTTPError as e:
        try:
            j = json.loads(e.read().decode() or "{}")
        except Exception:
            j = {"message": "HTTP %s" % e.code}
        return e.code, j
    except Exception as e:
        return 0, {"message": str(e)[:80]}


def _rt_find_id(tg_user_id):
    st, j = _rt_http_req("GET", "/api/admin/emby-users?page=1&page_size=200&config_id=1")
    if st != 200:
        return None
    for u in (j.get("data") or []):
        if int(u.get("tg_user_id") or 0) == int(tg_user_id):
            return u.get("id")
    return None


def rt_http_renew(tg, days):
    """给 RT 用户续期 days 天（加 days）。返回 dict。"""
    uid = _rt_find_id(tg)
    if uid is None:
        return {"ok": False, "msg": "RT 中无该 TG 用户"}
    st, j = _rt_http_req("POST", "/api/admin/emby-users/renew",
                         {"ids": [uid], "days": int(days)})
    if st not in (200, 201):
        return {"ok": False, "msg": "RT 续期失败：%s" % ((j or {}).get("message") or st)}
    return {"ok": True, "msg": "RT 已续 %d 天" % int(days)}


def rt_set_cookie(tg, cookie):
    """给 RT 用户设置/清除 115 cookie。返回 dict。"""
    uid = _rt_find_id(tg)
    if uid is None:
        return {"ok": False, "msg": "RT 中无该 TG 用户"}
    st, j = _rt_http_req("GET", "/api/admin/emby-users?page=1&page_size=200&config_id=1")
    if st != 200:
        return {"ok": False, "msg": "RT 读取失败"}
    u = next((x for x in (j.get("data") or []) if int(x.get("tg_user_id") or 0) == int(tg)), None)
    if not u:
        return {"ok": False, "msg": "RT 中无该 TG 用户"}
    body = {k: u.get(k) for k in (
        "username", "emby302_config_id", "policy_template_id", "user_mode",
        "allowed_modes", "status", "cache_path", "transfer_quota_on",
        "is_whitelist", "is_admin", "bypass302", "remark", "recycle_code",
        "emby_user_id", "max_devices", "tg_user_id")}
    body["cookie115"] = cookie or ""
    body["pan115_config_id"] = 0
    st2, j2 = _rt_http_req("PUT", "/api/admin/emby-users/%s" % uid, body)
    if st2 not in (200, 201):
        return {"ok": False, "msg": "RT 更新失败：%s" % ((j2 or {}).get("message") or st2)}
    return {"ok": True, "msg": "已绑定 115 cookie" if cookie else "已清除 115 cookie"}


def rt_create_account(tg, username, password, days=30, policy_template_id=1,
                      user_mode="shared", allowed_modes="shared", max_devices=2,
                      cookie115="", pan115_config_id=0, remark="Web 开号"):
    """在 RT 建号（同时建 Emby 账号），并回填 boss 台账→三端互通。返回 dict。"""
    from datetime import datetime, timedelta
    tg = int(tg)
    body = {
        "username": str(username)[:64], "password": password,
        "emby302_config_id": 1, "policy_template_id": int(policy_template_id),
        "user_mode": user_mode, "allowed_modes": allowed_modes,
        "status": "active", "cookie115": cookie115 or "",
        "pan115_config_id": int(pan115_config_id), "cache_path": "/ResourceTool",
        "transfer_quota_on": False,
        "expiry_date": (datetime.now() + timedelta(days=int(days))).strftime("%Y-%m-%dT%H:%M:%S"),
        "is_whitelist": False, "is_admin": False, "bypass302": False,
        "remark": remark, "recycle_code": "", "emby_user_id": "",
        "max_devices": int(max_devices), "tg_user_id": tg,
    }
    st, j = _rt_http_req("POST", "/api/admin/emby-users", body)
    if st not in (200, 201):
        return {"ok": False, "msg": "RT 建号失败：%s" % ((j or {}).get("message") or st)}
    d = j.get("data") or {}
    eid = str(d.get("emby_user_id") or "")
    if not eid:
        return {"ok": False, "msg": "RT 返回无 emby_user_id"}
    try:
        exp = (datetime.now() + timedelta(days=int(days))).strftime("%Y-%m-%d %H:%M:%S")
        _bossq("INSERT INTO emby (tg, embyid, name, pwd, pwd2, lv, cr, ex, us, iv) "
               "VALUES (%(tg)s, %(eid)s, %(n)s, %(p)s, %(p)s, 'b', NOW(), %(ex)s, 0, 0) "
               "ON DUPLICATE KEY UPDATE embyid=VALUES(embyid), name=VALUES(name), "
               "pwd=VALUES(pwd), pwd2=VALUES(pwd2), lv=IF(lv='c','c','b'), ex=VALUES(ex)",
               {"tg": tg, "eid": eid[:32], "n": str(username)[:64],
                "p": str(password)[:64], "ex": exp})
    except Exception as e:
        logger.warning("RT 建号回填台账失败: %s", e)
    return {"ok": True, "emby_user_id": eid, "username": username,
            "expiry_date": d.get("expiry_date"), "msg": "RT 建号成功，已回填台账"}


def rt_edit(tg, user_mode, allowed_modes, max_devices, pan115_config_id):
    """编辑 RT 用户的 115/模式配置（user_mode/allowed_modes/max_devices/pan115）。
    仅通过 RT 的 PUT /api/admin/emby-users/{id} 修改，绝不直接写 RT 的 SQLite。"""
    tg = int(tg)
    uid = _rt_find_id(tg)
    if uid is None:
        return {"ok": False, "msg": "RT 中无该 TG 用户"}
    st, j = _rt_http_req("GET", "/api/admin/emby-users?page=1&page_size=200&config_id=1")
    if st != 200:
        return {"ok": False, "msg": "RT 读取失败"}
    u = next((x for x in (j.get("data") or []) if int(x.get("tg_user_id") or 0) == int(tg)), None)
    if not u:
        return {"ok": False, "msg": "RT 中无该 TG 用户"}
    body = {k: u.get(k) for k in (
        "username", "emby302_config_id", "policy_template_id", "user_mode",
        "allowed_modes", "status", "cache_path", "transfer_quota_on",
        "is_whitelist", "is_admin", "bypass302", "remark", "recycle_code",
        "emby_user_id", "max_devices", "tg_user_id")}
    # 保留已有 115 cookie，不覆盖
    body["cookie115"] = u.get("cookie115") or ""
    body["user_mode"] = user_mode
    body["allowed_modes"] = allowed_modes
    body["max_devices"] = int(max_devices)
    body["pan115_config_id"] = int(pan115_config_id)
    st2, j2 = _rt_http_req("PUT", "/api/admin/emby-users/%s" % uid, body)
    if st2 not in (200, 201):
        return {"ok": False, "msg": "RT 更新失败：%s" % ((j2 or {}).get("message") or st2)}
    # best-effort：RT 专属字段(user_mode/max_devices/pan115)不在统一台账 emby 表中，
    # 这里仅保持 embyid 映射同步，确保三端互通；失败不影响主流程
    try:
        eid = str(u.get("emby_user_id") or "")[:32]
        if eid:
            _bossq("UPDATE emby SET embyid=%(eid)s WHERE tg=%(tg)s "
                   "AND (embyid IS NULL OR embyid='' OR embyid<>%(eid)s)",
                   {"tg": tg, "eid": eid})
    except Exception as e:
        logger.warning("rt_edit 同步台账 embyid 失败: %s", e)
    return {"ok": True, "msg": "已更新 RT 用户配置"}


def rt_sync_renewals():
    """对账：把 boss 台账(embyboss.emby)里已续的到期时间同步到 RT。
    仅当台账到期 > RT 当前到期时才续（加差值天数），幂等、不会重复续。"""
    n_synced = n_skip = n_err = 0
    detail = []
    try:
        rows = _bossq("SELECT tg, ex FROM embyboss.emby "
                      "WHERE tg IS NOT NULL AND tg>0 AND lv IN ('b','c')")
    except Exception as e:
        return {"ok": False, "msg": "读台账失败: %s" % str(e)[:80]}
    rt_map = {}
    try:
        for r in _rtq("SELECT tg_user_id, expiry_date FROM emby_users "
                      "WHERE tg_user_id IS NOT NULL AND tg_user_id<>0"):
            rt_map[int(r["tg_user_id"])] = r.get("expiry_date") or ""
    except Exception as e:
        return {"ok": False, "msg": "读 RT 失败: %s" % str(e)[:80]}
    for r in rows:
        tg = int(r["tg"])
        ex = r.get("ex")
        if ex is None:
            continue
        ex = str(ex)
        if not ex or ex.startswith("0000-00-00"):
            continue
        ex = ex[:19]
        rt_ex = rt_map.get(tg) or ""
        if not rt_ex or str(rt_ex).startswith("0000-00-00"):
            continue
        rt_ex = str(rt_ex)[:19]
        if not rt_ex:
            continue
        try:
            lt = time.mktime(time.strptime(ex, "%Y-%m-%d %H:%M:%S"))
            lrt = time.mktime(time.strptime(rt_ex, "%Y-%m-%d %H:%M:%S"))
        except Exception:
            n_err += 1
            continue
        if lt <= lrt:
            n_skip += 1
            continue
        days = max(1, int((lt - lrt) / 86400) + 1)
        rr = rt_http_renew(tg, days)
        if rr.get("ok"):
            n_synced += 1
            detail.append("tg=%d +%dd" % (tg, days))
        else:
            n_err += 1
            detail.append("tg=%d ❌%s" % (tg, str(rr.get("msg", ""))[:24]))
    return {"ok": True, "synced": n_synced, "skip": n_skip, "err": n_err,
            "detail": detail[:20], "msg": "同步 %d、跳过 %d、失败 %d" % (n_synced, n_skip, n_err)}


def _rt_sync_loop():
    """每 6 小时：① RT→台账 单向补登（只读 RT）② boss 续期→RT 对账同步。"""
    time.sleep(90)          # 启动错峰
    while True:
        try:
            r = rt_pull_sync()
            if r.get("new") or r.get("upd"):
                logger.info("RT 定时补登: %s", r.get("msg"))
        except Exception as e:
            logger.warning("RT 补登异常: %s", e)
        try:
            rr = rt_sync_renewals()
            if rr.get("synced") or rr.get("err"):
                logger.info("boss→RT 续期对账: %s", rr.get("msg"))
        except Exception as e:
            logger.warning("boss→RT 续期对账异常: %s", e)
        time.sleep(6 * 3600)

# ══════════════════════════════════════════════════════════════
#  ☁️ Cloud Cookie 实时通道（2026-10-15 用户拍板：Web 实时读取展示 + 推送 MP，
#  作为油猴抓取之外的备用主通道）。
#   · cc_live()   —— 直连 CC 服务器解密，按域名映射出「每站点 cookie 数 +
#                     关键项 + 抓取时间」，60s 缓存，Web 秒开。
#   · cc_apply_mp —— 把 CC 里的站点 cookie 推给 MoviePilot（PUT /api/v1/site/，
#                     与 ccpull 同链路但**即时**，用户点一下 MP 就活）。
#   · cc_apply_keepalive —— 顺带刷进保号 secrets（merge，保 HttpOnly/cf）。
#  数据源结构（实测）：cookie_data={'m-team.cc':[{name,value,domain,path,...}]}
#  local_storage_data={'kp.m-team.cc': {auth/did/visitorId...}}
# ══════════════════════════════════════════════════════════════
CC_CACHE = {"data": None, "ts": 0.0}
CC_TTL = 60


def _cc_walk_cookies(obj, _out=None):
    """CC cookie_data 递归展开 → [(domain, [cookie,...])]。
    兼容 {domain:[...]} 与 {uid:{domain:[...]}} 两种结构。"""
    out = _out if _out is not None else []
    if isinstance(obj, dict):
        for k, v in obj.items():
            if isinstance(v, list):
                out.append((str(k), v))
            elif isinstance(v, dict):
                _cc_walk_cookies(v, out)
    return out


def _cc_domain_site(dom):
    """CC 域名 → (类别, 站点id / 网盘名)。复用 COOKIE_DOMAIN_MAP + 泛化。"""
    d = (dom or "").lower().lstrip(".")
    for key, val in (COOKIE_DOMAIN_MAP or {}).items():
        if d == key or d.endswith("." + key):
            return val
    if d in ("115.com", "115cdn.com", "115vod.com", "webapi.115.com",
             "proapi.115.com", "my.115.com", "a.115.com"):
        return ("netdisk", "115")
    if "115" in d:
        return ("netdisk", "115")
    return None


def cc_live(force=False):
    """实时读取 CC 解密数据 → 站点展示结构。返回 {ok, domains, sites, mteam, update_time}。"""
    now = time.time()
    if not force and CC_CACHE["data"] is not None and now - CC_CACHE["ts"] < CC_TTL:
        return CC_CACHE["data"]
    try:
        dec = _cc_fetch_decrypted()
    except Exception as e:
        return {"ok": False, "msg": str(e)[:100]}
    if not dec:
        return {"ok": False, "msg": "CC 服务器不可达或未解密成功"}
    cd = dec.get("cookie_data") or {}
    ls = dec.get("local_storage_data") or {}
    domains, sites = [], {}
    pairs = _cc_walk_cookies(cd)
    keynames = {"cookie": 1, "phpbb3": 1, "passkey": 1, "cf_clearance": 1,
                "uid": 1, "token": 1, "auth": 1, "ssid": 1, "sess": 1}
    for dom, cklist in pairs:
        if not isinstance(cklist, list):
            continue
        m = _cc_domain_site(dom)
        n = len(cklist)
        names = [str(c.get("name") or "") for c in cklist if isinstance(c, dict)]
        keys = [x for x in names if any(k in x.lower() for k in keynames)][:6]
        domains.append({"domain": dom, "n_cookie": n, "site": m[1] if m else "",
                        "kind": m[0] if m else "", "key_names": keys})
        if m and m[0] == "pt" and n:
            sid = m[1]
            cur = sites.setdefault(sid, {"site": sid, "n_cookie": 0, "domains": []})
            cur["n_cookie"] += n
            cur["domains"].append(dom)
    # M-Team：localStorage 三件套单独展示
    mt = {"has_jwt": False, "has_did": False, "iat": "", "exp_left": 0}
    for k, v in (ls.items() if isinstance(ls, dict) else []):
        if "m-team" in str(k).lower() and isinstance(v, dict) and v.get("auth"):
            try:
                import base64 as _b64, json as _j
                pl = str(v["auth"]).split(".")[1]
                pl += "=" * (-len(pl) % 4)
                dd = _j.loads(_b64.urlsafe_b64decode(pl))
                mt.update(has_jwt=True,
                          has_did=bool(v.get("did") and v.get("visitorId")),
                          iat=time.strftime("%m-%d %H:%M", time.localtime(dd.get("iat") or 0)),
                          exp_left=round(((dd.get("exp") or 0) - now) / 86400, 1))
            except Exception:
                mt.update(has_jwt=True)
            break
    out = {"ok": True, "update_time": dec.get("update_time"),
           "n_domains": len(domains), "domains": domains[:24],
           "sites": sites, "mteam": mt,
           "pushed_at": CC_CACHE.get("pushed_at")}
    CC_CACHE.update(data=out, ts=now)
    return out


def cc_apply(target="mp"):
    """Cloud Cookie 一键应用：
       target=mp        → 站点 cookie 推进 MoviePilot（PUT /api/v1/site/）
       target=keepalive → merge 进保号 secrets.json（油猴通道同一落点）
       target=both      → 两个都做。返回各站点成功明细。"""
    dec = _cc_fetch_decrypted()
    if not dec:
        return {"ok": False, "msg": "CC 不可达"}
    cd = dec.get("cookie_data") or {}
    pairs = _cc_walk_cookies(cd)
    if not pairs:
        return {"ok": False, "msg": "CC 里没有任何 cookie 数据"}
    by_site = {}
    for dom, cklist in pairs:
        m = _cc_domain_site(dom)
        if not m or m[0] != "pt" or not cklist:
            continue
        sid = m[1]
        buf = by_site.setdefault(sid, {})
        for c in cklist:
            if isinstance(c, dict) and c.get("name"):
                buf[str(c["name"])] = str(c.get("value") or "")
    done, errs = [], []
    if target in ("mp", "both"):
        try:
            rsites = mp_call("/api/v1/site/")
            _d = rsites.get("data") if isinstance(rsites, dict) else rsites
            if isinstance(_d, list):
                rlist = _d
            elif isinstance(_d, dict):
                rlist = _d.get("sites") or []
            else:
                rlist = rsites.get("sites") if isinstance(rsites, dict) else []
            for stg in rlist:
                if not isinstance(stg, dict):
                    continue
                sid = _site_domain_key(str(stg.get("domain") or ""))
                if sid in by_site:
                    ck = "; ".join("%s=%s" % (k, v) for k, v in by_site[sid].items())
                    body = dict(stg)
                    body["cookie"] = ck
                    mp_call("/api/v1/site/", method="PUT", body=body)
                    done.append(sid)
        except Exception as e:
            errs.append("MP: %s" % str(e)[:80])
    if target in ("keepalive", "both"):
        try:
            sec = _ck_read_secrets()
            for sid, buf in by_site.items():
                st = sec.setdefault("sites", {}).setdefault(sid, {})
                old = st.get("cookies") or {}
                old.update(buf)
                st["cookies"] = old
                st["cookie_ts"] = time.time()
                st.setdefault("bound", True)
            _ck_write_secrets(sec)
            done.append("secrets:%d站" % len(by_site))
        except Exception as e:
            errs.append("secrets: %s" % str(e)[:80])
    CC_CACHE["pushed_at"] = time.time()
    CC_CACHE["data"] = None
    try:
        oplog('cookie', 'ccapply', 'Cloud Cookie 应用 → %s' % target,
              bool(done),
              '站点 %s；%s' % (','.join(by_site.keys()) or '无',
                              ('已应用:' + '、'.join(done)) if done else '无变化'))
    except Exception:
        pass
    return {"ok": bool(done), "applied": done, "sites": list(by_site.keys()),
            "msg": ("已应用：%s" % "、".join(done)) if done else "没有可应用的站点",
            "errors": errs}


def _site_domain_key(domain):
    """MP 站点 domain → 保号站点 id（与 COOKIE_DOMAIN_MAP 对齐）"""
    d = (domain or "").lower().lstrip(".")
    for key, val in (COOKIE_DOMAIN_MAP or {}).items():
        if d == key or d.endswith("." + key):
            if val[0] == "pt":
                return val[1]
    return ""



# ── CookieCloud 直连通道（localStorage / JWT） ──────────────────
# MP 的 CookieCloud 同步只解析 cookie_data，local_storage_data 被整体丢弃；
# M-Team 2026-10 全站迁移（NexusPHP → SPA + API）后，登录态是浏览器
# localStorage 里的 JWT（localStorage['auth']），必须由 media-hub 直连
# CC 服务器取解密明文（POST /get/{uuid}，body 带 password）。
# ★★ v1.37 S2 开源脱敏：CookieCloud 的地址/UUID/密码默认值全部清空，
#   改由引导向导或设置页填写。环境变量可预置（docker-compose / .env）。
CC_SERVER_DEFAULT = os.environ.get('CC_SERVER', '')
CC_UUID_DEFAULT = os.environ.get('CC_UUID', '')
CC_PASSWORD_DEFAULT = os.environ.get('CC_PASSWORD', '')


def _cc_cfg():
    c = cfg()
    return ((c.get('cc_server') or CC_SERVER_DEFAULT).rstrip('/'),
            c.get('cc_uuid') or CC_UUID_DEFAULT,
            c.get('cc_password') or CC_PASSWORD_DEFAULT)


def _cc_fetch_decrypted():
    """CC 服务器 POST /get/{uuid}（body 带 password）→ 解密后数据 dict；失败 None"""
    server, uuid, pwd = _cc_cfg()
    if not uuid or not pwd:
        return None
    req = urllib.request.Request(
        '%s/get/%s' % (server, uuid),
        data=json.dumps({'password': pwd}).encode(),
        method='POST', headers={'Content-Type': 'application/json'})
    opener = urllib.request.build_opener(urllib.request.ProxyHandler({}))  # 内网直连
    try:
        with opener.open(req, timeout=20) as r:
            j = json.loads(r.read().decode('utf-8', 'replace'))
        return j if isinstance(j, dict) else None
    except Exception as e:
        logger.warning('CC 直连解密失败: %s', e)
        return None


def _cc_mteam_ls(dec):
    """从 CC 解密数据提取 kp.m-team.cc 的 localStorage 三件套：
    auth(JWT) / did(设备指纹) / visitorId。返回 (jwt, did, vid, update_time)。"""
    if not dec:
        return None, "", "", None
    ls = dec.get('local_storage_data')
    if not ls:
        return None, "", "", None
    if isinstance(ls, dict):
        items = list(ls.items())
    elif isinstance(ls, list):
        items = [(x.get('domain') or x.get('key') or '', x)
                 for x in ls if isinstance(x, dict)]
    else:
        items = []
    for key, val in items:
        if 'm-team' not in str(key).lower():
            continue
        data = val
        if isinstance(val, str):
            try:
                data = json.loads(val)
            except Exception:
                continue
        if isinstance(data, dict):
            auth = data.get('auth')
            if isinstance(auth, str) and auth.startswith('eyJ'):
                return (auth, str(data.get('did') or ''),
                        str(data.get('visitorId') or ''), dec.get('update_time'))
    return None, "", "", None


def _mt_beacon_probe(jwt, did="", vid=""):
    """实测一次 updateLastBrowse（与 bot 的保号信标同协议），验证 JWT+设备指纹
    是否有效。返回 (ok, code, msg)。"""
    import hashlib as _hl
    import hmac as _hm
    import base64 as _b64
    SECRET = "HLkPcWmycL57mfJt"
    ts = int(time.time() * 1000)
    msg = f"POST&/api/member/updateLastBrowse&{ts}".encode()
    sgn = _b64.b64encode(_hm.new(SECRET.encode(), msg, _hl.sha1).digest()).decode()
    fp = _hl.sha256((jwt or "").encode()).hexdigest()
    hdr = {"Content-Type": "application/x-www-form-urlencoded; charset=UTF-8",
           "Accept": "application/json, text/plain, */*",
           "Authorization": jwt, "Origin": "https://kp.m-team.cc",
           "Referer": "https://kp.m-team.cc/index", "Ts": str(ts // 1000),
           "webversion": "2000", "Did": did or fp[:32],
           "visitorid": vid or fp[32:],
           "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120 Safari/537.36"}
    try:
        import urllib.request as _ur
        body = ("_timestamp=%s&_sgin=%s" % (ts, urllib.parse.quote(sgn, safe=""))).encode()
        req = _ur.Request("https://api.m-team.cc/api/member/updateLastBrowse",
                          data=body, headers=hdr, method="POST")
        with urllib.request.urlopen(req, timeout=25) as resp:
            raw = resp.read().decode("utf-8", "ignore")
        try:
            j = json.loads(raw)
        except Exception:
            return False, "?", "非JSON响应"
        code = str(j.get("code"))
        m = str(j.get("message") or "")
        if j.get("success") is True or code == "0" or m.upper() == "SUCCESS" \
                or (code == "1" and m.upper() == "FAIL"):
            return True, code, "保号信标成功"
        if code == "401":
            return False, code, "JWT 会话被站点撤销（401），浏览器重新登录后再试"
        return False, code, m[:60] or "接口未确认"
    except Exception as e:
        return False, "ERR", str(e)[:80]


def mteam_verify(source="cc", pasted_jwt="", did="", vid=""):
    """★ 馒头 JWT「验证 + 生效」一条龙（Web 一键按钮用）。

    source=cc     → 从 CookieCloud 拉浏览器同步的 auth/did/visitorId
    source=manual → 用手动粘贴的 jwt（浏览器 F12→Application→Local Storage→
                    localStorage.getItem('auth') 抄出来的那串）
    流程：拿到 JWT → 实测保号信标 → 通过才写入 secrets.json（bot 立即可用）
          → 清掉 bot 的 last_error（解除红色告警）。不通过则原样返回原因。
    """
    jwt, use_did, use_vid = "", did or "", vid or ""
    if source == "manual":
        jwt = (pasted_jwt or "").strip()
        if not jwt or not jwt.startswith("eyJ"):
            return {'ok': False, 'msg': '粘贴内容不像 JWT（应以 eyJ 开头）。'
                    '浏览器 F12 → Console 执行 localStorage.getItem("auth") 复制全部'}
    else:
        try:
            dec = _cc_fetch_decrypted()
        except Exception as e:
            return {'ok': False, 'msg': 'CC 拉取失败：%s' % str(e)[:80]}
        jwt, ccd, ccv, upd = _cc_mteam_ls(dec)
        use_did = use_did or ccd
        use_vid = use_vid or ccv
        if not jwt:
            return {'ok': False, 'msg': 'CC 里没有 M-Team localStorage——'
                    '浏览器需装 CookieCloud 扩展并开 localStorage 同步，'
                    '登录 kp.m-team.cc 后点「上传数据」'}
    ok, code, msg = _mt_beacon_probe(jwt, use_did, use_vid)
    if not ok:
        return {'ok': False, 'jwt_head': jwt[:12] + '...', 'code': code,
                'msg': '实测失败：%s' % msg}
    # 生效：写 secrets（jwt + 真实设备指纹一起落盘）
    sec = _ck_read_secrets()
    mt = sec.setdefault('sites', {}).setdefault('mteam', {})
    mt['jwt'] = jwt
    mt['jwt_ts'] = time.time()
    if use_did:
        mt['did'] = use_did
    if use_vid:
        mt['visitorid'] = use_vid
    _ck_write_secrets(sec)
    # 解除 bot 告警态：清 last_error + bound + last_login 记本次成功
    def _clr(x, j=jwt):
        ss = x.setdefault('sites', {}).setdefault('mteam', {})
        if str(ss.get('last_error') or ''):
            ss['last_error'] = ''
        ss['bound'] = True
        ss['last_login'] = time.time()
        return True
    _ka_write_state(_clr)
    return {'ok': True, 'msg': 'JWT 实测通过并已生效（bot 告警已解除）',
            'did': bool(use_did), 'jwt_head': jwt[:12] + '...'}


def _cc_mteam_jwt(dec):
    """从 CC 解密数据提取 M-Team 的 JWT（localStorage['auth']）。
    local_storage_data 形如 {'LS-kp.m-team.cc': {'auth': 'eyJ...'}}，
    兼容 dict / list 两种历史结构。返回 (jwt, update_time)。"""
    if not dec:
        return None, None
    ls = dec.get('local_storage_data')
    if not ls:
        return None, None
    if isinstance(ls, dict):
        items = list(ls.items())
    elif isinstance(ls, list):
        items = [(x.get('domain') or x.get('key') or '', x)
                 for x in ls if isinstance(x, dict)]
    else:
        items = []
    for key, val in items:
        if 'm-team' not in str(key).lower():
            continue
        data = val
        if isinstance(val, str):
            try:
                data = json.loads(val)
            except Exception:
                continue
        if isinstance(data, dict):
            auth = data.get('auth')
            if isinstance(auth, str) and auth.startswith('eyJ'):
                return auth, dec.get('update_time')
    return None, None


def _cc_pull_mteam_jwt(sec):
    """把 CC 里 M-Team 的 JWT + 设备指纹合并进 sec['sites']['mteam']（自愈版）。

    ★ 2026-10-14 重写：旧版盲目写入 JWT，但馒头 JWT 是设备绑定的——浏览器
    重新登录会撤销旧会话（401），光有 JWT 不够，还得带上同一浏览器的
    did/visitorId。现在：
      1. 取 CC 三件套（auth / did / visitorId）；
      2. 只在「本地无 JWT」或「bot 报了 JWT 错」或「CC 明显更新」时才尝试；
      3. 写入前**实测保号信标**，通过才落盘（含 did/vid），并清 bot 告警；
      4. 不通过则保持原样，返回真实原因（避免把好 JWT 被坏 CC 顶掉）。
    """
    dec = _cc_fetch_decrypted()
    jwt, did, vid, upd = _cc_mteam_ls(dec)
    if not jwt:
        return {'jwt': False, 'changed': False,
                'msg': 'CC 未采到 M-Team localStorage（扩展需开 localStorage 同步并重新登录）'}
    st_mt = sec.setdefault('sites', {}).setdefault('mteam', {})
    cur = (st_mt.get('jwt') or '').strip()
    cur_ts = float(st_mt.get('jwt_ts') or 0)
    stt = _ka_read_state()
    err = str(((stt.get('sites') or {}).get('mteam') or {}).get('last_error') or '')
    jwt_broken = bool(err) and ('JWT' in err or '会话' in err or 'authentication' in err.lower())
    upd_ts = 0
    if upd:
        try:
            upd_ts = time.mktime(time.strptime(str(upd)[:19], '%Y-%m-%dT%H:%M:%S')) + time.timezone
        except Exception:
            upd_ts = 0
    # 同 JWT 且没报错 → 只补设备指纹（不重复实测，省流量）
    if cur == jwt and not jwt_broken:
        if did and vid and (st_mt.get('did') != did or st_mt.get('visitorid') != vid):
            st_mt['did'], st_mt['visitorid'] = did, vid
            return {'jwt': True, 'changed': True, 'msg': '补齐设备指纹 did/visitorId'}
        return {'jwt': True, 'changed': False, 'msg': '本地 JWT 与 CC 相同（跳过）'}
    # 需要尝试：本地没有 / JWT 坏了 / CC 更新 → 实测后择优写入
    if not jwt_broken and cur and not (upd_ts and upd_ts > cur_ts + 300):
        return {'jwt': True, 'changed': False, 'msg': '本地 JWT 更新（跳过覆盖）'}
    ok, code, vmsg = _mt_beacon_probe(jwt, did, vid)
    if not ok:
        # 信标失败但 apikey 若仍可用 → 账号没危险，只是这个浏览器会话被撤销。
        # 保持 last_error 不变（真实状态，告警已做 24h 冷却），不动 last_login。
        return {'jwt': True, 'changed': False, 'code': code,
                'msg': 'CC JWT 实测未通过（%s），保持原值' % vmsg[:40]}
    st_mt['jwt'] = jwt
    st_mt['jwt_ts'] = time.time()
    if did:
        st_mt['did'] = did
    if vid:
        st_mt['visitorid'] = vid

    # 实测通过 → 顺带解除 bot 红色告警（下轮 tick 就会成功）
    def _clr(x):
        ss = x.setdefault('sites', {}).setdefault('mteam', {})
        if str(ss.get('last_error') or ''):
            ss['last_error'] = ''
        ss['bound'] = True
        ss['last_login'] = time.time()
        return True
    _ka_write_state(_clr)
    return {'jwt': True, 'changed': True, 'verified': True,
            'msg': 'M-Team JWT 实测通过并生效（含设备指纹），告警已解除'}


def cc_pull_to_secrets():
    """CookieCloud 全自动：从 MP 拉取已同步的站点 Cookie，merge 进 kfcgame secrets.json；
    M-Team 新版（SPA + API）额外直连 CC 服务器拉 localStorage 里的 JWT。
    MP 侧已完成 CookieCloud 解密（COOKIECLOUD_* 已配置并验证），cookie 部分直接复用，
    无需本地解密；localStorage 部分 MP 会丢弃，故由本服务直连 CC 取解密明文。
    每 60 分钟由 _cc_pull_loop 自动执行；也可手动 POST /api/cookie/ccpull 触发。
    """
    try:
        r = mp_call('/api/v1/site/')
    except Exception as e:
        logger.warning('CC→secrets 拉取失败: %s', e)
        return {'ok': False, 'msg': str(e)}
    if not r.get('ok'):
        return {'ok': False, 'msg': r.get('msg', 'MP 调用失败')}
    sites = r.get('data') or []
    if not isinstance(sites, list):
        return {'ok': False, 'msg': 'MP 返回结构异常'}
    sec = _ck_read_secrets()
    n = 0
    for s in sites:
        dom = (s.get('domain') or '').lower().strip()
        ck_str = s.get('cookie') or ''
        kind, sid = COOKIE_DOMAIN_MAP.get(dom, (None, None))
        if kind != 'pt' or not sid or not ck_str:
            continue
        ck = _parse_cookie(ck_str)
        if not ck:
            continue
        st = sec.setdefault('sites', {}).setdefault(sid, {})
        st.setdefault('cookies', {}).update(ck)
        if ck.get('passkey') and not st.get('passkey'):
            st['passkey'] = ck['passkey']
        _ka_write_state(lambda x, sid=sid: (
            x.setdefault('sites', {}).setdefault(sid, {}).__setitem__('bound', True) or x))
        _ka_write_state(lambda x, sid=sid: (
            x.setdefault('sites', {}).setdefault(sid, {}).__setitem__('cookie_ts', time.time()) or x))
        n += 1
    # 补 passkey：有 cookie 但无 passkey 的 PT 站，用 cookie 抓站点页面提取
    # （CookieCloud 只同步 cookie、不同步 passkey；NexusPHP 的 passkey 在下载链接/usercp 页）。
    # 每站最多 6 小时重试一次，避免每小时自动循环频繁打站点。
    cfg = {c.get('id'): c for c in (_ka_read_state().get('_cfg') or [])}
    now = time.time()
    grabbed = 0
    for sid, st in (sec.get('sites') or {}).items():
        if st.get('passkey') or not st.get('cookies'):
            continue
        if now - float(st.get('pk_try') or 0) < 6 * 3600:
            continue
        home = (cfg.get(sid) or {}).get('home') or ''
        if not home:
            continue
        st['pk_try'] = now
        pk = _cc_grab_passkey(home, st.get('cookies'))
        if pk:
            st['passkey'] = pk
            grabbed += 1
            logger.info('CC passkey 自动补全：%s', sid)
    # M-Team 新版（SPA + API 认证）：apikey 从 MP 站点同步（profile 统计用），
    # JWT 从 CC localStorage 直连获取（updateLastBrowse 保号用）
    mt_ak = ''
    for s in sites:
        if 'm-team' in (s.get('domain') or '').lower():
            mt_ak = (s.get('apikey') or '').strip()
            break
    mt_changed = False
    if mt_ak and (sec.setdefault('sites', {}).setdefault('mteam', {}).get('apikey') != mt_ak):
        sec['sites']['mteam']['apikey'] = mt_ak
        mt_changed = True
        logger.info('M-Team apikey 已从 MP 同步到 secrets.json')
    jr = _cc_pull_mteam_jwt(sec)
    if jr.get('changed'):
        mt_changed = True
        # 清掉 bot 的 JWT 失效标记，下一轮 tick 自动重试保号
        _ka_write_state(lambda x: (x.setdefault('sites', {}).setdefault('mteam', {})
                                   .__setitem__('last_error', '') or x))
        logger.info('M-Team JWT 已从 CC 写入 secrets.json')
    if n or grabbed or mt_changed:
        _ck_write_secrets(sec)
    return {'ok': True,
            'msg': '已从 MP 同步 %d 站 cookie、补 %d 站 passkey；M-Team：%s'
                   % (n, grabbed, jr.get('msg')),
            'n': n, 'passkey': grabbed, 'mteam': jr}


# 版本升级公告（与 bot 读同一份 changelog.json，rw 挂载免部署）
def changelog_get():
    """读取 kfcgame 保号目录里的 changelog.json。找不到返回空壳。
    ★ v4 联动：附带 bot_synced 与 bot_shown_version，让前端展示推送状态。"""
    # ★★ v1.42 开源兼容：作者机器的保号目录放第一位；
    #   开源部署时那个路径不存在，必须兜底到容器内的 /app/changelog.json
    #   （Dockerfile COPY web/changelog.json /app/changelog.json）。
    #   之前只写了作者路径 → 新装用户 /api/changelog 恔底返回
    #   ok:false / data:null，前端版本号与更新公告全空。
    paths = ['/dockroot/kfcgame/keepalive/changelog.json']
    try:
        paths.append(KA_SECRET_PATH.replace('secrets.json', 'changelog.json'))
    except Exception:
        pass
    paths.append(os.path.join(HERE, 'changelog.json'))
    paths.append('/app/changelog.json')
    paths.append('/data/changelog.json')
    cur_ver = None
    for path in paths:
        try:
            with open(path, encoding='utf-8') as f:
                d = json.load(f)
            if isinstance(d, dict) and d.get('version'):
                cur_ver = d.get('version')
                # 读取 bot 记录的「已展示版本」（bot 存的是字符串，不是 dict）
                state_path = path.replace('changelog.json', 'state.json')
                shown_ver = ''
                bot_synced = True
                try:
                    if os.path.exists(state_path):
                        st_data = json.load(open(state_path, encoding='utf-8'))
                        shown_ver = str(st_data.get('changelog_shown') or '')
                        bot_synced = bool(cur_ver) and bool(shown_ver) and (shown_ver == cur_ver)
                except Exception:
                    pass
                return {'ok': True, 'data': d,
                        'meta': {'bot_synced': bot_synced, 'bot_shown_version': shown_ver,
                                 'current_version': cur_ver, 'source_path': path}}
        except Exception:
            continue
    return {'ok': False, 'data': None, 'msg': '暂无更新公告'}


def selftest_get():
    """读取 kfcgame 自检日志（rw 挂载，bot 每次启动自动写）。"""
    paths = ['/dockroot/kfcgame/keepalive/selftest_log.json']
    for path in paths:
        try:
            with open(path, encoding='utf-8') as f:
                d = json.load(f)
            if isinstance(d, dict) and 'results' in d:
                return {'ok': True, 'data': d}
        except Exception:
            continue
    return {'ok': False, 'data': None, 'msg': '暂无自检日志'}


def changelog_bounce():
    """★ v4 立刻把当前 changelog 私聊推送群主（不依赖 bot 重启）。
    实现：调用 kfcgame_changelog 模块的渲染逻辑，文本走 _tg_owner 直发。
    推送成功后：把 changelog_shown 标记为当前版本（与 bot 行为一致），避免重启重复推。"""
    d = changelog_get()
    if not d.get('ok'):
        return {'ok': False, 'msg': 'changelog.json 不可读'}
    a = d['data']
    ver = a.get('version', '')
    parts = [f"🚀 KFC 影音 v{ver} · {a.get('title','')}"]
    if a.get('date'): parts.append(f"📅 {a['date']}")
    for s in (a.get('sections') or []):
        ic = s.get('icon', '•'); nm = s.get('name', '')
        parts.append(f"\n{ic} <b>{nm}</b>")
        for it in (s.get('items') or [])[:6]:
            parts.append(f"  • {it}")
    parts.append("\n💡 详情见 media-hub「更新公告」面板")
    text = "\n".join(parts)
    ok = _tg_owner(text)
    # 推送成功后标记已展示（与 bot 行为一致）
    if ok and ver:
        for path in ['/dockroot/kfcgame/keepalive/state.json',
                     KA_SECRET_PATH.replace('secrets.json', 'state.json')]:
            try:
                st_data = {}
                if os.path.exists(path):
                    try: st_data = json.load(open(path, encoding='utf-8'))
                    except Exception: st_data = {}
                st_data['changelog_shown'] = ver
                tmp = path + '.tmp'
                json.dump(st_data, open(tmp, 'w', encoding='utf-8'), ensure_ascii=False)
                os.replace(tmp, path)
            except Exception:
                pass
    return {'ok': ok, 'msg': '已私聊推送' if ok else '推送失败（TG 通道异常）', 'version': ver}


def changelog_reset_sync():
    """★ v4 清除 bot 「已展示版本」记录，下次 bot 启动会重新推送本版本。"""
    paths = ['/dockroot/kfcgame/keepalive/state.json']
    try:
        paths.append(KA_SECRET_PATH.replace('secrets.json', 'state.json'))
    except Exception:
        pass
    for path in paths:
        try:
            st_data = {}
            if os.path.exists(path):
                try:
                    st_data = json.load(open(path, encoding='utf-8'))
                except Exception:
                    st_data = {}
            # 与 bot 保持一致：changelog_shown 是字符串版本号
            st_data['changelog_shown'] = ''
            tmp = path + '.tmp'
            json.dump(st_data, open(tmp, 'w', encoding='utf-8'), ensure_ascii=False)
            os.replace(tmp, path)
            return {'ok': True, 'msg': '同步记录已重置', 'path': path}
        except Exception as e:
            continue
    return {'ok': False, 'msg': 'state.json 不可写'}


def _e(s):
    return str(s).replace('&', '&amp;').replace('<', '&lt;').replace('>', '&gt;')


def selftest_page():
    """自检日志的自包含 HTML 页面（/selftest）。"""
    d = selftest_get().get('data') or {}
    if not d:
        body = '<p style="color:#94a3b8">暂无自检日志（bot 启动后会自动生成）</p>'
    else:
        rows = ''
        for r in d.get('results', []):
            icon = '✅' if r['ok'] else '❌'
            color = '#22c55e' if r['ok'] else '#ef4444'
            rows += ('<tr><td style="color:%s;font-size:18px;width:24px">%s</td>'
                     '<td style="color:#e5e7eb">%s</td>'
                     '<td style="color:#94a3b8;font-size:13px">%s</td></tr>'
                     % (color, icon, _e(r['name']), _e(r['detail'])))
        ts = _e(d.get('ts', ''))
        passed = d.get('passed', 0)
        total = d.get('total', 0)
        head = ('通过 <b style="color:#22c55e">%d/%d</b>' % (passed, total)) + (
            '' if passed == total else ' · 失败 <b style="color:#ef4444">%d</b>' % (total - passed))
        body = ('<h2 style="color:#fff;margin:0 0 6px">🧪 KFC bot 自检报告</h2>'
                '<p style="color:#cbd5e1">%s · %s · ver %s</p>'
                '<table style="width:100%%;border-collapse:collapse;margin-top:10px">%s</table>'
                % (head, ts, _e(str(d.get('version', ''))), rows))
    return ('<!DOCTYPE html><html lang="zh"><head><meta charset="utf-8">'
            '<meta name="viewport" content="width=device-width,initial-scale=1">'
            '<title>KFC bot 自检</title>'
            '<style>body{font-family:-apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;'
            'background:#0b0f1a;color:#e5e7eb;padding:24px;max-width:920px;margin:auto}'
            'table{border-collapse:collapse}td{padding:9px 12px;border-bottom:1px solid #1f2937;'
            'vertical-align:top}</style></head><body>' + body + '</body></html>')


