COOKIE_GRABBER_JS = """// ==UserScript==
// @name         KFC Cookie 抓取器
// @namespace    https://kfc.local
// @version      1.1
// @description  一键抓取当前站点 Cookie + localStorage 上报到 media-hub（支持 PT 站与 115 网盘）
// @match        *://*/*
// @downloadURL  __HUB__/api/cookie/user.js
// @updateURL    __HUB__/api/cookie/user.js
// @grant        none
// ==/UserScript==

(function () {
  'use strict';
  var INGEST = '__HUB__/api/cookie/ingest';
  var TOKEN  = 'kfccookiehub';

  function toast(msg, ok) {
    var t = document.createElement('div');
    t.textContent = msg;
    t.style.cssText = 'position:fixed;right:12px;bottom:54px;z-index:2147483647;' +
      'background:' + (ok ? '#2e7d32' : '#c62828') + ';color:#fff;padding:8px 12px;' +
      'border-radius:8px;font:13px/1.4 sans-serif;max-width:340px;box-shadow:0 2px 8px rgba(0,0,0,.35);';
    document.body.appendChild(t);
    setTimeout(function () { t.remove(); }, 4500);
  }

  function grab() {
    try {
      var domain = location.hostname;
      var cookie = document.cookie || '';
      var local = {};
      try {
        for (var i = 0; i < localStorage.length; i++) {
          var k = localStorage.key(i);
          local[k] = localStorage.getItem(k);
        }
      } catch (e) {}
      var payload = JSON.stringify({ token: TOKEN, domain: domain, cookie: cookie, local: local });
      fetch(INGEST, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: payload
      }).then(function (r) { return r.json(); }).then(function (j) {
        if (j && j.ok) toast('✅ ' + (j.msg || '已上报') + '（' + (j.site || '') + '）', true);
        else toast('❌ ' + ((j && j.msg) || '上报失败'), false);
      }).catch(function (e) { toast('❌ 网络错误：' + e.message, false); });
    } catch (e) { toast('❌ ' + e.message, false); }
  }

  function mount() {
    if (document.getElementById('kfc_ck_btn')) return;
    var b = document.createElement('div');
    b.id = 'kfc_ck_btn';
    b.textContent = '🍪 抓Cookie';
    b.title = 'KFC：抓取本站 Cookie 上报到 media-hub';
    b.style.cssText = 'position:fixed;right:12px;bottom:12px;z-index:2147483647;' +
      'background:#ff6a00;color:#fff;padding:8px 12px;border-radius:8px;' +
      'font:14px/1.2 sans-serif;cursor:pointer;box-shadow:0 2px 8px rgba(0,0,0,.35);user-select:none;';
    b.addEventListener('click', grab);
    document.body.appendChild(b);
  }

  if (document.body) mount();
  else window.addEventListener('DOMContentLoaded', mount);
})();
"""

