def do_action(svc, act, arg=None):
    if svc in ACTIONS:
        return ACTIONS[svc]['fn'](act, arg)
    # 未注册服务走通用容器动作（支持对任意容器做启停/日志/统计）
    return act_generic(svc, act, arg)


# ★★★ 2026-10-24 P0：自杀防护必须在「入队之前」拦截。
#   v1.28 把防护写在 ctr_action() 里，但 /api/action 的异步分支是先 submit()
#   后执行 → 作业真正跑到 ctr_action 时容器已被重启，作业丢失 → 「防护」变侥幸。
#   现在收口成一个纯函数，在路由入口（入队前）先拦，executor 里再兜底拦一次。
_CTR_SELF_NAME = 'media-hub'
_CTR_DENY_SET = {'media-hub', 'localhost', 'host', 'media-hub:local', 'mediahub'}
_CTR_DESTRUCTIVE = {'stop', 'restart', 'kill', 'pause', 'remove', 'rm', 'delete'}


def _resolve_svc_cname(svc):
    """svc 既可能是服务键（moviepilot）也可能是裸容器名（moviepilot-v3）。"""
    c = (containers().get(svc) or {}).get('cname') or svc
    # 兼容别人直接传 docker 容器名
    for v in containers().values():
        if v.get('cname') == svc:
            c = svc
            break
    return c


def ctr_self_guard(svc, act):
    """命中返回错误 dict，未命中返回 None。只拦破坏性动作，读操作放行。"""
    cname = _resolve_svc_cname(str(svc or ''))
    base = cname.split('/')[-1]
    if act in _CTR_DESTRUCTIVE and (base in _CTR_DENY_SET or base == _CTR_SELF_NAME):
        return {'ok': False, 'blocked': True,
                'msg': '禁止操作 media-hub 自身（会断开本面板，已拦截）'}
    return None


# ══════════════════════ 工作流 ══════════════════════
def workflow():
    lg = tail(2500)
    rq = host_of('/主号/待整理/PT/求片')
    req = []
    if os.path.isdir(rq):
        for site in sorted(os.listdir(rq))[:12]:
            sp = os.path.join(rq, site)
            if not os.path.isdir(sp):
                continue
            for cat in sorted(os.listdir(sp))[:12]:
                cp = os.path.join(sp, cat)
                if not os.path.isdir(cp):
                    continue
                for t in sorted(os.listdir(cp))[:40]:
                    req.append('%s/%s/%s' % (site, cat, t))
    with db() as c:
        rt = [dict(r) for r in c.execute(
            "SELECT id,profile_id,total_files,done_files FROM organize_tasks WHERE status='running'")]
        tstat = {r['status']: r['n'] for r in c.execute("SELECT status,count(*) n FROM organize_tasks GROUP BY status")}
        ststat = {r['status']: r['n'] for r in c.execute("SELECT status,count(*) n FROM strm_tasks GROUP BY status")}
    doing = []
    for l in lg:
        if '批量转移' in l.get('msg', ''):
            d = l.get('destDir') or ''
            if d and d not in doing:
                doing.append(d)
    ov = {x['key']: x for x in svc_overview()}
    stages = []

    def stage(key, name, icon, desc, cnt, items, need):
        o = ov.get(key, {})
        stages.append({'key': key, 'svc': key, 'icon': icon, 'name': name, 'desc': desc,
                       'count': cnt, 'items': items, 'need': need,
                       'online': bool(o.get('running')), 'addr': o.get('addr'),
                       'ctr': o.get('ctr')})

    stage('moviepilot', '求片', '🎯', 'MoviePilot 自动订阅写入 115', len(req), req[:8], None)
    stage('qbittorrent', '下载', '⬇️', 'qBittorrent 下载 PT 内容', None, [], None)
    stage('clouddrive2', '转存', '☁️', 'CloudDrive2 转存到待整理', len(req), [], None)
    stage('mediatidy', '整理', '🎬', 'MediaTidy 识别→命名→洗版', rec_count(), doing[:8], None)
    stage('avdb', '刮削', '📚', 'avdb 元数据刮削', None, [], None)
    stage('emby', '入库', '📺', 'Emby 扫库入库', None, [], None)
    stage('mediatidy', 'STRM', '🔗', '生成 .strm 供播放器直连', ststat.get('done', 0), [], None)
    return {'stages': stages, 'task_status': tstat, 'strm_status': ststat, 'running': rt}


def workflow_run(stages):
    """按用户选择的工作流节点，依次触发真实动作；返回每节点结果（供前端逐步展示）。"""
    order = ['moviepilot', 'qbittorrent', 'clouddrive2', 'mediatidy', 'avdb', 'emby']
    steps = [x for x in order if x in (stages or order)]
    results = []
    for s in steps:
        try:
            if s == 'moviepilot':
                r = act_mp('refresh_subs', None)
            elif s == 'qbittorrent':
                r = act_qb('reannounce', None)
            elif s == 'clouddrive2':
                r = act_cd2('fuse_check', None)
            elif s == 'mediatidy':
                r = act_mt('scan', None)
            elif s == 'avdb':
                r = act_avdb('health', None)
            elif s == 'emby':
                r = act_emby('emby', 'refresh', None)
            else:
                r = {'ok': False, 'msg': '未知节点 %s' % s}
        except Exception as e:
            r = {'ok': False, 'msg': '节点 %s 异常：%s' % (s, e)}
        results.append({'stage': s, 'ok': r.get('ok'), 'msg': r.get('msg')})
    ok_n = sum(1 for x in results if x['ok'])
    return {'ok': True, 'msg': '工作流执行完成：%d/%d 节点成功' % (ok_n, len(results)),
            'data': {'results': results}}


def workflow_heal():
    """全链路自愈：逐段检测卡点并触发可安全自动化的修复，返回每步结果。"""
    plan = [
        ('求片(MP刷新订阅)', lambda: act_mp('refresh_subs', None)),
        ('下载(qB重新汇报)', lambda: act_qb('reannounce', None)),
        ('上云(CD2清缓存)', lambda: act_cd2('clear_cache', None)),
        ('整理(MT疏通队列)', lambda: act_mt('unblock', None)),
        ('整理(MT清僵尸)', lambda: act_mt('clean_zombie', None)),
        ('入库(Emby刷新)', lambda: act_emby('emby', 'refresh', None)),
    ]
    results = []
    for name, fn in plan:
        try:
            r = fn()
            results.append({'step': name, 'ok': bool(r.get('ok') if isinstance(r, dict) else True),
                            'msg': (r.get('msg') if isinstance(r, dict) else str(r))[:160]})
        except Exception as e:
            results.append({'step': name, 'ok': False, 'msg': '异常：%s' % e})
    ok_n = sum(1 for x in results if x['ok'])
    return {'ok': True, 'msg': '自愈完成：%d/%d 步成功' % (ok_n, len(results)),
            'data': {'results': results}}


def features_summary():
    """功能中心聚合：把查库 / 站点 / 保号 / 流水线 等能力汇总暴露到 Web。"""
    out = {'ok': True, 'sections': []}
    # 1) 查库（Emby 画质）
    out['sections'].append({
        'key': 'libcheck', 'name': 'Emby 查库（画质）', 'icon': '🔎',
        'desc': '按片名查 Emby 库是否已存在，并解析分辨率/来源/编码/HDR',
        'endpoint': '/api/libcheck?title=<片名>', 'need': 'emby_key'})
    # 2) PT 站点状态
    sec = {'key': 'sites', 'name': 'PT 站点状态', 'icon': '🛰️',
           'desc': 'MoviePilot 已激活站点与保号状态', 'items': []}
    try:
        r = mp_api('/api/v1/site/')
        data = (r.get('data') or []) if isinstance(r, dict) else []
        if isinstance(data, dict):
            data = data.get('data') or []
        for s in (data or [])[:20]:
            if isinstance(s, dict):
                sec['items'].append({'name': s.get('name') or s.get('site_name'),
                                      'active': s.get('active'), 'bound': s.get('bound')})
    except Exception:
        pass
    out['sections'].append(sec)
    # 3) 保号（发电）状态
    sec = {'key': 'keepalive', 'name': '保号（发电）状态', 'icon': '🔋',
           'desc': '各 PT 站保号/辅种执行状态', 'items': []}
    try:
        r = keepalive_sites()
        if isinstance(r, dict):
            sec['items'] = (r.get('items') or r.get('sites') or [])[:20]
    except Exception:
        pass
    out['sections'].append(sec)
    # 4) 全链路流水线
    try:
        wf = workflow()
        out['sections'].append({
            'key': 'pipeline', 'name': '入库流水线', 'icon': '⚙️',
            'desc': '求片→下载→归类→上云→整理→入库 全链路',
            'endpoint': '/api/workflow', 'stages': wf.get('stages')})
    except Exception as e:
        out['sections'].append({'key': 'pipeline', 'name': '入库流水线', 'icon': '⚙️',
                                'desc': str(e), 'stages': []})
    return out




# ══════════════════════ HTTP ══════════════════════
# ══════════════════════ 深度巡检（代理链路 / 流水线 / 限流 / 资源）══════════════════════
# 设计原则：
#   1. 只读。任何检查都不改 MediaTidy 配置、不动115、不重启容器。
#   2. 每条异常都带「手动解决步骤」；可安全自动化的额外给 auto_ok，由用户在页面勾选授权。
#   3. 改配置类动作（换端口、调配速、改 delay）一律 auto_ok=False，只能手动。

PROXY_HOST_DEFAULT = os.environ.get('PROXY_HOST', '')
PROXY_PORT_MAIN = 7893          # MT 实际使用
PROXY_PORT_ALT = 7890           # 备用
AUTOF_SNAP = '/data/health_snap.json'

# 关键域名矩阵：mode=proxy 必须走代理；mode=direct 必须直连；mode=opt 建议代理
DOMAIN_MATRIX = [
    {'host': 'api.themoviedb.org', 'mode': 'proxy', 'why': 'TMDB 识别，直连被 DNS 污染（解析到 Facebook 段）'},
    {'host': 'api.telegram.org', 'mode': 'proxy', 'why': 'TG 播报，直连被污染到 31.13.73.9'},
    {'host': 'ff.mediatidy.dpdns.org', 'mode': 'proxy', 'why': 'MT 主授权服务器（Cloudflare），直连基本超时'},
    {'host': 'image.tmdb.org', 'mode': 'opt', 'why': '海报图，代理更快'},
    {'host': 'raw.githubusercontent.com', 'mode': 'opt', 'why': '规则/元数据，代理明显更快'},
    {'host': 'mediahelp-authcode.tymd.fun', 'mode': 'direct', 'why': '备用授权（腾讯 EdgeOne 新加坡），直连 0.6s 可用'},
    {'host': 'ff.84295588.xyz', 'mode': 'direct', 'why': '备用授权服务器，当前服务器自身宕机'},
    {'host': 'webapi.115.com', 'mode': 'direct', 'why': '115 主接口，直连 0.16s；走代理反而增风控'},
    {'host': '115cdn.com', 'mode': 'direct', 'why': '115 CDN，直连即可'},
]

# ══════════════ 2026-10-16 深度排查 v2：风暴归因 / STRM健康 / 队列霸占 / 资源 探测 ══════════════
# 10-16 实测「整理慢 + 文件管理转圈」后补的探测。慢的真凶往往不是 MT 本身：
#   ①队列被巨型垃圾任务霸占（task1226 跑 16h）②CD2 被 403 流风暴占满 FUSE worker
#   ③STRM 全量批挂了没人发现（atomically replace 失败）④Emby 重启后全库扫描/外部抽帧读爆 115
# 每项带影响因素(causes)与修复方法(fixes)；命中白名单的可被 /api/deep/autofix 一键全自动执行。
# 注意：media-hub 容器无 docker CLI，一律走 dk()（Engine API over socket）与 MT DB。

def _loadavg():
    try:
        l1, l5, l15 = os.getloadavg()
        return {'l1': round(l1, 2), 'l5': round(l5, 2), 'cores': os.cpu_count() or 0}
    except Exception:
        return {}


def _meminfo():
    try:
        d = {}
        for ln in open('/proc/meminfo'):
            k, v = ln.split(':', 1)
            d[k] = int(v.strip().split()[0])  # kB
        tot = d.get('MemTotal') or 0
        swt = d.get('SwapTotal') or 0
        return {'mem_pct': round(100.0 * (1 - (d.get('MemAvailable') or 0) / tot), 1) if tot else 0,
                'swap_used_mb': round((swt - (d.get('SwapFree') or 0)) / 1024.0) if swt else 0,
                'swap_pct': round(100.0 * (swt - (d.get('SwapFree') or swt)) / swt, 1) if swt else 0}
    except Exception:
        return {}


def _iowait():
    try:
        def snap():
            f = open('/proc/stat').readline().split()
            return int(f[5]), sum(int(x) for x in f[1:])
        io1, t1 = snap()
        time.sleep(0.4)
        io2, t2 = snap()
        dt = t2 - t1
        return round(100.0 * (io2 - io1) / dt, 1) if dt > 0 else 0.0
    except Exception:
        return -1.0


READER_CONTAINERS = ['emby-main', 'emby-adult', 'embyboss', 'framebase', 'clouddrive2', 'mediatidy']


def _container_stats(cnames):
    """CPU% / 内存（docker Engine API，stream=false 单次快照）。"""
    out = {}
    for nm in cnames:
        try:
            st, b = dk('GET', '/containers/%s/stats?stream=false' % nm, t=15)
            if st != 200:
                continue
            d = json.loads(b)
            cs, ps = d.get('cpu_stats') or {}, d.get('precpu_stats') or {}
            cu, pu = cs.get('cpu_usage') or {}, ps.get('cpu_usage') or {}
            dc = (cu.get('total_usage') or 0) - (pu.get('total_usage') or 0)
            ds = (cs.get('system_cpu_usage') or 0) - (ps.get('system_cpu_usage') or 0)
            ncpu = len(cu.get('percpu_usage') or [1])
            cpu = round(100.0 * dc / ds * ncpu, 1) if ds > 0 and dc >= 0 else 0.0
            mem = ((d.get('memory_stats') or {}).get('usage') or 0) / 1048576.0
            out[nm] = {'cpu': cpu, 'mem_mb': round(mem)}
        except Exception:
            continue
    return out


def _cd2_logs(minutes):
    """经 Docker Engine API 拉 CD2 近 N 分钟日志行（media-hub 容器内没有 docker CLI）。"""
    since = int(time.time()) - minutes * 60
    st, b = dk('GET', '/containers/clouddrive2/logs?stdout=1&stderr=1&since=%d&tail=0' % since, t=60)
    if st != 200:
        return []
    out = []
    for ln in b.split('\n'):
        if len(ln) > 8 and ln[0] in '\x01\x02':
            ln = ln[8:]
        if ln.strip():
            out.append(ln)
    return out


def _cd2_stream_storm(since='15m'):
    """CD2 403 流读取风暴：条数/每分钟/读写归因/受影响目录 TOP/是否播放读(dl=1)。"""
    o = {'n': 0, 'per_min': 0.0, 'top': [], 'write_err': 0, 'play_n': 0}
    try:
        mm = {'2m': 2, '5m': 5, '15m': 15, '30m': 30, '1h': 60}.get(since, 15)
        raw = _cd2_logs(mm)
        lines = [l for l in raw if 'failed to get url stream' in l and 'status code 403' in l]
        o['n'] = len(lines)
        o['per_min'] = round(len(lines) / float(mm), 1)
        cnt = collections.Counter()
        for l in lines:
            m = re.search(r'/115open/([^"\' ]+)', l)
            if m:
                seg = '/'.join(m.group(1).split('/')[:3])
                cnt[seg] += 1
            if 'dl=1' in l:
                o['play_n'] += 1
        o['top'] = [{'dir': k, 'n': v} for k, v in cnt.most_common(5)]
        o['write_err'] = sum(1 for l in raw if 'delete_entries error' in l)
    except Exception:
        pass
    return o


def _strm_health():
    """STRM 助手健康：今日失败批 / 近60分钟批时长 / 删除量 / 最近失败原因摘录。"""
    o = {'fail_today': 0, 'last_fail': None, 'avg_min': None, 'max_min': 0.0,
         'batches_60m': 0, 'del_recent': 0, 'fail_why': ''}
    try:
        with db() as c:
            f = c.execute("SELECT count(*) n, max(created_at) at FROM strm_tasks "
                          "WHERE status='failed' AND created_at>=date('now','localtime')").fetchone()
            o['fail_today'] = int(f['n'] or 0)
            o['last_fail'] = (f['at'] or '')[11:19] or None
            if o['fail_today']:
                fw = c.execute("SELECT error_log FROM strm_tasks WHERE status='failed' "
                               "AND created_at>=date('now','localtime') "
                               "ORDER BY id DESC LIMIT 1").fetchone()
                o['fail_why'] = ((fw['error_log'] or '')[:160] if fw else '')
            rows = [dict(r) for r in c.execute(
                "SELECT id,status,total_files,deleted_files,created_at,finished_at FROM strm_tasks "
                "WHERE created_at>=datetime('now','localtime','-60 minutes') "
                "ORDER BY id DESC LIMIT 30")]
    except Exception:
        return o
    mins = []
    for r in rows:
        try:
            a = time.mktime(time.strptime(r['created_at'][:19], '%Y-%m-%d %H:%M:%S'))
            b = r['finished_at']
            b = time.mktime(time.strptime(b[:19], '%Y-%m-%d %H:%M:%S')) if b else time.time()
            mins.append(max(0.0, (b - a) / 60.0))
            o['del_recent'] += int(r['deleted_files'] or 0)
        except Exception:
            continue
    o['batches_60m'] = len(rows)
    if mins:
        o['avg_min'] = round(sum(mins) / len(mins), 1)
        o['max_min'] = round(max(mins), 1)
    return o


def _queue_hog():
    """队列霸占：running 超 2h 的任务（10-16 的 1226：5.6万文件跑16h堵死管道）。"""
    o = {'hogs': [], 'worst_min': 0}
    try:
        with db() as c:
            rows = [dict(r) for r in c.execute(
                "SELECT id,profile_id,total_files,done_files,error_files,started_at "
                "FROM organize_tasks WHERE status='running'")]
        for r in rows:
            try:
                mins = int((time.time() - time.mktime(time.strptime(
                    (r['started_at'] or '')[:19], '%Y-%m-%d %H:%M:%S'))) / 60)
            except Exception:
                mins = 0
            tot = int(r['total_files'] or 0)
            epct = round(100.0 * int(r['error_files'] or 0) / tot, 1) if tot else 0
            if mins > 120:
                o['hogs'].append({'id': r['id'], 'profile': r['profile_id'], 'min': mins,
                                  'tot': tot, 'done': r['done_files'], 'err_pct': epct})
                o['worst_min'] = max(o['worst_min'], mins)
    except Exception:
        pass
    return o


def _stalled_tasks():
    """零吞吐卡死：running 且 done 长期不动、进度接近 0 的任务（auto_stall_kill 的目标）。"""
    out = []
    try:
        with db() as c:
            rows = [dict(r) for r in c.execute(
                "SELECT id,total_files,done_files,started_at FROM organize_tasks WHERE status='running'")]
        for r in rows:
            try:
                mins = int((time.time() - time.mktime(time.strptime(
                    (r['started_at'] or '')[:19], '%Y-%m-%d %H:%M:%S'))) / 60)
            except Exception:
                mins = 0
            if mins >= 20 and int(r['done_files'] or 0) == 0 and int(r['total_files'] or 0) > 0:
                out.append({'id': r['id'], 'min': mins, 'tot': r['total_files']})
    except Exception:
        pass
    return out


def _stall_progress():
    """对比上次快照判断「running 但 done 不增长」。快照存 /data/_stall_probe.json。"""
    f = '/data/_stall_probe.json'
    prev = {}
    try:
        prev = json.load(open(f, encoding='utf-8'))
    except Exception:
        pass
    cur = {}
    try:
        with db() as c:
            for r in c.execute("SELECT id,done_files FROM organize_tasks WHERE status='running'"):
                cur[str(r['id'])] = int(r['done_files'] or 0)
    except Exception:
        return [], prev
    stalled = []
    pt = prev.get('ts') or 0
    if pt and time.time() - pt < 3600:
        for tid, dn in cur.items():
            if tid in prev.get('done', {}) and dn == prev['done'][tid]:
                stalled.append({'id': int(tid), 'since_prev': int(time.time() - pt)})
    try:
        json.dump({'ts': time.time(), 'done': cur}, open(f, 'w', encoding='utf-8'))
    except Exception:
        pass
    return stalled, prev


def _emby_scanning():
    """Emby 是否正在全库扫描/探测（重启后或手动扫描会读爆 115 → 403 风暴常见主源）。"""
    o = {'main': 0, 'adult': 0, 'sample': ''}
    for key, cname in (('main', 'emby-main'), ('adult', 'emby-adult')):
        try:
            st, b = dk('GET', '/containers/%s/logs?stdout=1&stderr=1&tail=400' % cname, t=15)
            if st != 200:
                continue
            txt = b
            n = sum(1 for ln in txt.split('\n')
                    if re.search(r'Probing|Entering library scan|Queueing.*refresh|Scanning media', ln, re.I))
            o[key] = n
            if key == 'main':
                for ln in txt.split('\n'):
                    if re.search(r'Probing|Scanning', ln, re.I):
                        o['sample'] = ln[:140]
                        break
        except Exception:
            continue
    return o


def _unrec_burst(days=2):
    """近期「认不出」爆发目录：organize_failure_records 按路径前两级聚类（卡顿候选）。"""
    o = {'rows': [], 'total': 0}
    try:
        with db() as c:
            rows = [dict(r) for r in c.execute(
                "SELECT current_path p FROM organize_failure_records "
                "WHERE created_at>=date('now','localtime',?) ORDER BY id DESC LIMIT 4000",
                ('-%d day' % int(days),))]
            prof = {}
            for r in c.execute("SELECT id, json_extract(config,'$.sourceDir') sd FROM scheduled_jobs"):
                prof[r['id']] = (r['sd'] or '').rstrip('/')
            cnt = collections.Counter()
            for r in rows:
                p = r['p'] or ''
                sd = None
                for k, v in prof.items():
                    if v and p.startswith(v + '/'):
                        sd = v
                        break
                rel = p[len(sd):].strip('/') if sd else p
                key = '/'.join(rel.split('/')[:2]) if rel else '?'
                cnt[(sd.split('/')[-1] if sd else '?') + ' :: ' + key] += 1
            o['total'] = len(rows)
            o['rows'] = [{'dir': k, 'n': v} for k, v in cnt.most_common(6) if v >= 80]
    except Exception:
        pass
    return o


