# ══════════════════════════════════════════════════════════════════
# MT 工具箱（原 mt-tools 容器 8787/8788 的能力整合进 5678）
# 设计原则：诊断类只读；提交/改名复用本文件已有的 mt_manual / rename2，
# 不新增第二套引擎，避免行为不一致。路由走 /api/mtbox/* 单一入口分发。
# ══════════════════════════════════════════════════════════════════
MTBOX_INBOX = os.environ.get('MTBOX_INBOX', '未识别/未识别-MT/未识别-MT-MT转存')
_VIDEXT = ('.mkv', '.mp4', '.avi', '.ts', '.m2ts', '.rmvb', '.iso', '.wmv', '.mov', '.flv')


def cloud_of(lp):
    """本地挂载路径 -> MT 云盘路径（/主号/...）。与 host_of() 互为逆操作。"""
    lp = (lp or '').strip()
    if lp.startswith(MOUNT):
        rest = lp[len(MOUNT):].lstrip('/')
        return '/主号/' + rest if rest else '/主号'
    return lp


def mtbox_db():
    """只读打开 MT 库（诊断用，绝不写入）。"""
    c = sqlite3.connect('file:%s?mode=ro' % DB, uri=True, timeout=20)
    c.row_factory = sqlite3.Row
    return c


def _roq(sql, params=()):
    """只读查询，返回 dict 列表；任何异常都收敛成空列表而不是 500。"""
    c = mtbox_db()
    try:
        c.execute("PRAGMA busy_timeout=20000")
        return [dict(r) for r in c.execute(sql, params)]
    except Exception:
        return []
    finally:
        try:
            c.close()
        except Exception:
            pass


def _fbadge(code):
    c = (code or '').lower()
    if c.startswith('ai_'):
        return 'AI'
    if c == 'tmdb_api_error':
        return '接口'
    if c in ('no_candidates', 'ambiguous_candidates', 'no_new_search_clues',
             'candidate_recall_incomplete'):
        return '检索'
    if any(x in c for x in ('conflict', 'mismatch', 'missing', 'incomplete', 'unsupported')):
        return '校验'
    return '其他'


def mtbox_stats(days=2):
    st = _roq("SELECT status AS k, COUNT(*) AS n FROM organize_records GROUP BY status ORDER BY 2 DESC")
    rs = _roq("SELECT reason_code AS k, COUNT(*) AS n FROM organize_failure_records "
              "GROUP BY reason_code ORDER BY 2 DESC LIMIT 15")
    rc = _roq("SELECT COUNT(*) AS n FROM organize_failure_records WHERE created_at>=date('now',?)",
              ('-%d day' % int(days),))
    return {'ok': True, 'status': st, 'reasons': rs, 'days': int(days),
            'fail_n': (rc[0]['n'] if rc else 0)}


def mtbox_failures(days=2, code=None, limit=40):
    groups = _roq("SELECT reason_code AS k, COUNT(*) AS n FROM organize_failure_records "
                  "WHERE created_at>=date('now',?) GROUP BY reason_code ORDER BY 2 DESC",
                  ('-%d day' % int(days),))
    sql = ("SELECT reason_code AS code, file_name AS fn, reason_message AS msg, "
           "current_path AS path, created_at AS ts FROM organize_failure_records "
           "WHERE created_at>=date('now',?)")
    pr = ['-%d day' % int(days)]
    if code:
        sql += " AND reason_code=?"
        pr.append(code)
    sql += " ORDER BY id DESC LIMIT ?"
    pr.append(int(limit))
    rows = _roq(sql, pr)
    for r in rows:
        r['badge'] = _fbadge(r.get('code'))
    return {'ok': True, 'groups': groups, 'rows': rows, 'days': int(days)}


def mtbox_records(like='%', limit=40):
    rows = _roq("SELECT dest_path AS path, status AS st, tmdb_id AS tid, title AS title "
                "FROM organize_records WHERE dest_path LIKE ? ORDER BY id DESC LIMIT ?",
                (like or '%', int(limit)))
    return {'ok': True, 'rows': rows}


def mtbox_ls(path=None):
    p = (path or '').strip() or MOUNT
    if p.startswith('/主号'):
        p = host_of(p)
    p = os.path.normpath(p)
    if not p.startswith(MOUNT):
        return {'ok': False, 'msg': '只允许浏览云盘目录（%s 下）' % MOUNT}
    if not os.path.isdir(p):
        return {'ok': False, 'msg': '目录不存在：%s' % p}
    dirs, files = [], []
    try:
        for n in sorted(os.listdir(p)):
            if n.startswith('.'):
                continue
            fp = os.path.join(p, n)
            if os.path.isdir(fp):
                dirs.append({'path': fp, 'cloud': cloud_of(fp), 'name': n})
            elif n.lower().endswith(_VIDEXT):
                files.append({'path': fp, 'cloud': cloud_of(fp), 'name': n})
    except Exception as e:
        return {'ok': False, 'msg': str(e)}
    return {'ok': True, 'path': p, 'cloud': cloud_of(p), 'parent': os.path.dirname(p),
            'dirs': dirs[:200], 'files': files[:100]}


def mtbox_tmdb_search(q, kind='', year=None):
    q = (q or '').strip()
    if not q:
        return {'ok': False, 'msg': '缺关键词'}
    k = tmdb_key()
    if not k:
        return {'ok': False, 'msg': '未取到 TMDB key（MT 系统配置里没有）'}
    out = []
    for kd in ([kind] if kind else ['tv', 'movie']):
        u = 'https://api.themoviedb.org/3/search/%s?api_key=%s&language=zh-CN&query=%s' % (
            kd, k, urllib.parse.quote(q))
        if year:
            u += '&' + ('first_air_date_year=%d' % int(year) if kd == 'tv' else 'year=%d' % int(year))
        j = _tmdb_get(u)
        if isinstance(j, dict) and j.get('results'):
            for r in j['results'][:20]:
                out.append({'kind': kd, 'id': r.get('id'),
                            'name': r.get('name') or r.get('title') or '',
                            'orig': r.get('original_name') or r.get('original_title') or '',
                            'date': (r.get('first_air_date') or r.get('release_date') or '')[:10],
                            'pop': round(r.get('popularity') or 0, 1)})
    return {'ok': True, 'results': out}


def mtbox_tv_seasons(tid):
    k = tmdb_key()
    if not k:
        return {}
    j = _tmdb_get('https://api.themoviedb.org/3/tv/%d?api_key=%s' % (int(tid), k))
    if not isinstance(j, dict):
        return {}
    return {s.get('season_number'): s.get('episode_count')
            for s in (j.get('seasons') or []) if s.get('season_number') is not None}


_MB_NOISE = re.compile(
    r'\b(\d{3,4}[pi]|4K|UHD|Blu-?ray|REMUX|WEB-?DL|HDTV|HDR10?\+?|DV|DoVi|x26[45]|'
    r'H\.?26[45]|HEVC|AVC|AAC|FLAC|DTS(-HD)?( MA)?|TrueHD|Atmos|DDP|AC3|SDR|'
    r'10-?bit|8-?bit|REPACK|PROPER)\b', re.I)
_MB_BR = re.compile(r'[\[【（(][^\]】）)]*[\]】）)]')


# ★ v1.06 全自动识别强化：老 _MB_NOISE 只认「画质/编码」类词，
#   未识别目录里大量真实 PT 目录名带的是「版本/片源/完整度/国语配音」类尾巴：
#   7_人民的名义4K.60FPS高码珍藏版 → 老规则剩 "60FPS 高码 珍藏版"
#   → 检索出一堆同名杂牌 → 客观分拉不开 → 又没有 AI 兜底（ai_cfg 为空）
#   → 全部掉进 need「多候选不敢确认」，用户看到的就是「全自动根本没用」。
#   新增：帧率/码率/片源版本/完整度/音轨国语/发行厂牌/自制标签。
_MB_NOISE_V2 = re.compile(
    r'\b('
    # 帧率 / 码率 / 分辨率衍生
    r'\d{2,3}(?:FPS|fps)|\d{1,2}(?:bit|BIT)?Mbps|HighCode|高码|原盘|'
    # 片源 / 版本 / 介质
    r'WEBRip|WEB-?Rip|BDRip|DVDRip|HDRip|BD-?Rip|NF|AMZN|DSNP|HULU|ATVP|PCOK|'
    r'playWEB|PTerWEB|PTer|HDCTV|CHD|CMCT|WiKi|OneHD|beAst|TLF|MTeam|MTeamTV|'
    r'Remux|ENCODE|Limited|Uncut|Unrated|Extended|Internal|Theatrical|'
    r'Complete|全集|完结|未删减|删减|足版|珍藏版|典藏版|修复版|最终版|终极版|'
    # 音轨 / 字幕 / 国语配音
    r'国语|国配|国英|双语|双字|中字|外挂|内嵌|配音|音轨|'
    # 集数 / 碟片数（DVD9原盘10disc 之类）
    r'\d{1,2}[Dd]isc|DISC|disc\s*\d+|'
    # 常见冗余前缀/后缀
    r'压制|字幕组|发布|转载|下载|高清|超清|蓝光|'
    # 频道/台标（中国广电重温经典频道）
    r'重温经典频道|经典频道|央视|卫视|电影频道'
    r')\b', re.I)
# CJK 噪声词表（\b 对中文无效，改用直接 replace；长词在前优先）
_MB_CJK_NOISE = [
    '高码珍藏版', '珍藏版', '典藏版', '修复版', '最终版', '终极版',
    '未删减', '删减', '足版', '完整版', '全集', '完结', '全集完结',
    '双语双字', '双字', '双语', '国语配音', '国语', '国配', '中字', '外挂字幕', '内嵌字幕',
    '重温经典频道', '经典频道', '电影频道', '央视', '卫视',
    '字幕组', '压制', '发布', '转载',
    '原盘', '蓝光原盘', '蓝光', '高清', '超清',
]


# ★ v1.07：「整个清理结果退化成片源/厂牌词」时的兜底词表。
#   场景：[整形过后.全10集].2025.LINETV.WEB-DL.1080p... ——
#   _MB_BR 把「[整形过后.全10集]」连同片名一起吃掉（因为括号内含数字 10），
#   剩下 "LINETV WEB-DL 1080p..."，再被噪声规则清干净 → 只剩 'LINETV'，
#   于是拿一个厂牌名去 TMDB 检索，命中 '3 Artists On-Line on Slow-Scan-TV'
#   这种毫不相干的片子 —— 用户看到的就是「全自动在乱命名」。
#   规则：清理结果整体就是这类词（或只剩这类词）时，退回括号内中文片段。
_MB_JUNK_ONLY = [
    'linetv', 'wetv', 'iqiyi', 'youku', 'tencent', 'bilibili', 'netflix',
    'playweb', 'pterweb', 'pter', 'hdcctv', 'cmct', 'wiki', 'onehd', 'beast',
    'chd', 'tlf', 'mteam', 'mteamtv', 'nf', 'amzn', 'dsnp', 'hulu', 'atvp',
    'pcok', 'web', 'webdl', 'webrip', 'bdrip', 'hdtv', 'bluray', 'remux',
    'encode', 'repack', 'proper', 'internal', 'limited', 'uncut', 'unrated',
    'extended', 'theatrical', 'complete', 'vip', 'hd', 'sd', '4k', '1080p',
    '2160p', '720p', 'uhd', 'hevc', 'avc', 'h264', 'h265', 'aac', 'dts',
    'atmos', 'truehd', 'ddp', 'ac3', 'flac', 'sdr', 'dv', 'dovi', 'hdr',
    'hdctv', 'myvideo', 'viki', 'hbo', 'hmax', 'paramount', 'disney',
]


def _mb_title_from_brackets(name):
    """抽取括号内的纯中文片名（兜底）。

    场景：[TVB][1992]【大时代】双语双字DVD9原盘10disc... —— 括号内的中文片名被 _MB_BR 整条吃掉。
    规则：只取「纯中文 + 长度 1~12 + 不含版本/集数等噪声词」的第一个片段。
    """
    best = ''
    for m in re.finditer(r'[\[\u3010\u3014\uff08(]([^\]\u3011\u3015\uff09)]{1,20})[\]\u3011\u3015\uff09)]', name or ''):
        seg = m.group(1).strip()
        if not seg or len(seg) > 12:
            continue
        if not re.search(r'[\u4e00-\u9fff]', seg):
            continue
        # ★ v1.07：不再一见数字就整体否决。
        #   「整形过后.全10集」「人民的名义4K」这类括号片名本身就带集数/版本，
        #   老规则 continue 掉 → 兜底失效 → 只剩 'LINETV' 这种厂牌词。
        #   现在改成：把「集数/版本」片段切掉，只要还剩中文就当候选。
        seg = re.sub(r'[.\s_\-]*(?:全|共|第)?\s*\d{1,3}\s*(?:集|季|部|话|話|卷|disc|Disc)?\s*[.\s_\-]*$', ' ', seg)
        seg = re.sub(r'^[.\s_\-]+|[.\s_\-]+$', ' ', seg).strip()
        seg = re.sub(r'\s+', ' ', seg)
        if not seg or len(seg) > 12:
            continue
        if not re.search(r'[\u4e00-\u9fff]', seg):
            continue
        if any(w in seg for w in _MB_CJK_NOISE):
            continue
        if len(seg) > len(best):
            best = seg
    return best


def _mb_clean_cjk(s):
    """CJK 噪声词清理：\b 对中文无效，这里按「长词优先」直接 replace。

    只删「明显不属于片名」的常见副作品词；“书/传/\u5c4f幕版”等可能进片名的一字不动。
    """
    if not s:
        return s
    for w in _MB_CJK_NOISE:
        if w in s:
            s = s.replace(w, ' ')
    return s


def mtbox_clean(name):
    s = _MB_BR.sub(' ', name or '')
    s = re.sub(r'\.(mkv|mp4|avi|ts|iso|rmvb|m2ts|mov)$', '', s, flags=re.I)
    s = _MB_NOISE.sub(' ', s)
    s = _MB_NOISE_V2.sub(' ', s)
    # CJK 的噪声词没有\b 词边界（re 的\b 只能擅加西文/数字），
    # 必须用一套独立的「长词优先」直接 replace，否则上面的中文规则完全不生效。
    s = _mb_clean_cjk(s)
    # CJK 与数字/西文直接粘连（人民的名义4K / 亮剑2005HD）：在中文与 ASCII 边界插空格，
    # 让后续的\b规则能拍不下去（否则 '4K' 会因为前面是汉字而存活）。
    s = re.sub(r'([\u4e00-\u9fff\u3040-\u30ff])([0-9A-Za-z])', r'\1 \2', s)
    s = re.sub(r'([0-9A-Za-z])([\u4e00-\u9fff\u3040-\u30ff])', r'\1 \2', s)
    # 分开后再走一遍\b规则（拍不下人民的名义后面的 4K/UHD/2160p 等）
    s = _MB_NOISE.sub(' ', s)
    s = _MB_NOISE_V2.sub(' ', s)
    s = _mb_clean_cjk(s)

    # 老规则之后可能留下「数字+字母」粘连残气（DD+5.1 / H265.10bit / S01.2160p），
    # 这里再把「字母夹数字」的编码残片清一遍，避免 "The Fix HDR DD+5 1" 这种噪声标题。
    s = re.sub(r'\b[A-Z]{1,4}\+?\d+(?:\.\d+)?\b', ' ', s)
    s = re.sub(r'\b\d+(?:\.\d+)?[A-Za-z]{1,4}\b', ' ', s)
    s = re.sub(r'[Ss]\d{1,2}[Ee]\d{1,3}', ' ', s)
    s = re.sub(r'\bSeason\s*\d{1,2}\b', ' ', s, flags=re.I)
    s = re.sub(r'第\s*\d{1,2}\s*季', ' ', s)
    s = re.sub(r'\bS\d{1,2}\b', ' ', s)          # 裸季号（文件夹常写成 ...S01）
    s = re.sub(r'\b(19|20)\d{2}\b', ' ', s)
    s = s.replace('.', ' ').replace('_', ' ')
    # “The Fix HDR” / “Drawing Sword -QHstudIo” 之类的副作品尾巴：
    #   1) HDR/HDR10/DoVi 这类本该被 _MB_NOISE 拍掉，但若前面粘中文或片名已被抢先分割，这里补刀；
    #   2) 刻意保留 “-” 连接的制作组/发行组（LUMiERE / HDCTV / QHstudIo）。
    s = re.sub(r'(?i)\b(HDR10\+?|DoVi|DV|SDR|HFR|3D)\b', ' ', s)
    s = re.sub(r'[-\u2013\u2014]\s*[A-Za-z][A-Za-z0-9]{1,15}$', ' ', s)
    s = re.sub(r'(?i)\bHDR\b', ' ', s)
    s = re.sub(r'\s+', ' ', s).strip(' -–—、·')
    # 兜底：\u3010大时代\u3011/〔亮剑〕 这类「括号里就是片名」的目录，_MB_BR 会把整个括号吃掉导致清理后为空。
    # 这里从原始 name 里抽「括号内纯中文（去掉版本/集数等）」当片名。
    if not s:
        s = _mb_title_from_brackets(name)
    # ★ v1.07：清理结果「只剩片源/厂牌词」也要兜底。
    #   [整形过后.全10集].2025.LINETV... → 老逻辑剩 'LINETV'（非空，不进上面的兜底）
    #   → 拿厂牌名去检索 → 命中毫不相干的片子 = 「全自动在乱命名」。
    #   判据：清理后所有 token 都在 _MB_JUNK_ONLY 里，且原始名里能抽到中文片名。
    if s:
        _toks = [t for t in re.split(r'[\s·、\-]+', s) if t]
        if _toks and all(t.lower().strip('()') in _MB_JUNK_ONLY or
                         re.fullmatch(r'[\d.]+', t) for t in _toks):
            _fb = _mb_title_from_brackets(name)
            if _fb and re.search(r'[\u4e00-\u9fff]', _fb):
                s = _fb
    # ★ v1.07：清不掉的花括号残留（{tmdb=24019} / {tmdb-211270}）：
    #   这些是刮削标记不是片名一部分，带进去检索会把相似度打散。
    s = re.sub(r'\{[^{}]*\}', ' ', s)
    s = re.sub(r'\s+', ' ', s).strip(' -–—、·')
    return s


def _mtbox_pool(title, kind, y):
    """候选池：按标题检索（TMDB 热度序）。年份【只参与排序，不做淘汰】——
    系列剧各季年份不同（迷失 2004 起，S02 是 2005），拿 first_air_date_year 硬过滤
    会把本体滤掉、只剩碰巧同年的重名杂牌（10-16 实测 Lost 被滤成 Lost Cargo）。
    带年份检索的结果前置合并 + 无年份广搜补足，去重后一起交给打分/合并环节。"""
    pool, seen = [], set()

    def _add(j, kd, year_tag):
        for it in (j.get('results') or []):
            k = (it.get('id'), kd)
            if k in seen:
                continue
            seen.add(k)
            d = dict(it, kind=kd)
            if year_tag:
                d['year_hit'] = True
            pool.append(d)
    for kd in ([kind] if kind else ['tv', 'movie']):
        if y:
            try:
                _add(mtbox_tmdb_search(title, kd, y) or {}, kd, True)
            except Exception:
                pass
        _add(mtbox_tmdb_search(title, kd, None) or {}, kd, False)
    return pool


def _norm_t(x):
    x = (x or '').lower()
    x = re.sub(r'[^0-9a-z\u4e00-\u9fff]+', ' ', x)
    return x.strip()


def _bigs(x):
    x = (x or '').replace(' ', '')
    if len(x) < 2:
        return {x} if x else set()
    return set(x[i:i + 2] for i in range(len(x) - 1))


def _dice(a, b):
    A, B = _bigs(a), _bigs(b)
    if not A or not B:
        return 0.0
    return 2.0 * len(A & B) / (len(A) + len(B))


def _workkey(c):
    """候选的『作品核心键』：原名优先，剥离季/部/裸数字后缀。
    迷失各季 → lost；Lost Cargo → lost cargo（不同键，天然区分重名作品）。"""
    x = _norm_t(c.get('orig') or c.get('name') or '')
    x = re.sub(r'\b(season|series)\s*\d+\b', ' ', x)
    x = re.sub(r'第\s*[0-9零一二三四五六七八九十百]+\s*[季部]', ' ', x)
    x = re.sub(r'\b\d{1,3}\b', ' ', x)
    return re.sub(r'\s+', ' ', x).strip()


def _mtbox_score(nname, ntitle_nospace, cands, year_in_name):
    """打分 + 同作品键合并：相等/前缀/包含分级，系列剧多季只算一个最强代表。
    确定性优先——重名作品（Lost vs Lost Cargo）靠键相等/前缀区分，不再赌 AI。"""
    groups = {}
    for c in cands:
        wk = _workkey(c) or 'x'
        t1 = _norm_t(c.get('name') or '')
        t2 = _norm_t(c.get('orig') or '')
        base = max(_dice(nname, t1), _dice(nname, t2))
        rel = 0.0
        wkn = wk.replace(' ', '')
        nnm = nname.replace(' ', '')
        if nname and wk:
            if wkn == nnm:
                rel = 1.0
            elif wkn.startswith(nnm) or nnm.startswith(wkn):
                # 去空格前缀：中文「请回答1988」⊃「请回答」、英文「lost cargo」⊃「lost」都走这里
                rel = 0.82
            else:
                cn = t1.replace(' ', '') or t2.replace(' ', '')
                ns = (ntitle_nospace or '') + ' '
                if cn and ns.startswith(cn) or (' ' + wkn + ' ') in (' ' + nnm + ' '):
                    rel = 0.30
        ybonus = 1.0 if (year_in_name and str(year_in_name) in
                         ((c.get('name') or '') + ' ' + (c.get('orig') or ''))) else 0.0
        pops = min(float(c.get('pop') or 0), 300.0) / 300.0
        score = rel * 0.50 + base * 0.30 + ybonus * 0.12 + pops * 0.12
        g = groups.setdefault(wk, {'best': None, 'n': 0})
        g['n'] += 1
        if g['best'] is None or score > g['best'][0]:
            g['best'] = (score, c)
    out = []
    for wk, g in groups.items():
        sc, c = g['best']
        if g['n'] > 1:
            sc = min(1.0, sc + 0.06)   # 系列多季本体：轻微加成一票
        out.append((sc, c))
    out.sort(key=lambda x: -x[0])
    return out


def _mtbox_ai_pick(name, cands):
    """AI 兜底裁决：把候选列表交给 MT 已配置的 LLM，只允许回答候选 ID。
    任何异常/越界 ID 一律放弃（保持「绝不乱猜」原则）。"""
    base, key, mdl = ai_cfg()
    if not base or not cands:
        return None, ''
    _LET = 'ABCDEFGH'
    lines = []
    for i, c in enumerate(cands[:8], 1):
        # 序号用字母：避免推理模型复述候选行里的数字干扰答案解析
        lines.append('候选%s：中文名=%s 原名=%s 年份=%s 类型=%s 热度=%s' % (
            _LET[i - 1], c.get('name') or '',
            c.get('orig') or '', (c.get('date') or '')[:4], c.get('kind') or '', c.get('pop') or 0))
    prompt = ('下面是若干影视候选条目：\n%s\n'
              '问题：目录名「%s」最可能对应哪一个候选？'
              '名字（英文原名、拼音、常见中文译名）对得上、年份合理即算匹配，优先热度高的。'
              '规则：最终答案只输出一个字母（候选编号）；若全部明显不相关则输出 X。'
              '思考过程不要复述候选内容。') % (
        '\n'.join(lines), name)
    try:
        payload = {'model': mdl or 'auto', 'temperature': 0, 'max_tokens': 80,
                   'messages': [{'role': 'user', 'content': prompt}]}
        hdrs = {'Content-Type': 'application/json'}
        if key:
            hdrs['Authorization'] = 'Bearer ' + key
        last_err = ''
        j = None
        bare = {'Content-Type': 'application/json'}
        for hd in ([hdrs, bare] if key else [bare]):
            req = urllib.request.Request(
                base.rstrip('/') + '/chat/completions',
                data=json.dumps(payload, ensure_ascii=False).encode('utf-8'), headers=hd)
            try:
                with urllib.request.urlopen(req, timeout=20) as _r:
                    j = json.loads(_r.read().decode('utf-8', 'replace'))
                break
            except Exception as e:
                last_err = str(e)[:60]
        if j is None:
            return None, 'AI 调用失败 %s' % last_err
        msg = ((j.get('choices') or [{}])[0].get('message') or {})
        content = (msg.get('content') or '').strip() or (msg.get('reasoning') or '').strip()
        pick = ''
        _ls = [l.strip() for l in content.splitlines() if l.strip()]
        for l in reversed(_ls[-4:]):
            m = re.fullmatch(r'(?:答案[:：]?\s*)?([A-HXx])[.。\s]*', l)
            if m:
                pick = m.group(1).upper(); break
        if not pick:
            m = re.findall(r'(?:答案[:：]?\s*)([A-HXx])\b', content)
            if m:
                pick = m[-1].upper()
        if pick in ('', 'X'):
            return None, 'AI 判定都不相关' if pick == 'X' else ('AI 未给有效字母(末行=%s)' % ((_ls[-1][:30]) if _ls else '空'))
        c = cands[ord(pick) - 65]
        return c, 'AI 裁决(%s)' % pick
    except Exception as e:
        return None, 'AI 异常 %s' % str(e)[:50]


def _mtbox_resolve_multi(name, title, pool, year, ai=True):
    """多候选 → 客观消歧 →（仍歧义且允许时）AI 兜底。返回 (cand, note)。"""
    ys_in_name = re.findall(r'\b((?:19|20)\d{2})\b', name or '')
    nname = _norm_t(title)
    nns = nname.replace(' ', '')
    scored = _mtbox_score(nname, nns, pool, int(ys_in_name[-1]) if ys_in_name else None)
    if scored:
        s1, c1 = scored[0]
        s2 = scored[1][0] if len(scored) > 1 else 0.0
        if len(scored) == 1:
            return c1, '同作品键唯一(%d 条候选合并)' % len(pool)
        if s1 >= 0.45 and (s1 - s2) >= 0.10:
            return c1, '客观消歧(sim %.2f 领先 %.2f)' % (s1, s1 - s2)
        # 领先不明显 / 全部低分 → AI
    if ai:
        top = [dict(c) for _, c in scored[:8]] or list(pool[:8])
        c, note = _mtbox_ai_pick(name, top)
        if c:
            return c, note
        return None, ('多候选(前%d)，客观分不明显且 AI 不敢确认：%s' % (
            len(pool), ' / '.join('%s:%s' % (x.get('kind'), x.get('id')) for x in pool[:4])))
    return None, '多候选无法区分(%d)：%s' % (
        len(pool), ' / '.join('%s:%s' % (x['kind'], x['id']) for x in pool[:4]))


def mtbox_resolve(name, kind=None, year=None, season=None, ai=True):
    """按客观依据（年份/类型/季）唯一定位；定不了就明确说原因，绝不乱猜。"""
    title = mtbox_clean(name)
    if not title:
        return {'ok': True, 'cand': None, 'reason': '标题剥离后为空'}
    ys = re.findall(r'\b((?:19|20)\d{2})\b', name or '')
    y = int(year) if year else (int(ys[-1]) if ys else None)
    # 退化重试：整名搜不到时逐级去掉末尾词（"请回答 Reply" → "请回答"），最多 3 次
    tried, pool = title, []
    for _ in range(3):
        pool = _mtbox_pool(tried, kind, y)
        if pool or ' ' not in tried:
            break
        tried = tried.rsplit(' ', 1)[0]
    if not pool and y:
        # 年份可能是片名的一部分（如 Reply 1997）→ 去掉年份约束再试一次
        pool = _mtbox_pool(title, kind, None)
    if not pool:
        return {'ok': True, 'cand': None,
                'reason': '检索无结果：%s（已退化重试 + 去年份约束）' % title}
    note = ''
    if len(pool) > 1:
        c0, note = _mtbox_resolve_multi(name, title, pool, year, ai=ai)
        if c0 is None:
            return {'ok': True, 'cand': None, 'reason': note}
    else:
        c0 = pool[0]
    cand = {'id': c0['id'], 'kind': c0['kind'], 'title': c0['name'],
            'year': (c0.get('date') or '')[:4]}
    if c0['kind'] == 'tv' and season:
        seasons = mtbox_tv_seasons(c0['id'])
        if int(season) not in seasons:
            return {'ok': True, 'cand': None, 'reason': 'TMDB 未列出第 %s 季（已列：%s）'
                    % (season, sorted(seasons))}
    return {'ok': True, 'cand': cand,
            'reason': note or '年份/类型吻合，唯一定位'}


def mtbox_submit(b):
    src = (b.get('dir') or b.get('file') or '').strip()
    if not src:
        return {'ok': False, 'msg': '缺源目录/文件'}
    try:
        tid = int(b.get('tmdb'))
    except Exception:
        return {'ok': False, 'msg': 'TMDB ID 必须是数字'}
    return mt_manual(cloud_of(src), tid, b.get('type') or 'tv', b.get('profile'))


def mtbox_inbox():
    return os.path.join(MOUNT, MTBOX_INBOX)


def mtbox_scan(limit=20):
    inbox = mtbox_inbox()
    if not os.path.isdir(inbox):
        return {'ok': False, 'msg': '未识别目录不存在：%s' % inbox}
    lim = max(1, min(int(limit or 20), 50))
    items = []
    for name in sorted(os.listdir(inbox))[:lim]:
        p = os.path.join(inbox, name)
        try:
            if os.path.isdir(p):
                vids = [f for _, _, fs in os.walk(p) for f in fs if f.lower().endswith(_VIDEXT)]
                if not vids:
                    items.append({'name': name, 'state': 'skip', 'why': '无视频文件'})
                    continue
            elif not name.lower().endswith(_VIDEXT):
                items.append({'name': name, 'state': 'skip', 'why': '非视频文件'})
                continue
            r = mtbox_resolve(name)
            items.append({'name': name,
                          'state': 'ok' if r.get('cand') else 'need',
                          'cand': r.get('cand'), 'why': r.get('reason')})
        except Exception as e:
            items.append({'name': name, 'state': 'err', 'why': str(e)[:120]})
    return {'ok': True, 'inbox': inbox, 'cloud': cloud_of(inbox), 'items': items}


def mtbox_run(mode='dry', table=None, profile=None):
    """按人工确认表批量提交。dry 只给计划，apply 才真的调 MT。"""
    apply_ = (mode == 'apply')
    inbox = mtbox_inbox()
    rep = {'planned': [], 'submitted': [], 'failed': []}
    for name, spec in (table or {}).items():
        spec = spec or {}
        if not spec.get('tmdb'):
            continue
        p = os.path.join(inbox, str(name))
        if not os.path.exists(p):
            rep['failed'].append({'name': name, 'msg': '条目不存在'})
            continue
        if not apply_:
            rep['planned'].append({'name': name, 'tmdb': spec.get('tmdb'),
                                   'kind': spec.get('kind', 'tv')})
            continue
        try:
            r = mt_manual(cloud_of(p), int(spec.get('tmdb')), spec.get('kind', 'tv'), profile)
        except Exception as e:
            r = {'ok': False, 'msg': str(e)[:200]}
        (rep['submitted'] if r.get('ok') else rep['failed']).append(
            {'name': name, 'tmdb': spec.get('tmdb'), 'msg': r.get('msg')})
    return {'ok': True, 'mode': mode, 'report': rep}


def mtbox_iso(path=None):
    p = (path or '').strip()
    if p.startswith('/主号'):
        p = host_of(p)
    if not p or not os.path.isfile(p):
        return {'ok': False, 'msg': '文件不存在：%s' % p}
    try:
        size = os.path.getsize(p)
        names, studios = [], []
        hints = {'Paramount': [b'paramount'], 'Sony': [b'sony'], 'Warner': [b'warner', b'wbhv'],
                 'Universal': [b'universal'], 'Disney': [b'disney', b'buena'],
                 'Lionsgate': [b'lionsgate']}
        with open(p, 'rb') as fh:
            scanned = 0
            while scanned < min(size, 96 * 1024 * 1024):
                buf = fh.read(4 * 1024 * 1024)
                if not buf:
                    break
                scanned += len(buf)
                for m in re.finditer(rb'<di:name>(.*?)</di:name>', buf, re.S):
                    t = m.group(1).decode('utf-8', 'replace').strip()
                    if t and t not in names:
                        names.append(t)
                low = buf.lower()
                for s, hs in hints.items():
                    if s not in studios and any(h in low for h in hs):
                        studios.append(s)
                if names and studios:
                    break
        disc = next((n for n in names if not re.match(
            r'^(Menu|Bootstrap|Title|Top|FirstPlay|.*\.bdmv)$', n, re.I)), None)
        return {'ok': True, 'info': {'file': os.path.basename(p), 'size_gb': round(size / 1e9, 2),
                                     'disc_name': disc, 'studios': studios, 'raw': names[:6]}}
    except Exception as e:
        return {'ok': False, 'msg': str(e)}


# ══════════════════ MT 工具箱 · 「全自动」板块 ══════════════════
# 用户诉求（2026-10-19）：「全自动命名」点了就不该再弹「选年份」等人工操作；
# 并把命名能力融进 MT 工具箱，加一个板块，逻辑按 MT 工具箱官方来。
#
# 设计（只增不减，复用既有官方引擎，不另建第二套）：
#   · 识别  = mtbox_resolve()          ← MT 工具箱官方 TMDB 判定（唯一定位才动手）
#   · 改名  = rename_plan2/prerename_apply ← 命名引擎（SxxEyy / 日期型综艺）
#   · 联动  = create([targetDir])      ← 建 MT 整理方案（五步：停MT→备份→写→checkpoint→启MT）
#   · 执行  = naming_autorun()         ← 既有的全自动编排（dry 预览 / 实跑）
# 新增三件事：① 免交互（不收年份/剧名）② 源目录路径容错 ③ 联动建 MT 任务后回报任务号


AUTORUN_DEFAULTS = {'budget': 60, 'tmdb_sleep': 1.5, 'mode': 'rename_move'}


def autorun_norm(b):
    """把前端随便传的字段归一成 naming_autorun 能吃的 task。

    关键点：**不接收 title/year/season**（全自动 = 由 MT tool 判定），
    也绝不弹任何人工交互。路径同时容忍 /主号/、/115open/、/CloudNAS/115open/ 三种写法
    （host_of 已统一处理），源目录不存在时给出可读的原因而不是笼统一句。
    """
    b = b or {}
    src = (b.get('sourceDir') or b.get('dir') or b.get('src') or '').strip()
    tg = (b.get('targetDir') or b.get('target') or '').strip()
    if not src:
        return None, {'ok': False, 'msg': '请先选「源目录」（一堆待整理子目录的父目录）'}
    # ★ v1.06 修复「源目录不存在」误报：相对路径（未识别 / foo/bar）会被 host_of 静默拼成
    #   /CloudNAS/115open/未识别 —— 若容器 CWD 下带同名目录，就会「误告成功」，结果是掉进
    #   一个完全无关的目录扫描，用户看到的就是「全自动在跑但什么都不识别」。
    #   今后绝对路径直接拒绝，并告诉他该怎么填。
    if not src.startswith('/'):
        return None, {'ok': False,
                      'msg': ('源目录必须是绝对路径（当前填的是「%s」）。\n'
                              '请点「📂 选目录」挑选，或填 /主号/未识别/... '
                              '这类以 / 开头的完整路径。') % src[:80]}
    t = {
        'name': (b.get('name') or '').strip() or 'MT工具箱·全自动',
        'sourceDir': src,
        'targetDir': tg,
        'mode': b.get('mode') if b.get('mode') in ('rename_only', 'rename_move') else 'rename_move',
        'auto': True,                    # 全自动标记（_naming_loop 也用这条分支）
        'ai_pick': bool(b.get('ai_pick', True)),
        'tmdb_sleep': float(b.get('tmdb_sleep') or AUTORUN_DEFAULTS['tmdb_sleep']),
        'mt_after': bool(b.get('mt_after', True)),
    }
    if not tg:
        t['mode'] = 'rename_only'       # 没给目标目录就不移动，只改名（不报错）
    return t, None


def mtbox_autorun_scan(b):
    """预览（dry）：不落盘，只报「能识别 / 待人工 / 会改名多少文件」。"""
    # ★ v1.11 多目录批量（用户要求「进一个目录勾几个 → 返回上级再勾几个 → 一起处理」）：
    #   sourceDirs 是跨目录勾选出来的目录列表，逐个跑同一套官方识别逻辑再合并结果。
    #   必须放在 autorun_norm **之前**：多选模式下 sourceDir 可能为空（只填了 sourceDirs），
    #   先跑 norm 会被「请先选源目录」挡掉。
    dirs = autorun_dirs(b)
    if len(dirs) > 1:
        return autorun_multi(b, dirs, dry=True)
    t, err = autorun_norm(b)
    if err:
        return err
    src = host_of(t['sourceDir'])
    if not os.path.isdir(src):
        return {'ok': False, 'msg': '源目录不存在：%s（已按云盘/宿主机两种写法试过：%s）'
                % (t['sourceDir'], src)}
    budget = int(b.get('budget') or AUTORUN_DEFAULTS['budget'])
    r = naming_autorun(t, dry=True, budget=budget)
    if not r.get('ok'):
        return r
    r['sourceDir'] = t['sourceDir']
    r['targetDir'] = t['targetDir']
    r['inbox_note'] = '识别用 MT 工具箱官方 mtbox_resolve（唯一定位才动手，定不了进待人工，绝不乱猜）'
    return r


def autorun_dirs(b):
    """★ v1.11：把前端「跨目录批量勾选」的目录列表归一成绝对路径列表。

    兼容三种输入：sourceDirs（list）/ sourceDir（单个）/ dir / src。
    去重 + 丢掉空项，保持用户勾选顺序（前端按勾选顺序传，回显才对得上）。
    """
    b = b or {}
    raw = []
    for k in ('sourceDirs', 'source_dir_list', 'dirs'):
        v = b.get(k)
        if isinstance(v, (list, tuple)):
            raw.extend([str(x or '').strip() for x in v])
        elif v:
            raw.extend([str(x).strip() for x in str(v).split('\n') if x.strip()])
    for k in ('sourceDir', 'dir', 'src'):
        v = b.get(k)
        if isinstance(v, (list, tuple)):
            raw.extend([str(x or '').strip() for x in v])
        elif v:
            raw.append(str(v).strip())
    seen, out = set(), []
    for x in raw:
        if not x or x in seen:
            continue
        seen.add(x)
        out.append(x)
    return out


def autorun_multi(b, dirs, dry=False, budget=None):
    """★ v1.11：多个源目录 → 逐个跑 naming_autorun → 合并成一份回执。

    合并口径（只增不减，字段与单目录版完全一致，前端复用同一套渲染）：
      · scanned / processed / recognized / renamed_files / moved 求和
      · items / need / errors / skipped 拼接（need 里带上 dir 字段标明来自哪个目录）
      · msg 给一句人话总结；per_dir 逐目录明细，方便用户看清每个目录干了什么
      · 只要有一个目录真改了东西，mt_after 就按该目录联动 MT 建整理任务
    """
    t0 = time.time()
    budget = int(budget or b.get('budget') or AUTORUN_DEFAULTS['budget'])
    total = {'ok': True, 'dry': bool(dry), 'scanned': 0, 'processed': 0,
             'recognized': 0, 'renamed_files': 0, 'moved': 0,
             'items': [], 'need': [], 'errors': [], 'skipped': [],
             'bulk': [], 'bulk_skipped': 0, 'stopped': False,
             'per_dir': [], 'sourceDirs': list(dirs), 'multi': True}
    mt_msgs = []
    for d in dirs:
        tt, err = autorun_norm(dict(b, sourceDir=d))
        if err:
            total['errors'].append({'name': d, 'msg': (err.get('msg') or '参数错误')[:140]})
            continue
        if not os.path.isdir(host_of(d)):
            total['errors'].append({'name': d, 'msg': '源目录不存在：%s' % d})
            continue
        r = naming_autorun(tt, dry=dry, budget=budget)
        if not r.get('ok'):
            total['errors'].append({'name': d, 'msg': (r.get('msg') or '执行失败')[:140]})
            continue
        for k in ('scanned', 'processed', 'recognized', 'renamed_files', 'moved'):
            total[k] += int(r.get(k) or 0)
        total['bulk_skipped'] += int(r.get('bulk_skipped') or 0)
        total['stopped'] = total['stopped'] or bool(r.get('stopped'))
        total['bulk'].extend(r.get('bulk') or [])
        for key, tag in (('items', 'items'), ('need', 'need'),
                         ('errors', 'errors'), ('skipped', 'skipped')):
            for x in (r.get(key) or []):
                if isinstance(x, dict):
                    x.setdefault('dir', d)
                total[tag].append(x)
        total['per_dir'].append({
            'dir': d, 'scanned': r.get('scanned') or 0,
            'recognized': r.get('recognized') or 0,
            'moved': r.get('moved') or 0, 'renamed': r.get('renamed_files') or 0,
            'need': len(r.get('need') or []),
            'msg': (r.get('msg') or '')[:120]})
        if r.get('mt_created'):
            mt_msgs.append(r.get('mt_msg') or ('已联动 MT 建整理任务（源：%s）' % d))
        if r.get('mt_src'):
            total.setdefault('mt_src', r.get('mt_src'))
    if mt_msgs:
        total['mt_created'] = True
        total['mt_msg'] = '；'.join(mt_msgs)[:400]
    total['msg'] = ('已处理 %d 个目录：扫描 %d 项，识别 %d 项，改名 %d 个文件，移动 %d 项'
                    % (len(total['per_dir']), total['scanned'], total['recognized'],
                       total['renamed_files'], total['moved'])
                    + ('；待人工 %d 项' % len(total['need']) if total['need'] else '')
                    + ('；错误 %d 项' % len(total['errors']) if total['errors'] else ''))
    oplog('mtbox', 'autorun-multi',
           'MT工具箱·全自动整理（多目录 %d 个）' % len(dirs),
           total['ok'], total['msg'][:200])
    return total


def mtbox_autorun_run(b):
    """执行（apply）：真实改名 / 移动，并按需联动 MT 建整理任务。

    同步返回（有 dry 同步跑完再回的，也有大目录走 submit 后台的）。
    为了「点了就有结果」，这里同步跑；超过 90s 的由前端再切后台。
    """
    # ★ v1.11 多目录批量：见 mtbox_autorun_scan 同款说明
    #   （须在 autorun_norm 之前：多选模式可能只填 sourceDirs）
    dirs = autorun_dirs(b)
    if len(dirs) > 1:
        return autorun_multi(b, dirs, dry=False)
    t, err = autorun_norm(b)
    if err:
        return err
    src = host_of(t['sourceDir'])
    if not os.path.isdir(src):
        return {'ok': False, 'msg': '源目录不存在：%s（已按云盘/宿主机两种写法试过：%s）'
                % (t['sourceDir'], src)}
    budget = int(b.get('budget') or AUTORUN_DEFAULTS['budget'])
    r = naming_autorun(t, dry=False, budget=budget)
    if not r.get('ok'):
        return r
    r['sourceDir'] = t['sourceDir']
    r['targetDir'] = t['targetDir']
    r['mode'] = t['mode']
    # naming_autorun 内部已按 mt_after 调 create([tg])；这里把 MT 侧结果补成可读文案
    if r.get('mt_created'):
        # ★ v1.07 修复「源目录显示为空」：老写法是
        #   '...（源：%s）' % t['targetDir'] or t['sourceDir']
        #   Python 里 % 优先级高于 or → 永远取 t['targetDir']（只改名模式下为空），
        #   于是回执变成「源：」（空），用户根本不知道 MT 任务建在哪个目录上。
        _mtsrc = (t['targetDir'] or '').strip() or t['sourceDir']
        r['mt_msg'] = '已联动 MediaTidy 建整理任务（源：%s）' % _mtsrc
        r['mt_src'] = _mtsrc
    oplog('mtbox', 'autorun', 'MT工具箱·全自动整理 · %s' % t['sourceDir'],
          r.get('ok'), (r.get('msg') or '')[:200])
    return r


# 未识别目录「视频数」统计结果缓存：deep walk 对 /CloudNAS 大目录要几分钟，
# 不能放在同步请求里（用户点一下要 200s+ 才回，表现为「功能没用」）。
_INBOX_VIDEO_CACHE = {'ts': 0.0, 'map': {}}
_INBOX_VIDEO_TTL = 300.0

# v1.08：inbox 深层目录视频数统计 —— 持久化 + 分层限时
_INBOX_VIDEO_FILE = os.path.join(os.path.dirname(os.path.abspath(DB)), 'inbox_video_cache.json')
_INBOX_VIDEO_RUNNING = {'busy': False, 'doing': set()}   # doing：正在重算的条目名
# v1.08b：115 网盘（CloudDrive2/FUSE）对并发 listdir 会限流 —— 实测两个统计
# 线程同时跑，单次 listdir 从 0.00s 劣化到 0.3~0.9s，4 层结构从 0.05s
# 劣化到 25~99 秒（用户看到的就是「统计中…」永远不变）。
# 这把锁保证**同一时刻只有一个统计在跑**，其余排队。
_INBOX_IO_LOCK = threading.Lock()
_INBOX_APPROX = set()          # 标记哪些条目的视频数是量级估算（非精确）


def _inbox_cache_load():
    """v1.08：把深层目录的视频数统计结果落盘。

    老实现只放内存 dict，容器一重启就全丢 → 用户又得干等 37 秒看「数据为 0」。
    现在启动时先读盘顶上，后台线程再增量刷新。
    """
    try:
        if os.path.exists(_INBOX_VIDEO_FILE):
            with open(_INBOX_VIDEO_FILE, 'r', encoding='utf-8') as f:
                d = json.load(f)
            m = d.get('map') if isinstance(d, dict) else None
            if isinstance(m, dict):
                _INBOX_VIDEO_CACHE['map'] = {str(k): int(v) for k, v in m.items()
                                             if isinstance(v, (int, float))}
                _INBOX_VIDEO_CACHE['ts'] = float(d.get('ts') or 0.0)
                _ap = d.get('approx')
                if isinstance(_ap, list):
                    _INBOX_APPROX.clear()
                    _INBOX_APPROX.update(str(x) for x in _ap)
    except Exception as e:
        logger.warning('inbox 视频数缓存读取失败: %s', e)


def _inbox_cache_save():
    """统计结果落盘（原子写：先 .tmp 再 rename，避免半截文件）。

    v1.08：approx 集合也一起落盘，否则重启后「≈ 量级估算」标记丢了，
    用户分不清哪个数是精确的、哪个是估的。
    """
    try:
        tmp = _INBOX_VIDEO_FILE + '.tmp'
        with open(tmp, 'w', encoding='utf-8') as f:
            json.dump({'ts': _INBOX_VIDEO_CACHE['ts'],
                       'map': _INBOX_VIDEO_CACHE['map'],
                       'approx': sorted(_INBOX_APPROX)},
                      f, ensure_ascii=False)
        os.replace(tmp, _INBOX_VIDEO_FILE)
    except Exception as e:
        logger.warning('inbox 视频数缓存写入失败: %s', e)


try:
    _inbox_cache_load()
except Exception:
    pass


def _ls_par(dirs, workers=1, budget=None):
    """v1.08b：listdir 一批目录（默认**串行**，可选小并发）。

    ⚠️ 实测结论（2026-10-19，115 网盘 / CloudDrive2 FUSE）：
       16 线程并发一层要 **33~89 秒**，比串行 13 秒慢得多 —— 115 对并发
       listdir 会限流。所以默认 workers=1（串行），只在确知不是 115 的场景
       才可调高。真正解决「慢」的办法是**接口立即返回 + 后台线程算完落盘**，
       见 mtbox_autorun_inbox / _inbox_video_map。

    budget：本批总时限（秒）。超时后**取消未完成的 future**并返回已完成部分，
    绝不无限等待 —— 这是「不能让用户等 80 秒」的硬保证。
    返回 [(dir, [entries...]), ...]。
    """
    out = []
    dirs = [d for d in (dirs or []) if d]
    if not dirs:
        return out
    w = max(1, min(int(workers or 1), len(dirs)))
    if w == 1:
        for d in dirs:                      # 串行：稳定、不触发限流
            try:
                out.append((d, os.listdir(d)))
            except Exception:
                out.append((d, []))
        return out
    import concurrent.futures as cf
    from concurrent.futures import ThreadPoolExecutor
    ex = ThreadPoolExecutor(max_workers=w)
    try:
        futs = {ex.submit(os.listdir, d): d for d in dirs}
        for f in cf.as_completed(futs, timeout=budget):
            d = futs[f]
            try:
                out.append((d, f.result(timeout=0.05)))
            except Exception:
                out.append((d, []))
    except Exception:
        done = set(d for d, _ in out)
        for d in dirs:
            if d not in done:
                out.append((d, []))
    finally:
        try:
            ex.shutdown(wait=False, cancel_futures=True)   # 关键：取消挂起的 IO
        except Exception:
            pass
    return out


def _inbox_count_fast(p, budget=3.0, max_depth=6, workers=1):
    """v1.08：并发 + 限时 + 限深的 BFS 统计单个目录的视频数。

    为什么不能只探两层：实测「未识别」里的真实目录是 4~5 层嵌套，例如
      日韩剧 / 2013 / 你是谁 (2013) / Season 1 / xxx.mkv
      11.剧集_Remux / 02.Series_Remux / Series_Remux_Anime / 某剧 / S01 / xxx.mkv
    v1.07 的「探两层」和「封顶 6 个子目录」对这种结构直接漏光 → 前端显示 0，
    就是用户点名的「每个站点的数据根本都是 0」。

    v1.08 三个关键改动：
      ① 并发 listdir（_ls_par）：115 网盘顺序 IO，一层 35 个目录串行 13 秒，
         并发后约 1 秒，2 秒预算内能探完 4 层；
      ② 外推改成按「剩余层数 × 已完层的每目录均产」估算，不再用
         「本层视频数 / 本层目录数」——视频常集中在深层，老算法必然塌成 1；
      ③ 确实探完 → 精确值；预算耗尽 → approx 量级估算。
    返回 (count, approx)。
    """
    t0 = time.time()
    # v1.08b：非阻塞抢 IO 锁。抢不到说明后台正在统计 → 立刻返回 approx，
    # 调用方（mtbox_autorun_inbox）会走 pending 分支，接口照样秒回。
    if not _INBOX_IO_LOCK.acquire(blocking=False):
        return 0, True
    try:
        return _inbox_count_fast_locked(p, budget, max_depth, workers, t0)
    finally:
        _INBOX_IO_LOCK.release()


def _inbox_count_fast_locked(p, budget, max_depth, workers, t0):
    """_inbox_count_fast 的实现体（调用方必须已持有 _INBOX_IO_LOCK）。"""
    total = 0
    try:
        ents = os.listdir(p)
    except Exception:
        return 0, False
    cur = []
    for e in ents:
        if e.lower().endswith(_VIDEXT):
            total += 1
        else:
            fp = os.path.join(p, e)
            if os.path.isdir(fp):
                cur.append(fp)
    if not cur:
        return total, False          # 纯文件层，精确值
    depth = 1
    approx = False
    done_dirs = 0
    done_vid = 0
    while cur and depth < max_depth:
        if time.time() - t0 > budget:
            approx = True
            break
        nxt = []
        layer_vid = 0
        layer_dirs = 0
        for d, ents2 in _ls_par(cur, workers=workers):
            if time.time() - t0 > budget:
                approx = True
                break
            # （持锁由调用方保证；这里不做锁操作，避免每目录一次加锁开销）
            layer_dirs += 1
            for e in ents2:
                if e.lower().endswith(_VIDEXT):
                    layer_vid += 1
                else:
                    fp = os.path.join(d, e)
                    if os.path.isdir(fp):
                        nxt.append(fp)
        total += layer_vid
        if not approx:
            done_dirs += layer_dirs
            done_vid += layer_vid
        depth += 1
        if approx:
            break
        cur = nxt
    if approx:
        # 外推：按「剩余待探目录数」给量级，绝不让结果塌成 1。
        #
        # 实测坑（v1.08 遗留）：「日韩剧」4 层嵌套，视频全在第 4 层，
        # 前 3 层 layer_vid=0 → 老逻辑走 est<=1 分支返回 max(len(cur),1)=35，
        # 而真实值是 738。**量级都不对，用户照样看到「数据是 35」**。
        # 新逻辑：只要还有没探完的目录，就按「每目录至少 1 个视频」的下限
        # 再乘一个保守深度倍数，保证量级 >= 剩余目录数。
        per = (done_vid / done_dirs) if done_dirs else 0.0
        left = max(0, len(cur))
        if per > 0:
            est = int(total + per * left)
        else:
            # 前几层完全没视频：按剩余层数与目录数给保守量级
            est = int(total + left * 1.5) + 1
        if est <= total and total > 0:
            est = int(total * 2) + 1
        elif est <= 1 and left > 0:
            est = max(int(left * 1.5) + 1, 2)
        return max(est, 1), True
    return total, False


def _shallow_video_count(p, budget=1.2):
    """浅层统计视频数：只 listdir 两层，不再 os.walk 整棵树。

    对「一层就是视频文件」的条目（未识别里绝大多数单文件 Remux/原盘）足够；
    对多季/多盘目录**再下探一层做粗估**（子目录数 × 平均视频数），
    避免前端只能看到 -1（用户原话：「每个站点的数据根本都是 0」）。
    精确数仍由后台 _inbox_video_map 补。

    v1.08b：加 budget 总时限（默认 1.2 秒）。
    实测坑：115 网盘上对 50 个条目各做 1+6 次 listdir = 350 次 IO，
    会被限流到**每个目录 0.3~0.9 秒**，整轮 60 秒以上 → 用户看到
    「一直转圈 → 功能是坏的」。现在超时就地刹车，只保证返回「有没有子目录」
    （有子目录必然走缓存/后台通道，不影响最终数值准确性）。
    """
    import time as _t
    _t0 = _t.time()
    try:
        ents = os.listdir(p)
    except Exception:
        return 0, False
    n = 0
    sub = False
    subdirs = []
    for e in ents:
        if e.lower().endswith(_VIDEXT):
            n += 1
        elif os.path.isdir(os.path.join(p, e)):
            sub = True
            subdirs.append(os.path.join(p, e))
    # 一层没有视频但有子目录：再下探一层做粗估（封顶 6 个子目录）
    if n == 0 and subdirs:
        _subn = 0
        _subdir_with_vid = 0
        for d in subdirs[:6]:
            if _t.time() - _t0 > budget:      # 时限到：刹车，靠后台补精确值
                break
            try:
                ents2 = os.listdir(d)
            except Exception:
                continue
            c2 = sum(1 for e in ents2 if e.lower().endswith(_VIDEXT))
            _subn += c2
            if c2:
                _subdir_with_vid += 1
        if _subn:
            # 粗估：已探 6 个目录的视频数 / 有视频的目录数 × 总子目录数
            n = int(_subn / max(1, _subdir_with_vid) * len(subdirs))
    return n, sub


def _inbox_video_map(inbox, names, total_budget=900.0):
    """v1.08：后台统计 {name: 视频数}（分层限时 + 落盘 + 防重入）。

    老实现对每个条目 os.walk 整棵树。未识别目录里有
    「115网盘精心整理影视剧 100T」「22T 国漫」这种超大目录，一轮要好几分钟，
    期间前端只能看到 0（用户原话：「每个站点的数据根本都是 0」）。

    v1.07 改成「8 秒硬停 + 采样倍数」，实测两个问题：
      ① 100T 目录只估出 40 个视频（真实上万），量级完全不对；
      ② 缓存只在内存里，容器一重启就归零，用户又得干等。
    v1.08 改：
      ① 单条目用 _inbox_count_fast（分层限时 2.5s + 按均值外推），
         量级对得上；整轮有 total_budget 上限，绝不死循环；
      ② 结果同时写内存和落盘（_inbox_cache_save），重启不丢；
      ③ _INBOX_VIDEO_RUNNING 防重入，避免多个请求叠加起 N 个线程抢 IO。
    """
    if _INBOX_VIDEO_RUNNING['busy']:
        return _INBOX_VIDEO_CACHE['map']
    _INBOX_VIDEO_RUNNING['busy'] = True
    out = {}
    _partial = set()          # 本轮没算完（预算耗尽）的条目，不落盘
    try:
        _t_all = time.time()
        # v1.08b：按「子目录数」降序处理。实测字母序会把
        # 「115网盘…100T」「22T 国漫」「国产剧」这种深层大盘排到后面，
        # 300s 整轮预算被前面的小目录吃光 → 用户**永远**看不到大目录的
        # 精确值（一直显示「统计中…」）。子目录数是秒级可得的规模代理指标。
        def _size_hint(nm):
            try:
                return len(os.listdir(os.path.join(inbox, nm)))
            except Exception:
                return 0
        try:
            names = sorted(names, key=_size_hint, reverse=True)
        except Exception:
            pass
        for n in names:
            if time.time() - _t_all > total_budget:
                break
            # v1.08b：只把「当前正在算」的条目标出来（不是整批），
            # 前台见到就显示「统计中…」，不再把上一轮的旧脏值
            # （日韩剧=35，真实 738）当精确值透出。
            _INBOX_VIDEO_RUNNING['doing'] = set([n])
            p = os.path.join(inbox, n)
            try:
                if os.path.isdir(p):
                    # 单条目 45 秒预算（后台跑，不阻塞前台；持全局 IO 锁，
                    # 前台请求抢不到锁会立刻走 pending 分支，接口照样秒回）。
                    # 实测：串行 BFS 在 115 缓存冷/热之间波动极大
                    # （日韩剧 0.05s ~ 16.5s，国产剧 54s ~ 82s），
                    # 45s 能覆盖绝大多数结构；仍超时的记为 ≈ 量级估算。
                    cnt, apx = _inbox_count_fast(p, budget=120.0)
                    if apx:
                        # 预算耗尽 → 量级估算。v1.08b：**也写进缓存**并标 ≈，
                        # 前端显示「≈2151 视频」—— 比显示 0 / 「统计中…」
                        # 有用得多（用户诉求就是「数据不要再是 0」）。
                        # exact 值由下一轮预热算出来后覆盖。
                        if cnt > 0:
                            out[n] = cnt
                            _INBOX_APPROX.add(n)
                        else:
                            _partial.add(n)
                    else:
                        out[n] = cnt
                        _INBOX_APPROX.discard(n)
                else:
                    out[n] = 1 if n.lower().endswith(_VIDEXT) else 0
                    _INBOX_APPROX.discard(n)
            except Exception:
                out[n] = -1
            time.sleep(0.05)                # 让出 IO，别把前台请求堵死
        if out:
            _INBOX_VIDEO_CACHE['map'].update(out)
            _INBOX_VIDEO_CACHE['ts'] = time.time()
            _inbox_cache_save()   # 落盘：容器重启也不丢，用户不再干等
    finally:
        _INBOX_VIDEO_RUNNING['busy'] = False
        _INBOX_VIDEO_RUNNING['doing'] = set()
    return out


def mtbox_autorun_inbox(limit=20):
    """列「未识别」目录里可自动处理的候选（一键喂给全自动用）。

    ★ 2026-10-19 修复「点了 45s+ 无响应」：老实现对每个条目 os.walk 整棵树，
      未识别目录里有 100T 级大目录（115网盘精心整理影视剧 100T 等），
      一次请求要几分钟 → 前端超时 → 用户以为功能是坏的。
      现在：listdir 一层拿条目（毫秒级）→ 浅层判视频数 → 精确数后台补。
    """
    inbox = mtbox_inbox()
    if not os.path.isdir(inbox):
        return {'ok': False, 'msg': '未识别目录不存在：%s' % inbox, 'inbox': inbox}
    lim = max(1, min(int(limit or 20), 100))
    try:
        names = sorted(os.listdir(inbox))[:lim]
    except Exception as e:
        return {'ok': False, 'msg': '读目录失败：%s' % str(e)[:120], 'inbox': inbox}
    rows = []
    _pending_names = set()
    _approx_names = set(_INBOX_APPROX)
    _fresh = (time.time() - _INBOX_VIDEO_CACHE['ts']) < _INBOX_VIDEO_TTL

    # ★ v1.08b：整轮硬时限 3 秒。
    # 实测（2026-10-19，115 网盘 / CloudDrive2 FUSE）：
    #   · 顶层 listdir（82 项）0.00s（本地缓存命中）
    #   · 但**子目录** listdir 0.3~0.9s，且对 50 个条目各探 6 个子目录
    #     = 350 次 IO → 整轮 60 秒以上 → 用户以为功能是坏的。
    #   · 并发只会更糟（触发限流，实测 82s/62s/80s）。
    # 现在：3 秒内能探多少探多少，超预算的条目**一次 listdir 都不做**，
    # 直接标 pending 丢后台线程；前端显示「统计中…」并自动轮询补数字。
    # 接口**永远在 5 秒内返回**。
    _t_round = time.time()
    _ROUND_BUDGET = 3.0
    for n in names:
        p = os.path.join(inbox, n)
        _left = _ROUND_BUDGET - (time.time() - _t_round)
        try:
            if not os.path.isdir(p):
                nv = 1 if n.lower().endswith(_VIDEXT) else 0
                rows.append({'name': n, 'cloud': cloud_of(p), 'kind': 'file',
                             'videos': nv, 'deep': False, 'pending': False,
                             'approx': False, 'ok': nv > 0})
                continue
            kind = 'dir'
            # ★ v1.08b：**缓存优先，零 IO**。实测「日韩剧」这种 4 层目录
            # _shallow_video_count 要 2.48s，50 个条目排下来 3 秒整轮预算
            # 早就耗尽 → 排在后面的大目录（国产剧/整理综艺）永远拿不到
            # 缓存值，一直显示 0 / 「统计中…」。现在只要缓存有值就直接返回，
            # 一次 listdir 都不做，接口对已缓存的条目是**毫秒级**。
            _cached0 = _INBOX_VIDEO_CACHE['map'].get(n)
            if _cached0 is not None and _cached0 > 0:
                rows.append({'name': n, 'cloud': cloud_of(p), 'kind': kind,
                             'videos': _cached0, 'deep': False, 'pending': False,
                             'approx': n in _INBOX_APPROX, 'ok': True})
                continue
            if _left <= 0.2:
                # ★ v1.09d：时限到**也要做一次最小浅层探测**。
                # 老实现这里一次 listdir 都不做、直接 pending=0，
                # 导致「电影」这种一层就是视频文件的目录（1 次 listdir
                # 毫秒级就能算出精确值）因为排位靠后而永远显示 0 / 统计中。
                # _shallow_video_count 自带 budget 刹车，单层目录只需 1 次
                # listdir，不会拖慢接口；探到单层就立刻给精确值。
                try:
                    _nv0, _sub0 = _shallow_video_count(p, budget=0.3)
                except Exception:
                    _nv0, _sub0 = 0, True
                if not _sub0:
                    rows.append({'name': n, 'cloud': cloud_of(p), 'kind': kind,
                                 'videos': _nv0, 'deep': False, 'pending': False,
                                 'approx': False, 'ok': _nv0 > 0})
                    continue
                # 确实是深层结构：丢后台（前端显示「统计中…」）
                _pending_names.add(n)
                rows.append({'name': n, 'cloud': cloud_of(p), 'kind': kind,
                             'videos': 0, 'deep': True, 'pending': True,
                             'approx': False, 'ok': False})
                continue
            nv, sub = _shallow_video_count(p, budget=max(0.3, min(1.2, _left)))
            if not sub:
                # 单层结构（一层就是视频文件）：浅层值就是精确值
                rows.append({'name': n, 'cloud': cloud_of(p), 'kind': kind,
                             'videos': nv, 'deep': False, 'pending': False,
                             'approx': False, 'ok': nv > 0})
                continue
            # ↓↓↓ 深层结构（有子目录）：一律以落盘缓存 / 后台统计为准 ↓↓↓
            # 浅层粗估对 4~5 层嵌套会返回 22 / 37 / 11 / 144 这种
            # 「看起来像真的」的错值（真实是 86 / 2945 / 2606 / 150），
            # 所以这里**绝不采信** _shallow_video_count 的返回值。
            cached = _INBOX_VIDEO_CACHE['map'].get(n)
            _doing = _INBOX_VIDEO_RUNNING.get('doing') or set()
            if cached is not None and cached > 0 and n not in _doing:
                # ① 缓存有值且后台没在重算它：立刻用。
                nv = cached
                if n in _INBOX_APPROX:
                    _approx_names.add(n)
                rows.append({'name': n, 'cloud': cloud_of(p), 'kind': kind,
                             'videos': nv, 'deep': False, 'pending': False,
                             'approx': n in _approx_names, 'ok': nv > 0})
            elif cached is not None and cached > 0:
                # ①b 有旧值但后台正在重算：先显示旧值（带 ≈），
                #     同时标 pending，后台算完下一次轮询就换成精确值。
                nv = cached
                rows.append({'name': n, 'cloud': cloud_of(p), 'kind': kind,
                             'videos': nv, 'deep': True, 'pending': True,
                             'approx': True, 'ok': nv > 0})
            else:
                # ② 无缓存 / 正在重算：本回显示「统计中…」。
                #    入队仅当后台线程没在算它（否则同一批条目被反复入队，
                #    防重入让后来的线程直接返回，用户永远看到「统计中…」）。
                if n in _doing:
                    rows.append({'name': n, 'cloud': cloud_of(p), 'kind': kind,
                                 'videos': 0, 'deep': True, 'pending': True,
                                 'approx': False, 'ok': False})
                else:
                    _pending_names.add(n)
                    rows.append({'name': n, 'cloud': cloud_of(p), 'kind': kind,
                                 'videos': 0, 'deep': True, 'pending': True,
                                 'approx': False, 'ok': False})
        except Exception:
            rows.append({'name': n, 'cloud': cloud_of(p), 'kind': 'err',
                         'videos': 0, 'deep': False, 'pending': False,
                         'approx': False, 'ok': False})

    # 后台补精确数（不阻塞本次响应；下次刷新就有值）。线程内部有防重入
    # + 整轮预算上限（300s），不会把前台请求堵死。
    if _pending_names:
        try:
            if not _INBOX_VIDEO_RUNNING['busy']:
                # v1.09b：按「子目录数降序」入队 —— 大盘优先。
                # 老实现用 set 迭代（顺序随机），45s 预算下大盘经常跑不到，
                # 用户反复刷新都只看到小目录的数字，大盘永远是 0 / 统计中。
                def _sz(nm):
                    try:
                        return len(os.listdir(os.path.join(inbox, nm)))
                    except Exception:
                        return 0
                _q = sorted(_pending_names, key=_sz, reverse=True)
                threading.Thread(target=_inbox_video_map,
                                 args=(inbox, _q),
                                 daemon=True, name='inbox-video-map').start()
        except Exception:
            pass
    _np = len(_pending_names)
    return {'ok': True, 'inbox': inbox, 'cloud': cloud_of(inbox),
            'count': len(rows), 'items': rows,
            'pending_deep': _np, 'pending': _np,
            'approx_count': len(_approx_names),
            'note': ('%d 个深层目录的精确视频数正在后台统计，算完会自动补上，无需手动刷新；'
                     '带 ≈ 的是量级估算' % _np) if _np else ''}


def mtbox_config():
    cfg = mt_sys_cfg() or {}
    t = cfg.get('tmdb') or {}
    return {'ok': True, 'mt_base': mt_base(), 'db': DB, 'mount': MOUNT,
            'inbox': mtbox_inbox(), 'inbox_ok': os.path.isdir(mtbox_inbox()),
            'mount_ok': os.path.isdir(MOUNT), 'db_ok': os.path.exists(DB),
            'tmdb_key': bool(t.get('apiKey')), 'tmdb_proxy': tmdb_proxy()}


def mtbox_get(p, q1):
    if p == '/api/mtbox/stats':
        return mtbox_stats(int(q1('days', '2') or 2))
    if p == '/api/mtbox/failures':
        return mtbox_failures(int(q1('days', '2') or 2), q1('code') or None,
                              int(q1('limit', '40') or 40))
    if p == '/api/mtbox/records':
        return mtbox_records(q1('like') or '%', int(q1('limit', '40') or 40))
    if p == '/api/mtbox/ls':
        return mtbox_ls(q1('path'))
    if p == '/api/mtbox/tmdb/search':
        return mtbox_tmdb_search(q1('q'), q1('kind'), q1('year') or None)
    if p == '/api/mtbox/config':
        return mtbox_config()
    if p == '/api/mtbox/autorun/inbox':
        return mtbox_autorun_inbox(int(q1('limit') or 20))
    return {'ok': False, 'msg': '未知接口 %s' % p}


def mtbox_post(p, b):
    if p == '/api/mtbox/tmdb/resolve':
        return mtbox_resolve(b.get('name', ''), b.get('kind') or None,
                             b.get('year') or None, b.get('season') or None)
    if p == '/api/mtbox/submit':
        return mtbox_submit(b)
    if p == '/api/mtbox/pipeline/scan':
        return mtbox_scan(int(b.get('limit') or 20))
    if p == '/api/mtbox/pipeline/run':
        return mtbox_run(b.get('mode', 'dry'), b.get('table') or {}, b.get('profile'))
    if p == '/api/mtbox/iso':
        return mtbox_iso(b.get('path'))
    if p == '/api/mtbox/autorun/scan':
        return mtbox_autorun_scan(b)
    if p == '/api/mtbox/autorun/run':
        return mtbox_autorun_run(b)
    return {'ok': False, 'msg': '未知接口 %s' % p}


