def _ui_page(title, body, cur=''):
    nav = ('<a href="/" >总览</a>'
           '<a href="/features" class="%s">功能中心</a>'
           '<a href="/qb" class="%s">qB 详情</a>'
           '<a href="/pipeline" class="%s">入库流水线</a>' % (
               'cur' if cur == 'features' else '',
               'cur' if cur == 'qb' else '',
               'cur' if cur == 'pipeline' else ''))
    return ('<!doctype html><html lang="zh-CN"><head><meta charset="utf-8">'
            '<meta name="viewport" content="width=device-width,initial-scale=1">'
            '<title>%s · Media Hub</title><style>%s</style></head>'
            '<body><div class="wrap"><nav>%s</nav>%s</div></body></html>'
            ) % (title, UI_CSS, nav, body)


def qb_dash_html():
    body = r'''
    <div class="top"><h1>qBittorrent 种子详情</h1><span class="ver">方案4 · 点击任意种子查看 Trackers / Peers / 文件</span></div>
    <div class="card">
      <div class="row">
        <input id="q" placeholder="搜索种子名…" style="flex:1;min-width:200px">
        <button id="rf" class="sec">刷新</button>
        <span id="cnt" class="muted"></span>
      </div>
      <div class="scroll"><table id="tb"><thead><tr>
        <th>名称</th><th>状态</th><th>进度</th><th>↑速度</th><th>↓速度</th><th>做种</th><th>下载量</th><th>上传量</th>
      </tr></thead><tbody></tbody></table></div>
    </div>
    <div class="card" id="det" style="display:none"><h2><span class="ic">🔬</span> 详细参数</h2><div id="detbody"></div></div>
    <script>
    const fmtB=b=>{if(b==null)return'-';const u=['B','KB','MB','GB','TB'];let i=0;while(b>=1024&&i<u.length-1){b/=1024;i++}return b.toFixed(1)+' '+u[i]};
    const fmtS=s=>{if(!s||s<0)return'-';s=Math.round(s);const h=Math.floor(s/3600),m=Math.floor(s%3600/60),x=s%60;return (h?h+'h':'')+(m?m+'m':'')+x+'s'};
    let DATA=[];
    async function load(){const btn=document.getElementById('rf');btn.disabled=true;btn.innerHTML='<span class="spin"></span>刷新中';
      try{const r=await fetch('/api/action',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({svc:'qbittorrent',act:'torrents'})});
      const j=await r.json();DATA=j.data||[];render();}catch(e){alert('加载失败: '+e);}finally{btn.disabled=false;btn.textContent='刷新';}}
    function stateTag(s){const c={downloading:'ok',seeding:'ok',stalled:'warn',uploading:'ok',paused:'mut',queued:'mut',checking:'warn',allocating:'mut'};return '<span class="tag '+(c[s]||'mut')+'">'+(s||'-')+'</span>';}
    function render(){const q=document.getElementById('q').value.toLowerCase();
      const rows=DATA.filter(t=>(t.name||'').toLowerCase().includes(q));
      document.getElementById('cnt').textContent='共 '+DATA.length+' 个，匹配 '+rows.length;
      const tb=document.querySelector('#tb tbody');tb.innerHTML='';
      for(const t of rows){const tr=document.createElement('tr');tr.style.cursor='pointer';
        tr.innerHTML='<td>'+(t.name||'')+'</td><td>'+stateTag(t.state)+'</td><td>'+((t.progress||0).toFixed(1))+'%</td><td>'+fmtB(t.upspeed)+'/s</td><td>'+fmtB(t.dlspeed)+'/s</td><td>'+(t.num_seeds==null?'-':t.num_seeds)+'</td><td>'+fmtB(t.total_size)+'</td><td>'+fmtB(t.total_uploaded)+'</td>';
        tr.onclick=()=>detail(t.hash,t.name);tb.appendChild(tr);}}
    async function detail(hash,name){const box=document.getElementById('det');box.style.display='';
      document.getElementById('detbody').innerHTML='<span class="spin"></span>加载 '+name+' …';
      try{const r=await fetch('/api/qb/detail?hash='+encodeURIComponent(hash));const j=await r.json();
        if(!j.ok){document.getElementById('detbody').innerHTML='<span class="tag bad">'+j.msg+'</span>';return;}
        let h='<div class="muted" style="margin-bottom:8px">'+name+'</div>';
        h+='<div class="grid" style="grid-template-columns:repeat(auto-fill,minmax(165px,1fr))">';
        const p=j.props||{};const kv=[['保存路径',p.save_path],['总大小',fmtB(p.total_size)],['已上传',fmtB(p.total_uploaded)],['分享率',p.ratio],['做种时长',fmtS(p.seeding_time)],['活跃时长',fmtS(p.time_active)],['可用度',p.availability],['下载限速',p.dl_limit?fmtB(p.dl_limit)+'/s':'不限'],['上传限速',p.up_limit?fmtB(p.up_limit)+'/s':'不限'],['最后完整时刻',p.last_seen_complete]];
        for(const [k,v] of kv){h+='<div class="kpi"><div class="n" style="font-size:13px;word-break:break-all">'+(v==null||v===''?'<span class=muted>-</span>':v)+'</div><div class="l">'+k+'</div></div>';}
        h+='</div>';
        if(j.trackers&&j.trackers.length){h+='<h2 style="margin-top:16px"><span class="ic">🛰️</span> Trackers ('+j.trackers.length+')</h2><div class="scroll"><table><thead><tr><th>URL</th><th>状态</th><th>Peer数</th><th>信息</th></tr></thead><tbody>';
          for(const t of j.trackers){h+='<tr><td style="word-break:break-all">'+(t.url||'')+'</td><td>'+trk(t.status)+'</td><td>'+(t.num_peers||0)+'</td><td class=muted>'+(t.msg||'')+'</td></tr>';}
          h+='</tbody></table></div>';}
        if(j.files&&j.files.length){h+='<h2 style="margin-top:16px"><span class="ic">📁</span> 文件 ('+j.files.length+')</h2><div class="scroll"><table><thead><tr><th>名称</th><th>大小</th><th>进度</th><th>优先级</th></tr></thead><tbody>';
          for(const f of j.files){h+='<tr><td style="word-break:break-all">'+(f.name||'')+'</td><td>'+fmtB(f.size)+'</td><td>'+f.progress+'%</td><td><span class="pill">'+(f.priority||'-')+'</span></td></tr>';}
          h+='</tbody></table></div>';}
        if(j.peers&&j.peers.length){h+='<h2 style="margin-top:16px"><span class="ic">👥</span> Peers ('+j.peers.length+')</h2><div class="scroll"><table><thead><tr><th>IP</th><th>客户端</th><th>↓</th><th>↑</th></tr></thead><tbody>';
          for(const p of j.peers){h+='<tr><td>'+(p.ip||'')+'</td><td>'+(p.client||'')+'</td><td>'+fmtB(p.dl)+'/s</td><td>'+fmtB(p.up)+'/s</td></tr>';}
          h+='</tbody></table></div>';}
        document.getElementById('detbody').innerHTML=h;box.scrollIntoView({behavior:'smooth',block:'start'});
      }catch(e){document.getElementById('detbody').innerHTML='<span class="tag bad">错误: '+e+'</span>';}}
    function trk(s){if(s==0)return '<span class=tag ok>工作中</span>';if(s>0)return '<span class=tag bad>'+s+'</span>';return '<span class=tag mut>已禁用/未知('+s+')</span>';}
    document.getElementById('q').oninput=render;document.getElementById('rf').onclick=load;load();
    </script>
    '''
    return _ui_page('qB 种子详情', body, cur='qb')


