# ════════════════════════════════════════════════════════════════
# 命名整理自动化任务（原「群友命名 zip」rename.py 的引擎化 + 定时/手动触发）
# 作用：把 115 指定目录里的视频文件改名成 MT 能识别的「标题.年份.SxxExx」，
#       改名后可选地移动到另一个 115 目录（由 MT 的整理方案负责后续入库）。
# 触发方式对齐 MT organize 方案：off(手动) / polling(间隔) / cron(定时)，默认 off。
# ════════════════════════════════════════════════════════════════
def naming_load():
    d = cfg()
    t = (d or {}).get('naming')
    if isinstance(t, dict) and 'tasks' in t:
        return t
    return {'tasks': []}


def naming_save(state):
    c = cfg() or {}
    c['naming'] = state
    save_cfg(c)
    return state


def cron_match(expr, now=None):
    """最小 5 字段 cron 匹配（分 时 日 月 周），支持 * - , /。"""
    try:
        f = (expr or '').split()
        if len(f) != 5:
            return False
        now = now or datetime.datetime.now()
        vals = [now.minute, now.hour, now.day, now.month, now.weekday()]
        for v, cur in zip(f, vals):
            if v == '*':
                continue
            if ',' in v:
                if str(cur) not in v.split(','):
                    return False
            elif '-' in v:
                a, b = v.split('-')
                if not (int(a) <= cur <= int(b)):
                    return False
            elif '/' in v:
                if cur % int(v.split('/')[1]) != 0:
                    return False
            else:
                if int(v) != cur:
                    return False
        return True
    except Exception:
        return False


def _nm_cells(src):
    """源目录下可处理单元（三种，按商用场景覆盖全）：

    1) 每个「直接含视频的子目录」= 一捆剧/一部电影（主场景）；
    2) 源目录里**散装视频文件** = 每个文件自成一个单元（原来把它们整包当成
       一个名为父目录名的单元，永远识别不了，还白耗一次 TMDB 调用）；
    3) 源目录本身只在「既无子目录、又无散装文件可拆」时才兜底加入。

    返回 [(path, kind)]，kind ∈ {'dir','file'}。
    """
    cells = []

    def hasvid(p):
        try:
            for e in os.scandir(p):
                if e.is_file() and e.name.lower().endswith(_VID_EXT):
                    return True
        except Exception:
            pass
        return False
    try:
        entries = sorted(os.listdir(src))
    except Exception:
        return cells
    loose = []
    for n in entries:
        p = os.path.join(src, n)
        try:
            if os.path.isfile(p):
                if n.lower().endswith(_VID_EXT):
                    loose.append(p)
            elif os.path.isdir(p) and hasvid(p):
                cells.append((p, 'dir'))
        except Exception:
            continue
    if loose:
        cells.extend((p, 'file') for p in loose)
    elif not cells:
        cells.append((src, 'dir'))
    # ★ v1.06 全自动扫描速度保护：“115网盘精心整理影视剧 100T”、
    #   “2026长时连载国漫 22T” 这类巨盘，寄存着数千部片子——
    #   它们本身就不该被当成「一部待整理的目录」（能力上就不可能看懂），
    #   但会把扫描批次占爆＋一次 TMDB 检索就是几十秒。
    #   这里给“子目录数很多」的大盘标上 bulk 标记，预览/执行时默认跳过，
    #   但在回报里明列出来（只增不减：用户想强制包含时仍然可以）。
    bulk = []
    for i, (pth, kd) in enumerate(cells):
        if kd != 'dir':
            continue
        try:
            nsub = sum(1 for e in os.scandir(pth) if e.is_dir())
        except Exception:
            nsub = 0
        if nsub >= _NM_BULK_SUBDIR_N:
            bulk.append(pth)
            cells[i] = (pth, 'dir:bulk')
    if bulk:
        globals().setdefault('_NM_BULK_CACHE', {})[src] = bulk
    return cells


# 大盘阈值：子目录 >= 这个数就认为是「整包影视库」而非「一部待整理的目录」
_NM_BULK_SUBDIR_N = 12


def naming_autorun(task, dry=False, budget=120):
    """★ 全自动重命名（基于 MT tool 识别）：用户只选「源目录 + 目标目录」，不需人工逐个识别。
    流程：源目录每个子项(一部剧/一捆集) → mtbox_resolve 自动定位 TMDB（唯一命中才动手，
         定不了进 need 留人工，绝不乱猜）→ 剧集按 SxxEyy rename_plan2 改名 / 电影只规范目录
         → 移动到目标并以『剧名 (年份) [tmdbid-id]』命名（MT 目录级快路径 100% 命中）
         → 勾了 mt_after 再联动 MT 建整理任务。"""
    raw_src = (task.get('sourceDir') or task.get('dir') or task.get('src') or '').strip()
    src = host_of(raw_src)
    if not raw_src:
        return {'ok': False, 'msg': '请先选「源目录」（里面是一堆待整理子目录/视频的父目录）'}
    if not src or not os.path.isdir(src):
        return {'ok': False, 'msg': '源目录不存在：%s（云盘/宿主机两种写法都试过，解析为 %s；'
                '请用「📂 选目录」挑，或确认该目录在 115 里存在）' % (raw_src, src)}
    tg = (task.get('targetDir') or '').strip()
    do_move = bool(tg) and task.get('mode') != 'rename_only'
    dst = host_of(tg) if do_move else None
    if do_move and not os.path.isdir(dst):
        try:
            os.makedirs(dst, exist_ok=True)
        except Exception as _e:
            return {'ok': False, 'msg': '目标目录无法创建：%s（%s）' % (dst, str(_e)[:100])}
    cells = _nm_cells(src)
    rep = {'ok': True, 'dry': bool(dry), 'scanned': len(cells), 'processed': 0,
           'recognized': 0, 'renamed_files': 0, 'moved': 0,
           'items': [], 'need': [], 'errors': [], 'stopped': False, 'skipped': []}
    # _nm_cells 现在返回 (path, kind)；兼容旧的纯路径 list
    if not cells:
        rep['msg'] = '源目录里没有可处理的视频单元'
        return rep
    if do_move:
        try:
            os.makedirs(dst, exist_ok=True)
        except Exception as e:
            rep['errors'].append({'name': '-', 'msg': '建目标目录失败：%s' % str(e)[:100]})
            do_move = False
    sleep_i = max(0.3, float(task.get('tmdb_sleep') or 1.5))
    budget = max(1, int(budget))
    for cell in cells:
        if rep['processed'] >= budget:
            rep['stopped'] = True
            break
        d, ckind = cell if isinstance(cell, tuple) else (cell, 'dir')
        # ★ v1.07 修复「bulk 标记了却没人处理」：_nm_cells 把「子目录 ≥ 12 的整包影视库」
        #   标成 kind='dir:bulk'，但本循环从来没有对应分支 —— 它会被当成普通目录
        #   （name=basename）去打 TMDB，一次几十秒还必然识别不了，
        #   而结尾 rep['bulk_skipped'] 永远读不到值 → 前端「已跳过 N 个整包影视库」
        #   永远不显示。现在补齐跳过分支（只增不减：仍可通过 include_bulk 强制纳入）。
        if ckind == 'dir:bulk' and not task.get('include_bulk'):
            rep['skipped'].append({'name': os.path.basename(d.rstrip('/')),
                                   'reason': '整包影视库（子目录 ≥ %d），本身不是单部作品' % _NM_BULK_SUBDIR_N})
            continue
        if ckind == 'file':
            name = os.path.splitext(os.path.basename(d))[0]
            # 散装文件：目录名 = 源目录名，先试一次；识别不了就并入同批的 need
            probe_dir = os.path.basename(src.rstrip('/'))
        else:
            name = os.path.basename(d.rstrip('/'))
            probe_dir = name
        is_root = (ckind == 'dir' and os.path.normpath(d) == os.path.normpath(src))
        rep['processed'] += 1
        try:
            r = mtbox_resolve(name or probe_dir, ai=bool(task.get('ai_pick', True)))
        except Exception as e:
            rep['errors'].append({'name': name or probe_dir, 'msg': str(e)[:120]})
            continue
        cand = r.get('cand')
        if not cand:
            rep['need'].append({'name': name, 'reason': (r.get('reason') or '')[:140]})
            time.sleep(sleep_i)
            continue
        rep['recognized'] += 1
        title = cand.get('title') or name
        year = (cand.get('year') or '')[:4]
        std = '%s (%s) [tmdbid-%s]' % (title, year, cand.get('id'))
        std = re.sub(r'[\\/:*?"<>|]', '-', std).strip()
        item = {'name': name or probe_dir, 'cell': ckind,
                'tmdb': cand.get('id'), 'kind': cand.get('kind'),
                'title': title, 'year': year, 'std_dir': std, 'renamed': 0}
        # 已是标准名（含 tmdbid 且同名）→ 跳过，重跑幂等
        if is_root:
            item['note'] = '源目录整体（含多个子项时勿选整包模式）'
        if cand.get('kind') == 'movie':
            item['note'] = '电影：保持原文件名，仅规范目录'
            if ckind == 'file':
                # 散装电影文件：不进 rename_plan2（它只吃目录），
                # 直接把文件搬进 『片名 (年份) [tmdbid-id]』 目录，MT 就能识别。
                if do_move and not dry:
                    tdir = os.path.join(dst, std)
                    try:
                        os.makedirs(tdir, exist_ok=True)
                        tpath = os.path.join(tdir, os.path.basename(d))
                        if os.path.exists(tpath):
                            tpath = os.path.join(tdir, '%s-%s%s' % (
                                os.path.splitext(os.path.basename(d))[0],
                                time.strftime('%m%d%H%M%S'),
                                os.path.splitext(d)[1]))
                        shutil.move(d, tpath); rep['moved'] += 1
                        item['moved_to'] = cloud_of(tpath)
                    except Exception as e:
                        rep['errors'].append({'name': item['name'],
                                              'msg': '移动失败：%s' % str(e)[:100]})
                else:
                    item['renamed'] = 1
                    item['will'] = '将移入 %s' % std
                # ★ v1.07 修复「全自动但什么都没改」：老实现里 ckind=='file' 的电影
                #   在 rename_only（无目标目录）模式下，item['renamed']=1 报"将改名"，
                #   磁盘上一个字节都没动 → rep['renamed_files']=0 → 联动 MT 的门槛
                #   (moved>0 or renamed_files>0) 不满足 → mt_created 为 None。
                #   用户看到的正是「点了全自动，任务建了但 MT 那边什么都没有」。
                #   现在：只改名模式下也真的把文件搬进『片名 (年份) [tmdbid-id]』
                #   子目录（同一父目录下，不移动出源目录），MT 的目录级快路径
                #   才能命中 —— 这才是"整理"该有的结果。
                if not dry and not do_move:
                    _tdir = os.path.join(os.path.dirname(d.rstrip('/')) or src, std)
                    try:
                        os.makedirs(_tdir, exist_ok=True)
                        _tpath = os.path.join(_tdir, os.path.basename(d))
                        if os.path.exists(_tpath):
                            _tpath = os.path.join(_tdir, '%s-%s%s' % (
                                os.path.splitext(os.path.basename(d))[0],
                                time.strftime('%m%d%H%M%S'),
                                os.path.splitext(d)[1]))
                        shutil.move(d, _tpath)
                        rep['renamed_files'] += 1
                        rep['moved'] += 1
                        item['moved_to'] = cloud_of(_tpath)
                        item['note'] = '已归入标准目录：%s' % std
                    except Exception as e:
                        rep['errors'].append({'name': item['name'],
                                              'msg': '归目录失败：%s' % str(e)[:100]})
                rep['items'].append(item)
                time.sleep(sleep_i)
                continue
            if do_move and not dry:
                tpath = os.path.join(dst, std)
                if os.path.exists(tpath):
                    tpath = os.path.join(dst, '%s-%s' % (std, time.strftime('%m%d%H%M%S')))
                try:
                    shutil.move(d, tpath); rep['moved'] += 1; item['moved_to'] = cloud_of(tpath)
                except Exception as e:
                    rep['errors'].append({'name': name, 'msg': '移动失败：%s' % str(e)[:100]})
        elif ckind == 'file':
            # 散装剧集文件：rename_plan2 只吃目录，这里按 SxxEyy 直接给文件改名，
            # 再搬进标准目录。改名规则与 rename_plan2 的 L1 一致（同一套 _ep2）。
            if _ep2(d):
                s_, e_ = _ep2(d)
                newname = '%s (%s) S%02dE%02d%s' % (
                    title, year or '0000', s_ or 1, e_ or 1,
                    os.path.splitext(d)[1])
                item['renamed'] = 1
                item['will'] = '%s → %s' % (os.path.basename(d), newname)
                if do_move and not dry:
                    tdir = os.path.join(dst, std)
                    try:
                        os.makedirs(tdir, exist_ok=True)
                        shutil.move(d, os.path.join(tdir, newname))
                        rep['moved'] += 1
                        item['moved_to'] = cloud_of(os.path.join(tdir, newname))
                    except Exception as e:
                        rep['errors'].append({'name': item['name'],
                                              'msg': '移动失败：%s' % str(e)[:100]})
                rep['renamed_files'] += 1
            else:
                # 解析不出集号（如「凡人百世书 第一季.mp4」整季一个文件）：
                # 不乱猜集号，但仍搬进标准目录 —— MT 靠目录名『剧名 (年份) [tmdbid-id]』
                # 的目录级快路径就能识别，交给 MT 去判定。
                item['note'] = '文件名解析不出集号：保留原文件名，仅移入标准目录交给 MT 判定'
                if do_move and not dry:
                    tdir = os.path.join(dst, std)
                    try:
                        os.makedirs(tdir, exist_ok=True)
                        shutil.move(d, os.path.join(tdir, os.path.basename(d)))
                        rep['moved'] += 1
                        item['moved_to'] = cloud_of(os.path.join(tdir, os.path.basename(d)))
                    except Exception as e:
                        rep['errors'].append({'name': item['name'],
                                              'msg': '移动失败：%s' % str(e)[:100]})
                else:
                    item['will'] = '将移入 %s' % std
            rep['items'].append(item)
            time.sleep(sleep_i)
            continue
        else:
            pl = rename_plan2(d, title=title, year=year or None)
            plan = pl.get('plan') or []
            nchg = sum(1 for x in plan if x.get('need'))
            if not dry and plan:
                prerename_apply(d, plan, dry=False)
            item['renamed'] = nchg
            item['date_mode'] = pl.get('date_mode')
            item['unparsed'] = pl.get('unparsed')
            rep['renamed_files'] += nchg
            if do_move and not dry:
                tpath = os.path.join(dst, std)
                if os.path.exists(tpath):
                    tpath = os.path.join(dst, '%s-%s' % (std, time.strftime('%m%d%H%M%S')))
                try:
                    shutil.move(d, tpath); rep['moved'] += 1; item['moved_to'] = cloud_of(tpath)
                except Exception as e:
                    rep['errors'].append({'name': name, 'msg': '移动失败：%s' % str(e)[:100]})
        rep['items'].append(item)
        time.sleep(sleep_i)
    # 联动 MT：勾了 mt_after 且（有移动 或 有改名）就跑。没给目标目录时
    # 退化为对源目录建任务（MT 会自己发现已改名好的文件）。
    # ★ v1.07：门槛从「有移动/有改名」放宽到「本轮真的识别出了东西」。
    #   老门槛在幂等重跑时永远不满足（文件已归好目录，第二跑 moved=0）→
    #   用户重复点全自动就再也不建 MT 任务，表现为"时灵时不灵"。
    #   MT 侧建任务是幂等的（按 sourceDir 查重），重复建不会产生重复任务。
    if (not dry) and task.get('mt_after') and (rep['recognized'] > 0):
        _tg = tg if (do_move and tg) else raw_src
        if _tg:
            try:
                create([_tg])
                rep['mt_created'] = 'submitted'
                rep['mt_msg'] = ('已联动 MediaTidy 建整理任务（源：%s）' % _tg)
                rep['mt_note'] = ('本轮磁盘改动 0 项（可能已整理过，幂等），仍按识别结果重建/确认 MT 任务'
                                  if (rep['moved'] == 0 and rep['renamed_files'] == 0) else '')
            except Exception as e:
                rep['mt_created'] = 'error:%s' % str(e)[:60]
                rep['mt_msg'] = '联动 MT 失败：%s' % str(e)[:80]
        else:
            rep['mt_created'] = 'skipped-no-target'
            rep['mt_msg'] = '未联动 MT：源目录为空（无法确定 MT 任务的 sourceDir）'
    elif (not dry) and task.get('mt_after') and rep['recognized'] == 0:
        rep['mt_created'] = 'skipped-nothing-recognized'
        rep['mt_msg'] = '未联动 MT：本轮没有识别出任何影片（待人工 %d 项），不乱建任务' % len(rep['need'])
    if dry:
        rep['msg'] = '预览：扫描 %s 个单元（本轮预算 %d），可识别 %s、将改名 %d 个文件、待人工 %d——点「开始执行」才真实改动' % (
            rep['scanned'], budget, rep['recognized'], rep['renamed_files'], len(rep['need']))
    else:
        rep['msg'] = '完成：处理 %s/%s，识别 %s、改名 %d 文件、移动 %d 目录；待人工 %d、错误 %d' % (
            rep['processed'], rep['scanned'], rep['recognized'], rep['renamed_files'],
            rep['moved'], len(rep['need']), len(rep['errors']))
    if rep.get('stopped'):
        rep['msg'] += '（达本轮上限，剩余 %d 项请再次执行）' % (rep['scanned'] - rep['processed'])
    # ★ v1.07：skipped 里既有整包影视库，也预留其他跳过原因，这里统一汇总成计数
    if rep['skipped']:
        rep['bulk_skipped'] = len(rep['skipped'])
        rep['bulk'] = [x.get('name') for x in rep['skipped'] if x.get('name')]
    # ★ v1.06 大盘说明：把跳过的整包影视库明说出来，否则用户会以为「扫描了但没扫到」
    if rep.get('bulk_skipped'):
        rep['msg'] += ('；已跳过 %d 个整包影视库（子目录 ≥ %d，本身就是大库不是单部作品，'
                       '如「%s」）' % (rep['bulk_skipped'], _NM_BULK_SUBDIR_N, rep['bulk'][0]))
    rep['remaining'] = rep['scanned'] - rep['processed']
    return rep


def naming_run(task):
    """改名源目录（及直接子目录）→ 可选移动目标目录。返回结果 dict。"""
    src = host_of(task.get('sourceDir', ''))
    if not src or not os.path.isdir(src):
        return {'ok': False, 'msg': '源目录不存在：%s' % task.get('sourceDir', '')}
    tg = (task.get('targetDir') or '').strip()
    do_move = bool(tg) and task.get('mode') != 'rename_only'
    title = (task.get('title') or '').strip() or None
    year = (task.get('year') or '').strip() or None
    season = (task.get('season') or '').strip()
    season = int(season) if season and season.isdigit() else None
    try:
        entries = sorted(os.listdir(src))
    except Exception as e:
        return {'ok': False, 'msg': '读源目录失败：%s' % str(e)[:160]}
    # 待处理对象：源目录本身(若直接含视频) + 其直接子目录(含视频)
    work = []
    if any(n.lower().endswith(_VID_EXT) and os.path.isfile(os.path.join(src, n)) for n in entries):
        work.append(src)
    for n in entries:
        p = os.path.join(src, n)
        if os.path.isdir(p) and any(m.lower().endswith(_VID_EXT) for m in os.listdir(p) if os.path.isfile(os.path.join(p, m))):
            work.append(p)
    if not work:
        return {'ok': False, 'msg': '源目录及其子目录都没有视频文件'}
    renamed = []
    for d in work:
        r = rename_plan2(d, title, year, season, None, 1, 'split', True)
        if not r.get('ok'):
            continue
        plan = r.get('plan') or []
        if not plan:
            continue
        prerename_apply(d, plan, dry=False)
        renamed.append({'dir': os.path.basename(d.rstrip('/')), 'n': len(plan)})
    if not renamed:
        return {'ok': False, 'msg': '没有可改名的文件（可能已命名过，或目录名无法识别剧名）', 'renamed': []}
    moved = 0
    if do_move:
        dst = host_of(tg)
        try:
            os.makedirs(dst, exist_ok=True)
        except Exception:
            pass
        for d in work:
            name = os.path.basename(d.rstrip('/'))
            try:
                shutil.move(d, os.path.join(dst, name))
                moved += 1
            except Exception:
                pass
    return {'ok': True, 'msg': '改名 %d 个目录，移动 %d 个' % (len(renamed), moved),
            'renamed': renamed, 'moved': moved,
            'mt_created': _naming_mt_link(task, moved)}


def _naming_mt_link(task, moved):
    """★ 2026-10-15 用户要求：目录整理完 → 联动 MT 自动建整理任务并启动执行。
    仅当任务勾了 mt_after 且真的移动过目录时才建（空跑不建）。
    建失败不阻断命名主流程，只在回执里说明。"""
    try:
        if not task.get('mt_after'):
            return None
        if moved <= 0:
            return 'skipped-nothing-moved'
        tg = (task.get('targetDir') or '').strip()
        if not tg:
            return 'skipped-no-target'
        try:
            create([tg])
            return 'submitted'
        except Exception as e:
            return 'error:%s' % str(e)[:60]
    except Exception:
        return None


def _naming_loop():
    """守护线程：按触发方式自动跑命了名的任务。"""
    while True:
        time.sleep(20)
        try:
            st = naming_load()
            tasks = st.get('tasks') or []
            now = time.time()
            changed = False
            for t in tasks:
                if not t.get('enabled'):
                    continue
                trig = t.get('trigger', 'off')
                if trig == 'off':
                    continue
                if trig == 'cron':
                    if not cron_match(t.get('cronExpr', ''), datetime.datetime.now()):
                        continue
                elif trig == 'polling':
                    iv = max(30, int(t.get('interval') or 300))
                    if now - (t.get('last_run_epoch') or 0) < iv:
                        continue
                else:
                    continue
                if now - (t.get('last_run_epoch') or 0) < 60:   # cron 防同分钟重复
                    continue
                r = naming_autorun(t) if t.get('auto') else naming_run(t)
                t['last_run'] = time.strftime('%Y-%m-%d %H:%M')
                t['last_run_epoch'] = now
                t['last_msg'] = r.get('msg', '')
                changed = True
            if changed:
                naming_save(st)
        except Exception:
            pass


def _logged_autorun(b, budget):
    # ★ v1.11 多目录批量：sourceDirs 有多个时走合并版（同一套官方识别逻辑）
    _dirs = autorun_dirs(b)
    if len(_dirs) > 1:
        r = autorun_multi(b, _dirs, dry=False, budget=budget)
        oplog('naming', 'autorun-multi', '全自动重命名（多目录 %d 个）' % len(_dirs),
              r.get('ok'), r.get('msg'))
        try:
            if b.get('id'):
                st = naming_load()
                for t in st.get('tasks', []):
                    if t.get('id') == b.get('id'):
                        t['last_run'] = time.strftime('%Y-%m-%d %H:%M')
                        t['last_run_epoch'] = time.time()
                        t['last_msg'] = (r.get('msg') or '')[:120]
                naming_save(st)
        except Exception:
            pass
        return r
    r = naming_autorun(b, dry=False, budget=budget)
    oplog('naming', 'autorun', '全自动重命名 · %s' % (b.get('sourceDir') or ''), r.get('ok'), r.get('msg'))
    try:
        if b.get('id'):
            st = naming_load()
            for t in st.get('tasks', []):
                if t.get('id') == b.get('id'):
                    t['last_run'] = time.strftime('%Y-%m-%d %H:%M')
                    t['last_run_epoch'] = time.time()
                    t['last_msg'] = (r.get('msg') or '')[:120]
            naming_save(st)
    except Exception:
        pass
    return r


def naming_get(p, q1):
    if p == '/api/naming/tasks':
        return {'ok': True, 'tasks': naming_load().get('tasks', [])}
    return {'ok': False, 'msg': 'unknown'}


def naming_post(p, b):
    if p == '/api/naming/save':
        tasks = naming_load().get('tasks', [])
        tid = (b.get('id') or '').strip()
        rec = {
            'id': tid or ('n%d' % int(time.time())),
            'name': (b.get('name') or '').strip() or '未命名任务',
            'sourceDir': (b.get('sourceDir') or '').strip(),
            'targetDir': (b.get('targetDir') or '').strip(),
            'title': (b.get('title') or '').strip(),
            'year': (b.get('year') or '').strip(),
            'season': (b.get('season') or '').strip(),
            'mode': b.get('mode') or 'rename_move',
            'enabled': bool(b.get('enabled')),
            'trigger': b.get('trigger') or 'off',
            'interval': int(b.get('interval') or 300),
            'cronExpr': (b.get('cronExpr') or '').strip() or '0 3 * * *',
            'mt_after': bool(b.get('mt_after')),
            'auto': bool(b.get('auto')),
            'tmdb_sleep': float(b.get('tmdb_sleep') or 1.5),
            # ★ v1.11 多目录批量：批量勾选的源目录组（跨目录勾选，后端逐个跑再合并）
            'sourceDirs': autorun_dirs(b),
            'last_run': '', 'last_run_epoch': 0, 'last_msg': '',
        }
        if not rec['sourceDir']:
            return {'ok': False, 'msg': '源目录必填'}
        if tid:
            for i, t in enumerate(tasks):
                if t.get('id') == tid:
                    rec['last_run'] = t.get('last_run', '')
                    rec['last_run_epoch'] = t.get('last_run_epoch', 0)
                    rec['last_msg'] = t.get('last_msg', '')
                    tasks[i] = rec
                    break
            else:
                tasks.append(rec)
        else:
            tasks.append(rec)
        naming_save({'tasks': tasks})
        return {'ok': True, 'task': rec}
    if p == '/api/naming/del':
        st = naming_load()
        st['tasks'] = [t for t in st.get('tasks', []) if t.get('id') != b.get('id')]
        naming_save(st)
        return {'ok': True, 'msg': '已删除'}
    if p == '/api/naming/autorun':
        dry = bool(b.get('dry'))
        budget = int(b.get('budget') or 120)
        # ★ v1.11 多目录批量：sourceDirs 有多个 → 逐个跑官方识别逻辑再合并
        _mdirs = autorun_dirs(b)
        if len(_mdirs) > 1:
            return autorun_multi(b, _mdirs, dry=dry, budget=budget)
        if dry:
            return naming_autorun(b, dry=True, budget=budget)
        if b.get('id'):
            _t = next((x for x in naming_load().get('tasks', []) if x.get('id') == b.get('id')), None)
            if _t:
                b = dict(_t, **{k: v for k, v in b.items() if v not in (None, '')})
        jid = submit('naming.autorun', lambda: _logged_autorun(b, budget))
        return {'ok': True, 'async': True, 'job': jid,
                'msg': '全自动重命名已转入后台（大目录较慢，进度看任务列表「上次结果」）'}
    if p == '/api/naming/run':
        st = naming_load()
        t = next((t for t in st.get('tasks', []) if t.get('id') == b.get('id')), None)
        if not t:
            return {'ok': False, 'msg': '任务不存在'}
        r = naming_run(t)
        t['last_run'] = time.strftime('%Y-%m-%d %H:%M')
        t['last_run_epoch'] = time.time()
        t['last_msg'] = r.get('msg', '')
        naming_save(st)
        return r
    return {'ok': False, 'msg': 'unknown'}


