    def _prewarm():
        # v1.08：开机先读盘把 inbox 深层目录的视频数顶上，再后台刷新一遍。
        # 老实现这里是空壳 pass → 用户第一次点「用未识别目录作源」必然看到
        # 「数据为 0 / 统计中」，因为内存缓存是空的、后台线程要跑 37 秒。
        time.sleep(20)                      # 等服务完全就绪，避开首个请求高峰
        _round = 0
        while True:
            _round += 1
            try:
                _inbox_cache_load()
                # v1.08b：第一轮（缓存可能是上一轮留下的脏值/量级估算）与
                # 后续轮次都重算；后续轮次若缓存仍新鲜则跳过，少抢 IO。
                # 老实现「新鲜就 return」导致脏值（日韩剧=35，真实 738）
                # 永远不被修正，用户一直看到错数。
                if _round > 1 and (time.time() - _INBOX_VIDEO_CACHE['ts']) < _INBOX_VIDEO_TTL:
                    time.sleep(300)
                    continue
                _ib = mtbox_inbox()
                if os.path.isdir(_ib):
                    _names = []
                    for _n in sorted(os.listdir(_ib))[:60]:
                        _fp = os.path.join(_ib, _n)
                        if os.path.isdir(_fp):
                            _nv, _sub = _shallow_video_count(_fp, budget=1.2)
                            # ① 浅层探不到视频 → 深层结构，必须 BFS；
                            # ② 已被标 approx（量级估算）→ 也要重算成精确值
                            if (_sub and _nv == 0) or (_n in _INBOX_APPROX):
                                _names.append(_n)
                    if _names:
                        # v1.09b：按「子目录数降序」处理 —— 大盘优先。
                        # 老实现按字母序，「电视剧-001」这种 55 子目录的大盘
                        # 排在后面，45s 预算跑不到它 → 用户永远看到 0。
                        # 现在大盘先算，用户刷新一次就能看到最大的那几个数字。
                        def _sz(nm):
                            try:
                                return len(os.listdir(os.path.join(_ib, nm)))
                            except Exception:
                                return 0
                        try:
                            _names = sorted(_names, key=_sz, reverse=True)
                        except Exception:
                            pass
                        # 单条目 120s 预算（实测电视剧-004 需 99s）；
                        # 整轮 900s 上限，绝不无限占用 IO。
                        _inbox_video_map(_ib, _names, total_budget=900.0)
                        _inbox_cache_load()      # 立刻把新值读进内存，前台马上能拿到
            except Exception as _e:
                logger.warning('inbox 预热失败: %s', _e)
            time.sleep(300)                 # 5 分钟一轮，绝不连续抢 IO
    threading.Thread(target=_prewarm, daemon=True).start()
    threading.Thread(target=_logrotate_loop, daemon=True).start()

    def _cc_pull_loop():
        """CookieCloud 全自动：每 60 分钟从 MP 拉站点 cookie、
        直连 CC 拉 M-Team JWT 到保号 secrets.json。"""
        time.sleep(120)  # 启动后等 2 分钟再首拉，避开服务刚起的不稳定期
        while True:
            try:
                cc_pull_to_secrets()
            except Exception as e:
                logger.warning('CC 拉取循环异常: %s', e)
            time.sleep(3600)
    threading.Thread(target=_cc_pull_loop, daemon=True).start()
    # ★ 2026-10-24 第七轮：面板 HTML 部署守护（防再次被外部整文件覆盖而无人察觉）
    #   先记基线，再起 30s 巡检线程。只告警+快照，不回滚/不重启/不删文件。
    try:
        html_guard_baseline_init()
    except Exception as _e:
        logger.warning('[HTML-GUARD] 基线初始化失败: %s', _e)
    threading.Thread(target=html_guard_loop, daemon=True).start()
    threading.Thread(target=backup_loop, daemon=True).start()
    threading.Thread(target=_rt_sync_loop, daemon=True).start()

    # ★ 求片优先级抢占引擎（2026-10-14 用户拍板）：115 求片目录有货 →
    #   暂停其他方案、求片方案优先跑；清空后自动恢复。
    threading.Thread(target=_pri_loop, daemon=True).start()

    # ★ v1.18 缺集扫描定时循环（用户原话：「我可以手动执行也可以定时的执行
    #   然后也可以让它自动的去补齐」）—— 后端这一层必须有，
    #   否则前端开关只是个摆设，关掉页面就没了。
    threading.Thread(target=_gap_sched_loop, daemon=True).start()

    ThreadingHTTPServer(('0.0.0.0', PORT), H).serve_forever()
